import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type UserProfileType = 'admin' | 'vendedor';

export interface User {
  id: string;
  email: string;
  nome: string;
  perfil: UserProfileType;
  telefone?: string;
  ativo: boolean;
}

export interface Client {
  id: string;
  nome: string;
  telefone: string;
  endereco: string;
  bairro: string;
  cidade: string;
  observacoes?: string;
  vendedor_id: string;
}

export interface Product {
  id: string;
  nome: string;
  categoria: string;
  valor_avista: number;
  valor_parcelado: number;
  ativo: boolean;
}

export type SaleStatus = 'ABERTA' | 'PARCIAL' | 'QUITADA';

export interface Sale {
  id: string;
  cliente_id: string;
  vendedor_id: string;
  valor_total: number;
  qtd_parcelas: number;
  data_venda: string; // ISO Date
  status: SaleStatus;
  cliente_nome?: string; // Helper for UI
}

export interface Installment {
  id: string;
  venda_id: string;
  numero_parcela: number;
  valor: number;
  data_vencimento: string; // ISO Date
  pago: boolean;
  data_pagamento?: string | null;
}

export type CashFlowType = 'ENTRADA' | 'SAIDA';

export interface CashEntry {
  id: string;
  data: string; // ISO Date
  tipo: CashFlowType;
  valor: number;
  descricao: string;
  vendedor_id: string;
}

export interface CartItem extends Product {
  quantity: number;
}

import { User, Client, Product, Sale, Installment, CashEntry, SaleStatus } from '../types';
import { v4 as uuidv4 } from 'uuid';

// Initial Mock Data
const MOCK_USER: User = {
  id: 'user-1',
  email: 'admin@cla.com',
  nome: 'Carlos Admin',
  perfil: 'admin',
  ativo: true
};

const INITIAL_PRODUCTS: Product[] = [
  { id: 'p1', nome: 'Kit Cama Casal', categoria: 'Cama', valor_avista: 180, valor_parcelado: 220, ativo: true },
  { id: 'p2', nome: 'Jogo de Panelas', categoria: 'Cozinha', valor_avista: 250, valor_parcelado: 300, ativo: true },
  { id: 'p3', nome: 'Cobertor Microfibra', categoria: 'Cama', valor_avista: 90, valor_parcelado: 120, ativo: true },
  { id: 'p4', nome: 'Toalha de Banho', categoria: 'Banho', valor_avista: 45, valor_parcelado: 60, ativo: true },
];

const INITIAL_CLIENTS: Client[] = [
  { id: 'c1', nome: 'Maria Silva', telefone: '11999999999', endereco: 'Rua A, 123', bairro: 'Centro', cidade: 'São Paulo', vendedor_id: 'user-1' },
  { id: 'c2', nome: 'João Souza', telefone: '11888888888', endereco: 'Rua B, 456', bairro: 'Jardins', cidade: 'São Paulo', vendedor_id: 'user-1' },
];

// Helper to simulate network delay
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Local Storage Wrappers
const getStorage = <T>(key: string, initial: T): T => {
  const stored = localStorage.getItem(`cla_${key}`);
  if (!stored) {
    localStorage.setItem(`cla_${key}`, JSON.stringify(initial));
    return initial;
  }
  return JSON.parse(stored);
};

const setStorage = <T>(key: string, data: T) => {
  localStorage.setItem(`cla_${key}`, JSON.stringify(data));
};

// --- AUTH SERVICE ---
export const authService = {
  login: async (email: string, pass: string): Promise<{ user: User | null; error: string | null }> => {
    await delay(800);
    if (email === 'admin@cla.com' && pass === '123456') {
      const user = MOCK_USER;
      localStorage.setItem('cla_session', JSON.stringify(user));
      return { user, error: null };
    }
    return { user: null, error: 'Credenciais inválidas' };
  },
  logout: async () => {
    localStorage.removeItem('cla_session');
  },
  getSession: (): User | null => {
    const session = localStorage.getItem('cla_session');
    return session ? JSON.parse(session) : null;
  }
};

// --- DATA SERVICE ---
export const dataService = {
  // Clients
  getClients: async (): Promise<Client[]> => {
    await delay(300);
    return getStorage<Client[]>('clients', INITIAL_CLIENTS);
  },
  createClient: async (client: Omit<Client, 'id'>): Promise<Client> => {
    await delay(300);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
    const newClient = { ...client, id: uuidv4() };
    setStorage('clients', [newClient, ...clients]);
    return newClient;
  },

  // Products
  getProducts: async (): Promise<Product[]> => {
    await delay(300);
    return getStorage<Product[]>('products', INITIAL_PRODUCTS);
  },

  // Sales
  getSales: async (): Promise<Sale[]> => {
    await delay(300);
    const sales = getStorage<Sale[]>('sales', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
    // Join with client name
    return sales.map(s => ({
      ...s,
      cliente_nome: clients.find(c => c.id === s.cliente_id)?.nome || 'Cliente Desconhecido'
    })).sort((a, b) => new Date(b.data_venda).getTime() - new Date(a.data_venda).getTime());
  },

  createSale: async (saleData: Omit<Sale, 'id' | 'status'>, installmentsData: Omit<Installment, 'id' | 'venda_id'>[]): Promise<void> => {
    await delay(800);
    const sales = getStorage<Sale[]>('sales', []);
    const installments = getStorage<Installment[]>('installments', []);

    const newSaleId = uuidv4();
    const newSale: Sale = {
      ...saleData,
      id: newSaleId,
      status: 'ABERTA'
    };

    const newInstallments = installmentsData.map(i => ({
      ...i,
      id: uuidv4(),
      venda_id: newSaleId,
      pago: false,
      data_pagamento: null
    }));

    setStorage('sales', [newSale, ...sales]);
    setStorage('installments', [...installments, ...newInstallments]);
  },

  // Installments & Payments
  getInstallmentsBySale: async (saleId: string): Promise<Installment[]> => {
    await delay(200);
    const all = getStorage<Installment[]>('installments', []);
    return all.filter(i => i.venda_id === saleId).sort((a, b) => a.numero_parcela - b.numero_parcela);
  },

  getDueInstallments: async (): Promise<(Installment & { cliente_nome: string, venda_id: string })[]> => {
    await delay(400);
    const installments = getStorage<Installment[]>('installments', []);
    const sales = getStorage<Sale[]>('sales', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);

    // Get today and past due that are not paid
    const today = new Date();
    today.setHours(23, 59, 59, 999);

    return installments
      .filter(i => !i.pago && new Date(i.data_vencimento) <= today)
      .map(i => {
        const sale = sales.find(s => s.id === i.venda_id);
        const client = clients.find(c => c.id === sale?.cliente_id);
        return {
          ...i,
          cliente_nome: client?.nome || 'Desconhecido',
          venda_id: i.venda_id
        };
      })
      .sort((a, b) => new Date(a.data_vencimento).getTime() - new Date(b.data_vencimento).getTime());
  },

  payInstallment: async (installmentId: string, vendedorId: string): Promise<void> => {
    await delay(500);
    let installments = getStorage<Installment[]>('installments', []);
    let sales = getStorage<Sale[]>('sales', []);
    let cash = getStorage<CashEntry[]>('cash', []);

    const instIndex = installments.findIndex(i => i.id === installmentId);
    if (instIndex === -1) throw new Error("Parcela não encontrada");

    // 1. Mark installment as paid
    const installment = installments[instIndex];
    if (installment.pago) return; // Already paid

    const updatedInstallment = {
      ...installment,
      pago: true,
      data_pagamento: new Date().toISOString()
    };
    installments[instIndex] = updatedInstallment;

    // 2. Add to Cash Flow
    const newCashEntry: CashEntry = {
      id: uuidv4(),
      data: new Date().toISOString(),
      tipo: 'ENTRADA',
      valor: updatedInstallment.valor,
      descricao: `Pagamento Parcela ${updatedInstallment.numero_parcela}`,
      vendedor_id: vendedorId
    };
    cash.push(newCashEntry);

    // 3. Update Sale Status
    const saleIndex = sales.findIndex(s => s.id === updatedInstallment.venda_id);
    if (saleIndex !== -1) {
      const saleInstallments = installments.filter(i => i.venda_id === updatedInstallment.venda_id);
      const allPaid = saleInstallments.every(i => i.pago);
      const somePaid = saleInstallments.some(i => i.pago);

      let newStatus: SaleStatus = 'ABERTA';
      if (allPaid) newStatus = 'QUITADA';
      else if (somePaid) newStatus = 'PARCIAL';

      sales[saleIndex].status = newStatus;
    }

    setStorage('installments', installments);
    setStorage('sales', sales);
    setStorage('cash', cash);
  },

  getCashFlow: async (): Promise<CashEntry[]> => {
     await delay(300);
     return getStorage<CashEntry[]>('cash', []).sort((a,b) => new Date(b.data).getTime() - new Date(a.data).getTime());
  },

  // Dashboard Stats
  getDashboardStats: async () => {
     await delay(500);
     const sales = getStorage<Sale[]>('sales', []);
     const installments = getStorage<Installment[]>('installments', []);

     const totalVendido = sales.reduce((acc, curr) => acc + curr.valor_total, 0);
     const totalRecebido = installments.filter(i => i.pago).reduce((acc, curr) => acc + curr.valor, 0);
     const totalReceber = installments.filter(i => !i.pago).reduce((acc, curr) => acc + curr.valor, 0);

     // Very basic overdue calculation
     const today = new Date();
     const inadimplencia = installments
        .filter(i => !i.pago && new Date(i.data_vencimento) < today)
        .reduce((acc, curr) => acc + curr.valor, 0);

     return {
         totalVendido,
         totalRecebido,
         totalReceber,
         inadimplencia
     };
  }
};

import React from 'react';

// --- BUTTON ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger';
  fullWidth?: boolean;
  isLoading?: boolean;
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, variant = 'primary', fullWidth, isLoading, icon, className, ...props 
}) => {
  const baseStyles = "relative flex items-center justify-center gap-2 px-4 py-3 rounded-xl font-medium transition-all active:scale-[0.98] disabled:opacity-50 disabled:active:scale-100";

  const variants = {
    primary: "bg-[#FF7A00] text-white hover:bg-[#E66E00] shadow-lg shadow-orange-900/20",
    secondary: "bg-[#404040] text-white hover:bg-[#505050]",
    outline: "border-2 border-[#FF7A00] text-[#FF7A00] hover:bg-[#FF7A00]/10",
    ghost: "text-gray-400 hover:text-white hover:bg-white/5",
    danger: "bg-red-500/10 text-red-500 border border-red-500/20 hover:bg-red-500/20"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? (
        <span className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
      ) : (
        <>
          {icon}
          {children}
        </>
      )}
    </button>
  );
};

// --- INPUT ---
interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: string;
  error?: string;
}

export const Input: React.FC<InputProps> = ({ label, error, className, ...props }) => {
  return (
    <div className="flex flex-col gap-1.5 w-full">
      {label && <label className="text-sm font-medium text-gray-400 ml-1">{label}</label>}
      <input 
        className={`w-full bg-[#2E2E2E] border border-[#404040] rounded-xl px-4 py-3.5 text-white placeholder-gray-500 focus:outline-none focus:border-[#FF7A00] focus:ring-1 focus:ring-[#FF7A00] transition-all disabled:opacity-50 ${className}`}
        {...props}
      />
      {error && <span className="text-xs text-red-400 ml-1">{error}</span>}
    </div>
  );
};

// --- CARD ---
export const Card: React.FC<{ children: React.ReactNode; className?: string; onClick?: () => void }> = ({ children, className, onClick }) => {
  return (
    <div 
      onClick={onClick}
      className={`bg-[#2E2E2E] rounded-2xl p-4 shadow-sm border border-white/5 ${onClick ? 'cursor-pointer active:bg-[#353535]' : ''} ${className}`}
    >
      {children}
    </div>
  );
};

// --- BADGE ---
export const Badge: React.FC<{ status: 'ABERTA' | 'PARCIAL' | 'QUITADA' | string }> = ({ status }) => {
  const styles: Record<string, string> = {
    'ABERTA': 'bg-blue-500/10 text-blue-400 border-blue-500/20',
    'PARCIAL': 'bg-orange-500/10 text-orange-400 border-orange-500/20',
    'QUITADA': 'bg-green-500/10 text-green-400 border-green-500/20',
    'ENTRADA': 'bg-green-500/10 text-green-400',
    'SAIDA': 'bg-red-500/10 text-red-400'
  };

  const defaultStyle = 'bg-gray-500/10 text-gray-400';

  return (
    <span className={`px-2.5 py-1 rounded-full text-xs font-semibold border ${styles[status] || defaultStyle}`}>
      {status}
    </span>
  );
};

// --- MODAL ---
interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}

export const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children }) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-fade-in">
      <div className="bg-[#1A1A1A] w-full max-w-md rounded-3xl border border-[#333] overflow-hidden flex flex-col max-h-[90vh]">
        <div className="flex items-center justify-between p-5 border-b border-[#333]">
          <h3 className="text-lg font-bold text-white">{title}</h3>
          <button onClick={onClose} className="p-2 bg-[#2E2E2E] rounded-full text-gray-400 hover:text-white">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M18 6L6 18M6 6l12 12" />
            </svg>
          </button>
        </div>
        <div className="p-5 overflow-y-auto custom-scrollbar">
          {children}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { useLocation, useNavigate, Outlet } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { authService } from '../services/mockSupabase';

const BottomNavItem: React.FC<{ 
  to: string; 
  icon: React.ReactNode; 
  label: string; 
  isActive: boolean 
}> = ({ to, icon, label, isActive }) => {
  const navigate = useNavigate();
  return (
    <button 
      onClick={() => navigate(to)}
      className={`flex flex-col items-center justify-center w-full gap-1 transition-colors ${isActive ? 'text-[#FF7A00]' : 'text-gray-500'}`}
    >
      <div className={`transition-transform duration-200 ${isActive ? '-translate-y-1' : ''}`}>
        {icon}
      </div>
      <span className="text-[10px] font-medium">{label}</span>
    </button>
  );
};

const Layout: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const session = authService.getSession();

  React.useEffect(() => {
    if (!session) {
      navigate(ROUTES.LOGIN);
    }
  }, [session, navigate]);

  if (!session) return null;

  // Routes where the bottom bar should be hidden (like New Sale flow if desired, but keeping it simple)
  const hideBottomBar = false;

  const currentPath = location.pathname;

  return (
    <div className="flex flex-col h-screen w-screen bg-[#1A1A1A] overflow-hidden text-[#E5E5E5]">
      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto overflow-x-hidden pb-24 custom-scrollbar">
        <Outlet />
      </main>

      {/* Bottom Navigation */}
      {!hideBottomBar && (
        <div className="fixed bottom-0 left-0 right-0 bg-[#2E2E2E]/90 backdrop-blur-lg border-t border-white/5 pb-safe-area-inset-bottom">
          <div className="flex justify-around items-center h-16 max-w-md mx-auto px-2">
            <BottomNavItem 
              to={ROUTES.DASHBOARD} 
              icon={ICONS.Dashboard} 
              label="Início" 
              isActive={currentPath === ROUTES.DASHBOARD} 
            />
            <BottomNavItem 
              to={ROUTES.SALES} 
              icon={ICONS.Sales} 
              label="Vendas" 
              isActive={currentPath === ROUTES.SALES} 
            />
            {/* FAB Placeholder for visual spacing */}
            <div className="w-12"></div>

            <BottomNavItem 
              to={ROUTES.PAYMENTS} 
              icon={ICONS.Payments} 
              label="Caixa" 
              isActive={currentPath === ROUTES.PAYMENTS} 
            />
            <BottomNavItem 
              to={ROUTES.CLIENTS} 
              icon={ICONS.Clients} 
              label="Clientes" 
              isActive={currentPath === ROUTES.CLIENTS} 
            />
          </div>
        </div>
      )}

      {/* Floating Action Button (New Sale) */}
      <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-20">
        <button 
          onClick={() => navigate(ROUTES.NEW_SALE)}
          className="bg-[#FF7A00] text-white p-4 rounded-full shadow-xl shadow-orange-500/30 hover:bg-[#E66E00] active:scale-95 transition-all border-4 border-[#1A1A1A]"
        >
          {ICONS.Add}
        </button>
      </div>
    </div>
  );
};

export default Layout;

import React, { useEffect, useState } from 'react';
import { ICONS, COLORS } from '../constants';
import { Card } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, Tooltip } from 'recharts';

const Dashboard: React.FC = () => {
  const user = authService.getSession();
  const [stats, setStats] = useState({
    totalVendido: 0,
    totalRecebido: 0,
    totalReceber: 0,
    inadimplencia: 0
  });

  useEffect(() => {
    const loadStats = async () => {
      const data = await dataService.getDashboardStats();
      setStats(data);
    };
    loadStats();
  }, []);

  const pieData = [
    { name: 'Recebido', value: stats.totalRecebido, color: COLORS.success },
    { name: 'A Receber', value: stats.totalReceber, color: COLORS.primary },
    { name: 'Atrasado', value: stats.inadimplencia, color: COLORS.danger },
  ];

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
  };

  return (
    <div className="p-5 space-y-6 animate-fade-in">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <p className="text-gray-400 text-sm">Bem-vindo,</p>
          <h1 className="text-2xl font-bold text-white">{user?.nome || 'Vendedor'}</h1>
        </div>
        <div className="w-10 h-10 rounded-full bg-[#333] flex items-center justify-center text-[#FF7A00] font-bold">
          {user?.nome?.charAt(0) || 'U'}
        </div>
      </div>

      {/* Main Stats */}
      <div className="grid grid-cols-2 gap-4">
        <Card className="col-span-2 bg-gradient-to-br from-[#FF7A00] to-[#CC6200] border-none">
          <div className="flex items-center gap-3 mb-2 opacity-90">
            <div className="p-2 bg-white/20 rounded-lg text-white">
              {ICONS.Trending}
            </div>
            <span className="text-white font-medium">Total Vendido</span>
          </div>
          <h2 className="text-3xl font-bold text-white">{formatCurrency(stats.totalVendido)}</h2>
          <p className="text-white/70 text-sm mt-1">Neste período</p>
        </Card>

        <Card>
          <p className="text-gray-400 text-xs mb-1">Recebido</p>
          <p className="text-lg font-bold text-emerald-500">{formatCurrency(stats.totalRecebido)}</p>
        </Card>
        <Card>
          <p className="text-gray-400 text-xs mb-1">A Receber</p>
          <p className="text-lg font-bold text-[#FF7A00]">{formatCurrency(stats.totalReceber)}</p>
        </Card>
      </div>

      {/* Charts Section */}
      <h3 className="text-lg font-bold text-white mt-8">Visão Geral</h3>
      <div className="h-64 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={pieData}
              cx="50%"
              cy="50%"
              innerRadius={60}
              outerRadius={80}
              paddingAngle={5}
              dataKey="value"
              stroke="none"
            >
              {pieData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} />
              ))}
            </Pie>
            <Tooltip 
               contentStyle={{ backgroundColor: '#2E2E2E', border: 'none', borderRadius: '8px' }}
               itemStyle={{ color: '#fff' }}
               formatter={(value: number) => formatCurrency(value)}
            />
          </PieChart>
        </ResponsiveContainer>
      </div>

      {/* Legend */}
      <div className="flex justify-center gap-4 text-sm">
        {pieData.map((item, idx) => (
          <div key={idx} className="flex items-center gap-2">
            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: item.color }} />
            <span className="text-gray-400">{item.name}</span>
          </div>
        ))}
      </div>

      {/* Quick Action - Inadimplencia Warning */}
      {stats.inadimplencia > 0 && (
        <Card className="bg-red-500/10 border-red-500/20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="text-red-500">{ICONS.Alert}</div>
            <div>
              <p className="text-red-400 font-bold text-sm">Atenção Necessária</p>
              <p className="text-red-300/70 text-xs">{formatCurrency(stats.inadimplencia)} em atraso</p>
            </div>
          </div>
          <button className="text-xs bg-red-500/20 text-red-400 px-3 py-1.5 rounded-lg font-medium">
            Ver
          </button>
        </Card>
      )}

      <div className="h-20"></div>
    </div>
  );
};

export default Dashboard;

