               <div className="text-right">
                 <p className="text-gray-500 text-xs">Parcelas</p>
                 <p className="text-white font-medium">{sale.qtd_parcelas}x</p>
               </div>
             </div>
          </Card>
        ))}
        {sales.length === 0 && (
          <p className="text-gray-500 text-center py-10">Nenhuma venda registrada ainda.</p>
        )}
      </div>
    </div>
  );
};

