import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Input, Card } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';
import { Client, Product, CartItem, Installment } from '../types';
import { addMonths, format } from 'date-fns';

const NewSale: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const session = authService.getSession();

  const [step, setStep] = useState<1|2|3>(1);
  const [clients, setClients] = useState<Client[]>([]);
  const [products, setProducts] = useState<Product[]>([]);

  // Sale State
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [installmentsCount, setInstallmentsCount] = useState(1);
  const [generatedInstallments, setGeneratedInstallments] = useState<Omit<Installment, 'id' | 'venda_id'>[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const init = async () => {
      const [c, p] = await Promise.all([dataService.getClients(), dataService.getProducts()]);
      setClients(c);
      setProducts(p);

      // Handle pre-selected client from navigation state
      const state = location.state as { client?: Client };
      if (state?.client) {
        setSelectedClient(state.client);
        setStep(2);
      }
    };
    init();
  }, [location.state]);

  // -- STEP 1: Select Client --
  const handleClientSelect = (client: Client) => {
    setSelectedClient(client);
    setStep(2);
  };

  // -- STEP 2: Products --
  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(p => p.id === product.id);
      if (existing) {
        return prev.map(p => p.id === product.id ? { ...p, quantity: p.quantity + 1 } : p);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(p => p.id !== productId));
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.valor_parcelado * item.quantity), 0);

  // -- STEP 3: Installments --
  const generateInstallments = () => {
    const list: Omit<Installment, 'id' | 'venda_id'>[] = [];
    const baseValue = Math.floor((cartTotal / installmentsCount) * 100) / 100;
    const remainder = Math.round((cartTotal - (baseValue * installmentsCount)) * 100) / 100;

    const today = new Date();

    for (let i = 0; i < installmentsCount; i++) {
      let val = baseValue;
      if (i === installmentsCount - 1) val += remainder;

      list.push({
        numero_parcela: i + 1,
        valor: val,
        data_vencimento: addMonths(today, i + 1).toISOString(), // First installment next month
        pago: false
      });
    }
    setGeneratedInstallments(list);
  };

  useEffect(() => {
    if (step === 3) generateInstallments();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [installmentsCount, step]);

  const handleFinishSale = async () => {
    if (!selectedClient || cart.length === 0 || !session) return;
    setLoading(true);
    try {
      await dataService.createSale({
        cliente_id: selectedClient.id,
        vendedor_id: session.id,
        valor_total: cartTotal,
        qtd_parcelas: installmentsCount,
        data_venda: new Date().toISOString()
      }, generatedInstallments);

      navigate(ROUTES.SALES);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  // --- RENDER HELPERS ---

  return (
    <div className="flex flex-col h-screen bg-[#1A1A1A]">
      {/* Header */}
      <div className="bg-[#2E2E2E] p-4 flex items-center gap-4 border-b border-white/5">
        <button onClick={() => step > 1 ? setStep(prev => prev - 1 as any) : navigate(-1)} className="text-white">
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold text-white">
          {step === 1 ? 'Selecionar Cliente' : step === 2 ? 'Adicionar Produtos' : 'Pagamento'}
        </h1>
        <div className="ml-auto text-sm text-[#FF7A00] font-bold">Passo {step}/3</div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
        {step === 1 && (
          <div className="space-y-3">
             <Input placeholder="Buscar cliente..." className="mb-4" />
             {clients.map(c => (
               <Card key={c.id} onClick={() => handleClientSelect(c)} className="flex items-center justify-between">
                 <div>
                   <p className="font-bold text-white">{c.nome}</p>
                   <p className="text-gray-500 text-sm">{c.bairro}</p>
                 </div>
                 <div className="text-[#FF7A00]">{ICONS.Right}</div>
               </Card>
             ))}
          </div>
        )}

        {step === 2 && (
          <div className="space-y-6">
            <div>
              <h3 className="text-gray-400 text-sm mb-2">Produtos Disponíveis</h3>
              <div className="space-y-2">
                {products.map(p => (
                  <div key={p.id} className="bg-[#2E2E2E] p-3 rounded-xl flex justify-between items-center">
                    <div>
                      <p className="text-white font-medium">{p.nome}</p>
                      <p className="text-[#FF7A00] font-bold">R$ {p.valor_parcelado}</p>
                    </div>
                    <Button variant="secondary" onClick={() => addToCart(p)} className="!p-2">
                      {ICONS.Add}
                    </Button>
                  </div>
                ))}
              </div>
            </div>

            {cart.length > 0 && (
              <div className="border-t border-white/10 pt-4">
                <h3 className="text-white font-bold mb-3">Carrinho</h3>
                {cart.map(item => (
                  <div key={item.id} className="flex justify-between items-center mb-2">
                    <span className="text-gray-300 text-sm">{item.quantity}x {item.nome}</span>
                    <div className="flex items-center gap-3">
                      <span className="text-white">R$ {item.valor_parcelado * item.quantity}</span>
                      <button onClick={() => removeFromCart(item.id)} className="text-red-400">
                        {ICONS.Close}
                      </button>
                    </div>
                  </div>
                ))}
                <div className="mt-4 flex justify-between items-center text-xl font-bold text-[#FF7A00]">
                  <span>Total</span>
                  <span>R$ {cartTotal}</span>
                </div>
              </div>
            )}
          </div>
        )}

        {step === 3 && (
           <div className="space-y-6">
             <Card className="text-center py-6">
               <p className="text-gray-400">Valor Total</p>
               <h2 className="text-3xl font-bold text-[#FF7A00]">R$ {cartTotal}</h2>
               <p className="text-sm text-gray-500 mt-1">{selectedClient?.nome}</p>
             </Card>

             <div className="space-y-2">
               <label className="text-gray-300 font-medium">Número de Parcelas</label>
               <div className="flex gap-2 overflow-x-auto pb-2">
                 {[1,2,3,4,5,6,10,12].map(num => (
                   <button 
                    key={num}
                    onClick={() => setInstallmentsCount(num)}
                    className={`min-w-[50px] h-10 rounded-lg font-bold transition-all ${installmentsCount === num ? 'bg-[#FF7A00] text-white' : 'bg-[#333] text-gray-400'}`}
                   >
                     {num}x
                   </button>
                 ))}
               </div>
             </div>

             <div className="space-y-2">
               <h3 className="text-white font-bold">Resumo das Parcelas</h3>
               {generatedInstallments.map((inst, idx) => (
                 <div key={idx} className="flex justify-between p-3 bg-[#2E2E2E] rounded-lg border border-white/5">
                   <span className="text-gray-400 text-sm">Parc. {inst.numero_parcela}/{installmentsCount}</span>
                   <span className="text-gray-400 text-sm">{format(new Date(inst.data_vencimento), 'dd/MM/yyyy')}</span>
                   <span className="text-white font-bold">R$ {inst.valor.toFixed(2)}</span>
                 </div>
               ))}
             </div>
           </div>
        )}
      </div>

      <div className="p-4 bg-[#2E2E2E] border-t border-white/5">
        {step === 2 && (
          <Button 
            fullWidth 
            onClick={() => setStep(3)} 
            disabled={cart.length === 0}
          >
            Continuar
          </Button>
        )}
        {step === 3 && (
          <Button fullWidth onClick={handleFinishSale} isLoading={loading}>
            Finalizar Venda
          </Button>
        )}
      </div>
    </div>
  );
};

export default NewSale;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Input, Card, Modal } from '../components/ui';
import { dataService } from '../services/mockSupabase';
import { Client } from '../types';

const Clients: React.FC = () => {
  const navigate = useNavigate();
  const [clients, setClients] = useState<Client[]>([]);
  const [search, setSearch] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  // Form State
  const [newClient, setNewClient] = useState<Partial<Client>>({
    nome: '', telefone: '', endereco: '', bairro: '', cidade: ''
  });

  const loadClients = async () => {
    const data = await dataService.getClients();
    setClients(data);
  };

  useEffect(() => {
    loadClients();
  }, []);

  const handleSaveClient = async () => {
    if (!newClient.nome || !newClient.telefone) return;
    setLoading(true);
    try {
      await dataService.createClient(newClient as Omit<Client, 'id'>);
      await loadClients();
      setIsModalOpen(false);
      setNewClient({ nome: '', telefone: '', endereco: '', bairro: '', cidade: '' });
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const filteredClients = clients.filter(c => 
    c.nome.toLowerCase().includes(search.toLowerCase()) || 
    c.telefone.includes(search)
  );

  return (
