      </div>

      <div className="space-y-3">
        {filteredClients.map(client => (
          <Card 
            key={client.id} 
            className="flex justify-between items-center group cursor-pointer active:bg-[#353535]"
            onClick={() => navigate(ROUTES.CLIENT_DETAILS.replace(':id', client.id))}
          >
            <div>
              <h3 className="text-white font-semibold">{client.nome}</h3>
              <p className="text-gray-400 text-sm">{client.telefone}</p>
