import React, { useEffect, useState } from 'react';
import { ICONS, COLORS } from '../constants';
import { Card, Badge, Modal, Button } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';
import { Installment, CashEntry } from '../types';
import { format, isToday, isPast } from 'date-fns';

const Payments: React.FC = () => {
  const session = authService.getSession();
  const [view, setView] = useState<'due' | 'cash'>('due');
  const [dueList, setDueList] = useState<(Installment & { cliente_nome: string, venda_id: string })[]>([]);
  const [cashFlow, setCashFlow] = useState<CashEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [confirmItem, setConfirmItem] = useState<(Installment & { cliente_nome: string }) | null>(null);

  const loadData = async () => {
    const dues = await dataService.getDueInstallments();
    const flow = await dataService.getCashFlow();
    setDueList(dues);
    setCashFlow(flow);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handlePay = async () => {
    if (!confirmItem || !session) return;
    setLoading(true);
    try {
      await dataService.payInstallment(confirmItem.id, session.id);
      await loadData();
      setConfirmItem(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-5 animate-fade-in pb-24">
      <div className="flex gap-4 mb-6">
        <button 
          onClick={() => setView('due')}
          className={`flex-1 pb-2 font-bold text-lg transition-colors border-b-2 ${view === 'due' ? 'text-[#FF7A00] border-[#FF7A00]' : 'text-gray-500 border-transparent'}`}
        >
          A Receber
        </button>
        <button 
          onClick={() => setView('cash')}
          className={`flex-1 pb-2 font-bold text-lg transition-colors border-b-2 ${view === 'cash' ? 'text-[#FF7A00] border-[#FF7A00]' : 'text-gray-500 border-transparent'}`}
        >
          Caixa
        </button>
      </div>

      {view === 'due' && (
        <div className="space-y-4">
          {dueList.length === 0 ? (
            <div className="text-center text-gray-500 py-10">
              <div className="mb-2 opacity-50">{ICONS.Check}</div>
              <p>Nenhum pagamento pendente para hoje.</p>
            </div>
          ) : (
            dueList.map(item => {
              const overdue = isPast(new Date(item.data_vencimento)) && !isToday(new Date(item.data_vencimento));
              return (
                <Card key={item.id} className="flex justify-between items-center border-l-4 border-l-[#FF7A00]">
                  <div>
                    <h4 className="font-bold text-white">{item.cliente_nome}</h4>
                    <p className="text-sm text-gray-400">Parcela {item.numero_parcela}</p>
                    <div className="flex items-center gap-2 mt-1">
                      {overdue && <span className="text-[10px] bg-red-500/20 text-red-400 px-1.5 py-0.5 rounded">Atrasado</span>}
                      <span className="text-xs text-gray-500">{format(new Date(item.data_vencimento), 'dd/MM/yyyy')}</span>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-2">
                    <span className="font-bold text-lg text-white">R$ {item.valor.toFixed(2)}</span>
                    <button 
                      onClick={() => setConfirmItem(item)}
                      className="text-xs bg-green-500/10 text-green-400 px-3 py-1.5 rounded-lg border border-green-500/20 active:bg-green-500/20"
                    >
                      Receber
                    </button>
                  </div>
                </Card>
              );
            })
          )}
        </div>
      )}

      {view === 'cash' && (
        <div className="space-y-4">
          {cashFlow.map(entry => (
             <div key={entry.id} className="flex justify-between items-center p-3 border-b border-white/5">
                <div className="flex items-center gap-3">
                  <div className={`p-2 rounded-full ${entry.tipo === 'ENTRADA' ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'}`}>
                    {entry.tipo === 'ENTRADA' ? ICONS.Trending : ICONS.Alert}
                  </div>
                  <div>
                    <p className="text-white font-medium">{entry.descricao}</p>
                    <p className="text-xs text-gray-500">{format(new Date(entry.data), 'dd/MM HH:mm')}</p>
                  </div>
                </div>
                <span className={`font-bold ${entry.tipo === 'ENTRADA' ? 'text-green-400' : 'text-red-400'}`}>
                   {entry.tipo === 'ENTRADA' ? '+' : '-'} R$ {entry.valor.toFixed(2)}
                </span>
             </div>
          ))}
        </div>
      )}

      <Modal isOpen={!!confirmItem} onClose={() => setConfirmItem(null)} title="Confirmar Recebimento">
        <div className="space-y-6 text-center">
           <div className="w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center text-green-500 mx-auto">
             {ICONS.Check}
           </div>
           <div>
             {confirmItem && (
               <>
                 <p className="text-gray-300">Receber <strong className="text-white">R$ {confirmItem.valor.toFixed(2)}</strong> de <strong className="text-white">{confirmItem.cliente_nome}</strong>?</p>
                 <p className="text-xs text-gray-500 mt-2">Parcela {confirmItem.numero_parcela} • Vencimento {format(new Date(confirmItem.data_vencimento), 'dd/MM/yyyy')}</p>
                 <p className="text-xs text-gray-600 mt-4">Esta ação lançará o valor no caixa imediatamente.</p>
               </>
             )}
           </div>
           <div className="grid grid-cols-2 gap-3">
             <Button variant="secondary" onClick={() => setConfirmItem(null)}>Cancelar</Button>
