];

// Helper to simulate network delay
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Local Storage Wrappers
const getStorage = <T>(key: string, initial: T): T => {
  const stored = localStorage.getItem(`cla_${key}`);
  if (!stored) {
    localStorage.setItem(`cla_${key}`, JSON.stringify(initial));
    return initial;
  }
  return JSON.parse(stored);
};

const setStorage = <T>(key: string, data: T) => {
  localStorage.setItem(`cla_${key}`, JSON.stringify(data));
};

// --- AUTH SERVICE ---
export const authService = {
  login: async (email: string, pass: string): Promise<{ user: User | null; error: string | null }> => {
    await delay(800);
    if (email === 'admin@cla.com' && pass === '123456') {
      const user = MOCK_USER;
      localStorage.setItem('cla_session', JSON.stringify(user));
      return { user, error: null };
    }
    return { user: null, error: 'Credenciais inválidas' };
  },
  logout: async () => {
    localStorage.removeItem('cla_session');
  },
  getSession: (): User | null => {
    const session = localStorage.getItem('cla_session');
    return session ? JSON.parse(session) : null;
  }
};

// --- DATA SERVICE ---
export const dataService = {
  // Clients
  getClients: async (): Promise<Client[]> => {
    await delay(300);
    return getStorage<Client[]>('clients', INITIAL_CLIENTS);
  },
  getClientById: async (id: string): Promise<Client | undefined> => {
    await delay(200);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
    return clients.find(c => c.id === id);
  },
  createClient: async (client: Omit<Client, 'id'>): Promise<Client> => {
    await delay(300);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
    const newClient = { ...client, id: uuidv4() };
    setStorage('clients', [newClient, ...clients]);
    return newClient;
  },

  // Products
  getProducts: async (): Promise<Product[]> => {
    await delay(300);
    return getStorage<Product[]>('products', INITIAL_PRODUCTS);
  },

  // Sales
  getSales: async (): Promise<Sale[]> => {
    await delay(300);
    const sales = getStorage<Sale[]>('sales', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
    // Join with client name
    return sales.map(s => ({
      ...s,
      cliente_nome: clients.find(c => c.id === s.cliente_id)?.nome || 'Cliente Desconhecido'
    })).sort((a, b) => new Date(b.data_venda).getTime() - new Date(a.data_venda).getTime());
  },

  getSalesByClient: async (clientId: string): Promise<Sale[]> => {
    await delay(300);
    const sales = getStorage<Sale[]>('sales', []);
    return sales
      .filter(s => s.cliente_id === clientId)
      .sort((a, b) => new Date(b.data_venda).getTime() - new Date(a.data_venda).getTime());
  },

  createSale: async (saleData: Omit<Sale, 'id' | 'status'>, installmentsData: Omit<Installment, 'id' | 'venda_id'>[]): Promise<void> => {
    await delay(800);
    const sales = getStorage<Sale[]>('sales', []);
    const installments = getStorage<Installment[]>('installments', []);

    const newSaleId = uuidv4();
    const newSale: Sale = {
      ...saleData,
      id: newSaleId,
      status: 'ABERTA'
    };

    const newInstallments = installmentsData.map(i => ({
      ...i,
      id: uuidv4(),
      venda_id: newSaleId,
      pago: false,
      data_pagamento: null
    }));

    setStorage('sales', [newSale, ...sales]);
    setStorage('installments', [...installments, ...newInstallments]);
  },

  // Installments & Payments
  getInstallmentsBySale: async (saleId: string): Promise<Installment[]> => {
    await delay(200);
    const all = getStorage<Installment[]>('installments', []);
    return all.filter(i => i.venda_id === saleId).sort((a, b) => a.numero_parcela - b.numero_parcela);
  },

  updateInstallment: async (id: string, updates: Partial<Pick<Installment, 'valor' | 'data_vencimento'>>): Promise<void> => {
    await delay(300);
    const installments = getStorage<Installment[]>('installments', []);
    const index = installments.findIndex(i => i.id === id);
    if (index === -1) throw new Error("Parcela não encontrada");

    installments[index] = { ...installments[index], ...updates };
    setStorage('installments', installments);

    // Optional: Recalculate Sale Total if needed, but for simplicity we keep sale total as snapshot
  },

  getDueInstallments: async (): Promise<(Installment & { cliente_nome: string, venda_id: string })[]> => {
    await delay(400);
    const installments = getStorage<Installment[]>('installments', []);
    const sales = getStorage<Sale[]>('sales', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);

    // Get today and past due that are not paid
    const today = new Date();
    today.setHours(23, 59, 59, 999);

    return installments
      .filter(i => !i.pago && new Date(i.data_vencimento) <= today)
      .map(i => {
        const sale = sales.find(s => s.id === i.venda_id);
        const client = clients.find(c => c.id === sale?.cliente_id);
        return {
          ...i,
          cliente_nome: client?.nome || 'Desconhecido',
          venda_id: i.venda_id
        };
      })
      .sort((a, b) => new Date(a.data_vencimento).getTime() - new Date(b.data_vencimento).getTime());
  },

  payInstallment: async (installmentId: string, vendedorId: string): Promise<void> => {
    await delay(500);
    let installments = getStorage<Installment[]>('installments', []);
    let sales = getStorage<Sale[]>('sales', []);
    let cash = getStorage<CashEntry[]>('cash', []);

    const instIndex = installments.findIndex(i => i.id === installmentId);
    if (instIndex === -1) throw new Error("Parcela não encontrada");

    // 1. Mark installment as paid
    const installment = installments[instIndex];
    if (installment.pago) return; // Already paid

    const updatedInstallment = {
      ...installment,
      pago: true,
      data_pagamento: new Date().toISOString()
    };
    installments[instIndex] = updatedInstallment;

    // 2. Add to Cash Flow
    const newCashEntry: CashEntry = {
      id: uuidv4(),
      data: new Date().toISOString(),
      tipo: 'ENTRADA',
      valor: updatedInstallment.valor,
      descricao: `Pagamento Parcela ${updatedInstallment.numero_parcela}`,
      vendedor_id: vendedorId
    };
    cash.push(newCashEntry);

    // 3. Update Sale Status
    const saleIndex = sales.findIndex(s => s.id === updatedInstallment.venda_id);
    if (saleIndex !== -1) {
      const saleInstallments = installments.filter(i => i.venda_id === updatedInstallment.venda_id);
      const allPaid = saleInstallments.every(i => i.pago);
      const somePaid = saleInstallments.some(i => i.pago);

      let newStatus: SaleStatus = 'ABERTA';
      if (allPaid) newStatus = 'QUITADA';
      else if (somePaid) newStatus = 'PARCIAL';

      sales[saleIndex].status = newStatus;
    }

    setStorage('installments', installments);
    setStorage('sales', sales);
    setStorage('cash', cash);
  },

  addExpense: async (description: string, value: number, vendedorId: string): Promise<void> => {
    await delay(400);
    let cash = getStorage<CashEntry[]>('cash', []);

    const newExpense: CashEntry = {
      id: uuidv4(),
      data: new Date().toISOString(),
      tipo: 'SAIDA',
      valor: value,
      descricao: description,
      vendedor_id: vendedorId
    };

    cash.push(newExpense);
    setStorage('cash', cash);
  },

  getCashFlow: async (): Promise<CashEntry[]> => {
     await delay(300);
     return getStorage<CashEntry[]>('cash', []).sort((a,b) => new Date(b.data).getTime() - new Date(a.data).getTime());
  },

  // Dashboard Stats
  getDashboardStats: async () => {
     await delay(500);
     const sales = getStorage<Sale[]>('sales', []);
     const installments = getStorage<Installment[]>('installments', []);

     const totalVendido = sales.reduce((acc, curr) => acc + curr.valor_total, 0);
     const totalRecebido = installments.filter(i => i.pago).reduce((acc, curr) => acc + curr.valor, 0);
     const totalReceber = installments.filter(i => !i.pago).reduce((acc, curr) => acc + curr.valor, 0);

     // Very basic overdue calculation
     const today = new Date();
     const inadimplencia = installments
        .filter(i => !i.pago && new Date(i.data_vencimento) < today)
        .reduce((acc, curr) => acc + curr.valor, 0);

     return {
         totalVendido,
         totalRecebido,
         totalReceber,
         inadimplencia
     };
  }
};

import React, { useEffect, useState } from 'react';
import { ICONS, COLORS } from '../constants';
import { Card, Badge, Modal, Button, Input } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';
import { Installment, CashEntry } from '../types';
import { format, isToday, isPast } from 'date-fns';

const Payments: React.FC = () => {
  const session = authService.getSession();
  const [view, setView] = useState<'due' | 'cash'>('due');
  const [dueList, setDueList] = useState<(Installment & { cliente_nome: string, venda_id: string })[]>([]);
  const [cashFlow, setCashFlow] = useState<CashEntry[]>([]);
  const [loading, setLoading] = useState(false);

  // Modals state
  const [confirmItem, setConfirmItem] = useState<(Installment & { cliente_nome: string }) | null>(null);
  const [showExpenseModal, setShowExpenseModal] = useState(false);
  const [expenseForm, setExpenseForm] = useState({ descricao: '', valor: '' });

  const loadData = async () => {
    const dues = await dataService.getDueInstallments();
    const flow = await dataService.getCashFlow();
    setDueList(dues);
    setCashFlow(flow);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handlePay = async () => {
    if (!confirmItem || !session) return;
    setLoading(true);
    try {
      await dataService.payInstallment(confirmItem.id, session.id);
      await loadData();
      setConfirmItem(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleAddExpense = async () => {
    if (!expenseForm.descricao || !expenseForm.valor || !session) return;
    setLoading(true);
    try {
      await dataService.addExpense(expenseForm.descricao, parseFloat(expenseForm.valor), session.id);
      await loadData();
      setShowExpenseModal(false);
      setExpenseForm({ descricao: '', valor: '' });
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  // Calculations for "Caixa Detalhado"
  const totalEntradas = cashFlow.filter(c => c.tipo === 'ENTRADA').reduce((acc, c) => acc + c.valor, 0);
  const totalSaidas = cashFlow.filter(c => c.tipo === 'SAIDA').reduce((acc, c) => acc + c.valor, 0);
  const saldo = totalEntradas - totalSaidas;

  return (
    <div className="p-5 animate-fade-in pb-24">
      <div className="flex gap-4 mb-6">
        <button 
          onClick={() => setView('due')}
          className={`flex-1 pb-2 font-bold text-lg transition-colors border-b-2 ${view === 'due' ? 'text-[#FF7A00] border-[#FF7A00]' : 'text-gray-500 border-transparent'}`}
        >
          A Receber
        </button>
        <button 
          onClick={() => setView('cash')}
          className={`flex-1 pb-2 font-bold text-lg transition-colors border-b-2 ${view === 'cash' ? 'text-[#FF7A00] border-[#FF7A00]' : 'text-gray-500 border-transparent'}`}
        >
          Caixa
        </button>
      </div>

      {view === 'due' && (
        <div className="space-y-4">
          {dueList.length === 0 ? (
            <div className="text-center text-gray-500 py-10">
              <div className="mb-2 opacity-50">{ICONS.Check}</div>
              <p>Nenhum pagamento pendente para hoje.</p>
            </div>
          ) : (
            dueList.map(item => {
              const overdue = isPast(new Date(item.data_vencimento)) && !isToday(new Date(item.data_vencimento));
              return (
                <Card key={item.id} className="flex justify-between items-center border-l-4 border-l-[#FF7A00]">
                  <div>
                    <h4 className="font-bold text-white">{item.cliente_nome}</h4>
                    <p className="text-sm text-gray-400">Parcela {item.numero_parcela}</p>
                    <div className="flex items-center gap-2 mt-1">
                      {overdue && <span className="text-[10px] bg-red-500/20 text-red-400 px-1.5 py-0.5 rounded">Atrasado</span>}
                      <span className="text-xs text-gray-500">{format(new Date(item.data_vencimento), 'dd/MM/yyyy')}</span>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-2">
                    <span className="font-bold text-lg text-white">R$ {item.valor.toFixed(2)}</span>
                    <button 
                      onClick={() => setConfirmItem(item)}
                      className="text-xs bg-green-500/10 text-green-400 px-3 py-1.5 rounded-lg border border-green-500/20 active:bg-green-500/20"
                    >
                      Receber
                    </button>
                  </div>
                </Card>
              );
            })
          )}
        </div>
      )}

      {view === 'cash' && (
        <div className="space-y-6">
          {/* Caixa Detalhado Summary */}
          <div className="grid grid-cols-2 gap-3">
             <div className="bg-[#2E2E2E] p-4 rounded-2xl border border-white/5 col-span-2">
                <p className="text-gray-400 text-sm">Saldo em Caixa</p>
                <h2 className={`text-3xl font-bold ${saldo >= 0 ? 'text-white' : 'text-red-400'}`}>
                  R$ {saldo.toFixed(2)}
                </h2>
             </div>
             <div className="bg-[#2E2E2E] p-3 rounded-xl border border-white/5">
                <div className="flex items-center gap-2 mb-1">
                   <div className="w-2 h-2 rounded-full bg-green-500"></div>
                   <p className="text-xs text-gray-400">Entradas</p>
                </div>
                <p className="text-green-500 font-bold">R$ {totalEntradas.toFixed(2)}</p>
             </div>
             <div className="bg-[#2E2E2E] p-3 rounded-xl border border-white/5">
                <div className="flex items-center gap-2 mb-1">
                   <div className="w-2 h-2 rounded-full bg-red-500"></div>
                   <p className="text-xs text-gray-400">Saídas</p>
                </div>
                <p className="text-red-400 font-bold">R$ {totalSaidas.toFixed(2)}</p>
             </div>
          </div>

          <div className="flex justify-between items-center">
             <h3 className="text-white font-bold">Movimentações</h3>
             <button 
                onClick={() => setShowExpenseModal(true)}
                className="text-xs bg-red-500/10 text-red-400 px-3 py-2 rounded-lg font-medium hover:bg-red-500/20 flex items-center gap-1"
             >
                {ICONS.Add} Despesa
             </button>
          </div>

          <div className="space-y-3">
            {cashFlow.map(entry => (
               <div key={entry.id} className="flex justify-between items-center p-3 bg-[#2E2E2E] rounded-xl border border-white/5">
                  <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${entry.tipo === 'ENTRADA' ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'}`}>
                      {entry.tipo === 'ENTRADA' ? ICONS.Trending : ICONS.Alert}
                    </div>
                    <div>
                      <p className="text-white font-medium">{entry.descricao}</p>
                      <p className="text-xs text-gray-500">{format(new Date(entry.data), 'dd/MM HH:mm')}</p>
                    </div>
                  </div>
                  <span className={`font-bold ${entry.tipo === 'ENTRADA' ? 'text-green-400' : 'text-red-400'}`}>
                     {entry.tipo === 'ENTRADA' ? '+' : '-'} R$ {entry.valor.toFixed(2)}
                  </span>
               </div>
            ))}
            {cashFlow.length === 0 && (
              <p className="text-center text-gray-500 py-4 text-sm">Nenhuma movimentação registrada.</p>
            )}
          </div>
        </div>
      )}

      {/* Confirmation Modal */}
      <Modal isOpen={!!confirmItem} onClose={() => setConfirmItem(null)} title="Confirmar Recebimento">
        <div className="space-y-6 text-center">
           <div className="w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center text-green-500 mx-auto">
             {ICONS.Check}
           </div>
           <div>
             {confirmItem && (
               <>
                 <p className="text-gray-300">Receber <strong className="text-white">R$ {confirmItem.valor.toFixed(2)}</strong> de <strong className="text-white">{confirmItem.cliente_nome}</strong>?</p>
                 <p className="text-xs text-gray-500 mt-2">Parcela {confirmItem.numero_parcela} • Vencimento {format(new Date(confirmItem.data_vencimento), 'dd/MM/yyyy')}</p>
                 <p className="text-xs text-gray-600 mt-4">Esta ação lançará o valor no caixa imediatamente.</p>
               </>
             )}
           </div>
           <div className="grid grid-cols-2 gap-3">
             <Button variant="secondary" onClick={() => setConfirmItem(null)}>Cancelar</Button>
             <Button onClick={handlePay} isLoading={loading} className="bg-green-600 hover:bg-green-700 border-none shadow-green-900/20">
               Confirmar
             </Button>
           </div>
        </div>
      </Modal>

      {/* Add Expense Modal */}
      <Modal isOpen={showExpenseModal} onClose={() => setShowExpenseModal(false)} title="Nova Despesa">
         <div className="space-y-4">
            <Input 
               label="Descrição" 
               placeholder="Ex: Combustível, Almoço..."
               value={expenseForm.descricao}
               onChange={(e) => setExpenseForm(prev => ({ ...prev, descricao: e.target.value }))}
            />
            <Input 
               label="Valor (R$)" 
               type="number"
               step="0.01"
               placeholder="0,00"
               value={expenseForm.valor}
               onChange={(e) => setExpenseForm(prev => ({ ...prev, valor: e.target.value }))}
            />
            <Button 
               fullWidth 
               onClick={handleAddExpense} 
               isLoading={loading}
               variant="danger"
               className="mt-2"
            >
               Lançar Saída
            </Button>
         </div>
      </Modal>
    </div>
  );
};

