  getSession: (): User | null => {
    const session = localStorage.getItem('cla_session');
    return session ? JSON.parse(session) : null;
  }
};

// --- DATA SERVICE ---
export const dataService = {
  // Users (Sellers)
  getSellers: async (): Promise<User[]> => {
    await delay(300);
    const users = getStorage<User[]>('users', MOCK_USERS);
    return users.filter(u => u.perfil === 'vendedor' || u.perfil === 'admin');
  },

  createSeller: async (userData: Omit<User, 'id'>): Promise<void> => {
    await delay(400);
    const users = getStorage<User[]>('users', MOCK_USERS);
    const newUser = { ...userData, id: uuidv4(), ativo: true };
    setStorage('users', [...users, newUser]);
  },

  // Clients
  getClients: async (): Promise<Client[]> => {
    await delay(300);
    return getStorage<Client[]>('clients', INITIAL_CLIENTS);
  },
  getClientById: async (id: string): Promise<Client | undefined> => {
    await delay(200);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
    return clients.find(c => c.id === id);
  },
  createClient: async (client: Omit<Client, 'id'>): Promise<Client> => {
    await delay(300);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
    const newClient = { ...client, id: uuidv4() };
    setStorage('clients', [newClient, ...clients]);
    return newClient;
  },

  // Products
  getProducts: async (): Promise<Product[]> => {
    await delay(300);
    return getStorage<Product[]>('products', INITIAL_PRODUCTS);
  },

  // Sales
  getSales: async (): Promise<Sale[]> => {
    await delay(300);
    const sales = getStorage<Sale[]>('sales', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
    // Join with client name
    return sales.map(s => ({
      ...s,
      cliente_nome: clients.find(c => c.id === s.cliente_id)?.nome || 'Cliente Desconhecido'
    })).sort((a, b) => new Date(b.data_venda).getTime() - new Date(a.data_venda).getTime());
  },

  getSalesByClient: async (clientId: string): Promise<Sale[]> => {
    await delay(300);
    const sales = getStorage<Sale[]>('sales', []);
    return sales
      .filter(s => s.cliente_id === clientId)
      .sort((a, b) => new Date(b.data_venda).getTime() - new Date(a.data_venda).getTime());
  },

  createSale: async (saleData: Omit<Sale, 'id' | 'status'>, installmentsData: Omit<Installment, 'id' | 'venda_id'>[]): Promise<void> => {
    await delay(800);
    const sales = getStorage<Sale[]>('sales', []);
    const installments = getStorage<Installment[]>('installments', []);

    const newSaleId = uuidv4();
    const newSale: Sale = {
      ...saleData,
      id: newSaleId,
      status: 'ABERTA'
    };

    const newInstallments = installmentsData.map(i => ({
      ...i,
      id: uuidv4(),
      venda_id: newSaleId,
      pago: false,
      data_pagamento: null
    }));

    setStorage('sales', [newSale, ...sales]);
    setStorage('installments', [...installments, ...newInstallments]);
  },

  // Installments & Payments
  getInstallmentsBySale: async (saleId: string): Promise<Installment[]> => {
    await delay(200);
    const all = getStorage<Installment[]>('installments', []);
    return all.filter(i => i.venda_id === saleId).sort((a, b) => a.numero_parcela - b.numero_parcela);
  },

  updateInstallment: async (id: string, updates: Partial<Pick<Installment, 'valor' | 'data_vencimento'>>): Promise<void> => {
    await delay(300);
    const installments = getStorage<Installment[]>('installments', []);
    const index = installments.findIndex(i => i.id === id);
    if (index === -1) throw new Error("Parcela não encontrada");

    installments[index] = { ...installments[index], ...updates };
    setStorage('installments', installments);
  },

  getDueInstallments: async (): Promise<(Installment & { cliente_nome: string, venda_id: string })[]> => {
    await delay(400);
    const installments = getStorage<Installment[]>('installments', []);
    const sales = getStorage<Sale[]>('sales', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);

    const today = new Date();
    today.setHours(23, 59, 59, 999);

    return installments
      .filter(i => !i.pago && new Date(i.data_vencimento) <= today)
      .map(i => {
        const sale = sales.find(s => s.id === i.venda_id);
        const client = clients.find(c => c.id === sale?.cliente_id);
        return {
          ...i,
          cliente_nome: client?.nome || 'Desconhecido',
          venda_id: i.venda_id
        };
      })
      .sort((a, b) => new Date(a.data_vencimento).getTime() - new Date(b.data_vencimento).getTime());
  },

  payInstallment: async (installmentId: string, vendedorId: string): Promise<void> => {
    await delay(500);
    let installments = getStorage<Installment[]>('installments', []);
    let sales = getStorage<Sale[]>('sales', []);
    let cash = getStorage<CashEntry[]>('cash', []);

    const instIndex = installments.findIndex(i => i.id === installmentId);
    if (instIndex === -1) throw new Error("Parcela não encontrada");

    // 1. Mark installment as paid
    const installment = installments[instIndex];
    if (installment.pago) return; 

    const updatedInstallment = {
      ...installment,
      pago: true,
      data_pagamento: new Date().toISOString()
    };
    installments[instIndex] = updatedInstallment;

    // 2. Add to Cash Flow
    const newCashEntry: CashEntry = {
      id: uuidv4(),
      data: new Date().toISOString(),
      tipo: 'ENTRADA',
      valor: updatedInstallment.valor,
      descricao: `Pagamento Parcela ${updatedInstallment.numero_parcela}`,
      vendedor_id: vendedorId
    };
    cash.push(newCashEntry);

    // 3. Update Sale Status
    const saleIndex = sales.findIndex(s => s.id === updatedInstallment.venda_id);
    if (saleIndex !== -1) {
      const saleInstallments = installments.filter(i => i.venda_id === updatedInstallment.venda_id);
      const allPaid = saleInstallments.every(i => i.pago);
      const somePaid = saleInstallments.some(i => i.pago);

      let newStatus: SaleStatus = 'ABERTA';
      if (allPaid) newStatus = 'QUITADA';
      else if (somePaid) newStatus = 'PARCIAL';

      sales[saleIndex].status = newStatus;
    }

    setStorage('installments', installments);
    setStorage('sales', sales);
    setStorage('cash', cash);
  },

  addExpense: async (description: string, value: number, vendedorId: string): Promise<void> => {
    await delay(400);
    let cash = getStorage<CashEntry[]>('cash', []);

    const newExpense: CashEntry = {
      id: uuidv4(),
      data: new Date().toISOString(),
      tipo: 'SAIDA',
      valor: value,
      descricao: description,
      vendedor_id: vendedorId
    };

    cash.push(newExpense);
    setStorage('cash', cash);
  },

  getCashFlow: async (): Promise<CashEntry[]> => {
     await delay(300);
     return getStorage<CashEntry[]>('cash', []).sort((a,b) => new Date(b.data).getTime() - new Date(a.data).getTime());
  },

  // Dashboard Stats
  getDashboardStats: async () => {
     await delay(500);
     const sales = getStorage<Sale[]>('sales', []);
     const installments = getStorage<Installment[]>('installments', []);

     const totalVendido = sales.reduce((acc, curr) => acc + curr.valor_total, 0);
     const totalRecebido = installments.filter(i => i.pago).reduce((acc, curr) => acc + curr.valor, 0);
     const totalReceber = installments.filter(i => !i.pago).reduce((acc, curr) => acc + curr.valor, 0);

     const today = new Date();
     const inadimplencia = installments
        .filter(i => !i.pago && new Date(i.data_vencimento) < today)
        .reduce((acc, curr) => acc + curr.valor, 0);

     return {
         totalVendido,
         totalRecebido,
         totalReceber,
         inadimplencia
     };
  },

  // NEW: Detailed Reports
  getDetailedReports: async (startDate: Date, endDate: Date) => {
    await delay(600);
    const users = getStorage<User[]>('users', MOCK_USERS);
    const sales = getStorage<Sale[]>('sales', []);
    const cash = getStorage<CashEntry[]>('cash', []);

    // Filter by date range
    const filteredSales = sales.filter(s => {
      const d = new Date(s.data_venda);
      return d >= startDate && d <= endDate;
    });

    const filteredCash = cash.filter(c => {
      const d = new Date(c.data);
      return d >= startDate && d <= endDate && c.tipo === 'ENTRADA';
    });

    // Per Seller Report
    const sellerReports: SellerReport[] = users.map(user => {
      const userSales = filteredSales.filter(s => s.vendedor_id === user.id);
      const userCash = filteredCash.filter(c => c.vendedor_id === user.id);

      const totalVendas = userSales.reduce((acc, s) => acc + s.valor_total, 0);
      const totalRecebido = userCash.reduce((acc, c) => acc + c.valor, 0);

      // Calculate Commission (based on Sales total for this example)
      const comissao = totalVendas * ((user.comissao_porcentagem || 0) / 100);

      return {
        vendedor_nome: user.nome,
        total_vendas: totalVendas,
        total_recebido: totalRecebido,
        comissao_estimada: comissao,
        quantidade_vendas: userSales.length
      };
    });

    // Daily Report (Chart Data)
    const interval = eachDayOfInterval({ start: startDate, end: endDate });
    const dailyData: DailyReport[] = interval.map(date => {
      const daySales = filteredSales.filter(s => isSameDay(new Date(s.data_venda), date));
      const dayCash = filteredCash.filter(c => isSameDay(new Date(c.data), date));

      return {
        data: format(date, 'dd/MM'),
        vendas: daySales.reduce((acc, s) => acc + s.valor_total, 0),
        recebimentos: dayCash.reduce((acc, c) => acc + c.valor, 0)
      };
    });

    return { sellerReports, dailyData };
  }
};

