const Sellers: React.FC = () => {
  const navigate = useNavigate();
  const [sellers, setSellers] = useState<User[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  const [form, setForm] = useState({
    nome: '',
    email: '',
    comissao_porcentagem: ''
  });

  const loadSellers = async () => {
    const data = await dataService.getSellers();
    setSellers(data);
  };

  useEffect(() => {
    loadSellers();
  }, []);

  const handleSave = async () => {
    if (!form.nome || !form.email) return;
    setLoading(true);
    try {
      await dataService.createSeller({
        nome: form.nome,
        email: form.email,
        perfil: 'vendedor',
        ativo: true,
        comissao_porcentagem: Number(form.comissao_porcentagem) || 0
      });
      await loadSellers();
      setIsModalOpen(false);
      setForm({ nome: '', email: '', comissao_porcentagem: '' });
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#1A1A1A]">
      <div className="bg-[#2E2E2E] p-4 flex items-center gap-4 border-b border-white/5">
