        <Button onClick={() => setIsModalOpen(true)} fullWidth icon={ICONS.UserPlus}>
          Novo Vendedor
        </Button>

        <div className="space-y-3">
          {sellers.map(seller => (
            <Card key={seller.id} className="flex justify-between items-center">
              <div>
                <h3 className="text-white font-bold flex items-center gap-2">
                   {seller.nome}
                   {seller.perfil === 'admin' && <span className="bg-red-500/20 text-red-500 text-[10px] px-2 py-0.5 rounded-full">ADMIN</span>}
                </h3>
                <p className="text-gray-500 text-sm">{seller.email}</p>
              </div>
              <div className="text-right">
                <p className="text-xs text-gray-500">Comissão</p>
                <p className="text-[#FF7A00] font-bold">{seller.comissao_porcentagem}%</p>
              </div>
            </Card>
          ))}
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Cadastrar Vendedor">
        <div className="space-y-4">
          <Input 
            label="Nome Completo" 
            value={form.nome} 
            onChange={e => setForm({...form, nome: e.target.value})}
          />
