            label="E-mail" 
            type="email"
            value={form.email} 
            onChange={e => setForm({...form, email: e.target.value})}
          />
          <Input 
            label="Comissão (%)" 
            type="number"
            placeholder="Ex: 5"
            value={form.comissao_porcentagem} 
            onChange={e => setForm({...form, comissao_porcentagem: e.target.value})}
          />
          <p className="text-xs text-gray-500">* Senha padrão inicial: 123456</p>
          <Button fullWidth onClick={handleSave} isLoading={loading}>
            Salvar
          </Button>
        </div>
      </Modal>
    </div>
  );
};

