  { id: 'c2', nome: 'João Souza', telefone: '11888888888', endereco: 'Rua B, 456', bairro: 'Jardins', cidade: 'São Paulo', vendedor_id: 'user-2' },
];

// Helper to simulate network delay
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Local Storage Wrappers
const getStorage = <T>(key: string, initial: T): T => {
  const stored = localStorage.getItem(`cla_${key}`);
  if (!stored) {
    localStorage.setItem(`cla_${key}`, JSON.stringify(initial));
    return initial;
  }
  return JSON.parse(stored);
};

const setStorage = <T>(key: string, data: T) => {
  localStorage.setItem(`cla_${key}`, JSON.stringify(data));
};

// --- AUTH SERVICE ---
export const authService = {
  login: async (email: string, pass: string): Promise<{ user: User | null; error: string | null }> => {
    await delay(800);
    const users = getStorage<User[]>('users', MOCK_USERS);
    const user = users.find(u => u.email === email); // Simple mock check, ignores password for now

    if (user) {
      localStorage.setItem('cla_session', JSON.stringify(user));
      return { user, error: null };
    }
    return { user: null, error: 'Credenciais inválidas' };
  },
  logout: async () => {
    localStorage.removeItem('cla_session');
  },
  getSession: (): User | null => {
    const session = localStorage.getItem('cla_session');
    return session ? JSON.parse(session) : null;
  }
};

// --- DATA SERVICE ---
export const dataService = {
  // Users (Sellers)
  getSellers: async (): Promise<User[]> => {
    await delay(300);
    const users = getStorage<User[]>('users', MOCK_USERS);
    return users.filter(u => u.perfil === 'vendedor' || u.perfil === 'admin');
  },

  createSeller: async (userData: Omit<User, 'id'>): Promise<void> => {
    await delay(400);
    const users = getStorage<User[]>('users', MOCK_USERS);
    const newUser = { ...userData, id: uuidv4(), ativo: true };
    setStorage('users', [...users, newUser]);
  },

  // Clients
  getClients: async (): Promise<Client[]> => {
    await delay(300);
    return getStorage<Client[]>('clients', INITIAL_CLIENTS);
  },
  getClientById: async (id: string): Promise<Client | undefined> => {
    await delay(200);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
    return clients.find(c => c.id === id);
  },
  createClient: async (client: Omit<Client, 'id'>): Promise<Client> => {
    await delay(300);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
    const newClient = { ...client, id: uuidv4() };
    setStorage('clients', [newClient, ...clients]);
    return newClient;
  },

  // Products
  getProducts: async (): Promise<Product[]> => {
    await delay(300);
    return getStorage<Product[]>('products', INITIAL_PRODUCTS);
  },

  // Sales
  getSales: async (): Promise<Sale[]> => {
    await delay(300);
    const sales = getStorage<Sale[]>('sales', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
    // Join with client name
    return sales.map(s => ({
      ...s,
      cliente_nome: clients.find(c => c.id === s.cliente_id)?.nome || 'Cliente Desconhecido'
    })).sort((a, b) => new Date(b.data_venda).getTime() - new Date(a.data_venda).getTime());
  },

  getSalesByClient: async (clientId: string): Promise<Sale[]> => {
    await delay(300);
    const sales = getStorage<Sale[]>('sales', []);
    return sales
      .filter(s => s.cliente_id === clientId)
      .sort((a, b) => new Date(b.data_venda).getTime() - new Date(a.data_venda).getTime());
  },

  createSale: async (saleData: Omit<Sale, 'id' | 'status'>, installmentsData: Omit<Installment, 'id' | 'venda_id'>[]): Promise<void> => {
    await delay(800);
    const sales = getStorage<Sale[]>('sales', []);
    const installments = getStorage<Installment[]>('installments', []);

    const newSaleId = uuidv4();
    const newSale: Sale = {
      ...saleData,
      id: newSaleId,
      status: 'ABERTA'
    };

    const newInstallments = installmentsData.map(i => ({
      ...i,
      id: uuidv4(),
      venda_id: newSaleId,
      pago: false,
      data_pagamento: null
    }));

    setStorage('sales', [newSale, ...sales]);
    setStorage('installments', [...installments, ...newInstallments]);
  },

  // Installments & Payments
  getInstallmentsBySale: async (saleId: string): Promise<Installment[]> => {
    await delay(200);
    const all = getStorage<Installment[]>('installments', []);
    return all.filter(i => i.venda_id === saleId).sort((a, b) => a.numero_parcela - b.numero_parcela);
  },

  updateInstallment: async (id: string, updates: Partial<Pick<Installment, 'valor' | 'data_vencimento'>>): Promise<void> => {
    await delay(300);
    const installments = getStorage<Installment[]>('installments', []);
    const index = installments.findIndex(i => i.id === id);
    if (index === -1) throw new Error("Parcela não encontrada");

    installments[index] = { ...installments[index], ...updates };
    setStorage('installments', installments);
  },

  getDueInstallments: async (): Promise<(Installment & { cliente_nome: string, venda_id: string })[]> => {
    await delay(400);
    const installments = getStorage<Installment[]>('installments', []);
    const sales = getStorage<Sale[]>('sales', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);

    const today = new Date();
    today.setHours(23, 59, 59, 999);

    return installments
      .filter(i => !i.pago && new Date(i.data_vencimento) <= today)
      .map(i => {
        const sale = sales.find(s => s.id === i.venda_id);
        const client = clients.find(c => c.id === sale?.cliente_id);
        return {
          ...i,
          cliente_nome: client?.nome || 'Desconhecido',
          venda_id: i.venda_id
        };
      })
      .sort((a, b) => new Date(a.data_vencimento).getTime() - new Date(b.data_vencimento).getTime());
  },

  payInstallment: async (installmentId: string, vendedorId: string): Promise<void> => {
    await delay(500);
    let installments = getStorage<Installment[]>('installments', []);
    let sales = getStorage<Sale[]>('sales', []);
    let cash = getStorage<CashEntry[]>('cash', []);

    const instIndex = installments.findIndex(i => i.id === installmentId);
    if (instIndex === -1) throw new Error("Parcela não encontrada");

    // 1. Mark installment as paid
    const installment = installments[instIndex];
    if (installment.pago) return; 

    const updatedInstallment = {
      ...installment,
      pago: true,
      data_pagamento: new Date().toISOString()
    };
    installments[instIndex] = updatedInstallment;

    // 2. Add to Cash Flow
    const newCashEntry: CashEntry = {
      id: uuidv4(),
      data: new Date().toISOString(),
      tipo: 'ENTRADA',
      valor: updatedInstallment.valor,
      descricao: `Pagamento Parcela ${updatedInstallment.numero_parcela}`,
      vendedor_id: vendedorId
    };
    cash.push(newCashEntry);

    // 3. Update Sale Status
    const saleIndex = sales.findIndex(s => s.id === updatedInstallment.venda_id);
    if (saleIndex !== -1) {
      const saleInstallments = installments.filter(i => i.venda_id === updatedInstallment.venda_id);
      const allPaid = saleInstallments.every(i => i.pago);
      const somePaid = saleInstallments.some(i => i.pago);

      let newStatus: SaleStatus = 'ABERTA';
      if (allPaid) newStatus = 'QUITADA';
      else if (somePaid) newStatus = 'PARCIAL';

      sales[saleIndex].status = newStatus;
    }

    setStorage('installments', installments);
    setStorage('sales', sales);
    setStorage('cash', cash);
  },

  addExpense: async (description: string, value: number, vendedorId: string): Promise<void> => {
    await delay(400);
    let cash = getStorage<CashEntry[]>('cash', []);

    const newExpense: CashEntry = {
      id: uuidv4(),
      data: new Date().toISOString(),
      tipo: 'SAIDA',
      valor: value,
      descricao: description,
      vendedor_id: vendedorId
    };

    cash.push(newExpense);
    setStorage('cash', cash);
  },

  getCashFlow: async (): Promise<CashEntry[]> => {
     await delay(300);
     return getStorage<CashEntry[]>('cash', []).sort((a,b) => new Date(b.data).getTime() - new Date(a.data).getTime());
  },

  // Dashboard Stats
  getDashboardStats: async () => {
     await delay(500);
     const sales = getStorage<Sale[]>('sales', []);
     const installments = getStorage<Installment[]>('installments', []);

     const totalVendido = sales.reduce((acc, curr) => acc + curr.valor_total, 0);
     const totalRecebido = installments.filter(i => i.pago).reduce((acc, curr) => acc + curr.valor, 0);
     const totalReceber = installments.filter(i => !i.pago).reduce((acc, curr) => acc + curr.valor, 0);

     const today = new Date();
     const inadimplencia = installments
        .filter(i => !i.pago && new Date(i.data_vencimento) < today)
        .reduce((acc, curr) => acc + curr.valor, 0);

     return {
         totalVendido,
         totalRecebido,
         totalReceber,
         inadimplencia
     };
  },

  // NEW: Detailed Reports with Seller Filtering
  getDetailedReports: async (startDate: Date, endDate: Date, sellerId?: string) => {
    await delay(600);
    const users = getStorage<User[]>('users', MOCK_USERS);
    const sales = getStorage<Sale[]>('sales', []);
    const cash = getStorage<CashEntry[]>('cash', []);

    // Filter by date range
    let filteredSales = sales.filter(s => {
      const d = new Date(s.data_venda);
      return d >= startDate && d <= endDate;
    });

    let filteredCash = cash.filter(c => {
      const d = new Date(c.data);
      return d >= startDate && d <= endDate && c.tipo === 'ENTRADA';
    });

    // Filter by Seller if specified
    if (sellerId && sellerId !== 'all') {
      filteredSales = filteredSales.filter(s => s.vendedor_id === sellerId);
      filteredCash = filteredCash.filter(c => c.vendedor_id === sellerId);
    }

    // Per Seller Report Logic
    // If a seller is selected, we only show that seller. If 'all', we show all sellers involved in the filtered data.
    const relevantUsers = (sellerId && sellerId !== 'all') 
      ? users.filter(u => u.id === sellerId)
      : users;

    const sellerReports: SellerReport[] = relevantUsers.map(user => {
      const userSales = filteredSales.filter(s => s.vendedor_id === user.id);
      const userCash = filteredCash.filter(c => c.vendedor_id === user.id);

      const totalVendas = userSales.reduce((acc, s) => acc + s.valor_total, 0);
      const totalRecebido = userCash.reduce((acc, c) => acc + c.valor, 0);

      const comissao = totalVendas * ((user.comissao_porcentagem || 0) / 100);

      return {
        vendedor_nome: user.nome,
        total_vendas: totalVendas,
        total_recebido: totalRecebido,
        comissao_estimada: comissao,
        quantidade_vendas: userSales.length
      };
    }).filter(r => r.total_vendas > 0 || r.total_recebido > 0 || (sellerId && sellerId !== 'all')); // Only show active sellers unless explicitly filtered

    // Daily Report (Chart Data) - Aggregated based on filters
    const interval = eachDayOfInterval({ start: startDate, end: endDate });
    const dailyData: DailyReport[] = interval.map(date => {
      const daySales = filteredSales.filter(s => isSameDay(new Date(s.data_venda), date));
      const dayCash = filteredCash.filter(c => isSameDay(new Date(c.data), date));

      return {
        data: format(date, 'dd/MM'),
        vendas: daySales.reduce((acc, s) => acc + s.valor_total, 0),
        recebimentos: dayCash.reduce((acc, c) => acc + c.valor, 0)
      };
    });

    return { sellerReports, dailyData };
  }
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ICONS, COLORS } from '../constants';
import { Card } from '../components/ui';
import { dataService } from '../services/mockSupabase';
import { SellerReport, DailyReport, User } from '../types';
import { format, startOfMonth, endOfMonth } from 'date-fns';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, LineChart, Line, CartesianGrid } from 'recharts';

const Reports: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);

  // Date Filters (default current month)
  const [startDate, setStartDate] = useState(format(startOfMonth(new Date()), 'yyyy-MM-dd'));
  const [endDate, setEndDate] = useState(format(endOfMonth(new Date()), 'yyyy-MM-dd'));

  // Seller Filter
  const [sellers, setSellers] = useState<User[]>([]);
  const [selectedSeller, setSelectedSeller] = useState<string>('all');

  const [sellerReports, setSellerReports] = useState<SellerReport[]>([]);
  const [dailyData, setDailyData] = useState<DailyReport[]>([]);

  // Load Sellers on mount
  useEffect(() => {
    const fetchSellers = async () => {
      const data = await dataService.getSellers();
      setSellers(data);
    };
    fetchSellers();
  }, []);

  // Load Reports Data
  useEffect(() => {
    const loadData = async () => {
      setLoading(true);
      const data = await dataService.getDetailedReports(
        new Date(startDate), 
        new Date(endDate),
        selectedSeller
      );
      setSellerReports(data.sellerReports);
      setDailyData(data.dailyData);
      setLoading(false);
    };
    loadData();
  }, [startDate, endDate, selectedSeller]);

  // Aggregate Totals for the Summary Cards
  const totalSalesPeriod = sellerReports.reduce((acc, curr) => acc + curr.total_vendas, 0);
  const totalReceivedPeriod = sellerReports.reduce((acc, curr) => acc + curr.total_recebido, 0);
  const totalCommissionPeriod = sellerReports.reduce((acc, curr) => acc + curr.comissao_estimada, 0);

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-[#2E2E2E] p-3 border border-white/10 rounded-lg shadow-xl">
          <p className="text-white font-bold mb-1">{label}</p>
          {payload.map((p: any, idx: number) => (
             <p key={idx} style={{ color: p.color }} className="text-sm">
               {p.name}: R$ {p.value.toFixed(2)}
             </p>
          ))}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="flex flex-col h-screen bg-[#1A1A1A]">
      <div className="bg-[#2E2E2E] p-4 flex items-center gap-4 border-b border-white/5 sticky top-0 z-10">
        <button onClick={() => navigate(-1)} className="text-white">
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold text-white">Relatórios Detalhados</h1>
      </div>

      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar pb-24 space-y-6">

        {/* Filters Section */}
        <div className="grid grid-cols-2 gap-3 bg-[#262626] p-4 rounded-2xl border border-white/5">
           <div className="col-span-2 space-y-1">
             <label className="text-xs text-gray-400 ml-1">Vendedor</label>
             <select
                className="w-full bg-[#2E2E2E] border border-[#404040] rounded-xl px-3 py-2 text-white text-sm focus:outline-none focus:border-[#FF7A00]"
                value={selectedSeller}
                onChange={(e) => setSelectedSeller(e.target.value)}
             >
                <option value="all">Todos os Vendedores</option>
                {sellers.map(s => (
                  <option key={s.id} value={s.id}>{s.nome}</option>
                ))}
             </select>
           </div>
           <div className="space-y-1">
             <label className="text-xs text-gray-400 ml-1">Início</label>
             <input 
               type="date" 
               className="w-full bg-[#2E2E2E] border border-[#404040] rounded-xl px-3 py-2 text-white text-sm"
               value={startDate}
               onChange={(e) => setStartDate(e.target.value)}
             />
           </div>
           <div className="space-y-1">
             <label className="text-xs text-gray-400 ml-1">Fim</label>
             <input 
               type="date" 
               className="w-full bg-[#2E2E2E] border border-[#404040] rounded-xl px-3 py-2 text-white text-sm"
               value={endDate}
               onChange={(e) => setEndDate(e.target.value)}
             />
           </div>
        </div>

        {/* Global Stats for Filtered Period */}
        <div className="grid grid-cols-3 gap-2">
           <Card className="text-center p-2 !py-3">
             <p className="text-[10px] text-gray-400 uppercase tracking-wide">Vendido</p>
             <p className="text-[#FF7A00] font-bold text-sm sm:text-base break-all">R$ {totalSalesPeriod.toFixed(0)}</p>
           </Card>
           <Card className="text-center p-2 !py-3">
             <p className="text-[10px] text-gray-400 uppercase tracking-wide">Recebido</p>
             <p className="text-green-500 font-bold text-sm sm:text-base break-all">R$ {totalReceivedPeriod.toFixed(0)}</p>
           </Card>
           <Card className="text-center p-2 !py-3 bg-[#FF7A00]/5 border-[#FF7A00]/20">
             <p className="text-[10px] text-gray-400 uppercase tracking-wide">Comissão</p>
             <p className="text-white font-bold text-sm sm:text-base break-all">R$ {totalCommissionPeriod.toFixed(0)}</p>
           </Card>
        </div>

        {/* Chart: Sales vs Receipts */}
        <Card className="h-72 pb-8">
           <h3 className="text-white font-bold mb-4 text-sm">Evolução Diária</h3>
           {loading ? (
             <div className="h-full flex items-center justify-center text-gray-500 text-sm">Carregando...</div>
           ) : dailyData.length === 0 ? (
             <div className="h-full flex items-center justify-center text-gray-500 text-sm">Sem dados no período</div>
           ) : (
             <ResponsiveContainer width="100%" height="100%">
               <LineChart data={dailyData}>
                 <CartesianGrid strokeDasharray="3 3" stroke="#333" vertical={false} />
                 <XAxis dataKey="data" stroke="#666" fontSize={12} tickLine={false} />
                 <Tooltip content={<CustomTooltip />} />
                 <Line type="monotone" dataKey="vendas" name="Vendas" stroke={COLORS.primary} strokeWidth={3} dot={false} />
                 <Line type="monotone" dataKey="recebimentos" name="Recebimentos" stroke={COLORS.success} strokeWidth={3} dot={false} />
               </LineChart>
             </ResponsiveContainer>
           )}
        </Card>

        {/* Detailed Table per Seller */}
        <div className="space-y-4">
           <h3 className="text-white font-bold">Detalhamento por Vendedor</h3>
           {sellerReports.length === 0 ? (
             <p className="text-gray-500 text-sm">Nenhum registro encontrado para os filtros selecionados.</p>
           ) : (
             sellerReports.map((report, idx) => (
               <Card key={idx} className="bg-[#2E2E2E] overflow-hidden">
                  <div className="border-b border-white/5 pb-3 mb-3 flex justify-between items-center">
                     <div className="flex items-center gap-2">
                        <div className="w-8 h-8 bg-white/10 rounded-full flex items-center justify-center text-[#FF7A00] font-bold">
                          {report.vendedor_nome.charAt(0)}
                        </div>
                        <span className="text-white font-bold">{report.vendedor_nome}</span>
                     </div>
                     <div className="text-xs text-gray-500 bg-white/5 px-2 py-1 rounded">
                        {report.quantidade_vendas} vendas
                     </div>
                  </div>
                  <div className="grid grid-cols-3 gap-2 text-center">
                     <div>
                       <p className="text-[10px] text-gray-400">Total Vendas</p>
                       <p className="text-white font-bold text-sm">R$ {report.total_vendas.toFixed(2)}</p>
                     </div>
                     <div>
                       <p className="text-[10px] text-gray-400">Recebido</p>
                       <p className="text-green-500 font-bold text-sm">R$ {report.total_recebido.toFixed(2)}</p>
                     </div>
                     <div className="bg-[#FF7A00]/10 rounded-lg py-1">
                       <p className="text-[10px] text-[#FF7A00]">Comissão</p>
                       <p className="text-[#FF7A00] font-bold text-sm">R$ {report.comissao_estimada.toFixed(2)}</p>
                     </div>
                  </div>
               </Card>
             ))
           )}
        </div>
      </div>
    </div>
  );
};

export default Reports;

