        ...form,
        valor_avista: Number(form.valor_avista),
        valor_parcelado: Number(form.valor_parcelado)
      };

      if (editingId) {
        await dataService.updateProduct(editingId, productData);
      } else {
        await dataService.createProduct(productData as Omit<Product, 'id'>);
      }
      await loadProducts();
      setIsModalOpen(false);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!deletingId) return;
    setLoading(true);
    try {
      await dataService.deleteProduct(deletingId);
      await loadProducts();
      setIsDeleteModalOpen(false);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const filteredProducts = products.filter(p => 
    p.nome.toLowerCase().includes(search.toLowerCase()) || 
    p.categoria.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="flex flex-col h-screen bg-[#1A1A1A]">
      <div className="bg-[#2E2E2E] p-4 flex items-center gap-4 border-b border-white/5 sticky top-0 z-10">
        <button onClick={() => navigate(-1)} className="text-white">
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold text-white">Produtos</h1>
      </div>

      <div className="p-4 space-y-4">
        <Button onClick={handleOpenCreate} fullWidth icon={ICONS.Product}>
          Novo Produto
        </Button>

        <div className="relative">
            <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500">
            {ICONS.Search}
            </div>
            <Input 
            placeholder="Buscar produto..." 
            className="pl-10"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            />
        </div>

        <div className="space-y-3 pb-20">
          {filteredProducts.map(product => (
            <Card key={product.id} className="relative group">
              <div className="flex justify-between items-start mb-2">
                <div>
                   <span className="text-xs text-gray-500 uppercase tracking-wide bg-white/5 px-2 py-0.5 rounded">{product.categoria}</span>
                   <h3 className="text-white font-bold text-lg mt-1">{product.nome}</h3>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4 mt-3 pt-3 border-t border-white/5">
                 <div>
                    <p className="text-[10px] text-gray-500">À Vista</p>
                    <p className="text-green-500 font-bold">R$ {product.valor_avista.toFixed(2)}</p>
                 </div>
                 <div className="text-right">
                    <p className="text-[10px] text-gray-500">Parcelado</p>
                    <p className="text-[#FF7A00] font-bold">R$ {product.valor_parcelado.toFixed(2)}</p>
                 </div>
              </div>

              <div className="flex gap-2 pt-3 mt-2 border-t border-white/5">
                <button 
                  onClick={(e) => handleOpenEdit(product, e)}
                  className="flex-1 py-2 bg-gray-500/10 text-gray-400 rounded-lg hover:bg-white/10 flex justify-center items-center gap-2 text-sm"
                >
                    {ICONS.Edit} Editar
                </button>
                <button 
                  onClick={(e) => handleOpenDelete(product.id, e)}
                  className="flex-1 py-2 bg-red-500/10 text-red-400 rounded-lg hover:bg-red-500/20 flex justify-center items-center gap-2 text-sm"
                >
                    {ICONS.Trash} Excluir
                </button>
              </div>
            </Card>
          ))}
          {filteredProducts.length === 0 && (
            <p className="text-center text-gray-500 py-10">Nenhum produto encontrado.</p>
          )}
        </div>
      </div>

      {/* Create/Edit Modal */}
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingId ? "Editar Produto" : "Novo Produto"}>
        <div className="space-y-4">
          <Input 
            label="Nome do Produto" 
            value={form.nome} 
            onChange={e => setForm({...form, nome: e.target.value})}
          />
          <Input 
            label="Categoria" 
            placeholder="Ex: Cama, Mesa, Banho"
            value={form.categoria} 
            onChange={e => setForm({...form, categoria: e.target.value})}
          />
          <div className="grid grid-cols-2 gap-4">
            <Input 
                label="Valor à Vista (R$)" 
                type="number"
                step="0.01"
                value={form.valor_avista} 
                onChange={e => setForm({...form, valor_avista: e.target.value as any})}
            />
            <Input 
                label="Valor Parcelado (R$)" 
                type="number"
                step="0.01"
                value={form.valor_parcelado} 
                onChange={e => setForm({...form, valor_parcelado: e.target.value as any})}
            />
          </div>
          <Button fullWidth onClick={handleSave} isLoading={loading}>
            Salvar
          </Button>
        </div>
      </Modal>

      {/* Delete Confirmation Modal */}
      <Modal isOpen={isDeleteModalOpen} onClose={() => setIsDeleteModalOpen(false)} title="Excluir Produto">
         <div className="text-center space-y-4">
             <div className="w-16 h-16 bg-red-500/20 rounded-full flex items-center justify-center text-red-500 mx-auto">
                {ICONS.Trash}
             </div>
             <p className="text-gray-300">Tem certeza que deseja excluir este produto?</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setIsDeleteModalOpen(false)}>Cancelar</Button>
                 <Button variant="danger" onClick={handleDelete} isLoading={loading}>Excluir</Button>
             </div>
         </div>
      </Modal>
    </div>
  );
};

