    installments[index] = { ...installments[index], ...updates };
    setStorage('installments', installments);
  },

  getDueInstallments: async (): Promise<(Installment & { cliente_nome: string, venda_id: string })[]> => {
    await delay(400);
    const installments = getStorage<Installment[]>('installments', []);
    const sales = getStorage<Sale[]>('sales', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);

    const today = new Date();
    today.setHours(23, 59, 59, 999);

    return installments
      .filter(i => !i.pago && new Date(i.data_vencimento) <= today)
      .map(i => {
        const sale = sales.find(s => s.id === i.venda_id);
        const client = clients.find(c => c.id === sale?.cliente_id);
        return {
          ...i,
          cliente_nome: client?.nome || 'Desconhecido',
          venda_id: i.venda_id
        };
      })
      .sort((a, b) => new Date(a.data_vencimento).getTime() - new Date(b.data_vencimento).getTime());
  },

  payInstallment: async (installmentId: string, vendedorId: string): Promise<void> => {
    await delay(500);
    let installments = getStorage<Installment[]>('installments', []);
    let sales = getStorage<Sale[]>('sales', []);
    let cash = getStorage<CashEntry[]>('cash', []);

    const instIndex = installments.findIndex(i => i.id === installmentId);
    if (instIndex === -1) throw new Error("Parcela não encontrada");

    // 1. Mark installment as paid
    const installment = installments[instIndex];
    if (installment.pago) return; 

    const updatedInstallment = {
      ...installment,
      pago: true,
      data_pagamento: new Date().toISOString()
    };
    installments[instIndex] = updatedInstallment;

    // 2. Add to Cash Flow
    const newCashEntry: CashEntry = {
      id: uuidv4(),
      data: new Date().toISOString(),
      tipo: 'ENTRADA',
      valor: updatedInstallment.valor,
      descricao: `Pagamento Parcela ${updatedInstallment.numero_parcela}`,
      vendedor_id: vendedorId
    };
    cash.push(newCashEntry);

    // 3. Update Sale Status
    const saleIndex = sales.findIndex(s => s.id === updatedInstallment.venda_id);
    if (saleIndex !== -1) {
      const saleInstallments = installments.filter(i => i.venda_id === updatedInstallment.venda_id);
      const allPaid = saleInstallments.every(i => i.pago);
      const somePaid = saleInstallments.some(i => i.pago);

      let newStatus: SaleStatus = 'ABERTA';
      if (allPaid) newStatus = 'QUITADA';
      else if (somePaid) newStatus = 'PARCIAL';

      sales[saleIndex].status = newStatus;
    }

    setStorage('installments', installments);
    setStorage('sales', sales);
    setStorage('cash', cash);
  },

  addExpense: async (description: string, value: number, vendedorId: string): Promise<void> => {
    await delay(400);
    let cash = getStorage<CashEntry[]>('cash', []);

    const newExpense: CashEntry = {
      id: uuidv4(),
      data: new Date().toISOString(),
      tipo: 'SAIDA',
      valor: value,
      descricao: description,
      vendedor_id: vendedorId
    };

    cash.push(newExpense);
    setStorage('cash', cash);
  },

  deleteCashEntry: async (id: string): Promise<void> => {
    await delay(300);
    let cash = getStorage<CashEntry[]>('cash', []);
    setStorage('cash', cash.filter(c => c.id !== id));
  },

  getCashFlow: async (): Promise<CashEntry[]> => {
     await delay(300);
     return getStorage<CashEntry[]>('cash', []).sort((a,b) => new Date(b.data).getTime() - new Date(a.data).getTime());
  },

  // Dashboard Stats
  getDashboardStats: async () => {
     await delay(500);
     const sales = getStorage<Sale[]>('sales', []);
     const installments = getStorage<Installment[]>('installments', []);

     const totalVendido = sales.reduce((acc, curr) => acc + curr.valor_total, 0);
     const totalRecebido = installments.filter(i => i.pago).reduce((acc, curr) => acc + curr.valor, 0);
     const totalReceber = installments.filter(i => !i.pago).reduce((acc, curr) => acc + curr.valor, 0);

     const today = new Date();
     const inadimplencia = installments
        .filter(i => !i.pago && new Date(i.data_vencimento) < today)
        .reduce((acc, curr) => acc + curr.valor, 0);

     return {
         totalVendido,
         totalRecebido,
         totalReceber,
         inadimplencia
     };
  },

  // Detailed Reports
  getDetailedReports: async (startDate: Date, endDate: Date, sellerId?: string) => {
    await delay(600);
    const users = getStorage<User[]>('users', MOCK_USERS);
    const sales = getStorage<Sale[]>('sales', []);
    const cash = getStorage<CashEntry[]>('cash', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);

    // Filter by date range
    let filteredSales = sales.filter(s => {
      const d = new Date(s.data_venda);
      return d >= startDate && d <= endDate;
    });

    let filteredCash = cash.filter(c => {
      const d = new Date(c.data);
      return d >= startDate && d <= endDate && c.tipo === 'ENTRADA';
    });

    // Filter by Seller if specified
    if (sellerId && sellerId !== 'all') {
      filteredSales = filteredSales.filter(s => s.vendedor_id === sellerId);
      filteredCash = filteredCash.filter(c => c.vendedor_id === sellerId);
    }

    // Enrich Sales with Client Names for report
    const enrichedSales = filteredSales.map(s => ({
      ...s,
      cliente_nome: clients.find(c => c.id === s.cliente_id)?.nome || 'Cliente Desconhecido'
    })).sort((a,b) => new Date(b.data_venda).getTime() - new Date(a.data_venda).getTime());

    const enrichedCash = filteredCash.sort((a,b) => new Date(b.data).getTime() - new Date(a.data).getTime());

    // Daily Report (Chart Data) - Aggregated based on filters
    const interval = eachDayOfInterval({ start: startDate, end: endDate });
    const dailyData: DailyReport[] = interval.map(date => {
      const daySales = filteredSales.filter(s => isSameDay(new Date(s.data_venda), date));
      const dayCash = filteredCash.filter(c => isSameDay(new Date(c.data), date));

      return {
        data: format(date, 'dd/MM'),
        vendas: daySales.reduce((acc, s) => acc + s.valor_total, 0),
        recebimentos: dayCash.reduce((acc, c) => acc + c.valor, 0)
      };
    });

    // Summary Totals
    const totalSales = filteredSales.reduce((acc, s) => acc + s.valor_total, 0);
    const totalReceipts = filteredCash.reduce((acc, c) => acc + c.valor, 0);

    return { 
      dailyData, 
      sales: enrichedSales, 
      receipts: enrichedCash,
      summary: { totalSales, totalReceipts }
    };
  },

  // --- BACKUP & RESTORE ---
  exportBackupData: async (): Promise<string> => {
    await delay(500);
    const backup = {
      version: '1.0',
      timestamp: new Date().toISOString(),
      users: getStorage<User[]>('users', MOCK_USERS),
      clients: getStorage<Client[]>('clients', INITIAL_CLIENTS),
      products: getStorage<Product[]>('products', INITIAL_PRODUCTS),
      sales: getStorage<Sale[]>('sales', []),
      installments: getStorage<Installment[]>('installments', []),
      cash: getStorage<CashEntry[]>('cash', [])
    };
    return JSON.stringify(backup, null, 2);
  },

  importBackupData: async (jsonData: string): Promise<void> => {
    await delay(1000);
    try {
      const data = JSON.parse(jsonData);

      // Basic validation
      if (!data.version || !Array.isArray(data.clients) || !Array.isArray(data.sales)) {
        throw new Error("Formato de arquivo inválido");
      }

      setStorage('users', data.users || MOCK_USERS);
      setStorage('clients', data.clients || []);
      setStorage('products', data.products || []);
      setStorage('sales', data.sales || []);
      setStorage('installments', data.installments || []);
      setStorage('cash', data.cash || []);

    } catch (e) {
      console.error(e);
      throw new Error("Erro ao processar arquivo de backup");
    }
  }
};

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ICONS } from '../constants';
import { Card, Button, Modal } from '../components/ui';
import { dataService } from '../services/mockSupabase';

const Settings: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [successMsg, setSuccessMsg] = useState('');
  const [errorMsg, setErrorMsg] = useState('');

  // File upload ref
  const fileInputRef = React.useRef<HTMLInputElement>(null);

  const handleDownloadBackup = async () => {
    setLoading(true);
    setSuccessMsg('');
    setErrorMsg('');
    try {
      const jsonString = await dataService.exportBackupData();
      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);

      const a = document.createElement('a');
      a.href = url;
      a.download = `backup_cla_vendas_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      setSuccessMsg('Backup baixado com sucesso!');
    } catch (e) {
      console.error(e);
      setErrorMsg('Erro ao gerar backup.');
    } finally {
      setLoading(false);
    }
  };

  const handleRestoreClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setSuccessMsg('');
    setErrorMsg('');

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const content = event.target?.result as string;
        await dataService.importBackupData(content);
        setSuccessMsg('Dados restaurados com sucesso! O app será recarregado.');
        setTimeout(() => {
           window.location.reload();
        }, 2000);
      } catch (err) {
        console.error(err);
        setErrorMsg('Erro ao restaurar arquivo. Verifique se é um backup válido.');
        setLoading(false);
      }
    };
    reader.readAsText(file);

    // Reset input
    e.target.value = ''; 
  };

  return (
    <div className="flex flex-col h-screen bg-[#1A1A1A]">
      <div className="bg-[#2E2E2E] p-4 flex items-center gap-4 border-b border-white/5 sticky top-0 z-10">
        <button onClick={() => navigate(-1)} className="text-white">
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold text-white">Configurações & Dados</h1>
      </div>

      <div className="p-4 space-y-6">
        <div className="bg-blue-500/10 border border-blue-500/20 p-4 rounded-xl text-sm text-blue-200">
           <p className="flex items-center gap-2 mb-2 font-bold text-blue-400">
              <span className="p-1 bg-blue-500/20 rounded-lg">{ICONS.Alert}</span>
              Importante
           </p>
           Os dados deste aplicativo ficam salvos no armazenamento do seu navegador. 
           Recomendamos fazer o download do backup periodicamente para não perder suas informações.
        </div>

        <Card className="space-y-4">
           <h3 className="text-white font-bold text-lg flex items-center gap-2">
              {ICONS.Database} Gerenciamento de Dados
           </h3>
           <p className="text-gray-400 text-sm">
             Exporte seus dados para um arquivo seguro ou restaure de um arquivo salvo anteriormente.
           </p>

           <div className="grid grid-cols-1 gap-3 pt-2">
              <Button 
                onClick={handleDownloadBackup} 
                disabled={loading}
                icon={ICONS.Download}
                variant="outline"
                fullWidth
              >
                 Baixar Backup (Exportar)
              </Button>

              <Button 
                onClick={handleRestoreClick} 
                disabled={loading}
                icon={ICONS.Upload}
                variant="secondary"
                fullWidth
              >
                 Carregar Backup (Importar)
              </Button>
              {/* Hidden Input */}
              <input 
                 type="file" 
                 accept=".json" 
                 ref={fileInputRef}
                 className="hidden"
                 onChange={handleFileChange}
              />
           </div>
        </Card>

        {/* Feedback Messages */}
        {loading && (
           <div className="text-center py-4 text-gray-400 animate-pulse">
              Processando dados...
           </div>
        )}

        {successMsg && (
           <div className="p-4 bg-green-500/10 border border-green-500/20 text-green-400 rounded-xl text-center">
              {successMsg}
           </div>
        )}

        {errorMsg && (
           <div className="p-4 bg-red-500/10 border border-red-500/20 text-red-400 rounded-xl text-center">
              {errorMsg}
           </div>
        )}
      </div>
    </div>
  );
};

export default Settings;

