// --- AUTH SERVICE ---
export const authService = {
  login: async (email: string, pass: string): Promise<{ user: User | null; error: string | null }> => {
    try {
      // NOTE: In production, use supabase.auth.signInWithPassword. 
      // Here we query the 'users' table directly to match the previous simple structure.
      const { data, error } = await supabase
        .from('users')
        .select('*')
        .eq('email', email)
        .eq('senha', pass) // WARNING: Plain text password for demo. Use hashing in production.
        .single();

      if (error || !data) {
        return { user: null, error: 'Credenciais inválidas' };
      }

      if (!data.ativo) {
        return { user: null, error: 'Usuário desativado' };
      }

      const user: User = data;
      localStorage.setItem('cla_session', JSON.stringify(user));
      return { user, error: null };
    } catch (e) {
      console.error(e);
      return { user: null, error: 'Erro de conexão' };
    }
  },
  logout: async () => {
    localStorage.removeItem('cla_session');
    // await supabase.auth.signOut();
  },
  getSession: (): User | null => {
    const session = localStorage.getItem('cla_session');
    return session ? JSON.parse(session) : null;
  }
};

// --- DATA SERVICE ---
export const dataService = {
  // Users
  getSellers: async (): Promise<User[]> => {
    const { data } = await supabase.from('users').select('*').order('nome');
    return data || [];
  },

  createSeller: async (userData: Omit<User, 'id'>): Promise<void> => {
    // We map the incoming object to the table columns (assuming 'senha' is defaulted or handled)
    const { error } = await supabase.from('users').insert([{
      ...userData,
      senha: '123456' // Default password
    }]);
    if (error) throw error;
  },

  updateSeller: async (id: string, updates: Partial<User>): Promise<void> => {
    const { error } = await supabase.from('users').update(updates).eq('id', id);
    if (error) throw error;
  },

  deleteSeller: async (id: string): Promise<void> => {
    const { error } = await supabase.from('users').delete().eq('id', id);
    if (error) throw error;
  },

  // Clients
  getClients: async (): Promise<Client[]> => {
    const { data } = await supabase.from('clients').select('*').order('nome');
    return data || [];
  },

  getClientById: async (id: string): Promise<Client | undefined> => {
    const { data } = await supabase.from('clients').select('*').eq('id', id).single();
    return data || undefined;
  },

  createClient: async (client: Omit<Client, 'id'>): Promise<Client> => {
    const { data, error } = await supabase.from('clients').insert([client]).select().single();
    if (error) throw error;
    return data;
  },

  updateClient: async (id: string, updates: Partial<Client>): Promise<void> => {
    const { error } = await supabase.from('clients').update(updates).eq('id', id);
    if (error) throw error;
  },

  deleteClient: async (id: string): Promise<void> => {
    const { error } = await supabase.from('clients').delete().eq('id', id);
    if (error) throw error;
  },

  // Products
  getProducts: async (): Promise<Product[]> => {
    const { data } = await supabase.from('products').select('*').eq('ativo', true).order('nome');
    return data || [];
  },

  createProduct: async (productData: Omit<Product, 'id'>): Promise<void> => {
    const { error } = await supabase.from('products').insert([productData]);
    if (error) throw error;
  },

  updateProduct: async (id: string, updates: Partial<Product>): Promise<void> => {
    const { error } = await supabase.from('products').update(updates).eq('id', id);
    if (error) throw error;
  },

  deleteProduct: async (id: string): Promise<void> => {
    const { error } = await supabase.from('products').delete().eq('id', id);
    if (error) throw error;
  },

  // Sales
  getSales: async (): Promise<Sale[]> => {
    // Join with clients to get names
    const { data, error } = await supabase
      .from('sales')
      .select('*, clients(nome)')
      .order('data_venda', { ascending: false });

    if (error) throw error;

    return (data || []).map((s: any) => ({
      ...s,
      cliente_nome: s.clients?.nome || 'Desconhecido'
    }));
  },

  getSalesByClient: async (clientId: string): Promise<Sale[]> => {
    const { data } = await supabase
      .from('sales')
      .select('*')
      .eq('cliente_id', clientId)
      .order('data_venda', { ascending: false });
    return data || [];
  },

  createSale: async (saleData: Omit<Sale, 'id' | 'status'>, installmentsData: Omit<Installment, 'id' | 'venda_id'>[]): Promise<void> => {
    // 1. Create Sale
    const { data: sale, error: saleError } = await supabase
      .from('sales')
      .insert([{ ...saleData, status: 'ABERTA' }])
      .select()
      .single();

    if (saleError || !sale) throw saleError;

    // 2. Create Installments
    const installmentsWithId = installmentsData.map(i => ({
      ...i,
      venda_id: sale.id
    }));

    const { error: instError } = await supabase.from('installments').insert(installmentsWithId);
    if (instError) throw instError;
  },

  deleteSale: async (saleId: string): Promise<void> => {
    const { error } = await supabase.from('sales').delete().eq('id', saleId);
    if (error) throw error;
  },

  // Installments & Payments
  getInstallmentsBySale: async (saleId: string): Promise<Installment[]> => {
    const { data } = await supabase
      .from('installments')
      .select('*')
      .eq('venda_id', saleId)
      .order('numero_parcela');
    return data || [];
  },

  updateInstallment: async (id: string, updates: Partial<Pick<Installment, 'valor' | 'data_vencimento'>>): Promise<void> => {
    const { error } = await supabase.from('installments').update(updates).eq('id', id);
    if (error) throw error;
  },

  getDueInstallments: async (): Promise<(Installment & { cliente_nome: string, venda_id: string })[]> => {
    const today = new Date();
    today.setHours(23, 59, 59, 999);

    // Complex join: Installments -> Sales -> Clients
    const { data, error } = await supabase
      .from('installments')
      .select(`
        *,
        sales (
          id,
          clients (nome)
        )
      `)
      .eq('pago', false)
      .lte('data_vencimento', today.toISOString())
      .order('data_vencimento');

    if (error) throw error;

    return (data || []).map((i: any) => ({
      ...i,
      cliente_nome: i.sales?.clients?.nome || 'Desconhecido',
      venda_id: i.venda_id
    }));
  },

  payInstallment: async (installmentId: string, vendedorId: string): Promise<void> => {
    // 1. Get Installment
    const { data: inst } = await supabase.from('installments').select('*').eq('id', installmentId).single();
    if (!inst || inst.pago) return;

    // 2. Mark as Paid
    await supabase.from('installments').update({
      pago: true,
      data_pagamento: new Date().toISOString()
    }).eq('id', installmentId);

    // 3. Add to Cash Flow
    await supabase.from('cash_flow').insert([{
      tipo: 'ENTRADA',
      valor: inst.valor,
      descricao: `Pagamento Parcela ${inst.numero_parcela}`,
      vendedor_id: vendedorId,
      data: new Date().toISOString()
    }]);

    // 4. Check Sale Status (Simplified logic)
    // In a real app, use a DB trigger or a count query
    const { data: allInst } = await supabase.from('installments').select('pago').eq('venda_id', inst.venda_id);
    if (allInst) {
       const allPaid = allInst.every((i: any) => i.pago);
       const somePaid = allInst.some((i: any) => i.pago);
       let status: SaleStatus = 'ABERTA';
       if (allPaid) status = 'QUITADA';
       else if (somePaid) status = 'PARCIAL';

       await supabase.from('sales').update({ status }).eq('id', inst.venda_id);
    }
  },

  addExpense: async (description: string, value: number, vendedorId: string): Promise<void> => {
    const { error } = await supabase.from('cash_flow').insert([{
      tipo: 'SAIDA',
      valor: value,
      descricao: description,
      vendedor_id: vendedorId,
      data: new Date().toISOString()
    }]);
    if (error) throw error;
  },

  deleteCashEntry: async (id: string): Promise<void> => {
     const { error } = await supabase.from('cash_flow').delete().eq('id', id);
     if (error) throw error;
  },

  getCashFlow: async (): Promise<CashEntry[]> => {
     const { data } = await supabase.from('cash_flow').select('*').order('data', { ascending: false });
     return data || [];
  },

  // Dashboard Stats
  getDashboardStats: async () => {
     // This is heavy on the client side, ideally use RPC in Supabase
     const { data: sales } = await supabase.from('sales').select('valor_total');
     const { data: paidInst } = await supabase.from('installments').select('valor').eq('pago', true);
     const { data: openInst } = await supabase.from('installments').select('valor').eq('pago', false);

     const today = new Date().toISOString();
     const { data: overdueInst } = await supabase.from('installments')
        .select('valor')
        .eq('pago', false)
        .lt('data_vencimento', today);

     const totalVendido = sales?.reduce((acc, curr) => acc + curr.valor_total, 0) || 0;
     const totalRecebido = paidInst?.reduce((acc, curr) => acc + curr.valor, 0) || 0;
     const totalReceber = openInst?.reduce((acc, curr) => acc + curr.valor, 0) || 0;
     const inadimplencia = overdueInst?.reduce((acc, curr) => acc + curr.valor, 0) || 0;

     return { totalVendido, totalRecebido, totalReceber, inadimplencia };
  },

  // Detailed Reports
  getDetailedReports: async (startDate: Date, endDate: Date, sellerId?: string) => {
    let salesQuery = supabase.from('sales').select('*, clients(nome)')
        .gte('data_venda', startDate.toISOString())
        .lte('data_venda', endDate.toISOString());

    let cashQuery = supabase.from('cash_flow').select('*')
        .eq('tipo', 'ENTRADA')
        .gte('data', startDate.toISOString())
        .lte('data', endDate.toISOString());

    if (sellerId && sellerId !== 'all') {
       salesQuery = salesQuery.eq('vendedor_id', sellerId);
       cashQuery = cashQuery.eq('vendedor_id', sellerId);
    }

    const { data: salesData } = await salesQuery;
    const { data: cashData } = await cashQuery;

    const sales = (salesData || []).map((s: any) => ({
        ...s,
        cliente_nome: s.clients?.nome || 'Desconhecido'
    }));

    const receipts = cashData || [];

    // Daily Aggregation
    const interval = eachDayOfInterval({ start: startDate, end: endDate });
    const dailyData: DailyReport[] = interval.map(date => {
      const daySales = sales.filter(s => isSameDay(new Date(s.data_venda), date));
      const dayCash = receipts.filter(c => isSameDay(new Date(c.data), date));

      return {
        data: format(date, 'dd/MM'),
        vendas: daySales.reduce((acc, s) => acc + s.valor_total, 0),
        recebimentos: dayCash.reduce((acc, c) => acc + c.valor, 0)
      };
    });

    const totalSales = sales.reduce((acc, s) => acc + s.valor_total, 0);
    const totalReceipts = receipts.reduce((acc, c) => acc + c.valor, 0);

    return { 
      dailyData, 
      sales, 
      receipts,
      summary: { totalSales, totalReceipts }
    };
  },

  // --- BACKUP & RESTORE (Not fully applicable to Supabase but kept for interface compatibility) ---
  exportBackupData: async (): Promise<string> => {
     // In a real DB app, you backup the DB, not client-side dump. 
     // We'll return a basic JSON of current state for compatibility.
     const [users, clients, products, sales, installments, cash] = await Promise.all([
        dataService.getSellers(),
        dataService.getClients(),
        dataService.getProducts(),
        dataService.getSales(),
        supabase.from('installments').select('*').then(r => r.data),
        dataService.getCashFlow()
     ]);

     const backup = {
       version: '1.0',
       timestamp: new Date().toISOString(),
       users, clients, products, sales, installments, cash
     };
     return JSON.stringify(backup, null, 2);
  },

  importBackupData: async (jsonData: string): Promise<void> => {
