import { useNavigate } from 'react-router-dom';
import { Button, Input, Modal } from '../components/ui';
import { authService } from '../services/mockSupabase';
import { isSupabaseConfigured, configureSupabase, clearSupabaseConfig } from '../services/supabaseClient';
import { ROUTES, ICONS } from '../constants';

const Login: React.FC = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Config Modal State
  const [showConfig, setShowConfig] = useState(false);
  const [apiKey, setApiKey] = useState('');

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { user, error: authError } = await authService.login(email, password);
      if (authError) {
        setError(authError);
      } else if (user) {
        navigate(ROUTES.DASHBOARD);
      }
    } catch (err) {
      setError('Erro ao conectar ao servidor');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveConfig = () => {
    if (apiKey.length < 20) {
      alert("Chave inválida. Certifique-se de copiar a chave 'anon' / 'public' completa.");
      return;
    }
    configureSupabase(apiKey);
  };

  return (
    <div className="flex flex-col h-screen w-screen bg-[#1A1A1A] p-6 justify-center">
      <div className="w-full max-w-sm mx-auto space-y-8">

        <div className="text-center space-y-2">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-[#FF7A00]/10 text-[#FF7A00] mb-4">
             <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
               <path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6" />
             </svg>
          </div>
          <h1 className="text-3xl font-bold text-white tracking-tight">CLA VENDAS</h1>

          <div className="flex flex-col items-center justify-center gap-2 mt-2">
             <div className="flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full ${isSupabaseConfigured ? 'bg-green-500' : 'bg-orange-500'}`}></div>
                <p className="text-xs text-gray-500 uppercase tracking-widest">
                  {isSupabaseConfigured ? 'Online (Supabase)' : 'Modo Demonstração'}
                </p>
             </div>

             {!isSupabaseConfigured && (
               <button 
                 onClick={() => setShowConfig(true)}
                 className="text-xs text-[#FF7A00] underline mt-1"
               >
                 Configurar Chave API
               </button>
             )}

             {isSupabaseConfigured && (
               <div className="flex flex-col items-center">
                 <button 
                   onClick={() => navigate(ROUTES.SETUP)}
                   className="text-xs text-[#FF7A00] underline mt-1 font-bold"
                 >
                   Criar Tabelas e Usuário
                 </button>
                 <button 
                   onClick={clearSupabaseConfig}
                   className="text-[10px] text-gray-600 hover:text-red-400 mt-2"
                 >
                   Desconectar / Limpar Config
                 </button>
               </div>
             )}
          </div>
        </div>

        <form onSubmit={handleLogin} className="space-y-6">
          <div className="space-y-4">
            <Input 
              type="email" 
              placeholder="seu@email.com" 
              label="E-mail"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
            <Input 
              type="password" 
              placeholder="••••••" 
              label="Senha"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          {error && (
            <div className="p-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-sm text-center">
              {error}
            </div>
          )}

          <Button type="submit" fullWidth isLoading={loading}>
            Entrar
          </Button>

          <div className="text-center">
            <button type="button" className="text-sm text-gray-500 hover:text-[#FF7A00] transition-colors">
              Esqueci minha senha
            </button>
          </div>
        </form>

        <div className="pt-8 text-center space-y-2">
          {!isSupabaseConfigured && (
              <div className="text-xs text-gray-600 border border-dashed border-gray-700 p-3 rounded-lg">
                <p className="font-bold mb-1">Credenciais Demo:</p>
                <p>admin@cla.com / 123456</p>
              </div>
          )}
          {isSupabaseConfigured && (
              <p className="text-xs text-gray-600">
                  Conectado a: taubsuolhawpdibrhtkb.supabase.co
              </p>
          )}
        </div>
      </div>

      {/* Configuration Modal */}
      <Modal isOpen={showConfig} onClose={() => setShowConfig(false)} title="Configurar Conexão">
         <div className="space-y-4">
            <p className="text-sm text-gray-400">
               Insira a chave pública (anon key) do seu projeto Supabase para conectar o aplicativo ao banco de dados real.
            </p>
            <div className="bg-black/30 p-2 rounded text-xs font-mono text-gray-500 break-all">
               URL: https://taubsuolhawpdibrhtkb.supabase.co
            </div>
            <Input 
               label="Chave API (Anon Public Key)"
               placeholder="eyJh..."
               value={apiKey}
               onChange={(e) => setApiKey(e.target.value)}
            />
            <Button fullWidth onClick={handleSaveConfig}>
               Salvar e Conectar
            </Button>
            <div className="text-center">
               <button onClick={() => setShowConfig(false)} className="text-sm text-gray-500">
                  Cancelar
               </button>
            </div>
         </div>
      </Modal>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Card } from '../components/ui';

const Setup: React.FC = () => {
  const navigate = useNavigate();
  const [copied, setCopied] = useState(false);

  // This SQL script creates the necessary tables and the default admin user.
  // We use "if not exists" to avoid errors if run multiple times.
  // We enable RLS but add a permissive policy for simplicity in this specific starter app.
  const setupSQL = `
-- 1. Habilitar extensão para UUIDs
create extension if not exists "uuid-ossp";

-- 2. Tabela de Usuários (Login do App)
create table if not exists users (
  id uuid default uuid_generate_v4() primary key,
  email text unique not null,
  senha text not null,
  nome text,
  perfil text default 'vendedor',
  ativo boolean default true,
  comissao_porcentagem numeric default 0,
  created_at timestamptz default now()
);

-- 3. Tabela de Clientes
create table if not exists clients (
  id uuid default uuid_generate_v4() primary key,
  nome text not null,
  telefone text,
  endereco text,
  bairro text,
  cidade text,
  observacoes text,
  vendedor_id text, -- ID do usuário (string/uuid)
  created_at timestamptz default now()
);

-- 4. Tabela de Produtos
create table if not exists products (
  id uuid default uuid_generate_v4() primary key,
  nome text not null,
  categoria text,
  valor_avista numeric default 0,
  valor_parcelado numeric default 0,
  ativo boolean default true,
  created_at timestamptz default now()
);

-- 5. Tabela de Vendas
create table if not exists sales (
  id uuid default uuid_generate_v4() primary key,
  cliente_id uuid references clients(id),
  vendedor_id text,
  valor_total numeric default 0,
  qtd_parcelas integer default 1,
  data_venda timestamptz default now(),
  status text default 'ABERTA', -- ABERTA, PARCIAL, QUITADA
  created_at timestamptz default now()
);

-- 6. Tabela de Parcelas
create table if not exists installments (
  id uuid default uuid_generate_v4() primary key,
  venda_id uuid references sales(id) on delete cascade,
  numero_parcela integer,
  valor numeric default 0,
  data_vencimento timestamptz,
  pago boolean default false,
  data_pagamento timestamptz,
  created_at timestamptz default now()
);

-- 7. Tabela de Fluxo de Caixa (Despesas e Entradas Extras)
create table if not exists cash_flow (
  id uuid default uuid_generate_v4() primary key,
  data timestamptz default now(),
  tipo text, -- ENTRADA ou SAIDA
  valor numeric default 0,
  descricao text,
  vendedor_id text,
  created_at timestamptz default now()
);

-- 8. Configurar Políticas de Segurança (Permissivo para este App)
-- ATENÇÃO: Em produção real, você deve restringir isso.
-- Aqui liberamos acesso total para facilitar o uso imediato com a Anon Key.

alter table users enable row level security;
create policy "Acesso Total Users" on users for all using (true) with check (true);

alter table clients enable row level security;
create policy "Acesso Total Clients" on clients for all using (true) with check (true);

alter table products enable row level security;
create policy "Acesso Total Products" on products for all using (true) with check (true);

alter table sales enable row level security;
create policy "Acesso Total Sales" on sales for all using (true) with check (true);

alter table installments enable row level security;
create policy "Acesso Total Installments" on installments for all using (true) with check (true);

alter table cash_flow enable row level security;
create policy "Acesso Total CashFlow" on cash_flow for all using (true) with check (true);

-- 9. CRIAR USUÁRIO ADMIN PADRÃO
insert into users (email, senha, nome, perfil, ativo, comissao_porcentagem)
values ('admin@cla.com', '123456', 'Administrador', 'admin', true, 0)
on conflict (email) do nothing;
`;

  const copyToClipboard = () => {
    navigator.clipboard.writeText(setupSQL);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="min-h-screen bg-[#1A1A1A] p-6 flex flex-col items-center">
      <div className="w-full max-w-2xl space-y-6">

        {/* Header */}
        <div className="flex items-center gap-4">
          <button 
            onClick={() => navigate(ROUTES.LOGIN)} 
            className="p-2 bg-[#2E2E2E] rounded-full text-white hover:bg-[#333]"
          >
            {ICONS.Left}
          </button>
          <h1 className="text-2xl font-bold text-white">Configuração do Banco de Dados</h1>
        </div>

        <Card className="bg-[#2E2E2E] border-l-4 border-[#FF7A00]">
          <h3 className="text-white font-bold text-lg mb-2">Instruções</h3>
          <ol className="list-decimal list-inside text-gray-300 space-y-2 text-sm">
            <li>Copie o código SQL abaixo.</li>
            <li>Acesse o painel do seu projeto no <a href="https://supabase.com/dashboard" target="_blank" className="text-[#FF7A00] underline">Supabase Dashboard</a>.</li>
            <li>No menu lateral esquerdo, clique em <strong>SQL Editor</strong>.</li>
            <li>Clique em <strong>New Query</strong>.</li>
            <li>Cole o código e clique em <strong>Run</strong> (botão verde).</li>
          </ol>
          <p className="mt-4 text-green-400 text-sm font-bold">
            Isso criará o usuário: <span className="text-white">admin@cla.com</span> / senha: <span className="text-white">123456</span>
          </p>
        </Card>

        <div className="relative">
          <div className="flex justify-between items-center mb-2">
            <label className="text-gray-400 text-sm font-mono">Script SQL</label>
            <button 
              onClick={copyToClipboard}
              className={`text-xs px-3 py-1.5 rounded-lg font-medium transition-colors ${copied ? 'bg-green-500 text-white' : 'bg-[#FF7A00] text-white hover:bg-[#E66E00]'}`}
            >
              {copied ? 'Copiado!' : 'Copiar Código'}
            </button>
          </div>
          <textarea 
            readOnly
            value={setupSQL}
            className="w-full h-96 bg-[#111] text-green-400 font-mono text-xs p-4 rounded-xl border border-white/10 focus:outline-none resize-none"
          />
        </div>

        <Button fullWidth onClick={() => navigate(ROUTES.LOGIN)}>
          Voltar para Login
        </Button>

      </div>
    </div>
  );
};

export default Setup;

