    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
  };

  return (
    <div className="p-5 space-y-6 animate-fade-in">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <p className="text-gray-400 text-sm">Bem-vindo,</p>
          <h1 className="text-2xl font-bold text-white">{user?.nome || 'Vendedor'}</h1>
        </div>
        <div className="flex items-center gap-3">
            <button 
              onClick={handleLogout}
              className="p-2 rounded-full bg-[#2E2E2E] text-red-400 hover:bg-red-500/20 hover:text-red-500 transition-colors"
              title="Sair do App"
            >
              {ICONS.Logout}
            </button>
            <div className="w-10 h-10 rounded-full bg-[#333] flex items-center justify-center text-[#FF7A00] font-bold border border-white/5">
              {user?.nome?.charAt(0) || 'U'}
            </div>
        </div>
      </div>

      {/* Main Stats */}
      <div className="grid grid-cols-2 gap-4">
        <Card className="col-span-2 bg-gradient-to-br from-[#FF7A00] to-[#CC6200] border-none">
          <div className="flex items-center gap-3 mb-2 opacity-90">
            <div className="p-2 bg-white/20 rounded-lg text-white">
              {ICONS.Trending}
            </div>
            <span className="text-white font-medium">Total Vendido</span>
          </div>
          <h2 className="text-3xl font-bold text-white">{formatCurrency(stats.totalVendido)}</h2>
          <p className="text-white/70 text-sm mt-1">Geral</p>
        </Card>

        <Card>
          <p className="text-gray-400 text-xs mb-1">Recebido</p>
          <p className="text-lg font-bold text-emerald-500">{formatCurrency(stats.totalRecebido)}</p>
        </Card>
        <Card>
          <p className="text-gray-400 text-xs mb-1">A Receber</p>
          <p className="text-lg font-bold text-[#FF7A00]">{formatCurrency(stats.totalReceber)}</p>
        </Card>
      </div>

      {/* Admin Shortcuts */}
      {user?.perfil === 'admin' && (
        <>
          <h3 className="text-lg font-bold text-white pt-2">Administração</h3>
          <div className="grid grid-cols-4 gap-3">
            <button 
              onClick={() => navigate(ROUTES.REPORTS)}
              className="bg-[#2E2E2E] p-2 rounded-xl flex flex-col items-center gap-1 border border-white/5 active:scale-95 transition-transform"
            >
              <div className="text-[#FF7A00] scale-90">{ICONS.Reports}</div>
              <span className="text-white text-[10px] font-medium">Relatórios</span>
            </button>
            <button 
              onClick={() => navigate(ROUTES.PRODUCTS)}
              className="bg-[#2E2E2E] p-2 rounded-xl flex flex-col items-center gap-1 border border-white/5 active:scale-95 transition-transform"
            >
              <div className="text-[#FF7A00] scale-90">{ICONS.Product}</div>
              <span className="text-white text-[10px] font-medium">Produtos</span>
            </button>
            <button 
              onClick={() => navigate(ROUTES.SELLERS)}
              className="bg-[#2E2E2E] p-2 rounded-xl flex flex-col items-center gap-1 border border-white/5 active:scale-95 transition-transform"
            >
              <div className="text-[#FF7A00] scale-90">{ICONS.Sellers}</div>
              <span className="text-white text-[10px] font-medium">Equipe</span>
            </button>
            <button 
              onClick={() => navigate(ROUTES.SETTINGS)}
              className="bg-[#2E2E2E] p-2 rounded-xl flex flex-col items-center gap-1 border border-white/5 active:scale-95 transition-transform"
            >
              <div className="text-[#FF7A00] scale-90">{ICONS.Settings}</div>
              <span className="text-white text-[10px] font-medium">Dados</span>
            </button>
          </div>
        </>
      )}

      {/* Charts Section */}
      <h3 className="text-lg font-bold text-white mt-4">Visão Geral</h3>
      <div className="h-64 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={pieData}
              cx="50%"
              cy="50%"
              innerRadius={60}
              outerRadius={80}
              paddingAngle={5}
              dataKey="value"
              stroke="none"
            >
              {pieData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} />
              ))}
            </Pie>
            <Tooltip 
               contentStyle={{ backgroundColor: '#2E2E2E', border: 'none', borderRadius: '8px' }}
               itemStyle={{ color: '#fff' }}
               formatter={(value: number) => formatCurrency(value)}
            />
          </PieChart>
        </ResponsiveContainer>
      </div>

      {/* Legend */}
      <div className="flex justify-center gap-4 text-sm pb-10">
        {pieData.map((item, idx) => (
          <div key={idx} className="flex items-center gap-2">
            <div className="w-3 h-3 rounded-full" style={{ backgroundColor: item.color }} />
            <span className="text-gray-400">{item.name}</span>
          </div>
        ))}
      </div>

      <div className="h-10"></div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Card, Button, Modal } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';

const Settings: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [successMsg, setSuccessMsg] = useState('');
  const [errorMsg, setErrorMsg] = useState('');

  // File upload ref
  const fileInputRef = React.useRef<HTMLInputElement>(null);

  const handleDownloadBackup = async () => {
    setLoading(true);
    setSuccessMsg('');
    setErrorMsg('');
    try {
      const jsonString = await dataService.exportBackupData();
      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);

      const a = document.createElement('a');
      a.href = url;
      a.download = `backup_cla_vendas_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      setSuccessMsg('Backup baixado com sucesso!');
    } catch (e) {
      console.error(e);
      setErrorMsg('Erro ao gerar backup.');
    } finally {
      setLoading(false);
    }
  };

  const handleRestoreClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setSuccessMsg('');
    setErrorMsg('');

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const content = event.target?.result as string;
        await dataService.importBackupData(content);
        setSuccessMsg('Dados restaurados com sucesso! O app será recarregado.');
        setTimeout(() => {
           window.location.reload();
        }, 2000);
      } catch (err) {
        console.error(err);
        setErrorMsg('Erro ao restaurar arquivo. Verifique se é um backup válido.');
        setLoading(false);
      }
    };
    reader.readAsText(file);

    // Reset input
    e.target.value = ''; 
  };

  const handleLogout = async () => {
    await authService.logout();
    navigate(ROUTES.LOGIN);
  };

  return (
    <div className="flex flex-col h-screen bg-[#1A1A1A]">
      <div className="bg-[#2E2E2E] p-4 flex items-center gap-4 border-b border-white/5 sticky top-0 z-10">
        <button onClick={() => navigate(-1)} className="text-white">
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold text-white">Configurações & Dados</h1>
      </div>

      <div className="p-4 space-y-6">
        <div className="bg-blue-500/10 border border-blue-500/20 p-4 rounded-xl text-sm text-blue-200">
           <p className="flex items-center gap-2 mb-2 font-bold text-blue-400">
              <span className="p-1 bg-blue-500/20 rounded-lg">{ICONS.Alert}</span>
              Importante
           </p>
           Os dados deste aplicativo ficam salvos no armazenamento do seu navegador. 
           Recomendamos fazer o download do backup periodicamente para não perder suas informações.
        </div>

        <Card className="space-y-4">
           <h3 className="text-white font-bold text-lg flex items-center gap-2">
              {ICONS.Database} Gerenciamento de Dados
           </h3>
           <p className="text-gray-400 text-sm">
             Exporte seus dados para um arquivo seguro ou restaure de um arquivo salvo anteriormente.
           </p>

           <div className="grid grid-cols-1 gap-3 pt-2">
              <Button 
                onClick={handleDownloadBackup} 
                disabled={loading}
                icon={ICONS.Download}
                variant="outline"
                fullWidth
              >
                 Baixar Backup (Exportar)
              </Button>

              <Button 
                onClick={handleRestoreClick} 
                disabled={loading}
                icon={ICONS.Upload}
                variant="secondary"
                fullWidth
              >
                 Carregar Backup (Importar)
              </Button>
              {/* Hidden Input */}
              <input 
                 type="file" 
                 accept=".json" 
                 ref={fileInputRef}
                 className="hidden"
                 onChange={handleFileChange}
              />
           </div>
        </Card>

        {/* Account Actions */}
        <Card className="space-y-4 border border-red-500/10">
           <h3 className="text-white font-bold text-lg flex items-center gap-2">
              {ICONS.Settings} Conta
           </h3>
           <Button 
             onClick={handleLogout} 
             variant="danger"
             icon={ICONS.Logout}
             fullWidth
           >
              Sair do Aplicativo
           </Button>
        </Card>

        {/* Feedback Messages */}
        {loading && (
           <div className="text-center py-4 text-gray-400 animate-pulse">
              Processando dados...
           </div>
        )}

        {successMsg && (
           <div className="p-4 bg-green-500/10 border border-green-500/20 text-green-400 rounded-xl text-center">
              {successMsg}
           </div>
        )}

        {errorMsg && (
           <div className="p-4 bg-red-500/10 border border-red-500/20 text-red-400 rounded-xl text-center">
              {errorMsg}
           </div>
        )}
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Input, Card, Modal } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';
import { Client } from '../types';

const Clients: React.FC = () => {
  const navigate = useNavigate();
  const session = authService.getSession();
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [clients, setClients] = useState<Client[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(false);

  // Modals
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);

  // Form State
  const [clientForm, setClientForm] = useState<Partial<Client>>({
    nome: '', telefone: '', endereco: '', bairro: '', cidade: ''
  });
  const [editingId, setEditingId] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [importStatus, setImportStatus] = useState('');

  const loadClients = async () => {
    const data = await dataService.getClients();
    setClients(data);
  };

  useEffect(() => {
    loadClients();
  }, []);

  // --- CRUD Handlers ---

  const handleOpenCreate = () => {
    setEditingId(null);
    setClientForm({ nome: '', telefone: '', endereco: '', bairro: '', cidade: '' });
    setIsModalOpen(true);
  };

  const handleOpenEdit = (client: Client, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingId(client.id);
    setClientForm({ ...client });
    setIsModalOpen(true);
  };

  const handleOpenDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setDeletingId(id);
    setIsDeleteModalOpen(true);
  };

  const handleSaveClient = async () => {
    if (!clientForm.nome || !clientForm.telefone) return;
    setLoading(true);
    try {
      if (editingId) {
        await dataService.updateClient(editingId, clientForm);
      } else {
        await dataService.createClient({
            ...clientForm,
            vendedor_id: session?.id || 'anon'
        } as Omit<Client, 'id'>);
      }
      await loadClients();
      setIsModalOpen(false);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteClient = async () => {
    if (!deletingId) return;
    setLoading(true);
    try {
      await dataService.deleteClient(deletingId);
      await loadClients();
      setIsDeleteModalOpen(false);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  // --- CSV IMPORT Handlers ---

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setImportStatus('Lendo arquivo...');

    const reader = new FileReader();
    reader.onload = async (event) => {
        try {
            const text = event.target?.result as string;
            await processCSV(text);
        } catch (err) {
            console.error(err);
            setImportStatus('Erro ao processar arquivo.');
        } finally {
            setLoading(false);
            // Clear input so same file can be selected again if needed
            if (fileInputRef.current) fileInputRef.current.value = '';
        }
    };
    reader.readAsText(file);
  };

  const processCSV = async (csvText: string) => {
      const lines = csvText.split('\n');
      if (lines.length < 2) {
          setImportStatus('Arquivo vazio ou sem cabeçalho.');
          return;
      }

      // Normalize headers to find columns
      const headers = lines[0].split(',').map(h => h.trim().toLowerCase().replace(/"/g, ''));

      const nomeIdx = headers.findIndex(h => h.includes('nome'));
      const telIdx = headers.findIndex(h => h.includes('telefone') || h.includes('celular') || h.includes('contato'));
      const endIdx = headers.findIndex(h => h.includes('endereco') || h.includes('endereço'));
      const bairroIdx = headers.findIndex(h => h.includes('bairro'));
      const cidIdx = headers.findIndex(h => h.includes('cidade'));

      if (nomeIdx === -1) {
          setImportStatus('Erro: Coluna "Nome" não encontrada no cabeçalho.');
          return;
      }

      let count = 0;
      setImportStatus('Importando clientes...');

      // Process rows
      for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;

          // Simple split by comma (handling basic CSV)
          // For more complex CSVs with commas inside quotes, a library would be better, but this suffices for basic lists
          const cols = line.split(',').map(c => c.trim().replace(/^"|"$/g, ''));

          if (cols[nomeIdx]) {
             const newClient: any = {
                 nome: cols[nomeIdx],
                 telefone: telIdx > -1 ? cols[telIdx] : '',
                 endereco: endIdx > -1 ? cols[endIdx] : '',
                 bairro: bairroIdx > -1 ? cols[bairroIdx] : '',
                 cidade: cidIdx > -1 ? cols[cidIdx] : '',
                 vendedor_id: session?.id || 'anon'
             };
             await dataService.createClient(newClient);
             count++;
          }
      }

      await loadClients();
      setImportStatus(`Sucesso! ${count} clientes importados.`);
      setTimeout(() => {
          setIsImportModalOpen(false);
          setImportStatus('');
      }, 2000);
  };

  const filteredClients = clients.filter(c => 
    c.nome.toLowerCase().includes(search.toLowerCase()) || 
    c.telefone.includes(search)
  );

  return (
    <div className="p-5 animate-fade-in space-y-4">
      <div className="flex justify-between items-center mb-2">
        <h1 className="text-2xl font-bold text-white">Clientes</h1>
        <div className="flex gap-2">
            <Button onClick={() => setIsImportModalOpen(true)} variant="secondary" className="!px-3 !py-2" title="Importar Planilha">
               {ICONS.Upload}
            </Button>
            <Button onClick={handleOpenCreate} className="!px-3 !py-2">
               {ICONS.Add}
            </Button>
        </div>
      </div>

      <div className="relative">
        <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500">
          {ICONS.Search}
        </div>
        <Input 
          placeholder="Buscar cliente..." 
          className="pl-10"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      <div className="space-y-3">
        {filteredClients.map(client => (
          <Card 
            key={client.id} 
            className="group cursor-pointer active:bg-[#353535] relative pr-10"
            onClick={() => navigate(ROUTES.CLIENT_DETAILS.replace(':id', client.id))}
          >
            <div className="flex justify-between items-start">
               <div>
                  <h3 className="text-white font-semibold">{client.nome}</h3>
                  <p className="text-gray-400 text-sm">{client.telefone}</p>
                  <p className="text-gray-500 text-xs mt-1">{client.bairro} - {client.cidade}</p>
               </div>
            </div>

            <div className="flex gap-2 items-center mt-3 border-t border-white/5 pt-2">
              <button 
                onClick={(e) => {
                    e.stopPropagation();
                    navigate(ROUTES.NEW_SALE, { state: { client } });
                }}
                className="flex-1 py-2 bg-[#FF7A00]/10 text-[#FF7A00] rounded-lg text-sm font-medium hover:bg-[#FF7A00]/20 z-10 flex justify-center items-center gap-2"
              >
                {ICONS.Sales} Nova Venda
              </button>

              <button 
                onClick={(e) => {
                    e.stopPropagation();
                    window.open(`https://wa.me/55${client.telefone.replace(/\D/g, '')}`, '_blank');
                }}
                className="p-2 bg-green-500/10 text-green-500 rounded-lg hover:bg-green-500/20 z-10"
                title="WhatsApp"
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
              </button>

              <button 
                onClick={(e) => handleOpenEdit(client, e)}
                className="p-2 bg-gray-500/10 text-gray-400 rounded-lg hover:bg-white/10 z-10"
              >
                {ICONS.Edit}
              </button>

              <button 
                onClick={(e) => handleOpenDelete(client.id, e)}
                className="p-2 bg-red-500/10 text-red-400 rounded-lg hover:bg-red-500/20 z-10"
              >
                {ICONS.Trash}
              </button>
            </div>

            <div className="absolute right-4 top-4 text-gray-500">
               {ICONS.Right}
            </div>
          </Card>
        ))}
      </div>

      {/* Create/Edit Modal */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title={editingId ? "Editar Cliente" : "Novo Cliente"}
      >
        <div className="space-y-4">
          <Input 
            label="Nome Completo" 
            value={clientForm.nome} 
            onChange={e => setClientForm({...clientForm, nome: e.target.value})}
          />
          <Input 
            label="Telefone (WhatsApp)" 
            type="tel"
            value={clientForm.telefone} 
            onChange={e => setClientForm({...clientForm, telefone: e.target.value})}
          />
          <Input 
            label="Endereço" 
            value={clientForm.endereco} 
            onChange={e => setClientForm({...clientForm, endereco: e.target.value})}
          />
          <div className="grid grid-cols-2 gap-4">
            <Input 
                label="Bairro" 
                value={clientForm.bairro} 
                onChange={e => setClientForm({...clientForm, bairro: e.target.value})}
            />
            <Input 
                label="Cidade" 
                value={clientForm.cidade} 
                onChange={e => setClientForm({...clientForm, cidade: e.target.value})}
            />
          </div>
          <Button fullWidth onClick={handleSaveClient} isLoading={loading}>
            Salvar
          </Button>
        </div>
      </Modal>

      {/* Import Modal */}
      <Modal isOpen={isImportModalOpen} onClose={() => setIsImportModalOpen(false)} title="Importar Clientes (CSV)">
         <div className="space-y-4">
             <div className="bg-blue-500/10 p-4 rounded-xl text-sm text-blue-300 border border-blue-500/20">
                <p className="font-bold mb-2">Instruções:</p>
                <p className="mb-2">1. No Google Sheets ou Excel, salve sua planilha como <strong>.csv (Valores separados por vírgula)</strong>.</p>
                <p className="mb-2">2. A primeira linha deve conter os cabeçalhos. O sistema tentará identificar automaticamente colunas com nomes:</p>
                <ul className="list-disc list-inside text-xs text-gray-400">
                    <li>Nome (Obrigatório)</li>
                    <li>Telefone</li>
                    <li>Endereço</li>
                    <li>Bairro</li>
                    <li>Cidade</li>
                </ul>
             </div>

             <div className="py-4">
                 <input 
                    type="file" 
                    accept=".csv"
                    ref={fileInputRef}
                    onChange={handleFileChange}
                    className="hidden" 
                 />
                 <Button fullWidth onClick={() => fileInputRef.current?.click()} isLoading={loading}>
                    Selecionar Arquivo CSV
                 </Button>
             </div>

             {importStatus && (
                 <div className={`text-center text-sm p-2 rounded ${importStatus.includes('Erro') ? 'text-red-400 bg-red-500/10' : 'text-green-400 bg-green-500/10'}`}>
                     {importStatus}
                 </div>
             )}
         </div>
      </Modal>

      {/* Delete Confirmation Modal */}
      <Modal isOpen={isDeleteModalOpen} onClose={() => setIsDeleteModalOpen(false)} title="Excluir Cliente">
         <div className="text-center space-y-4">
