        <div className="space-y-6">
          {/* Caixa Detalhado Summary */}
          <div className="grid grid-cols-2 gap-3">
             <div className="bg-[#2E2E2E] p-4 rounded-2xl border border-white/5 col-span-2">
                <p className="text-gray-400 text-sm">Saldo em Caixa</p>
                <h2 className={`text-3xl font-bold ${saldo >= 0 ? 'text-white' : 'text-red-400'}`}>
                  R$ {saldo.toFixed(2)}
                </h2>
             </div>
             <div className="bg-[#2E2E2E] p-3 rounded-xl border border-white/5">
                <div className="flex items-center gap-2 mb-1">
                   <div className="w-2 h-2 rounded-full bg-green-500"></div>
                   <p className="text-xs text-gray-400">Entradas</p>
                </div>
                <p className="text-green-500 font-bold">R$ {totalEntradas.toFixed(2)}</p>
             </div>
             <div className="bg-[#2E2E2E] p-3 rounded-xl border border-white/5">
                <div className="flex items-center gap-2 mb-1">
                   <div className="w-2 h-2 rounded-full bg-red-500"></div>
                   <p className="text-xs text-gray-400">Saídas</p>
                </div>
                <p className="text-red-400 font-bold">R$ {totalSaidas.toFixed(2)}</p>
             </div>
          </div>

          <div className="flex justify-between items-center">
             <h3 className="text-white font-bold">Movimentações</h3>
             <button 
                onClick={() => setShowExpenseModal(true)}
                className="text-xs bg-red-500/10 text-red-400 px-3 py-2 rounded-lg font-medium hover:bg-red-500/20 flex items-center gap-1"
             >
                {ICONS.Add} Despesa
             </button>
          </div>

          <div className="space-y-3">
            {cashFlow.map(entry => (
               <div key={entry.id} className="flex justify-between items-center p-3 bg-[#2E2E2E] rounded-xl border border-white/5 group">
                  <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${entry.tipo === 'ENTRADA' ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'}`}>
                      {entry.tipo === 'ENTRADA' ? ICONS.Trending : ICONS.Alert}
                    </div>
                    <div>
                      <p className="text-white font-medium">{entry.descricao}</p>
                      <p className="text-xs text-gray-500">{format(new Date(entry.data), 'dd/MM HH:mm')}</p>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-1">
                    <span className={`font-bold ${entry.tipo === 'ENTRADA' ? 'text-green-400' : 'text-red-400'}`}>
                        {entry.tipo === 'ENTRADA' ? '+' : '-'} R$ {entry.valor.toFixed(2)}
                    </span>
                    <button 
                        onClick={() => setDeleteCashId(entry.id)}
                        className="text-xs text-red-500/50 hover:text-red-500"
                    >
                        {ICONS.Trash}
                    </button>
                  </div>
               </div>
            ))}
            {cashFlow.length === 0 && (
              <p className="text-center text-gray-500 py-4 text-sm">Nenhuma movimentação registrada.</p>
            )}
          </div>
        </div>
      )}

      {/* Confirmation Modal */}
      <Modal isOpen={!!confirmItem} onClose={() => setConfirmItem(null)} title="Confirmar Recebimento">
        <div className="space-y-6 text-center">
           <div className="w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center text-green-500 mx-auto">
             {ICONS.Check}
           </div>
           <div>
             {confirmItem && (
               <>
                 <p className="text-gray-300">Receber <strong className="text-white">R$ {confirmItem.valor.toFixed(2)}</strong> de <strong className="text-white">{confirmItem.cliente_nome}</strong>?</p>
                 <p className="text-xs text-gray-500 mt-2">Parcela {confirmItem.numero_parcela} • Vencimento {format(new Date(confirmItem.data_vencimento), 'dd/MM/yyyy')}</p>
                 <p className="text-xs text-gray-600 mt-4">Esta ação lançará o valor no caixa imediatamente.</p>
               </>
             )}
           </div>
           <div className="grid grid-cols-2 gap-3">
             <Button variant="secondary" onClick={() => setConfirmItem(null)}>Cancelar</Button>
             <Button onClick={handlePay} isLoading={loading} className="bg-green-600 hover:bg-green-700 border-none shadow-green-900/20">
               Confirmar
             </Button>
           </div>
        </div>
      </Modal>

      {/* Add Expense Modal */}
      <Modal isOpen={showExpenseModal} onClose={() => setShowExpenseModal(false)} title="Nova Despesa">
         <div className="space-y-4">
            <Input 
               label="Descrição" 
               placeholder="Ex: Combustível, Almoço..."
               value={expenseForm.descricao}
