};

export default Payments;

import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Input, Card, Modal } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';
import { Client, Product, CartItem, Installment } from '../types';
import { addMonths, format } from 'date-fns';

const NewSale: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const session = authService.getSession();

  const [step, setStep] = useState<1|2|3>(1);
  const [clients, setClients] = useState<Client[]>([]);
  const [products, setProducts] = useState<Product[]>([]);

  // Sale State
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [installmentsCount, setInstallmentsCount] = useState(1);
  const [generatedInstallments, setGeneratedInstallments] = useState<Omit<Installment, 'id' | 'venda_id'>[]>([]);
  const [loading, setLoading] = useState(false);

  // New Product Modal State
  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [newProductForm, setNewProductForm] = useState({
    nome: '',
    categoria: '',
    valor_avista: '',
    valor_parcelado: ''
  });

  useEffect(() => {
    const init = async () => {
      const [c, p] = await Promise.all([dataService.getClients(), dataService.getProducts()]);
      setClients(c);
      setProducts(p);

      // Handle pre-selected client from navigation state
      const state = location.state as { client?: Client };
      if (state?.client) {
        setSelectedClient(state.client);
        setStep(2);
      }
    };
    init();
  }, [location.state]);

  // -- STEP 1: Select Client --
  const handleClientSelect = (client: Client) => {
    setSelectedClient(client);
    setStep(2);
  };

  // -- STEP 2: Products --
  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(p => p.id === product.id);
      if (existing) {
        return prev.map(p => p.id === product.id ? { ...p, quantity: p.quantity + 1 } : p);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(p => p.id !== productId));
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.valor_parcelado * item.quantity), 0);

  // -- STEP 2.5: New Product on the fly --
  const handleOpenNewProduct = () => {
      setNewProductForm({ nome: '', categoria: '', valor_avista: '', valor_parcelado: '' });
      setIsProductModalOpen(true);
  };

  const handleSaveNewProduct = async () => {
      if (!newProductForm.nome || !newProductForm.valor_parcelado) return;
      setLoading(true);
      try {
          await dataService.createProduct({
              nome: newProductForm.nome,
              categoria: newProductForm.categoria || 'Geral',
              valor_avista: Number(newProductForm.valor_avista) || 0,
              valor_parcelado: Number(newProductForm.valor_parcelado),
              ativo: true
          });

          // Refresh list
          const updatedProducts = await dataService.getProducts();
          setProducts(updatedProducts);

          setIsProductModalOpen(false);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  // -- STEP 3: Installments --
  const generateInstallments = () => {
    const list: Omit<Installment, 'id' | 'venda_id'>[] = [];
    const baseValue = Math.floor((cartTotal / installmentsCount) * 100) / 100;
    const remainder = Math.round((cartTotal - (baseValue * installmentsCount)) * 100) / 100;

    const today = new Date();

    for (let i = 0; i < installmentsCount; i++) {
      let val = baseValue;
      if (i === installmentsCount - 1) val += remainder;

      list.push({
        numero_parcela: i + 1,
        valor: val,
        data_vencimento: addMonths(today, i + 1).toISOString(), // First installment next month
        pago: false
      });
    }
    setGeneratedInstallments(list);
  };

  useEffect(() => {
    if (step === 3) generateInstallments();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [installmentsCount, step]);

  const handleFinishSale = async () => {
    if (!selectedClient || cart.length === 0 || !session) return;
    setLoading(true);
    try {
      await dataService.createSale({
        cliente_id: selectedClient.id,
        vendedor_id: session.id,
        valor_total: cartTotal,
        qtd_parcelas: installmentsCount,
        data_venda: new Date().toISOString()
      }, generatedInstallments);

      navigate(ROUTES.SALES);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  // --- RENDER HELPERS ---

  return (
    <div className="flex flex-col h-screen bg-[#1A1A1A]">
      {/* Header */}
      <div className="bg-[#2E2E2E] p-4 flex items-center gap-4 border-b border-white/5">
        <button onClick={() => step > 1 ? setStep(prev => prev - 1 as any) : navigate(-1)} className="text-white">
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold text-white">
          {step === 1 ? 'Selecionar Cliente' : step === 2 ? 'Adicionar Produtos' : 'Pagamento'}
        </h1>
        <div className="ml-auto text-sm text-[#FF7A00] font-bold">Passo {step}/3</div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
        {step === 1 && (
          <div className="space-y-3">
             <Input placeholder="Buscar cliente..." className="mb-4" />
             {clients.map(c => (
               <Card key={c.id} onClick={() => handleClientSelect(c)} className="flex items-center justify-between">
                 <div>
                   <p className="font-bold text-white">{c.nome}</p>
                   <p className="text-gray-500 text-sm">{c.bairro}</p>
                 </div>
                 <div className="text-[#FF7A00]">{ICONS.Right}</div>
               </Card>
             ))}
          </div>
        )}

        {step === 2 && (
          <div className="space-y-6">
            <div>
              <div className="flex justify-between items-center mb-3">
                  <h3 className="text-gray-400 text-sm">Produtos Disponíveis</h3>
                  <button 
                    onClick={handleOpenNewProduct}
                    className="text-xs bg-[#FF7A00]/10 text-[#FF7A00] px-3 py-1.5 rounded-lg border border-[#FF7A00]/20 font-bold flex items-center gap-1"
                  >
                    {ICONS.Add} Cadastrar Novo
                  </button>
              </div>

              <div className="space-y-2">
                {products.length === 0 && (
                    <p className="text-gray-500 text-center py-4 text-sm">Nenhum produto cadastrado.</p>
                )}
                {products.map(p => (
                  <div key={p.id} className="bg-[#2E2E2E] p-3 rounded-xl flex justify-between items-center border border-white/5">
                    <div>
                      <p className="text-white font-medium">{p.nome}</p>
                      <p className="text-[#FF7A00] font-bold">R$ {p.valor_parcelado.toFixed(2)}</p>
                    </div>
                    <Button variant="secondary" onClick={() => addToCart(p)} className="!p-2">
                      {ICONS.Add}
                    </Button>
                  </div>
                ))}
              </div>
            </div>

            {cart.length > 0 && (
              <div className="border-t border-white/10 pt-4 pb-20">
                <h3 className="text-white font-bold mb-3">Carrinho</h3>
                {cart.map(item => (
                  <div key={item.id} className="flex justify-between items-center mb-2">
                    <span className="text-gray-300 text-sm">{item.quantity}x {item.nome}</span>
                    <div className="flex items-center gap-3">
                      <span className="text-white">R$ {(item.valor_parcelado * item.quantity).toFixed(2)}</span>
                      <button onClick={() => removeFromCart(item.id)} className="text-red-400">
                        {ICONS.Close}
                      </button>
                    </div>
                  </div>
                ))}
                <div className="mt-4 flex justify-between items-center text-xl font-bold text-[#FF7A00]">
                  <span>Total</span>
                  <span>R$ {cartTotal.toFixed(2)}</span>
                </div>
              </div>
            )}
          </div>
        )}

        {step === 3 && (
           <div className="space-y-6">
             <Card className="text-center py-6">
               <p className="text-gray-400">Valor Total</p>
               <h2 className="text-3xl font-bold text-[#FF7A00]">R$ {cartTotal.toFixed(2)}</h2>
               <p className="text-sm text-gray-500 mt-1">{selectedClient?.nome}</p>
             </Card>

             <div className="space-y-2">
               <label className="text-gray-300 font-medium">Número de Parcelas</label>
               <div className="flex gap-2 overflow-x-auto pb-2">
                 {[1,2,3,4,5,6,10,12].map(num => (
                   <button 
                    key={num}
                    onClick={() => setInstallmentsCount(num)}
                    className={`min-w-[50px] h-10 rounded-lg font-bold transition-all ${installmentsCount === num ? 'bg-[#FF7A00] text-white' : 'bg-[#333] text-gray-400'}`}
                   >
                     {num}x
                   </button>
                 ))}
               </div>
             </div>

             <div className="space-y-2">
               <h3 className="text-white font-bold">Resumo das Parcelas</h3>
               {generatedInstallments.map((inst, idx) => (
                 <div key={idx} className="flex justify-between p-3 bg-[#2E2E2E] rounded-lg border border-white/5">
                   <span className="text-gray-400 text-sm">Parc. {inst.numero_parcela}/{installmentsCount}</span>
                   <span className="text-gray-400 text-sm">{format(new Date(inst.data_vencimento), 'dd/MM/yyyy')}</span>
                   <span className="text-white font-bold">R$ {inst.valor.toFixed(2)}</span>
                 </div>
               ))}
             </div>
           </div>
        )}
      </div>

      <div className="p-4 bg-[#2E2E2E] border-t border-white/5 sticky bottom-0">
        {step === 2 && (
          <Button 
            fullWidth 
            onClick={() => setStep(3)} 
            disabled={cart.length === 0}
          >
            Continuar
          </Button>
        )}
        {step === 3 && (
          <Button fullWidth onClick={handleFinishSale} isLoading={loading}>
            Finalizar Venda
          </Button>
        )}
      </div>

      {/* New Product Modal */}
      <Modal isOpen={isProductModalOpen} onClose={() => setIsProductModalOpen(false)} title="Novo Produto Rápido">
         <div className="space-y-4">
            <Input 
                label="Nome do Produto"
                value={newProductForm.nome}
                onChange={(e) => setNewProductForm({...newProductForm, nome: e.target.value})}
            />
            <Input 
                label="Categoria (Opcional)"
                value={newProductForm.categoria}
                onChange={(e) => setNewProductForm({...newProductForm, categoria: e.target.value})}
            />
            <div className="grid grid-cols-2 gap-4">
                <Input 
                    label="Valor à Vista"
                    type="number"
                    value={newProductForm.valor_avista}
                    onChange={(e) => setNewProductForm({...newProductForm, valor_avista: e.target.value})}
                />
                <Input 
                    label="Valor Parcelado *"
                    type="number"
                    value={newProductForm.valor_parcelado}
                    onChange={(e) => setNewProductForm({...newProductForm, valor_parcelado: e.target.value})}
                />
            </div>
            <Button fullWidth onClick={handleSaveNewProduct} isLoading={loading}>
                Cadastrar e Adicionar
            </Button>
         </div>
      </Modal>

    </div>
  );
};

export default NewSale;

import React, { useEffect, useState } from 'react';
import { ICONS, COLORS } from '../constants';
import { Card, Badge, Modal, Button, Input } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';
import { Installment, CashEntry } from '../types';
import { format, isToday, isPast, addDays, subDays, startOfDay, endOfDay, startOfWeek, endOfWeek, startOfMonth, endOfMonth, isWithinInterval } from 'date-fns';
import { ptBR } from 'date-fns/locale';

const Payments: React.FC = () => {
  const session = authService.getSession();
  const [view, setView] = useState<'due' | 'cash'>('due');

  // Due List (Route) State
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [dueList, setDueList] = useState<(Installment & { cliente_nome: string, venda_id: string })[]>([]);
  const [overdueCount, setOverdueCount] = useState(0);
  const [showOverdue, setShowOverdue] = useState(false);

  // Cash Flow State
  const [cashFlow, setCashFlow] = useState<CashEntry[]>([]);
  const [cashPeriod, setCashPeriod] = useState<'day' | 'week' | 'month'>('day');

  const [loading, setLoading] = useState(false);

  // Modals state
  const [confirmItem, setConfirmItem] = useState<(Installment & { cliente_nome: string }) | null>(null);
  const [showExpenseModal, setShowExpenseModal] = useState(false);
  const [deleteCashId, setDeleteCashId] = useState<string | null>(null);
  const [expenseForm, setExpenseForm] = useState({ descricao: '', valor: '' });

  const loadData = async () => {
    // 1. Load Route (Daily Collection)
    const routeData = await dataService.getInstallmentsByDate(selectedDate);

    if (showOverdue) {
        const allDue = await dataService.getDueInstallments();
        setDueList(allDue);
    } else {
        setDueList(routeData.daily);
    }
    setOverdueCount(routeData.overdueCount);

    // 2. Load Cash
    const flow = await dataService.getCashFlow();
    setCashFlow(flow);
  };

  useEffect(() => {
    loadData();
  }, [selectedDate, showOverdue]);

  const handlePay = async () => {
    if (!confirmItem || !session) return;
    setLoading(true);
    try {
      await dataService.payInstallment(confirmItem.id, session.id);
      await loadData();
      setConfirmItem(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleAddExpense = async () => {
    if (!expenseForm.descricao || !expenseForm.valor || !session) return;
    setLoading(true);
    try {
      await dataService.addExpense(expenseForm.descricao, parseFloat(expenseForm.valor), session.id);
      await loadData();
      setShowExpenseModal(false);
      setExpenseForm({ descricao: '', valor: '' });
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteCashEntry = async () => {
      if (!deleteCashId) return;
      setLoading(true);
      try {
          await dataService.deleteCashEntry(deleteCashId);
          await loadData();
          setDeleteCashId(null);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  // Date Navigation Helpers
  const nextDay = () => setSelectedDate(addDays(selectedDate, 1));
  const prevDay = () => setSelectedDate(subDays(selectedDate, 1));

  // Calculations
  const totalDoDia = dueList.reduce((acc, i) => acc + i.valor, 0);

  // Cash Flow Calculations based on Period
  const getFilteredCashFlow = () => {
      const now = new Date();
      let start, end;

      switch (cashPeriod) {
          case 'day':
              start = startOfDay(now);
              end = endOfDay(now);
              break;
          case 'week':
              start = startOfWeek(now, { weekStartsOn: 1 }); // Segunda-feira
              end = endOfWeek(now, { weekStartsOn: 1 });
              break;
          case 'month':
              start = startOfMonth(now);
              end = endOfMonth(now);
              break;
      }

      return cashFlow.filter(entry => 
          isWithinInterval(new Date(entry.data), { start, end })
      );
  };

  const filteredCash = getFilteredCashFlow();
  const cashEntradas = filteredCash.filter(c => c.tipo === 'ENTRADA').reduce((acc, c) => acc + c.valor, 0);
  const cashSaidas = filteredCash.filter(c => c.tipo === 'SAIDA').reduce((acc, c) => acc + c.valor, 0);
  const cashSaldo = cashEntradas - cashSaidas;

  return (
    <div className="p-5 animate-fade-in pb-24">
      {/* Tabs */}
      <div className="flex gap-4 mb-6">
        <button 
          onClick={() => setView('due')}
          className={`flex-1 pb-2 font-bold text-lg transition-colors border-b-2 ${view === 'due' ? 'text-[#FF7A00] border-[#FF7A00]' : 'text-gray-500 border-transparent'}`}
        >
          A Receber
        </button>
        <button 
          onClick={() => setView('cash')}
          className={`flex-1 pb-2 font-bold text-lg transition-colors border-b-2 ${view === 'cash' ? 'text-[#FF7A00] border-[#FF7A00]' : 'text-gray-500 border-transparent'}`}
        >
          Caixa
        </button>
      </div>

      {view === 'due' && (
        <div className="space-y-4">
          {/* Date Navigator */}
          <div className="bg-[#2E2E2E] p-3 rounded-2xl flex items-center justify-between border border-white/5">
             <button onClick={prevDay} className="p-2 text-gray-400 hover:text-white bg-white/5 rounded-lg">
                {ICONS.Left}
             </button>

             <div className="flex flex-col items-center">
                <input 
                  type="date" 
                  className="bg-transparent text-white font-bold text-center text-lg focus:outline-none"
                  value={format(selectedDate, 'yyyy-MM-dd')}
                  onChange={(e) => setSelectedDate(new Date(e.target.value + 'T00:00:00'))}
                />
                <span className="text-xs text-gray-500 capitalize">
                   {isToday(selectedDate) ? 'Hoje' : format(selectedDate, 'EEEE', { locale: ptBR })}
                </span>
             </div>

             <button onClick={nextDay} className="p-2 text-gray-400 hover:text-white bg-white/5 rounded-lg">
                {ICONS.Right}
             </button>
          </div>

          {/* Summary for the day */}
          <div className="flex justify-between items-center px-2">
             <span className="text-gray-400 text-sm">Total da Rota:</span>
             <span className="text-white font-bold text-lg">R$ {totalDoDia.toFixed(2)}</span>
          </div>

          {/* Overdue Alert */}
          {overdueCount > 0 && !showOverdue && (
             <div 
                onClick={() => setShowOverdue(true)}
                className="bg-red-500/10 border border-red-500/20 p-3 rounded-xl flex items-center justify-between cursor-pointer active:scale-[0.98] transition-transform"
             >
                <div className="flex items-center gap-2 text-red-400 text-sm">
                   {ICONS.Alert}
                   <span>Existem <strong>{overdueCount}</strong> parcelas atrasadas anteriores.</span>
                </div>
                <div className="text-red-400 text-xs font-bold underline">Ver Todas</div>
             </div>
          )}

          {/* Back to Day View button if Overdue is showing */}
          {showOverdue && (
              <Button variant="secondary" onClick={() => setShowOverdue(false)} fullWidth className="mb-2">
                 Voltar para Rota do Dia ({format(selectedDate, 'dd/MM')})
              </Button>
          )}

          {/* List */}
          {dueList.length === 0 ? (
            <div className="text-center text-gray-500 py-10">
              <div className="mb-2 opacity-50 flex justify-center">{ICONS.Check}</div>
              <p>Nenhuma cobrança {showOverdue ? 'pendente' : 'para esta data'}.</p>
            </div>
          ) : (
            dueList.map(item => {
              const overdue = isPast(new Date(item.data_vencimento)) && !isToday(new Date(item.data_vencimento));
              return (
                <Card key={item.id} className={`flex justify-between items-center border-l-4 ${overdue ? 'border-l-red-500' : 'border-l-[#FF7A00]'}`}>
                  <div>
                    <h4 className="font-bold text-white">{item.cliente_nome}</h4>
                    <p className="text-sm text-gray-400">Parcela {item.numero_parcela}</p>
                    <div className="flex items-center gap-2 mt-1">
                      {overdue && <span className="text-[10px] bg-red-500/20 text-red-400 px-1.5 py-0.5 rounded">Atrasado</span>}
                      <span className="text-xs text-gray-500">{format(new Date(item.data_vencimento), 'dd/MM/yyyy')}</span>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-2">
                    <span className="font-bold text-lg text-white">R$ {item.valor.toFixed(2)}</span>
                    <button 
                      onClick={() => setConfirmItem(item)}
                      className="text-xs bg-green-500/10 text-green-400 px-3 py-1.5 rounded-lg border border-green-500/20 active:bg-green-500/20"
                    >
                      Receber
                    </button>
                  </div>
                </Card>
              );
            })
          )}
        </div>
      )}

      {view === 'cash' && (
        <div className="space-y-6">

          {/* Period Selector */}
          <div className="flex p-1 bg-[#2E2E2E] rounded-xl border border-white/5">
              <button 
                onClick={() => setCashPeriod('day')}
                className={`flex-1 py-1.5 text-xs font-medium rounded-lg transition-all ${cashPeriod === 'day' ? 'bg-[#FF7A00] text-white shadow-lg' : 'text-gray-400'}`}
              >
                Hoje
              </button>
              <button 
                onClick={() => setCashPeriod('week')}
                className={`flex-1 py-1.5 text-xs font-medium rounded-lg transition-all ${cashPeriod === 'week' ? 'bg-[#FF7A00] text-white shadow-lg' : 'text-gray-400'}`}
              >
                Semana
              </button>
              <button 
                onClick={() => setCashPeriod('month')}
                className={`flex-1 py-1.5 text-xs font-medium rounded-lg transition-all ${cashPeriod === 'month' ? 'bg-[#FF7A00] text-white shadow-lg' : 'text-gray-400'}`}
              >
                Mês
              </button>
          </div>

          {/* Caixa Detalhado Summary */}
          <div className="grid grid-cols-2 gap-3">
             <div className="bg-[#2E2E2E] p-4 rounded-2xl border border-white/5 col-span-2">
                <p className="text-gray-400 text-sm">
                    Saldo 
                    {cashPeriod === 'day' ? ' do Dia' : cashPeriod === 'week' ? ' Semanal' : ' Mensal'}
                </p>
                <h2 className={`text-3xl font-bold ${cashSaldo >= 0 ? 'text-white' : 'text-red-400'}`}>
                  R$ {cashSaldo.toFixed(2)}
                </h2>
             </div>
             <div className="bg-[#2E2E2E] p-3 rounded-xl border border-white/5">
                <div className="flex items-center gap-2 mb-1">
                   <div className="w-2 h-2 rounded-full bg-green-500"></div>
                   <p className="text-xs text-gray-400">Entradas</p>
                </div>
                <p className="text-green-500 font-bold">R$ {cashEntradas.toFixed(2)}</p>
             </div>
             <div className="bg-[#2E2E2E] p-3 rounded-xl border border-white/5">
                <div className="flex items-center gap-2 mb-1">
                   <div className="w-2 h-2 rounded-full bg-red-500"></div>
                   <p className="text-xs text-gray-400">Saídas</p>
                </div>
                <p className="text-red-400 font-bold">R$ {cashSaidas.toFixed(2)}</p>
             </div>
          </div>

          <div className="flex justify-between items-center">
             <h3 className="text-white font-bold">Movimentações ({filteredCash.length})</h3>
             <button 
                onClick={() => setShowExpenseModal(true)}
                className="text-xs bg-red-500/10 text-red-400 px-3 py-2 rounded-lg font-medium hover:bg-red-500/20 flex items-center gap-1"
             >
                {ICONS.Add} Despesa
             </button>
          </div>

          <div className="space-y-3">
            {filteredCash.map(entry => (
               <div key={entry.id} className="flex justify-between items-center p-3 bg-[#2E2E2E] rounded-xl border border-white/5 group">
                  <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${entry.tipo === 'ENTRADA' ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'}`}>
                      {entry.tipo === 'ENTRADA' ? ICONS.Trending : ICONS.Alert}
                    </div>
                    <div>
                      <p className="text-white font-medium">{entry.descricao}</p>
                      <p className="text-xs text-gray-500">{format(new Date(entry.data), 'dd/MM HH:mm')}</p>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-1">
                    <span className={`font-bold ${entry.tipo === 'ENTRADA' ? 'text-green-400' : 'text-red-400'}`}>
                        {entry.tipo === 'ENTRADA' ? '+' : '-'} R$ {entry.valor.toFixed(2)}
                    </span>
                    <button 
                        onClick={() => setDeleteCashId(entry.id)}
                        className="text-xs text-red-500/50 hover:text-red-500"
                    >
                        {ICONS.Trash}
                    </button>
                  </div>
               </div>
            ))}
            {filteredCash.length === 0 && (
              <p className="text-center text-gray-500 py-4 text-sm">
                  Nenhuma movimentação {cashPeriod === 'day' ? 'hoje' : 'neste período'}.
              </p>
            )}
          </div>
        </div>
      )}

      {/* Confirmation Modal */}
      <Modal isOpen={!!confirmItem} onClose={() => setConfirmItem(null)} title="Confirmar Recebimento">
        <div className="space-y-6 text-center">
           <div className="w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center text-green-500 mx-auto">
             {ICONS.Check}
           </div>
           <div>
             {confirmItem && (
               <>
                 <p className="text-gray-300">Receber <strong className="text-white">R$ {confirmItem.valor.toFixed(2)}</strong> de <strong className="text-white">{confirmItem.cliente_nome}</strong>?</p>
                 <p className="text-xs text-gray-500 mt-2">Parcela {confirmItem.numero_parcela} • Vencimento {format(new Date(confirmItem.data_vencimento), 'dd/MM/yyyy')}</p>
                 <p className="text-xs text-gray-600 mt-4">Esta ação lançará o valor no caixa imediatamente.</p>
               </>
             )}
           </div>
           <div className="grid grid-cols-2 gap-3">
             <Button variant="secondary" onClick={() => setConfirmItem(null)}>Cancelar</Button>
             <Button onClick={handlePay} isLoading={loading} className="bg-green-600 hover:bg-green-700 border-none shadow-green-900/20">
               Confirmar
             </Button>
           </div>
        </div>
      </Modal>

      {/* Add Expense Modal */}
      <Modal isOpen={showExpenseModal} onClose={() => setShowExpenseModal(false)} title="Nova Despesa">
         <div className="space-y-4">
            <Input 
               label="Descrição" 
               placeholder="Ex: Combustível, Almoço..."
               value={expenseForm.descricao}
               onChange={(e) => setExpenseForm(prev => ({ ...prev, descricao: e.target.value }))}
            />
            <Input 
               label="Valor (R$)" 
               type="number"
               step="0.01"
               placeholder="0,00"
               value={expenseForm.valor}
               onChange={(e) => setExpenseForm(prev => ({ ...prev, valor: e.target.value }))}
            />
            <Button 
               fullWidth 
               onClick={handleAddExpense} 
               isLoading={loading}
               variant="danger"
               className="mt-2"
            >
               Lançar Saída
            </Button>
         </div>
      </Modal>

      {/* Delete Cash Entry Modal */}
      <Modal isOpen={!!deleteCashId} onClose={() => setDeleteCashId(null)} title="Excluir Lançamento">
         <div className="text-center space-y-4">
             <div className="w-16 h-16 bg-red-500/20 rounded-full flex items-center justify-center text-red-500 mx-auto">
                {ICONS.Trash}
             </div>
             <p className="text-gray-300">Tem certeza que deseja excluir este lançamento do caixa? O saldo será recalculado.</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setDeleteCashId(null)}>Cancelar</Button>
                 <Button variant="danger" onClick={handleDeleteCashEntry} isLoading={loading}>Excluir</Button>
             </div>
         </div>
      </Modal>
    </div>
  );
};

