import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ICONS, COLORS, ROUTES } from '../constants';
import { Card } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';

const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const user = authService.getSession();
  const [stats, setStats] = useState({
    totalVendido: 0,
    totalRecebido: 0,
    totalReceber: 0,
    inadimplencia: 0
  });

  // State to toggle value visibility
  const [valuesVisible, setValuesVisible] = useState(true);

  useEffect(() => {
    const loadStats = async () => {
      const data = await dataService.getDashboardStats();
      setStats(data);
    };
    loadStats();
  }, []);

  const handleLogout = async () => {
    await authService.logout();
    navigate(ROUTES.LOGIN);
  };

  const pieData = [
    { name: 'Recebido', value: stats.totalRecebido, color: COLORS.success },
    { name: 'A Receber', value: stats.totalReceber, color: COLORS.primary },
    { name: 'Atrasado', value: stats.inadimplencia, color: COLORS.danger },
  ];

  // Helper to format or mask values
  const formatCurrency = (val: number) => {
    if (!valuesVisible) return 'R$ •••••';
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
  };

  return (
    <div className="p-5 space-y-6 animate-fade-in">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <p className="text-gray-400 text-sm">Bem-vindo,</p>
          <div className="flex items-center gap-2">
             <h1 className="text-2xl font-bold text-white">{user?.nome || 'Vendedor'}</h1>
             <button 
                onClick={() => setValuesVisible(!valuesVisible)}
                className="text-gray-500 hover:text-white transition-colors"
             >
                {valuesVisible ? ICONS.Eye : ICONS.EyeOff}
             </button>
          </div>
        </div>
        <div className="flex items-center gap-3">
            <button 
              onClick={handleLogout}
              className="p-2 rounded-full bg-[#2E2E2E] text-red-400 hover:bg-red-500/20 hover:text-red-500 transition-colors"
              title="Sair do App"
            >
              {ICONS.Logout}
            </button>
            <div className="w-10 h-10 rounded-full bg-[#333] flex items-center justify-center text-[#FF7A00] font-bold border border-white/5">
              {user?.nome?.charAt(0) || 'U'}
            </div>
        </div>
      </div>

      {/* Main Stats */}
      <div className="grid grid-cols-2 gap-4">
        <Card className="col-span-2 bg-gradient-to-br from-[#FF7A00] to-[#CC6200] border-none">
          <div className="flex items-center gap-3 mb-2 opacity-90">
            <div className="p-2 bg-white/20 rounded-lg text-white">
              {ICONS.Trending}
            </div>
            <span className="text-white font-medium">Total Vendido</span>
          </div>
          <h2 className="text-3xl font-bold text-white">{formatCurrency(stats.totalVendido)}</h2>
          <p className="text-white/70 text-sm mt-1">Geral</p>
        </Card>

        <Card>
          <p className="text-gray-400 text-xs mb-1">Recebido</p>
          <p className="text-lg font-bold text-emerald-500">{formatCurrency(stats.totalRecebido)}</p>
        </Card>
        <Card>
          <p className="text-gray-400 text-xs mb-1">A Receber</p>
          <p className="text-lg font-bold text-[#FF7A00]">{formatCurrency(stats.totalReceber)}</p>
        </Card>
      </div>

      {/* Admin Shortcuts */}
      {user?.perfil === 'admin' && (
        <>
          <h3 className="text-lg font-bold text-white pt-2">Administração</h3>
          <div className="grid grid-cols-4 gap-3">
            <button 
              onClick={() => navigate(ROUTES.REPORTS)}
              className="bg-[#2E2E2E] p-2 rounded-xl flex flex-col items-center gap-1 border border-white/5 active:scale-95 transition-transform"
            >
              <div className="text-[#FF7A00] scale-90">{ICONS.Reports}</div>
              <span className="text-white text-[10px] font-medium">Relatórios</span>
            </button>
            <button 
              onClick={() => navigate(ROUTES.PRODUCTS)}
              className="bg-[#2E2E2E] p-2 rounded-xl flex flex-col items-center gap-1 border border-white/5 active:scale-95 transition-transform"
            >
              <div className="text-[#FF7A00] scale-90">{ICONS.Product}</div>
              <span className="text-white text-[10px] font-medium">Produtos</span>
            </button>
            <button 
              onClick={() => navigate(ROUTES.SELLERS)}
              className="bg-[#2E2E2E] p-2 rounded-xl flex flex-col items-center gap-1 border border-white/5 active:scale-95 transition-transform"
            >
              <div className="text-[#FF7A00] scale-90">{ICONS.Sellers}</div>
              <span className="text-white text-[10px] font-medium">Equipe</span>
            </button>
            <button 
              onClick={() => navigate(ROUTES.SETTINGS)}
              className="bg-[#2E2E2E] p-2 rounded-xl flex flex-col items-center gap-1 border border-white/5 active:scale-95 transition-transform"
            >
              <div className="text-[#FF7A00] scale-90">{ICONS.Settings}</div>
              <span className="text-white text-[10px] font-medium">Dados</span>
            </button>
          </div>
        </>
      )}

      {/* Charts Section */}
      <h3 className="text-lg font-bold text-white mt-4">Visão Geral</h3>
      <div className="h-64 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={pieData}
              cx="50%"
              cy="50%"
              innerRadius={60}
              outerRadius={80}
              paddingAngle={5}
              dataKey="value"
              stroke="none"
            >
              {pieData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} />
              ))}
