                {error}
              </div>
            )}

            <Button type="submit" fullWidth isLoading={loading} className="py-4 shadow-orange-900/20">
              Entrar no Sistema
            </Button>
          </form>

          <div className="mt-6 pt-6 border-t border-white/5 flex flex-col gap-3 text-center">
             <button 
               type="button" 
               onClick={() => navigate(ROUTES.REGISTER)}
               className="text-sm text-gray-400 hover:text-white transition-colors"
             >
              Não possui conta? <span className="text-[#FF7A00] font-bold">Cadastrar Usuário</span>
            </button>
            <button type="button" className="text-xs text-gray-600 hover:text-gray-400 transition-colors">
              Esqueci minha senha
            </button>
