  getInstallmentsByDate: async (date: Date): Promise<{ 
     daily: (Installment & { cliente_nome: string, venda_id: string })[], 
     overdueCount: number 
  }> => {
    const filterId = getUserFilter();
    const start = startOfDay(date).toISOString();
    const end = endOfDay(date).toISOString();
    const todayStr = new Date().toISOString();

    if (isSupabaseConfigured) {
        // Build query using INNER JOIN on sales to filter by sales.vendedor_id
        // Supabase-js: embedded filtering
        // We select installments, and sales where vendedor_id is match

        let query = supabase
            .from('installments')
            .select('*, sales!inner(id, vendedor_id, clients(nome))')
            .eq('pago', false)
            .gte('data_vencimento', start)
            .lte('data_vencimento', end)
            .order('data_vencimento');

        if (filterId) {
             query = query.eq('sales.vendedor_id', filterId);
        }

        const { data: daily } = await query;

        // Overdue Count
        let overdueQuery = supabase
            .from('installments')
            .select('*, sales!inner(vendedor_id)', { count: 'exact', head: true })
            .eq('pago', false)
            .lt('data_vencimento', startOfDay(new Date()).toISOString());

        if (filterId) {
            overdueQuery = overdueQuery.eq('sales.vendedor_id', filterId);
        }

        const { count: overdueCount } = await overdueQuery;

        return {
           daily: (daily || []).map((i: any) => ({ ...i, cliente_nome: i.sales?.clients?.nome || 'Desconhecido', venda_id: i.venda_id })),
           overdueCount: overdueCount || 0
        };
    }

    await delay(300);
    const installments = getStorage<Installment[]>('installments', []);
    const sales = getStorage<Sale[]>('sales', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);

    // Filter sales first
    const visibleSales = filterId ? sales.filter(s => s.vendedor_id === filterId) : sales;
    const visibleSaleIds = visibleSales.map(s => s.id);

    const daily = installments
      .filter(i => visibleSaleIds.includes(i.venda_id) && !i.pago && isSameDay(new Date(i.data_vencimento), date))
      .map(i => {
        const sale = sales.find(s => s.id === i.venda_id);
        const client = clients.find(c => c.id === sale?.cliente_id);
        return { ...i, cliente_nome: client?.nome || 'Desconhecido', venda_id: i.venda_id };
      });

    const overdueCount = installments.filter(i => visibleSaleIds.includes(i.venda_id) && !i.pago && new Date(i.data_vencimento) < startOfDay(new Date())).length;

    return { daily, overdueCount };
  },

  getDueInstallments: async (): Promise<(Installment & { cliente_nome: string, venda_id: string })[]> => {
    const filterId = getUserFilter();
    const today = new Date();
    today.setHours(23, 59, 59, 999);

    if (isSupabaseConfigured) {
        let query = supabase
            .from('installments')
            .select('*, sales!inner(id, vendedor_id, clients(nome))')
            .eq('pago', false)
            .lte('data_vencimento', today.toISOString())
            .order('data_vencimento');

        if (filterId) query = query.eq('sales.vendedor_id', filterId);

        const { data } = await query;
        return (data || []).map((i: any) => ({ ...i, cliente_nome: i.sales?.clients?.nome || 'Desconhecido', venda_id: i.venda_id }));
    }

    await delay(300);
    const installments = getStorage<Installment[]>('installments', []);
    const sales = getStorage<Sale[]>('sales', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);

    const visibleSales = filterId ? sales.filter(s => s.vendedor_id === filterId) : sales;
    const visibleSaleIds = visibleSales.map(s => s.id);

    return installments
      .filter(i => visibleSaleIds.includes(i.venda_id) && !i.pago && new Date(i.data_vencimento) <= today)
      .map(i => {
        const sale = sales.find(s => s.id === i.venda_id);
        const client = clients.find(c => c.id === sale?.cliente_id);
        return { ...i, cliente_nome: client?.nome || 'Desconhecido', venda_id: i.venda_id };
      })
      .sort((a, b) => new Date(a.data_vencimento).getTime() - new Date(b.data_vencimento).getTime());
  },

  payInstallment: async (installmentId: string, vendedorId: string, actualAmountPaid?: number): Promise<void> => {
    // 1. Get current installment info
    let currentInst: Installment | null = null;
    let nextInst: Installment | null = null;

    if (isSupabaseConfigured) {
        // Fetch current
        const { data: inst } = await supabase.from('installments').select('*').eq('id', installmentId).single();
        if (!inst || inst.pago) return;
        currentInst = inst;

        // Use the actual paid amount if provided, otherwise original amount
        const paidValue = actualAmountPaid !== undefined ? actualAmountPaid : inst.valor;
        const difference = inst.valor - paidValue; // Positive = paid less (debt), Negative = paid more (credit)

        // Update Current
        await supabase.from('installments').update({ 
            pago: true, 
            data_pagamento: new Date().toISOString(),
            valor: paidValue // Update to reflect what was actually paid
        }).eq('id', installmentId);

        // Cash Flow
        await supabase.from('cash_flow').insert([{ 
            tipo: 'ENTRADA', 
            valor: paidValue, 
            descricao: `Pagamento Parcela ${inst.numero_parcela}`, 
            vendedor_id: vendedorId, 
            data: new Date().toISOString() 
        }]);

        // Handle Difference (Recalculate Next)
        if (Math.abs(difference) > 0.01) {
            const { data: next } = await supabase
                .from('installments')
                .select('*')
                .eq('venda_id', inst.venda_id)
                .gt('numero_parcela', inst.numero_parcela)
                .order('numero_parcela')
                .limit(1)
                .single();

            if (next) {
                // Add difference to next parcel. 
                // If paid less (diff > 0), next parcel increases.
                // If paid more (diff < 0), next parcel decreases.
                await supabase.from('installments').update({
                    valor: next.valor + difference
                }).eq('id', next.id);
            }
        }

        // Check Status
        const { data: allInst } = await supabase.from('installments').select('pago').eq('venda_id', inst.venda_id);
        if (allInst) {
             const allPaid = allInst.every((i: any) => i.pago);
             const somePaid = allInst.some((i: any) => i.pago);
             let status: SaleStatus = 'ABERTA';
             if (allPaid) status = 'QUITADA';
             else if (somePaid) status = 'PARCIAL';
             await supabase.from('sales').update({ status }).eq('id', inst.venda_id);
        }
        return;
    }

    // MOCK LocalStorage
    await delay(500);
    let installments = getStorage<Installment[]>('installments', []);
    let sales = getStorage<Sale[]>('sales', []);
    let cash = getStorage<CashEntry[]>('cash', []);

    const instIndex = installments.findIndex(i => i.id === installmentId);
    if (instIndex === -1) return;
    const installment = installments[instIndex];
    if (installment.pago) return;

    const paidValue = actualAmountPaid !== undefined ? actualAmountPaid : installment.valor;
    const difference = installment.valor - paidValue;

    // Update Current
    installments[instIndex] = { 
        ...installment, 
        pago: true, 
        data_pagamento: new Date().toISOString(),
        valor: paidValue
    };

    // Add Cash
    cash.push({ 
        id: uuidv4(), 
        data: new Date().toISOString(), 
        tipo: 'ENTRADA', 
        valor: paidValue, 
        descricao: `Pagamento Parcela ${installment.numero_parcela}`, 
        vendedor_id: vendedorId 
    });

    // Handle Difference (Recalculate Next)
    if (Math.abs(difference) > 0.01) {
        // Find next installment
        const nextIndex = installments.findIndex(i => 
            i.venda_id === installment.venda_id && 
            i.numero_parcela > installment.numero_parcela &&
            !i.pago
        );

        // Simple sort to find the immediate next one if array is scrambled, 
        // but typically finding by lowest parcel number > current is safer.
        // For mock simple find is okay if we assume order, but let's be safe:
        const nextInstallments = installments
            .map((inst, idx) => ({ ...inst, originalIndex: idx }))
            .filter(i => i.venda_id === installment.venda_id && i.numero_parcela > installment.numero_parcela && !i.pago)
            .sort((a,b) => a.numero_parcela - b.numero_parcela);

        if (nextInstallments.length > 0) {
            const nextTarget = nextInstallments[0];
            installments[nextTarget.originalIndex] = {
                ...installments[nextTarget.originalIndex],
                valor: installments[nextTarget.originalIndex].valor + difference
            };
        }
    }

    // Update status
    const saleIndex = sales.findIndex(s => s.id === installment.venda_id);
    if (saleIndex !== -1) {
       const saleInsts = installments.filter(i => i.venda_id === installment.venda_id);
       const allPaid = saleInsts.every(i => i.pago);
       const somePaid = saleInsts.some(i => i.pago);
       sales[saleIndex].status = allPaid ? 'QUITADA' : somePaid ? 'PARCIAL' : 'ABERTA';
    }

    setStorage('installments', installments);
    setStorage('sales', sales);
    setStorage('cash', cash);
  },

  addExpense: async (description: string, value: number, vendedorId: string): Promise<void> => {
     // Expenses are linked to the user who creates them
     if (isSupabaseConfigured) {
         await supabase.from('cash_flow').insert([{ tipo: 'SAIDA', valor: value, descricao: description, vendedor_id: vendedorId, data: new Date().toISOString() }]);
         return;
     }
     await delay(300);
     const cash = getStorage<CashEntry[]>('cash', []);
     cash.push({ id: uuidv4(), data: new Date().toISOString(), tipo: 'SAIDA', valor: value, descricao: description, vendedor_id: vendedorId });
     setStorage('cash', cash);
  },

  deleteCashEntry: async (id: string): Promise<void> => {
      if (isSupabaseConfigured) {
          await supabase.from('cash_flow').delete().eq('id', id);
          return;
      }
      await delay(300);
      const cash = getStorage<CashEntry[]>('cash', []);
      setStorage('cash', cash.filter(c => c.id !== id));
  },

  getCashFlow: async (): Promise<CashEntry[]> => {
      const filterId = getUserFilter();

      if (isSupabaseConfigured) {
          let query = supabase.from('cash_flow').select('*').order('data', { ascending: false });
          if (filterId) query = query.eq('vendedor_id', filterId);
          const { data } = await query;
          return data || [];
      }
      await delay(300);
      let cash = getStorage<CashEntry[]>('cash', []);
      if (filterId) cash = cash.filter(c => c.vendedor_id === filterId);

      return cash.sort((a,b) => new Date(b.data).getTime() - new Date(a.data).getTime());
  },

  getDashboardStats: async () => {
      const filterId = getUserFilter();

      if (isSupabaseConfigured) {
          // Requires joining sales to filter installments by seller
          let salesQuery = supabase.from('sales').select('id, valor_total');
          if (filterId) salesQuery = salesQuery.eq('vendedor_id', filterId);
          const { data: sales } = await salesQuery;
          const salesIds = sales?.map(s => s.id) || [];

          if (salesIds.length === 0) return { totalVendido: 0, totalRecebido: 0, totalReceber: 0, inadimplencia: 0 };

          const { data: paidInst } = await supabase.from('installments').select('valor').in('venda_id', salesIds).eq('pago', true);
          const { data: openInst } = await supabase.from('installments').select('valor').in('venda_id', salesIds).eq('pago', false);
          const today = new Date().toISOString();
          const { data: overdueInst } = await supabase.from('installments').select('valor').in('venda_id', salesIds).eq('pago', false).lt('data_vencimento', today);

          return {
             totalVendido: sales?.reduce((acc, curr) => acc + curr.valor_total, 0) || 0,
             totalRecebido: paidInst?.reduce((acc, curr) => acc + curr.valor, 0) || 0,
             totalReceber: openInst?.reduce((acc, curr) => acc + curr.valor, 0) || 0,
             inadimplencia: overdueInst?.reduce((acc, curr) => acc + curr.valor, 0) || 0
          };
      }
      await delay(500);
      let sales = getStorage<Sale[]>('sales', []);
      if (filterId) sales = sales.filter(s => s.vendedor_id === filterId);
      const salesIds = sales.map(s => s.id);

      const installments = getStorage<Installment[]>('installments', []).filter(i => salesIds.includes(i.venda_id));

      const today = new Date();
      return {
          totalVendido: sales.reduce((acc, curr) => acc + curr.valor_total, 0),
          totalRecebido: installments.filter(i => i.pago).reduce((acc, curr) => acc + curr.valor, 0),
          totalReceber: installments.filter(i => !i.pago).reduce((acc, curr) => acc + curr.valor, 0),
          inadimplencia: installments.filter(i => !i.pago && new Date(i.data_vencimento) < today).reduce((acc, curr) => acc + curr.valor, 0)
      };
  },

  getDetailedReports: async (startDate: Date, endDate: Date, sellerId?: string) => {
    // Shared formatting logic
    const processData = (salesRes: Sale[], cashRes: CashEntry[]) => {
        const interval = eachDayOfInterval({ start: startDate, end: endDate });
        const dailyData: DailyReport[] = interval.map(date => {
            const daySales = salesRes.filter(s => isSameDay(new Date(s.data_venda), date));
            const dayCash = cashRes.filter(c => isSameDay(new Date(c.data), date));
            return {
                data: format(date, 'dd/MM'),
                vendas: daySales.reduce((acc, s) => acc + s.valor_total, 0),
                recebimentos: dayCash.reduce((acc, c) => acc + c.valor, 0)
            };
        });
        return {
            dailyData,
            sales: salesRes,
            receipts: cashRes,
            summary: {
                totalSales: salesRes.reduce((acc, s) => acc + s.valor_total, 0),
                totalReceipts: cashRes.reduce((acc, c) => acc + c.valor, 0)
            }
        };
    };

    const currentUser = getCurrentUser();
    // If user is admin, they can filter by sellerId provided in arguments.
    // If user is seller, force sellerId to be their own ID.
    let finalSellerId = sellerId;
    if (currentUser?.perfil !== 'admin') {
        finalSellerId = currentUser?.id;
    }

    if (isSupabaseConfigured) {
        let salesQuery = supabase.from('sales').select('*, clients(nome)').gte('data_venda', startDate.toISOString()).lte('data_venda', endDate.toISOString());
        let cashQuery = supabase.from('cash_flow').select('*').eq('tipo', 'ENTRADA').gte('data', startDate.toISOString()).lte('data', endDate.toISOString());

        if (finalSellerId && finalSellerId !== 'all') {
            salesQuery = salesQuery.eq('vendedor_id', finalSellerId);
            cashQuery = cashQuery.eq('vendedor_id', finalSellerId);
        }

        const { data: sData } = await salesQuery;
        const { data: cData } = await cashQuery;
        const sales = (sData || []).map((s: any) => ({ ...s, cliente_nome: s.clients?.nome || 'Desconhecido' }));
        return processData(sales, cData || []);
    }

    await delay(500);
    const sales = await dataService.getSales(); // Already filtered by user if standard user
    const cash = await dataService.getCashFlow(); // Already filtered

    let filteredSales = sales.filter(s => {
       const d = new Date(s.data_venda);
       return d >= startDate && d <= endDate;
    });
    let filteredCash = cash.filter(c => {
       const d = new Date(c.data);
       return d >= startDate && d <= endDate && c.tipo === 'ENTRADA';
    });

    if (finalSellerId && finalSellerId !== 'all') {
        filteredSales = filteredSales.filter(s => s.vendedor_id === finalSellerId);
        filteredCash = filteredCash.filter(c => c.vendedor_id === finalSellerId);
    }
    return processData(filteredSales, filteredCash);
  },

  // Backup & Restore (Local Only)
  exportBackupData: async (): Promise<string> => {
      // Dump local storage regardless of mode, or dump memory? 
      if (isSupabaseConfigured) {
          throw new Error("Exportação não disponível no modo Online (Supabase).");
      }
      const user = getCurrentUser();
      if (!user) throw new Error("Usuário não logado");

      // If Admin export all, if Seller export only theirs
      const allSales = getStorage<Sale[]>('sales', []);
      const allClients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
      const allCash = getStorage<CashEntry[]>('cash', []);
      const allInstallments = getStorage<Installment[]>('installments', []);

      let exportSales = allSales;
      let exportClients = allClients;
      let exportCash = allCash;
      let exportInstallments = allInstallments;

      if (user.perfil !== 'admin') {
          exportSales = allSales.filter(s => s.vendedor_id === user.id);
          exportClients = allClients.filter(c => c.vendedor_id === user.id);
          exportCash = allCash.filter(c => c.vendedor_id === user.id);
          const saleIds = exportSales.map(s => s.id);
          exportInstallments = allInstallments.filter(i => saleIds.includes(i.venda_id));
      }

      const backup = {
          version: '1.0',
          timestamp: new Date().toISOString(),
          exporter: user.email,
          users: user.perfil === 'admin' ? getStorage('users', MOCK_USERS) : [user], // Only admin exports users
          clients: exportClients,
          products: getStorage('products', INITIAL_PRODUCTS), // Products are global
          sales: exportSales,
          installments: exportInstallments,
          cash: exportCash
      };
      return JSON.stringify(backup, null, 2);
  },

  importBackupData: async (jsonData: string): Promise<void> => {
      if (isSupabaseConfigured) {
          throw new Error("Importação não disponível no modo Online (Supabase).");
      }
      try {
          const data = JSON.parse(jsonData);
          if (!data.version) throw new Error("Arquivo inválido");

          // Merge strategy: Overwrite or Append? 
          // For simplicity in this mock app, we overwrite if admin, or append if seller?
          // Let's simple overwrite for now to act as "Restore"

          setStorage('clients', data.clients || []);
          setStorage('products', data.products || []);
          setStorage('sales', data.sales || []);
          setStorage('installments', data.installments || []);
          setStorage('cash', data.cash || []);

          if (data.users && data.users.length > 0) {
              setStorage('users', data.users);
          }
      } catch (e) {
          console.error(e);
          throw new Error("Erro ao importar backup");
      }
  }
};

import React, { useEffect, useState } from 'react';
import { ICONS, COLORS } from '../constants';
import { Card, Badge, Modal, Button, Input } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';
import { Installment, CashEntry } from '../types';
import { format, isToday, isPast, addDays, subDays, startOfDay, endOfDay, startOfWeek, endOfWeek, startOfMonth, endOfMonth, isWithinInterval } from 'date-fns';
import { ptBR } from 'date-fns/locale';

const Payments: React.FC = () => {
  const session = authService.getSession();
  const [view, setView] = useState<'due' | 'cash'>('due');

  // Due List (Route) State
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [dueList, setDueList] = useState<(Installment & { cliente_nome: string, venda_id: string })[]>([]);
  const [overdueCount, setOverdueCount] = useState(0);
  const [showOverdue, setShowOverdue] = useState(false);

  // Cash Flow State
  const [cashFlow, setCashFlow] = useState<CashEntry[]>([]);
  const [cashPeriod, setCashPeriod] = useState<'day' | 'week' | 'month'>('day');

  const [loading, setLoading] = useState(false);

  // Modals state
  const [confirmItem, setConfirmItem] = useState<(Installment & { cliente_nome: string }) | null>(null);
  const [paymentAmount, setPaymentAmount] = useState('');

  const [showExpenseModal, setShowExpenseModal] = useState(false);
  const [deleteCashId, setDeleteCashId] = useState<string | null>(null);
  const [expenseForm, setExpenseForm] = useState({ descricao: '', valor: '' });

  const loadData = async () => {
    // 1. Load Route (Daily Collection)
    const routeData = await dataService.getInstallmentsByDate(selectedDate);

    if (showOverdue) {
        const allDue = await dataService.getDueInstallments();
        setDueList(allDue);
    } else {
        setDueList(routeData.daily);
    }
    setOverdueCount(routeData.overdueCount);

    // 2. Load Cash
    const flow = await dataService.getCashFlow();
    setCashFlow(flow);
  };

  useEffect(() => {
    loadData();
  }, [selectedDate, showOverdue]);

  const handleOpenPayment = (item: Installment & { cliente_nome: string, venda_id: string }) => {
      setConfirmItem(item);
      setPaymentAmount(item.valor.toFixed(2));
  };

  const handlePay = async () => {
    if (!confirmItem || !session || !paymentAmount) return;
    setLoading(true);
    try {
      await dataService.payInstallment(confirmItem.id, session.id, parseFloat(paymentAmount));
      await loadData();
      setConfirmItem(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleAddExpense = async () => {
    if (!expenseForm.descricao || !expenseForm.valor || !session) return;
    setLoading(true);
    try {
      await dataService.addExpense(expenseForm.descricao, parseFloat(expenseForm.valor), session.id);
      await loadData();
      setShowExpenseModal(false);
      setExpenseForm({ descricao: '', valor: '' });
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteCashEntry = async () => {
      if (!deleteCashId) return;
      setLoading(true);
      try {
          await dataService.deleteCashEntry(deleteCashId);
          await loadData();
          setDeleteCashId(null);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  // Date Navigation Helpers
  const nextDay = () => setSelectedDate(addDays(selectedDate, 1));
  const prevDay = () => setSelectedDate(subDays(selectedDate, 1));

  // Calculations
  const totalDoDia = dueList.reduce((acc, i) => acc + i.valor, 0);

  // Cash Flow Calculations based on Period
  const getFilteredCashFlow = () => {
      const now = new Date();
      let start, end;

      switch (cashPeriod) {
          case 'day':
              start = startOfDay(now);
              end = endOfDay(now);
              break;
          case 'week':
              start = startOfWeek(now, { weekStartsOn: 1 }); // Segunda-feira
              end = endOfWeek(now, { weekStartsOn: 1 });
              break;
          case 'month':
              start = startOfMonth(now);
              end = endOfMonth(now);
              break;
      }

      return cashFlow.filter(entry => 
          isWithinInterval(new Date(entry.data), { start, end })
      );
  };

  const filteredCash = getFilteredCashFlow();
  const cashEntradas = filteredCash.filter(c => c.tipo === 'ENTRADA').reduce((acc, c) => acc + c.valor, 0);
  const cashSaidas = filteredCash.filter(c => c.tipo === 'SAIDA').reduce((acc, c) => acc + c.valor, 0);
  const cashSaldo = cashEntradas - cashSaidas;

  return (
    <div className="p-5 animate-fade-in pb-24">
      {/* Tabs */}
      <div className="flex gap-4 mb-6">
        <button 
          onClick={() => setView('due')}
          className={`flex-1 pb-2 font-bold text-lg transition-colors border-b-2 ${view === 'due' ? 'text-[#FF7A00] border-[#FF7A00]' : 'text-gray-500 border-transparent'}`}
        >
          A Receber
        </button>
        <button 
          onClick={() => setView('cash')}
          className={`flex-1 pb-2 font-bold text-lg transition-colors border-b-2 ${view === 'cash' ? 'text-[#FF7A00] border-[#FF7A00]' : 'text-gray-500 border-transparent'}`}
        >
          Caixa
        </button>
      </div>

      {view === 'due' && (
        <div className="space-y-4">
          {/* Date Navigator */}
          <div className="bg-[#2E2E2E] p-3 rounded-2xl flex items-center justify-between border border-white/5">
             <button onClick={prevDay} className="p-2 text-gray-400 hover:text-white bg-white/5 rounded-lg">
                {ICONS.Left}
             </button>

             <div className="flex flex-col items-center">
                <input 
                  type="date" 
                  className="bg-transparent text-white font-bold text-center text-lg focus:outline-none"
                  value={format(selectedDate, 'yyyy-MM-dd')}
                  onChange={(e) => setSelectedDate(new Date(e.target.value + 'T00:00:00'))}
                />
                <span className="text-xs text-gray-500 capitalize">
                   {isToday(selectedDate) ? 'Hoje' : format(selectedDate, 'EEEE', { locale: ptBR })}
                </span>
             </div>

             <button onClick={nextDay} className="p-2 text-gray-400 hover:text-white bg-white/5 rounded-lg">
                {ICONS.Right}
             </button>
          </div>

          {/* Summary for the day */}
          <div className="flex justify-between items-center px-2">
             <span className="text-gray-400 text-sm">Total da Rota:</span>
             <span className="text-white font-bold text-lg">R$ {totalDoDia.toFixed(2)}</span>
          </div>

          {/* Overdue Alert */}
          {overdueCount > 0 && !showOverdue && (
             <div 
                onClick={() => setShowOverdue(true)}
                className="bg-red-500/10 border border-red-500/20 p-3 rounded-xl flex items-center justify-between cursor-pointer active:scale-[0.98] transition-transform"
             >
                <div className="flex items-center gap-2 text-red-400 text-sm">
                   {ICONS.Alert}
                   <span>Existem <strong>{overdueCount}</strong> parcelas atrasadas anteriores.</span>
                </div>
                <div className="text-red-400 text-xs font-bold underline">Ver Todas</div>
             </div>
          )}

          {/* Back to Day View button if Overdue is showing */}
          {showOverdue && (
              <Button variant="secondary" onClick={() => setShowOverdue(false)} fullWidth className="mb-2">
                 Voltar para Rota do Dia ({format(selectedDate, 'dd/MM')})
              </Button>
          )}

          {/* List */}
          {dueList.length === 0 ? (
            <div className="text-center text-gray-500 py-10">
              <div className="mb-2 opacity-50 flex justify-center">{ICONS.Check}</div>
              <p>Nenhuma cobrança {showOverdue ? 'pendente' : 'para esta data'}.</p>
            </div>
          ) : (
            dueList.map(item => {
              const overdue = isPast(new Date(item.data_vencimento)) && !isToday(new Date(item.data_vencimento));
              return (
                <Card key={item.id} className={`flex justify-between items-center border-l-4 ${overdue ? 'border-l-red-500' : 'border-l-[#FF7A00]'}`}>
                  <div>
                    <h4 className="font-bold text-white">{item.cliente_nome}</h4>
                    <p className="text-sm text-gray-400">Parcela {item.numero_parcela}</p>
                    <div className="flex items-center gap-2 mt-1">
                      {overdue && <span className="text-[10px] bg-red-500/20 text-red-400 px-1.5 py-0.5 rounded">Atrasado</span>}
                      <span className="text-xs text-gray-500">{format(new Date(item.data_vencimento), 'dd/MM/yyyy')}</span>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-2">
                    <span className="font-bold text-lg text-white">R$ {item.valor.toFixed(2)}</span>
                    <button 
                      onClick={() => handleOpenPayment(item)}
                      className="text-xs bg-green-500/10 text-green-400 px-3 py-1.5 rounded-lg border border-green-500/20 active:bg-green-500/20"
                    >
                      Receber
                    </button>
                  </div>
                </Card>
              );
            })
          )}
        </div>
      )}

      {view === 'cash' && (
        <div className="space-y-6">

          {/* Period Selector */}
          <div className="flex p-1 bg-[#2E2E2E] rounded-xl border border-white/5">
              <button 
                onClick={() => setCashPeriod('day')}
                className={`flex-1 py-1.5 text-xs font-medium rounded-lg transition-all ${cashPeriod === 'day' ? 'bg-[#FF7A00] text-white shadow-lg' : 'text-gray-400'}`}
              >
                Hoje
              </button>
              <button 
                onClick={() => setCashPeriod('week')}
                className={`flex-1 py-1.5 text-xs font-medium rounded-lg transition-all ${cashPeriod === 'week' ? 'bg-[#FF7A00] text-white shadow-lg' : 'text-gray-400'}`}
              >
                Semana
              </button>
              <button 
                onClick={() => setCashPeriod('month')}
                className={`flex-1 py-1.5 text-xs font-medium rounded-lg transition-all ${cashPeriod === 'month' ? 'bg-[#FF7A00] text-white shadow-lg' : 'text-gray-400'}`}
              >
                Mês
              </button>
          </div>

          {/* Caixa Detalhado Summary */}
          <div className="grid grid-cols-2 gap-3">
             <div className="bg-[#2E2E2E] p-4 rounded-2xl border border-white/5 col-span-2">
                <p className="text-gray-400 text-sm">
                    Saldo 
                    {cashPeriod === 'day' ? ' do Dia' : cashPeriod === 'week' ? ' Semanal' : ' Mensal'}
                </p>
                <h2 className={`text-3xl font-bold ${cashSaldo >= 0 ? 'text-white' : 'text-red-400'}`}>
                  R$ {cashSaldo.toFixed(2)}
                </h2>
             </div>
             <div className="bg-[#2E2E2E] p-3 rounded-xl border border-white/5">
                <div className="flex items-center gap-2 mb-1">
                   <div className="w-2 h-2 rounded-full bg-green-500"></div>
                   <p className="text-xs text-gray-400">Entradas</p>
                </div>
                <p className="text-green-500 font-bold">R$ {cashEntradas.toFixed(2)}</p>
             </div>
             <div className="bg-[#2E2E2E] p-3 rounded-xl border border-white/5">
                <div className="flex items-center gap-2 mb-1">
                   <div className="w-2 h-2 rounded-full bg-red-500"></div>
                   <p className="text-xs text-gray-400">Saídas</p>
                </div>
                <p className="text-red-400 font-bold">R$ {cashSaidas.toFixed(2)}</p>
             </div>
          </div>

          <div className="flex justify-between items-center">
             <h3 className="text-white font-bold">Movimentações ({filteredCash.length})</h3>
             <button 
                onClick={() => setShowExpenseModal(true)}
                className="text-xs bg-red-500/10 text-red-400 px-3 py-2 rounded-lg font-medium hover:bg-red-500/20 flex items-center gap-1"
             >
                {ICONS.Add} Despesa
             </button>
          </div>

          <div className="space-y-3">
            {filteredCash.map(entry => (
               <div key={entry.id} className="flex justify-between items-center p-3 bg-[#2E2E2E] rounded-xl border border-white/5 group">
                  <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${entry.tipo === 'ENTRADA' ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'}`}>
                      {entry.tipo === 'ENTRADA' ? ICONS.Trending : ICONS.Alert}
                    </div>
                    <div>
                      <p className="text-white font-medium">{entry.descricao}</p>
                      <p className="text-xs text-gray-500">{format(new Date(entry.data), 'dd/MM HH:mm')}</p>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-1">
                    <span className={`font-bold ${entry.tipo === 'ENTRADA' ? 'text-green-400' : 'text-red-400'}`}>
                        {entry.tipo === 'ENTRADA' ? '+' : '-'} R$ {entry.valor.toFixed(2)}
                    </span>
                    <button 
                        onClick={() => setDeleteCashId(entry.id)}
                        className="text-xs text-red-500/50 hover:text-red-500"
                    >
                        {ICONS.Trash}
                    </button>
                  </div>
               </div>
            ))}
            {filteredCash.length === 0 && (
              <p className="text-center text-gray-500 py-4 text-sm">
                  Nenhuma movimentação {cashPeriod === 'day' ? 'hoje' : 'neste período'}.
              </p>
            )}
          </div>
        </div>
      )}

      {/* Confirmation Modal */}
      <Modal isOpen={!!confirmItem} onClose={() => setConfirmItem(null)} title="Confirmar Recebimento">
        <div className="space-y-6 text-center">
           <div className="w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center text-green-500 mx-auto">
             {ICONS.Check}
           </div>
           <div>
             {confirmItem && (
               <>
                 <p className="text-gray-300">Receber de <strong className="text-white">{confirmItem.cliente_nome}</strong>?</p>
                 <p className="text-xs text-gray-500 mt-2 mb-4">Parcela {confirmItem.numero_parcela} • Vencimento {format(new Date(confirmItem.data_vencimento), 'dd/MM/yyyy')}</p>

                 <div className="text-left bg-[#1A1A1A] p-3 rounded-lg border border-white/10">
                     <Input 
                        label="Valor Recebido (R$)" 
                        type="number"
                        step="0.01"
                        value={paymentAmount}
                        onChange={(e) => setPaymentAmount(e.target.value)}
                        className="text-center font-bold text-xl text-green-500"
                     />
                     <p className="text-[10px] text-gray-500 mt-2 text-center">
                        * Se o valor for diferente, a diferença será somada ou descontada na próxima parcela.
                     </p>
                 </div>
               </>
             )}
           </div>
           <div className="grid grid-cols-2 gap-3">
             <Button variant="secondary" onClick={() => setConfirmItem(null)}>Cancelar</Button>
             <Button onClick={handlePay} isLoading={loading} className="bg-green-600 hover:bg-green-700 border-none shadow-green-900/20">
               Confirmar
             </Button>
           </div>
        </div>
      </Modal>

      {/* Add Expense Modal */}
      <Modal isOpen={showExpenseModal} onClose={() => setShowExpenseModal(false)} title="Nova Despesa">
         <div className="space-y-4">
            <Input 
               label="Descrição" 
               placeholder="Ex: Combustível, Almoço..."
               value={expenseForm.descricao}
               onChange={(e) => setExpenseForm(prev => ({ ...prev, descricao: e.target.value }))}
            />
            <Input 
               label="Valor (R$)" 
               type="number"
               step="0.01"
               placeholder="0,00"
               value={expenseForm.valor}
               onChange={(e) => setExpenseForm(prev => ({ ...prev, valor: e.target.value }))}
            />
            <Button 
               fullWidth 
               onClick={handleAddExpense} 
               isLoading={loading}
               variant="danger"
               className="mt-2"
            >
               Lançar Saída
            </Button>
         </div>
      </Modal>

      {/* Delete Cash Entry Modal */}
      <Modal isOpen={!!deleteCashId} onClose={() => setDeleteCashId(null)} title="Excluir Lançamento">
         <div className="text-center space-y-4">
             <div className="w-16 h-16 bg-red-500/20 rounded-full flex items-center justify-center text-red-500 mx-auto">
                {ICONS.Trash}
             </div>
             <p className="text-gray-300">Tem certeza que deseja excluir este lançamento do caixa? O saldo será recalculado.</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setDeleteCashId(null)}>Cancelar</Button>
                 <Button variant="danger" onClick={handleDeleteCashEntry} isLoading={loading}>Excluir</Button>
             </div>
         </div>
      </Modal>
    </div>
  );
};

export default Payments;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Card, Badge, Modal, Input } from '../components/ui';
import { ReceiptModal } from '../components/ReceiptModal';
import { dataService, authService } from '../services/mockSupabase';
import { Client, Sale, Installment } from '../types';
import { format } from 'date-fns';

const ClientDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const session = authService.getSession();

  const [client, setClient] = useState<Client | null>(null);
  const [sales, setSales] = useState<Sale[]>([]);
  const [installmentsMap, setInstallmentsMap] = useState<Record<string, Installment[]>>({});
  const [expandedSale, setExpandedSale] = useState<string | null>(null);

  // Modals
  const [editInstallment, setEditInstallment] = useState<Installment | null>(null);
  const [payInstallment, setPayInstallment] = useState<Installment | null>(null);
  const [paymentAmount, setPaymentAmount] = useState('');

  const [deleteSaleId, setDeleteSaleId] = useState<string | null>(null);
  const [isEditClientOpen, setIsEditClientOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  // Receipt Modal State
  const [receiptData, setReceiptData] = useState<{ type: 'SALE' | 'INSTALLMENT', data: any } | null>(null);

  // Forms
  const [editForm, setEditForm] = useState({ valor: '', data_vencimento: '' });
  const [clientForm, setClientForm] = useState<Partial<Client>>({});

  const loadData = async () => {
    if (!id) return;
    const clientData = await dataService.getClientById(id);
    const salesData = await dataService.getSalesByClient(id);
    setClient(clientData || null);
    setSales(salesData);

    // Load installments for all sales to calculate totals
    const map: Record<string, Installment[]> = {};
    for (const sale of salesData) {
      map[sale.id] = await dataService.getInstallmentsBySale(sale.id);
    }
    setInstallmentsMap(map);
  };

  useEffect(() => {
    loadData();
  }, [id]);

  const toggleSale = async (saleId: string) => {
    if (expandedSale === saleId) {
      setExpandedSale(null);
    } else {
      setExpandedSale(saleId);
      const data = await dataService.getInstallmentsBySale(saleId);
      setInstallmentsMap(prev => ({ ...prev, [saleId]: data }));
    }
  };

  // --- ACTIONS ---

  const handleOpenEditClient = () => {
      if(client) {
          setClientForm(client);
          setIsEditClientOpen(true);
      }
  };

  const handleSaveClient = async () => {
      if(!client || !id) return;
      if(!clientForm.nome || !clientForm.telefone) {
          alert("Nome e Telefone são obrigatórios.");
          return;
      }
      setLoading(true);
      try {
          // Sanitize: Remove ID from update payload
          const { id: _, ...updates } = clientForm as any;
          await dataService.updateClient(id, updates);
          await loadData();
          setIsEditClientOpen(false);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  const handleDeleteSale = async () => {
      if (!deleteSaleId) return;
      setLoading(true);
      try {
          await dataService.deleteSale(deleteSaleId);
          await loadData();
          setDeleteSaleId(null);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  const handleOpenEdit = (inst: Installment) => {
    setEditInstallment(inst);
    setEditForm({
      valor: inst.valor.toString(),
      data_vencimento: inst.data_vencimento.split('T')[0] // Format for date input
    });
  };

  const handleSaveEdit = async () => {
    if (!editInstallment) return;
    setLoading(true);
    try {
      await dataService.updateInstallment(editInstallment.id, {
        valor: parseFloat(editForm.valor),
        data_vencimento: new Date(editForm.data_vencimento).toISOString()
      });
      await loadData(); // Refresh all
      setEditInstallment(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleOpenPay = (inst: Installment) => {
      setPayInstallment(inst);
      setPaymentAmount(inst.valor.toFixed(2));
  };

  const handlePay = async () => {
    if (!payInstallment || !session || !paymentAmount) return;
    setLoading(true);
    try {
      const actualPaid = parseFloat(paymentAmount);
      await dataService.payInstallment(payInstallment.id, session.id, actualPaid);
      await loadData();

      // Auto open receipt after payment
      const updatedInst = { 
          ...payInstallment, 
          pago: true, 
          data_pagamento: new Date().toISOString(),
          valor: actualPaid // Reflect what was paid in the receipt
      };
      setReceiptData({ type: 'INSTALLMENT', data: updatedInst });

      setPayInstallment(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  // --- STATS ---
  const totalBought = sales.reduce((acc, s) => acc + s.valor_total, 0);
  const allInstallments: Installment[] = (Object.values(installmentsMap) as Installment[][]).reduce((acc, val) => acc.concat(val), [] as Installment[]);
  const totalDebt = allInstallments.filter(i => !i.pago).reduce((acc, i) => acc + i.valor, 0);

  if (!client) return <div className="p-5 text-center text-gray-500">Carregando...</div>;

  return (
    <div className="flex flex-col h-screen bg-[#1A1A1A]">
      {/* Header */}
      <div className="bg-[#2E2E2E] p-4 flex items-center gap-4 border-b border-white/5 sticky top-0 z-10">
        <button onClick={() => navigate(-1)} className="text-white">
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold text-white flex-1 truncate">{client.nome}</h1>
        <button onClick={handleOpenEditClient} className="text-[#FF7A00]">
            {ICONS.Edit}
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar pb-24 space-y-6">

        {/* Info Card */}
        <Card>
           <div className="flex items-start justify-between">
              <div className="space-y-1">
                 <div className="flex items-center gap-2 text-gray-400 text-sm">
                    {ICONS.Phone} {client.telefone}
                 </div>
                 <div className="flex items-center gap-2 text-gray-400 text-sm">
                    {ICONS.Map} {client.bairro}, {client.cidade}
                 </div>
              </div>
              <a 
                href={`https://wa.me/55${client.telefone.replace(/\D/g, '')}`} 
                target="_blank" 
                className="bg-green-500/10 text-green-500 p-2 rounded-lg"
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
              </a>
           </div>
        </Card>

        {/* Financial Summary */}
        <div className="grid grid-cols-2 gap-4">
           <Card className="bg-[#2E2E2E] border-none">
              <p className="text-gray-400 text-xs">Total Comprado</p>
              <p className="text-white font-bold text-lg">R$ {totalBought.toFixed(2)}</p>
           </Card>
           <Card className="bg-[#2E2E2E] border-none">
              <p className="text-gray-400 text-xs">Em Aberto</p>
              <p className="text-[#FF7A00] font-bold text-lg">R$ {totalDebt.toFixed(2)}</p>
           </Card>
        </div>

        {/* Sales History */}
        <h2 className="text-white font-bold text-lg pt-2">Histórico de Compras</h2>
        <div className="space-y-3">
           {sales.map(sale => {
              const installments = installmentsMap[sale.id] || [];
              const isExpanded = expandedSale === sale.id;

              return (
                <div key={sale.id} className="bg-[#2E2E2E] rounded-2xl overflow-hidden border border-white/5">
                   {/* Sale Header */}
                   <div 
                      onClick={() => toggleSale(sale.id)}
                      className="p-4 flex justify-between items-center cursor-pointer active:bg-[#353535]"
                   >
                      <div>
                         <div className="flex items-center gap-2 mb-1">
                            <span className="text-white font-bold">Compra #{sale.id.substring(0,6)}</span>
                            <Badge status={sale.status} />
                         </div>
                         <p className="text-gray-500 text-xs">
                            {format(new Date(sale.data_venda), 'dd/MM/yyyy')} • {sale.qtd_parcelas} parcelas
                         </p>
                      </div>
                      <div className="text-right">
                         <p className="text-[#FF7A00] font-bold">R$ {sale.valor_total.toFixed(2)}</p>
                         <div className="flex justify-end mt-1 text-gray-500">
                           {isExpanded ? ICONS.Up : ICONS.Down}
                         </div>
                      </div>
                   </div>

                   {/* Expanded Details */}
                   {isExpanded && (
                      <>
                        <div className="bg-[#262626] border-t border-white/5 p-3 space-y-2">
                           <div className="flex justify-between px-1 pb-2">
                                <button 
                                    onClick={(e) => { e.stopPropagation(); setReceiptData({ type: 'SALE', data: sale }); }}
                                    className="text-xs text-blue-400 flex items-center gap-1 hover:text-blue-300"
                                >
                                    {ICONS.Printer} Imprimir Recibo Venda
                                </button>
                                <button 
                                    onClick={(e) => { e.stopPropagation(); setDeleteSaleId(sale.id); }}
                                    className="text-xs text-red-400 flex items-center gap-1 hover:text-red-300"
                                >
                                    {ICONS.Trash} Excluir Venda
                                </button>
                           </div>
                           {installments.map(inst => (
                              <div key={inst.id} className="flex items-center justify-between p-3 bg-[#1F1F1F] rounded-xl border border-white/5">
                                 <div className="flex items-center gap-3">
                                    <div className={`w-2 h-2 rounded-full ${inst.pago ? 'bg-green-500' : 'bg-[#FF7A00]'}`} />
                                    <div>
                                       <p className="text-white text-sm font-medium">Parcela {inst.numero_parcela}</p>
                                       <p className="text-gray-500 text-xs">{format(new Date(inst.data_vencimento), 'dd/MM/yyyy')}</p>
                                    </div>
                                 </div>
                                 <div className="flex items-center gap-3">
                                    <span className={`text-sm font-bold ${inst.pago ? 'text-green-500 line-through opacity-50' : 'text-white'}`}>
                                       R$ {inst.valor.toFixed(2)}
                                    </span>

                                    {inst.pago ? (
                                        <button 
                                            onClick={() => setReceiptData({ type: 'INSTALLMENT', data: inst })}
                                            className="p-1.5 text-blue-400 hover:text-blue-300 bg-blue-500/10 rounded-lg"
                                            title="Comprovante"
                                        >
                                            {ICONS.Printer}
                                        </button>
                                    ) : (
                                       <div className="flex gap-1">
                                         <button 
                                            onClick={() => handleOpenEdit(inst)}
                                            className="p-1.5 text-gray-400 hover:text-white bg-white/5 rounded-lg"
                                         >
                                            {ICONS.Edit}
                                         </button>
                                         <button 
                                            onClick={() => handleOpenPay(inst)}
                                            className="p-1.5 text-green-500 hover:text-green-400 bg-green-500/10 rounded-lg"
                                         >
                                            {ICONS.Check}
                                         </button>
                                       </div>
                                    )}
                                 </div>
                              </div>
                           ))}
                        </div>
                      </>
                   )}
                </div>
              );
           })}
        </div>
      </div>

      {/* Edit Client Modal */}
      <Modal isOpen={isEditClientOpen} onClose={() => setIsEditClientOpen(false)} title="Editar Cliente">
        <div className="space-y-4">
          <Input 
            label="Nome Completo" 
            value={clientForm.nome || ''} 
            onChange={e => setClientForm({...clientForm, nome: e.target.value})}
          />
          <Input 
            label="Telefone (WhatsApp)" 
            type="tel"
            value={clientForm.telefone || ''} 
            onChange={e => setClientForm({...clientForm, telefone: e.target.value})}
          />
          <Input 
            label="Endereço" 
            value={clientForm.endereco || ''} 
            onChange={e => setClientForm({...clientForm, endereco: e.target.value})}
          />
          <div className="grid grid-cols-2 gap-4">
            <Input 
                label="Bairro" 
                value={clientForm.bairro || ''} 
                onChange={e => setClientForm({...clientForm, bairro: e.target.value})}
            />
            <Input 
                label="Cidade" 
                value={clientForm.cidade || ''} 
                onChange={e => setClientForm({...clientForm, cidade: e.target.value})}
            />
          </div>
          <Button fullWidth onClick={handleSaveClient} isLoading={loading}>
            Salvar Alterações
          </Button>
        </div>
      </Modal>

      {/* Edit Installment Modal */}
      <Modal isOpen={!!editInstallment} onClose={() => setEditInstallment(null)} title="Editar Parcela">
        <div className="space-y-4">
           <Input 
              label="Valor (R$)" 
              type="number"
              step="0.01"
              value={editForm.valor}
              onChange={(e) => setEditForm(prev => ({ ...prev, valor: e.target.value }))}
           />
           <Input 
              label="Data de Vencimento" 
              type="date"
              value={editForm.data_vencimento}
              onChange={(e) => setEditForm(prev => ({ ...prev, data_vencimento: e.target.value }))}
           />
           <div className="pt-2">
             <Button fullWidth onClick={handleSaveEdit} isLoading={loading}>
               Salvar Alterações
             </Button>
           </div>
        </div>
      </Modal>

      {/* Payment Confirmation Modal */}
      <Modal isOpen={!!payInstallment} onClose={() => setPayInstallment(null)} title="Receber Parcela">
        <div className="text-center space-y-4">
           <div className="w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center text-green-500 mx-auto">
             {ICONS.Check}
           </div>
           <div>
             <p className="text-gray-300">Confirmar recebimento desta parcela?</p>
             <p className="text-xs text-gray-500 mt-2 mb-4">Parcela {payInstallment?.numero_parcela} - Vencimento {payInstallment ? format(new Date(payInstallment.data_vencimento), 'dd/MM/yyyy') : ''}</p>

             <div className="text-left bg-[#1A1A1A] p-3 rounded-lg border border-white/10">
                 <Input 
                    label="Valor Recebido (R$)" 
                    type="number"
                    step="0.01"
                    value={paymentAmount}
                    onChange={(e) => setPaymentAmount(e.target.value)}
                    className="text-center font-bold text-xl text-green-500"
                 />
                 <p className="text-[10px] text-gray-500 mt-2 text-center">
                    * A diferença será automaticamente ajustada na próxima parcela.
                 </p>
             </div>
           </div>
           <div className="grid grid-cols-2 gap-3 pt-2">
             <Button variant="secondary" onClick={() => setPayInstallment(null)}>Cancelar</Button>
             <Button onClick={handlePay} isLoading={loading} className="bg-green-600 hover:bg-green-700 border-none">
               Confirmar
             </Button>
           </div>
        </div>
      </Modal>

      {/* Delete Sale Modal */}
      <Modal isOpen={!!deleteSaleId} onClose={() => setDeleteSaleId(null)} title="Excluir Venda">
         <div className="text-center space-y-4">
             <div className="w-16 h-16 bg-red-500/20 rounded-full flex items-center justify-center text-red-500 mx-auto">
                {ICONS.Trash}
             </div>
             <p className="text-gray-300">Tem certeza que deseja cancelar e excluir esta venda? Todas as parcelas serão removidas.</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setDeleteSaleId(null)}>Cancelar</Button>
                 <Button variant="danger" onClick={handleDeleteSale} isLoading={loading}>Excluir</Button>
             </div>
         </div>
      </Modal>

      {/* Receipt Modal */}
      {receiptData && (
          <ReceiptModal 
            isOpen={!!receiptData} 
            onClose={() => setReceiptData(null)} 
            type={receiptData.type}
            data={receiptData.data}
            client={client}
          />
      )}

    </div>
  );
};

