  // Modals
  const [editInstallment, setEditInstallment] = useState<Installment | null>(null);
  const [payInstallment, setPayInstallment] = useState<Installment | null>(null);
  const [paymentAmount, setPaymentAmount] = useState('');

  const [deleteSaleId, setDeleteSaleId] = useState<string | null>(null);
  const [returnSaleId, setReturnSaleId] = useState<string | null>(null);
  const [isEditClientOpen, setIsEditClientOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  // Receipt Modal State
  const [receiptData, setReceiptData] = useState<{ type: 'SALE' | 'INSTALLMENT', data: any } | null>(null);

  // Forms
  const [editForm, setEditForm] = useState({ valor: '', data_vencimento: '' });
  const [clientForm, setClientForm] = useState<Partial<Client>>({});

  const loadData = async () => {
    if (!id) return;
    const clientData = await dataService.getClientById(id);
    const salesData = await dataService.getSalesByClient(id);
    setClient(clientData || null);
    setSales(salesData);

    // Load installments for all sales to calculate totals
    const map: Record<string, Installment[]> = {};
    for (const sale of salesData) {
      map[sale.id] = await dataService.getInstallmentsBySale(sale.id);
    }
    setInstallmentsMap(map);
  };

  useEffect(() => {
    loadData();
  }, [id]);

  const toggleSale = async (saleId: string) => {
    if (expandedSale === saleId) {
      setExpandedSale(null);
    } else {
      setExpandedSale(saleId);
      const data = await dataService.getInstallmentsBySale(saleId);
      setInstallmentsMap(prev => ({ ...prev, [saleId]: data }));
    }
  };

  // --- ACTIONS ---

  const handleOpenEditClient = () => {
      if(client) {
          setClientForm(client);
          setIsEditClientOpen(true);
      }
  };

  const handleSaveClient = async () => {
      if(!client || !id) return;
      if(!clientForm.nome || !clientForm.telefone) {
          alert("Nome e Telefone são obrigatórios.");
          return;
      }
      setLoading(true);
      try {
          // Sanitize: Remove ID from update payload
          const { id: _, ...updates } = clientForm as any;
          await dataService.updateClient(id, updates);
          await loadData();
          setIsEditClientOpen(false);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  const handleDeleteSale = async () => {
      if (!deleteSaleId) return;
      setLoading(true);
      try {
          await dataService.deleteSale(deleteSaleId);
          await loadData();
          setDeleteSaleId(null);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  const handleReturnSale = async () => {
      if (!returnSaleId) return;
      setLoading(true);
      try {
          await dataService.returnSale(returnSaleId);
          await loadData();
          setReturnSaleId(null);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  const handleOpenEdit = (inst: Installment) => {
    setEditInstallment(inst);
    setEditForm({
      valor: inst.valor.toString(),
      data_vencimento: inst.data_vencimento.split('T')[0] // Format for date input
    });
  };

  const handleSaveEdit = async () => {
    if (!editInstallment) return;
    setLoading(true);
    try {
      await dataService.updateInstallment(editInstallment.id, {
        valor: parseFloat(editForm.valor),
        data_vencimento: new Date(editForm.data_vencimento).toISOString()
      });
      await loadData(); // Refresh all
      setEditInstallment(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleOpenPay = (inst: Installment) => {
      setPayInstallment(inst);
      setPaymentAmount(inst.valor.toFixed(2));
  };

  const handlePay = async () => {
    if (!payInstallment || !session || !paymentAmount) return;
    setLoading(true);
    try {
      const actualPaid = parseFloat(paymentAmount);
      await dataService.payInstallment(payInstallment.id, session.id, actualPaid);
      await loadData();

      // Auto open receipt after payment
      const updatedInst = { 
          ...payInstallment, 
          pago: true, 
          data_pagamento: new Date().toISOString(),
          valor: actualPaid // Reflect what was paid in the receipt
      };
      setReceiptData({ type: 'INSTALLMENT', data: updatedInst });

      setPayInstallment(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  // --- STATS ---
  const totalBought = sales.filter(s => s.status !== 'DEVOLVIDO').reduce((acc, s) => acc + s.valor_total, 0);
  const allInstallments: Installment[] = (Object.values(installmentsMap) as Installment[][]).reduce((acc, val) => acc.concat(val), [] as Installment[]);
  const totalDebt = allInstallments.filter(i => !i.pago).reduce((acc, i) => acc + i.valor, 0);

  if (!client) return <div className="p-5 text-center text-gray-500">Carregando...</div>;

  return (
    <div className="flex flex-col h-screen bg-[#1A1A1A]">
      {/* Header */}
      <div className="bg-[#2E2E2E] p-4 flex items-center gap-4 border-b border-white/5 sticky top-0 z-10">
        <button onClick={() => navigate(-1)} className="text-white">
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold text-white flex-1 truncate">{client.nome}</h1>
        <button onClick={handleOpenEditClient} className="text-[#FF7A00]">
            {ICONS.Edit}
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar pb-24 space-y-6">

        {/* Info Card */}
        <Card>
           <div className="flex items-start justify-between">
              <div className="space-y-1">
                 <div className="flex items-center gap-2 text-gray-400 text-sm">
                    {ICONS.Phone} {client.telefone}
                 </div>
                 <div className="flex items-center gap-2 text-gray-400 text-sm">
                    {ICONS.Map} {client.bairro}, {client.cidade}
                 </div>
              </div>
              <a 
                href={`https://wa.me/55${client.telefone.replace(/\D/g, '')}`} 
                target="_blank" 
                className="bg-green-500/10 text-green-500 p-2 rounded-lg"
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"/></svg>
              </a>
           </div>
        </Card>

        {/* Financial Summary */}
        <div className="grid grid-cols-2 gap-4">
           <Card className="bg-[#2E2E2E] border-none">
              <p className="text-gray-400 text-xs">Total Comprado (Válido)</p>
              <p className="text-white font-bold text-lg">R$ {totalBought.toFixed(2)}</p>
           </Card>
           <Card className="bg-[#2E2E2E] border-none">
              <p className="text-gray-400 text-xs">Em Aberto</p>
              <p className="text-[#FF7A00] font-bold text-lg">R$ {totalDebt.toFixed(2)}</p>
           </Card>
        </div>

        {/* Sales History */}
        <h2 className="text-white font-bold text-lg pt-2">Histórico de Compras</h2>
        <div className="space-y-3">
           {sales.map(sale => {
              const installments = installmentsMap[sale.id] || [];
              const isExpanded = expandedSale === sale.id;
              const isReturned = sale.status === 'DEVOLVIDO';

              return (
                <div key={sale.id} className={`bg-[#2E2E2E] rounded-2xl overflow-hidden border ${isReturned ? 'border-red-500/20 opacity-70' : 'border-white/5'}`}>
                   {/* Sale Header */}
                   <div 
                      onClick={() => toggleSale(sale.id)}
                      className="p-4 flex justify-between items-center cursor-pointer active:bg-[#353535]"
                   >
                      <div>
                         <div className="flex items-center gap-2 mb-1">
                            <span className="text-white font-bold">Compra #{sale.id.substring(0,6)}</span>
                            <Badge status={sale.status} />
                         </div>
                         <p className="text-gray-500 text-xs">
                            {format(new Date(sale.data_venda), 'dd/MM/yyyy')} • {sale.qtd_parcelas} parcelas
                         </p>
                      </div>
                      <div className="text-right">
                         <p className={`font-bold ${isReturned ? 'text-gray-400 line-through' : 'text-[#FF7A00]'}`}>
                            R$ {sale.valor_total.toFixed(2)}
                         </p>
                         <div className="flex justify-end mt-1 text-gray-500">
                           {isExpanded ? ICONS.Up : ICONS.Down}
                         </div>
                      </div>
                   </div>

                   {/* Expanded Details */}
                   {isExpanded && (
                      <>
                        <div className="bg-[#262626] border-t border-white/5 p-3 space-y-2">
                           <div className="flex justify-between px-1 pb-2 gap-2 flex-wrap">
                                <button 
                                    onClick={(e) => { e.stopPropagation(); setReceiptData({ type: 'SALE', data: sale }); }}
                                    className="text-xs text-blue-400 flex items-center gap-1 hover:text-blue-300"
                                >
                                    {ICONS.Printer} Recibo
                                </button>

                                {!isReturned && (
                                    <>
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); setReturnSaleId(sale.id); }}
                                            className="text-xs text-orange-400 flex items-center gap-1 hover:text-orange-300"
                                        >
                                            {ICONS.Return} Devolver Produto
                                        </button>
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); setDeleteSaleId(sale.id); }}
                                            className="text-xs text-red-400 flex items-center gap-1 hover:text-red-300"
                                        >
                                            {ICONS.Trash} Excluir Registro
                                        </button>
                                    </>
                                )}
                           </div>

                           {installments.length === 0 && isReturned && (
                               <p className="text-center text-sm text-gray-500 py-2 italic">Parcelas e pagamentos anulados.</p>
                           )}

                           {installments.map(inst => (
                              <div key={inst.id} className="flex items-center justify-between p-3 bg-[#1F1F1F] rounded-xl border border-white/5">
                                 <div className="flex items-center gap-3">
                                    <div className={`w-2 h-2 rounded-full ${inst.pago ? 'bg-green-500' : 'bg-[#FF7A00]'}`} />
                                    <div>
                                       <p className="text-white text-sm font-medium">Parcela {inst.numero_parcela}</p>
                                       <p className="text-gray-500 text-xs">{format(new Date(inst.data_vencimento), 'dd/MM/yyyy')}</p>
                                    </div>
                                 </div>
                                 <div className="flex items-center gap-3">
                                    <span className={`text-sm font-bold ${inst.pago ? 'text-green-500 line-through opacity-50' : 'text-white'}`}>
                                       R$ {inst.valor.toFixed(2)}
                                    </span>

                                    {inst.pago ? (
                                        <button 
                                            onClick={() => setReceiptData({ type: 'INSTALLMENT', data: inst })}
                                            className="p-1.5 text-blue-400 hover:text-blue-300 bg-blue-500/10 rounded-lg"
                                            title="Comprovante"
                                        >
                                            {ICONS.Printer}
                                        </button>
                                    ) : !isReturned && (
                                       <div className="flex gap-1">
                                         <button 
                                            onClick={() => handleOpenEdit(inst)}
                                            className="p-1.5 text-gray-400 hover:text-white bg-white/5 rounded-lg"
                                         >
                                            {ICONS.Edit}
                                         </button>
                                         <button 
                                            onClick={() => handleOpenPay(inst)}
                                            className="p-1.5 text-green-500 hover:text-green-400 bg-green-500/10 rounded-lg"
                                         >
                                            {ICONS.Check}
                                         </button>
                                       </div>
                                    )}
                                 </div>
                              </div>
                           ))}
                        </div>
                      </>
                   )}
                </div>
              );
           })}
        </div>
      </div>

      {/* Edit Client Modal */}
      <Modal isOpen={isEditClientOpen} onClose={() => setIsEditClientOpen(false)} title="Editar Cliente">
        <div className="space-y-4">
          <Input 
            label="Nome Completo" 
            value={clientForm.nome || ''} 
            onChange={e => setClientForm({...clientForm, nome: e.target.value})}
          />
          <Input 
            label="Telefone (WhatsApp)" 
            type="tel"
            value={clientForm.telefone || ''} 
            onChange={e => setClientForm({...clientForm, telefone: e.target.value})}
          />
          <Input 
            label="Endereço" 
            value={clientForm.endereco || ''} 
            onChange={e => setClientForm({...clientForm, endereco: e.target.value})}
          />
          <div className="grid grid-cols-2 gap-4">
            <Input 
                label="Bairro" 
                value={clientForm.bairro || ''} 
                onChange={e => setClientForm({...clientForm, bairro: e.target.value})}
            />
            <Input 
                label="Cidade" 
                value={clientForm.cidade || ''} 
                onChange={e => setClientForm({...clientForm, cidade: e.target.value})}
            />
          </div>
          <Button fullWidth onClick={handleSaveClient} isLoading={loading}>
            Salvar Alterações
          </Button>
        </div>
      </Modal>

      {/* Edit Installment Modal */}
      <Modal isOpen={!!editInstallment} onClose={() => setEditInstallment(null)} title="Editar Parcela">
        <div className="space-y-4">
           <Input 
              label="Valor (R$)" 
              type="number"
              step="0.01"
              value={editForm.valor}
              onChange={(e) => setEditForm(prev => ({ ...prev, valor: e.target.value }))}
           />
           <Input 
              label="Data de Vencimento" 
              type="date"
              value={editForm.data_vencimento}
              onChange={(e) => setEditForm(prev => ({ ...prev, data_vencimento: e.target.value }))}
           />
           <div className="pt-2">
             <Button fullWidth onClick={handleSaveEdit} isLoading={loading}>
               Salvar Alterações
             </Button>
           </div>
        </div>
      </Modal>

      {/* Payment Confirmation Modal */}
      <Modal isOpen={!!payInstallment} onClose={() => setPayInstallment(null)} title="Receber Parcela">
        <div className="text-center space-y-4">
           <div className="w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center text-green-500 mx-auto">
             {ICONS.Check}
           </div>
           <div>
             <p className="text-gray-300">Confirmar recebimento desta parcela?</p>
             <p className="text-xs text-gray-500 mt-2 mb-4">Parcela {payInstallment?.numero_parcela} - Vencimento {payInstallment ? format(new Date(payInstallment.data_vencimento), 'dd/MM/yyyy') : ''}</p>

             <div className="text-left bg-[#1A1A1A] p-3 rounded-lg border border-white/10">
                 <Input 
                    label="Valor Recebido (R$)" 
                    type="number"
                    step="0.01"
                    value={paymentAmount}
                    onChange={(e) => setPaymentAmount(e.target.value)}
                    className="text-center font-bold text-xl text-green-500"
                 />
                 <p className="text-[10px] text-gray-500 mt-2 text-center">
                    * A diferença será automaticamente ajustada na próxima parcela.
                 </p>
             </div>
           </div>
           <div className="grid grid-cols-2 gap-3 pt-2">
             <Button variant="secondary" onClick={() => setPayInstallment(null)}>Cancelar</Button>
             <Button onClick={handlePay} isLoading={loading} className="bg-green-600 hover:bg-green-700 border-none">
               Confirmar
             </Button>
           </div>
        </div>
      </Modal>

      {/* Return/Cancel Sale Modal */}
      <Modal isOpen={!!returnSaleId} onClose={() => setReturnSaleId(null)} title="Devolver Produto">
         <div className="text-center space-y-4">
             <div className="w-16 h-16 bg-orange-500/20 rounded-full flex items-center justify-center text-orange-500 mx-auto">
                {ICONS.Return}
             </div>
             <div>
                <p className="text-gray-300 font-bold mb-2">Confirmar devolução?</p>
                <p className="text-sm text-gray-400">
                    Ao confirmar, esta venda será marcada como <strong className="text-red-400">DEVOLVIDA</strong>.
                </p>
                <ul className="text-xs text-gray-500 mt-3 text-left bg-white/5 p-3 rounded-lg space-y-1">
                    <li>• Todas as parcelas pendentes serão canceladas.</li>
                    <li>• Pagamentos já recebidos serão removidos do caixa (estornados).</li>
                    <li>• O valor sairá dos relatórios de vendas.</li>
                </ul>
             </div>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setReturnSaleId(null)}>Cancelar</Button>
                 <Button variant="primary" onClick={handleReturnSale} isLoading={loading} className="bg-orange-600 hover:bg-orange-700 border-none">
                    Confirmar Devolução
                 </Button>
             </div>
         </div>
      </Modal>

      {/* Delete Sale Modal */}
      <Modal isOpen={!!deleteSaleId} onClose={() => setDeleteSaleId(null)} title="Excluir Registro">
         <div className="text-center space-y-4">
             <div className="w-16 h-16 bg-red-500/20 rounded-full flex items-center justify-center text-red-500 mx-auto">
                {ICONS.Trash}
             </div>
             <p className="text-gray-300">Tem certeza que deseja apagar permanentemente este registro?</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setDeleteSaleId(null)}>Cancelar</Button>
                 <Button variant="danger" onClick={handleDeleteSale} isLoading={loading}>Excluir</Button>
             </div>
         </div>
      </Modal>

      {/* Receipt Modal */}
      {receiptData && (
          <ReceiptModal 
            isOpen={!!receiptData} 
            onClose={() => setReceiptData(null)} 
            type={receiptData.type}
            data={receiptData.data}
            client={client}
          />
      )}

    </div>
  );
};

export default ClientDetails;

import React, { createContext, useContext, useEffect, useState } from 'react';

type Theme = 'dark' | 'light';

interface ThemeContextType {
  theme: Theme;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType>({
  theme: 'dark',
  toggleTheme: () => {},
});

export const useTheme = () => useContext(ThemeContext);

export const ThemeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [theme, setTheme] = useState<Theme>(() => {
    const saved = localStorage.getItem('cla_theme');
    return (saved as Theme) || 'dark';
  });

  useEffect(() => {
    const root = window.document.documentElement;
    const body = window.document.body;

    // 1. Update HTML Class
    if (theme === 'dark') {
      root.classList.add('dark');
      body.style.backgroundColor = '#1A1A1A'; // Match dark background
    } else {
      root.classList.remove('dark');
      body.style.backgroundColor = '#F3F4F6'; // Match light background (gray-100)
    }

    // 2. Save Preference
    localStorage.setItem('cla_theme', theme);

    // 3. Update Meta Theme Color (Status Bar / Browser Bar)
    // Dark: #1A1A1A, Light: #F3F4F6
    const metaThemeColor = document.querySelector("meta[name='theme-color']");
    if (metaThemeColor) {
        metaThemeColor.setAttribute("content", theme === 'dark' ? '#1A1A1A' : '#F3F4F6');
    }

  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

import React from 'react';
