import React from 'react';

// --- BUTTON ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger';
  fullWidth?: boolean;
  isLoading?: boolean;
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, variant = 'primary', fullWidth, isLoading, icon, className, ...props 
}) => {
  const baseStyles = "relative flex items-center justify-center gap-2 px-4 py-3 rounded-xl font-medium transition-all active:scale-[0.98] disabled:opacity-50 disabled:active:scale-100";

  // Adapted colors for light/dark
  const variants = {
    primary: "bg-[#FF7A00] text-white hover:bg-[#E66E00] shadow-lg shadow-orange-900/20",

    // Secondary: Light Gray in Light Mode, Dark Gray in Dark Mode
    secondary: "bg-gray-200 text-gray-800 hover:bg-gray-300 dark:bg-[#404040] dark:text-white dark:hover:bg-[#505050]",

    outline: "border-2 border-[#FF7A00] text-[#FF7A00] hover:bg-[#FF7A00]/10",

    ghost: "text-gray-500 hover:bg-gray-100 dark:text-gray-400 dark:hover:text-white dark:hover:bg-white/5",

    danger: "bg-red-500/10 text-red-500 border border-red-500/20 hover:bg-red-500/20"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${fullWidth ? 'w-full' : ''} ${className}`}
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? (
        <span className="w-5 h-5 border-2 border-current border-t-transparent rounded-full animate-spin" />
      ) : (
        <>
          {icon}
          {children}
        </>
      )}
    </button>
  );
};

