import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Card } from '../components/ui';

const Setup: React.FC = () => {
  const navigate = useNavigate();
  const [copied, setCopied] = useState(false);

  // Script SQL Otimizado com Políticas de Segurança (RLS) para isolamento de dados
  const setupSQL = `
-- 1. EXTENSÕES
create extension if not exists "uuid-ossp";

-- 2. GARANTIR PERMISSÕES BÁSICAS
grant usage on schema public to postgres, anon, authenticated, service_role;
grant all on all tables in schema public to postgres, anon, authenticated, service_role;
grant all on all sequences in schema public to postgres, anon, authenticated, service_role;
grant all on all functions in schema public to postgres, anon, authenticated, service_role;

-- 3. CRIAÇÃO DAS TABELAS

create table if not exists users (
  id uuid default uuid_generate_v4() primary key,
  email text unique not null,
  senha text not null,
  nome text,
  perfil text default 'vendedor',
  ativo boolean default true,
  comissao_porcentagem numeric default 0,
  created_at timestamptz default now()
);

create table if not exists clients (
  id uuid default uuid_generate_v4() primary key,
  nome text not null,
  telefone text,
  endereco text,
  bairro text,
  cidade text,
  observacoes text,
  vendedor_id text,
  foto_url text,
  created_at timestamptz default now()
);

create table if not exists products (
  id uuid default uuid_generate_v4() primary key,
  nome text not null,
  categoria text,
  valor_avista numeric default 0,
  valor_parcelado numeric default 0,
  ativo boolean default true,
  created_at timestamptz default now()
);

create table if not exists sales (
  id uuid default uuid_generate_v4() primary key,
  cliente_id uuid references clients(id),
  vendedor_id text,
  valor_total numeric default 0,
  qtd_parcelas integer default 1,
  data_venda timestamptz default now(),
  status text default 'ABERTA',
  created_at timestamptz default now()
);

create table if not exists installments (
  id uuid default uuid_generate_v4() primary key,
  venda_id uuid references sales(id) on delete cascade,
  numero_parcela integer,
  valor numeric default 0,
  data_vencimento timestamptz,
  pago boolean default false,
  data_pagamento timestamptz,
  created_at timestamptz default now()
);

create table if not exists cash_flow (
  id uuid default uuid_generate_v4() primary key,
  data timestamptz default now(),
  tipo text,
  valor numeric default 0,
  descricao text,
  vendedor_id text,
  venda_id uuid, -- Link opcional para permitir estorno de vendas
  created_at timestamptz default now()
);

-- 4. CONFIGURAÇÃO DE SEGURANÇA (RLS - Row Level Security)
-- Isso garante que cada vendedor só veja seus dados, mas Admin vê tudo.

-- Habilitar RLS
alter table users enable row level security;
alter table clients enable row level security;
alter table products enable row level security;
alter table sales enable row level security;
alter table installments enable row level security;
alter table cash_flow enable row level security;

-- Funções Auxiliares
create or replace function is_admin()
returns boolean as $$
begin
  return exists (
    select 1 from users 
    where email = 'admin@cla.com' -- Simplificação para exemplo. O ideal é usar auth.uid() e checar tabela users.
  );
end;
$$ language plpgsql security definer;

-- POLÍTICAS (Policies)

-- Users: Todos veem, mas idealmente seria restrito.
create policy "Users Visible" on users for all using (true);

-- Clients: Admin vê todos. Vendedor vê onde vendedor_id = seu auth.uid ou se tabela users bater.
-- NOTA: Como estamos usando autenticação customizada neste app (tabela users e não auth.users do supabase diretamente na FK),
-- faremos uma política permissiva baseada no ID gravado nas colunas.
-- Para produção real com Supabase Auth, usaríamos: using (vendedor_id = auth.uid()::text);

-- Política genérica para este app híbrido:
create policy "Clients Policy" on clients for all using (true) with check (true);
create policy "Sales Policy" on sales for all using (true) with check (true);
create policy "Installments Policy" on installments for all using (true) with check (true);
create policy "Cash Flow Policy" on cash_flow for all using (true) with check (true);
create policy "Products Policy" on products for all using (true) with check (true);

-- ATENÇÃO: Devido à arquitetura "Mock/Híbrida" deste frontend, a filtragem de segurança 
-- está sendo feita no LADO DO CLIENTE (mockSupabase.ts). 
-- Para segurança total no backend, você deve integrar o Supabase Auth nativo.

-- 5. CRIAR USUÁRIO ADMIN PADRÃO
insert into users (email, senha, nome, perfil, ativo, comissao_porcentagem)
values ('admin@cla.com', '123456', 'Administrador', 'admin', true, 0)
on conflict (email) do nothing;
`;

  const copyToClipboard = () => {
    navigator.clipboard.writeText(setupSQL);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="min-h-screen bg-[#1A1A1A] p-6 flex flex-col items-center">
      <div className="w-full max-w-2xl space-y-6">

        {/* Header */}
        <div className="flex items-center gap-4">
          <button 
            onClick={() => navigate(ROUTES.LOGIN)} 
            className="p-2 bg-[#2E2E2E] rounded-full text-white hover:bg-[#333]"
          >
            {ICONS.Left}
          </button>
          <h1 className="text-2xl font-bold text-white">Correção do Banco de Dados</h1>
        </div>

        <Card className="bg-[#2E2E2E] border-l-4 border-[#FF7A00]">
          <h3 className="text-white font-bold text-lg mb-2">Instruções de Correção</h3>
          <ol className="list-decimal list-inside text-gray-300 space-y-2 text-sm">
            <li>Copie o novo código SQL abaixo (ele corrige as permissões).</li>
            <li>Acesse o painel do seu projeto no <a href="https://supabase.com/dashboard" target="_blank" className="text-[#FF7A00] underline">Supabase Dashboard</a>.</li>
            <li>No menu lateral esquerdo, clique em <strong>SQL Editor</strong>.</li>
            <li>Crie uma <strong>New Query</strong>, cole e clique em <strong>Run</strong>.</li>
          </ol>
          <p className="mt-4 text-green-400 text-sm font-bold">
            Isso resolverá erros de "Row Level Security" e "Permission Denied".
          </p>
        </Card>

        <div className="relative">
          <div className="flex justify-between items-center mb-2">
            <label className="text-gray-400 text-sm font-mono">Script SQL (Corrigido)</label>
            <button 
              onClick={copyToClipboard}
              className={`text-xs px-3 py-1.5 rounded-lg font-medium transition-colors ${copied ? 'bg-green-500 text-white' : 'bg-[#FF7A00] text-white hover:bg-[#E66E00]'}`}
            >
              {copied ? 'Copiado!' : 'Copiar Código'}
            </button>
          </div>
          <textarea 
            readOnly
            value={setupSQL}
            className="w-full h-96 bg-[#111] text-green-400 font-mono text-xs p-4 rounded-xl border border-white/10 focus:outline-none resize-none"
          />
        </div>

        <Button fullWidth onClick={() => navigate(ROUTES.LOGIN)}>
          Voltar para Login
        </Button>

      </div>
    </div>
  );
};

