  // -- STORAGE HANDLER --
  uploadClientPhoto: async (file: File | Blob, clientId: string): Promise<string | null> => {
    if (isSupabaseConfigured) {
        const BUCKET = 'clientes-fotos';
        try {
            const timestamp = Date.now();
            const path = `clientes/${clientId}.jpg`;

            // 1. Try Upload
            const { error: uploadError } = await supabase.storage
                .from(BUCKET)
                .upload(path, file, { upsert: true });

            if (uploadError) {
                const errMsg = uploadError.message || (uploadError as any).error || '';

                // 2. AUTO-FIX: If bucket not found, try to create it
                if (errMsg.includes('Bucket not found') || errMsg.includes('not found')) {
                    console.warn("Bucket não encontrado. Tentando criar...");
                    const { error: createError } = await supabase.storage.createBucket(BUCKET, { 
                        public: true,
                        fileSizeLimit: 1048576, // 1MB
                        allowedMimeTypes: ['image/jpeg', 'image/png', 'image/webp']
                    });

                    if (!createError) {
                        // Retry upload after creation
                        const { error: retryError } = await supabase.storage
                            .from(BUCKET)
                            .upload(path, file, { upsert: true });

                        if (retryError) throw retryError;
                    } else {
                        // 3. Failed to auto-create (Permissions). Warn user.
                        alert("⚠️ CONFIGURAÇÃO NECESSÁRIA\n\nO local de armazenamento de fotos ('Bucket') não existe e não foi possível criá-lo automaticamente.\n\nAcesse: Configurações > Banco de Dados > Script de Correção.");
                        throw uploadError;
                    }
                } else {
                    console.error("Erro upload:", uploadError);
                    throw uploadError;
                }
            }

            // Get Public URL
            const { data: { publicUrl } } = supabase.storage
                .from(BUCKET)
                .getPublicUrl(path);

            return `${publicUrl}?t=${timestamp}`;

        } catch (e) {
            console.error("Upload Failed", e);
            return null;
        }
    } else {
        // Offline/Mock: Return null (component keeps existing base64 preview)
        return null; 
    }
  },

