-- 1. CRIAÇÃO DO BUCKET (Se não existir)
insert into storage.buckets (id, name, public)
values ('clientes-fotos', 'clientes-fotos', true)
on conflict (id) do nothing;

-- 2. POLÍTICAS DE SEGURANÇA (STORAGE RLS)

-- Permitir acesso público para visualização (Select)
create policy "Public Access"
  on storage.objects for select
  using ( bucket_id = 'clientes-fotos' );

-- Permitir upload apenas para usuários autenticados
create policy "Auth Upload"
  on storage.objects for insert
  with check ( bucket_id = 'clientes-fotos' and auth.role() = 'authenticated' );

-- Permitir atualização (substituir foto) para autenticados
create policy "Auth Update"
  on storage.objects for update
  with check ( bucket_id = 'clientes-fotos' and auth.role() = 'authenticated' );

-- Permitir deletar fotos
create policy "Auth Delete"
  on storage.objects for delete
  using ( bucket_id = 'clientes-fotos' and auth.role() = 'authenticated' );
`;

  const fixPhotoSQL = `
