  getInstallmentsByDate: async (date: Date): Promise<{ 
     daily: (Installment & { cliente_nome: string, venda_id: string })[], 
     overdueCount: number 
  }> => {
    const filterId = getUserFilter();
    const start = startOfDay(date).toISOString();
    const end = endOfDay(date).toISOString();

    if (isSupabaseConfigured) {
        let query = supabase
            .from('installments')
            .select('*, sales!inner(id, vendedor_id, clients(nome))')
            .eq('pago', false)
            .gte('data_vencimento', start)
            .lte('data_vencimento', end)
            .order('data_vencimento');

        if (filterId) {
             query = query.eq('sales.vendedor_id', filterId);
        }

        const { data: daily } = await query;

        let overdueQuery = supabase
            .from('installments')
            .select('*, sales!inner(vendedor_id)', { count: 'exact', head: true })
            .eq('pago', false)
            .lt('data_vencimento', startOfDay(new Date()).toISOString());

        if (filterId) {
            overdueQuery = overdueQuery.eq('sales.vendedor_id', filterId);
        }

        const { count: overdueCount } = await overdueQuery;

        return {
           daily: (daily || []).map((i: any) => ({ ...i, cliente_nome: i.sales?.clients?.nome || 'Desconhecido', venda_id: i.venda_id })),
           overdueCount: overdueCount || 0
        };
    }

    await delay(300);
    const installments = getStorage<Installment[]>('installments', []);
    const sales = getStorage<Sale[]>('sales', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);

    const visibleSales = filterId ? sales.filter(s => s.vendedor_id === filterId) : sales;
    const visibleSaleIds = visibleSales.map(s => s.id);

    const daily = installments
      .filter(i => visibleSaleIds.includes(i.venda_id) && !i.pago && isSameDay(new Date(i.data_vencimento), date))
      .map(i => {
        const sale = sales.find(s => s.id === i.venda_id);
        const client = clients.find(c => c.id === sale?.cliente_id);
        return { ...i, cliente_nome: client?.nome || 'Desconhecido', venda_id: i.venda_id };
      });

    const overdueCount = installments.filter(i => visibleSaleIds.includes(i.venda_id) && !i.pago && new Date(i.data_vencimento) < startOfDay(new Date())).length;

    return { daily, overdueCount };
  },

  getDueInstallments: async (): Promise<(Installment & { cliente_nome: string, venda_id: string })[]> => {
    const filterId = getUserFilter();
    const today = new Date();
    today.setHours(23, 59, 59, 999);

    if (isSupabaseConfigured) {
        let query = supabase
            .from('installments')
            .select('*, sales!inner(id, vendedor_id, clients(nome))')
            .eq('pago', false)
            .lte('data_vencimento', today.toISOString())
            .order('data_vencimento');
        if (filterId) query = query.eq('sales.vendedor_id', filterId);
        const { data } = await query;
        return (data || []).map((i: any) => ({ ...i, cliente_nome: i.sales?.clients?.nome || 'Desconhecido', venda_id: i.venda_id }));
    }

    await delay(300);
    const installments = getStorage<Installment[]>('installments', []);
    const sales = getStorage<Sale[]>('sales', []);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
    const visibleSales = filterId ? sales.filter(s => s.vendedor_id === filterId) : sales;
    const visibleSaleIds = visibleSales.map(s => s.id);

    return installments
      .filter(i => visibleSaleIds.includes(i.venda_id) && !i.pago && new Date(i.data_vencimento) <= today)
      .map(i => {
        const sale = sales.find(s => s.id === i.venda_id);
        const client = clients.find(c => c.id === sale?.cliente_id);
        return { ...i, cliente_nome: client?.nome || 'Desconhecido', venda_id: i.venda_id };
      })
      .sort((a, b) => new Date(a.data_vencimento).getTime() - new Date(b.data_vencimento).getTime());
  },

  payInstallment: async (installmentId: string, vendedorId: string, actualAmountPaid?: number): Promise<void> => {
    let currentInst: Installment | null = null;

    if (isSupabaseConfigured) {
        const { data: inst } = await supabase.from('installments').select('*').eq('id', installmentId).single();
        if (!inst || inst.pago) return;
        currentInst = inst;

        const paidValue = actualAmountPaid !== undefined ? actualAmountPaid : inst.valor;
        const difference = inst.valor - paidValue;

        await supabase.from('installments').update({ 
            pago: true, 
            data_pagamento: new Date().toISOString(),
            valor: paidValue 
        }).eq('id', installmentId);

        await supabase.from('cash_flow').insert([{ 
            tipo: 'ENTRADA', 
            valor: paidValue, 
            descricao: `Pagamento Parcela ${inst.numero_parcela}`, 
            vendedor_id: vendedorId, 
            venda_id: inst.venda_id,
            data: new Date().toISOString() 
        }]);

        if (Math.abs(difference) > 0.01) {
            const { data: next } = await supabase
                .from('installments')
                .select('*')
                .eq('venda_id', inst.venda_id)
                .gt('numero_parcela', inst.numero_parcela)
                .order('numero_parcela')
                .limit(1)
                .single();
            if (next) {
                await supabase.from('installments').update({
                    valor: next.valor + difference
                }).eq('id', next.id);
            }
        }

        const { data: allInst } = await supabase.from('installments').select('pago').eq('venda_id', inst.venda_id);
        if (allInst) {
             const allPaid = allInst.every((i: any) => i.pago);
             const somePaid = allInst.some((i: any) => i.pago);
             let status: SaleStatus = 'ABERTA';
             if (allPaid) status = 'QUITADA';
             else if (somePaid) status = 'PARCIAL';
             await supabase.from('sales').update({ status }).eq('id', inst.venda_id);
        }
        return;
    }

    await delay(500);
    let installments = getStorage<Installment[]>('installments', []);
    let sales = getStorage<Sale[]>('sales', []);
    let cash = getStorage<CashEntry[]>('cash', []);

    const instIndex = installments.findIndex(i => i.id === installmentId);
    if (instIndex === -1) return;
    const installment = installments[instIndex];
    if (installment.pago) return;

    const paidValue = actualAmountPaid !== undefined ? actualAmountPaid : installment.valor;
    const difference = installment.valor - paidValue;

    installments[instIndex] = { 
        ...installment, 
        pago: true, 
        data_pagamento: new Date().toISOString(),
        valor: paidValue
    };

    cash.push({ 
        id: uuidv4(), 
        data: new Date().toISOString(), 
        tipo: 'ENTRADA', 
        valor: paidValue, 
        descricao: `Pagamento Parcela ${installment.numero_parcela}`, 
        vendedor_id: vendedorId,
        venda_id: installment.venda_id
    });

    if (Math.abs(difference) > 0.01) {
        const nextInstallments = installments
            .map((inst, idx) => ({ ...inst, originalIndex: idx }))
            .filter(i => i.venda_id === installment.venda_id && i.numero_parcela > installment.numero_parcela && !i.pago)
            .sort((a,b) => a.numero_parcela - b.numero_parcela);

        if (nextInstallments.length > 0) {
            const nextTarget = nextInstallments[0];
            installments[nextTarget.originalIndex] = {
                ...installments[nextTarget.originalIndex],
                valor: installments[nextTarget.originalIndex].valor + difference
            };
        }
    }

    const saleIndex = sales.findIndex(s => s.id === installment.venda_id);
    if (saleIndex !== -1) {
       const saleInsts = installments.filter(i => i.venda_id === installment.venda_id);
       const allPaid = saleInsts.every(i => i.pago);
       const somePaid = saleInsts.some(i => i.pago);
       sales[saleIndex].status = allPaid ? 'QUITADA' : somePaid ? 'PARCIAL' : 'ABERTA';
    }

    setStorage('installments', installments);
    setStorage('sales', sales);
    setStorage('cash', cash);
  },

  addExpense: async (description: string, value: number, vendedorId: string): Promise<void> => {
     if (isSupabaseConfigured) {
         await supabase.from('cash_flow').insert([{ tipo: 'SAIDA', valor: value, descricao: description, vendedor_id: vendedorId, data: new Date().toISOString() }]);
         return;
     }
     await delay(300);
     const cash = getStorage<CashEntry[]>('cash', []);
     cash.push({ id: uuidv4(), data: new Date().toISOString(), tipo: 'SAIDA', valor: value, descricao: description, vendedor_id: vendedorId });
     setStorage('cash', cash);
  },

  deleteCashEntry: async (id: string): Promise<void> => {
      if (isSupabaseConfigured) {
          await supabase.from('cash_flow').delete().eq('id', id);
          return;
      }
      await delay(300);
      const cash = getStorage<CashEntry[]>('cash', []);
      setStorage('cash', cash.filter(c => c.id !== id));
  },

  getCashFlow: async (): Promise<CashEntry[]> => {
      const filterId = getUserFilter();
      if (isSupabaseConfigured) {
          let query = supabase.from('cash_flow').select('*').order('data', { ascending: false });
          if (filterId) query = query.eq('vendedor_id', filterId);
          const { data } = await query;
          return data || [];
      }
      await delay(300);
      let cash = getStorage<CashEntry[]>('cash', []);
      if (filterId) cash = cash.filter(c => c.vendedor_id === filterId);
      return cash.sort((a,b) => new Date(b.data).getTime() - new Date(a.data).getTime());
  },

  getDashboardStats: async () => {
      const filterId = getUserFilter();
      if (isSupabaseConfigured) {
          let salesQuery = supabase.from('sales').select('id, valor_total');
          if (filterId) salesQuery = salesQuery.eq('vendedor_id', filterId);
          const { data: sales } = await salesQuery;
          const salesIds = sales?.map(s => s.id) || [];
          if (salesIds.length === 0) return { totalVendido: 0, totalRecebido: 0, totalReceber: 0, inadimplencia: 0 };

          const { data: paidInst } = await supabase.from('installments').select('valor').in('venda_id', salesIds).eq('pago', true);
          const { data: openInst } = await supabase.from('installments').select('valor').in('venda_id', salesIds).eq('pago', false);
          const today = new Date().toISOString();
          const { data: overdueInst } = await supabase.from('installments').select('valor').in('venda_id', salesIds).eq('pago', false).lt('data_vencimento', today);

          return {
             totalVendido: sales?.reduce((acc, curr) => acc + curr.valor_total, 0) || 0,
             totalRecebido: paidInst?.reduce((acc, curr) => acc + curr.valor, 0) || 0,
             totalReceber: openInst?.reduce((acc, curr) => acc + curr.valor, 0) || 0,
             inadimplencia: overdueInst?.reduce((acc, curr) => acc + curr.valor, 0) || 0
          };
      }
      await delay(500);
      let sales = getStorage<Sale[]>('sales', []);
      if (filterId) sales = sales.filter(s => s.vendedor_id === filterId);
      const salesIds = sales.map(s => s.id);
      const installments = getStorage<Installment[]>('installments', []).filter(i => salesIds.includes(i.venda_id));
      const today = new Date();
      return {
          totalVendido: sales.reduce((acc, curr) => acc + curr.valor_total, 0),
          totalRecebido: installments.filter(i => i.pago).reduce((acc, curr) => acc + curr.valor, 0),
          totalReceber: installments.filter(i => !i.pago).reduce((acc, curr) => acc + curr.valor, 0),
          inadimplencia: installments.filter(i => !i.pago && new Date(i.data_vencimento) < today).reduce((acc, curr) => acc + curr.valor, 0)
      };
  },

  getDetailedReports: async (startDate: Date, endDate: Date, sellerId?: string) => {
    const processData = (salesRes: Sale[], cashRes: CashEntry[]) => {
        const interval = eachDayOfInterval({ start: startDate, end: endDate });
        const dailyData: DailyReport[] = interval.map(date => {
            const daySales = salesRes.filter(s => isSameDay(new Date(s.data_venda), date));
            const dayCash = cashRes.filter(c => isSameDay(new Date(c.data), date));
            return {
                data: format(date, 'dd/MM'),
                vendas: daySales.reduce((acc, s) => acc + s.valor_total, 0),
                recebimentos: dayCash.reduce((acc, c) => acc + c.valor, 0)
            };
        });
        return {
            dailyData,
            sales: salesRes,
            receipts: cashRes,
            summary: {
                totalSales: salesRes.reduce((acc, s) => acc + s.valor_total, 0),
                totalReceipts: cashRes.reduce((acc, c) => acc + c.valor, 0)
            }
        };
    };

    const currentUser = getCurrentUser();
    let finalSellerId = sellerId;
    if (currentUser?.perfil !== 'admin') {
        finalSellerId = currentUser?.id;
    }

    if (isSupabaseConfigured) {
        let salesQuery = supabase.from('sales').select('*, clients(nome)').gte('data_venda', startDate.toISOString()).lte('data_venda', endDate.toISOString());
        let cashQuery = supabase.from('cash_flow').select('*').eq('tipo', 'ENTRADA').gte('data', startDate.toISOString()).lte('data', endDate.toISOString());

        if (finalSellerId && finalSellerId !== 'all') {
            salesQuery = salesQuery.eq('vendedor_id', finalSellerId);
            cashQuery = cashQuery.eq('vendedor_id', finalSellerId);
        }

        const { data: sData } = await salesQuery;
        const { data: cData } = await cashQuery;
        const sales = (sData || []).map((s: any) => ({ ...s, cliente_nome: s.clients?.nome || 'Desconhecido' }));
        return processData(sales, cData || []);
    }

    await delay(500);
    const sales = await dataService.getSales(); 
    const cash = await dataService.getCashFlow(); 

    let filteredSales = sales.filter(s => {
       const d = new Date(s.data_venda);
       return d >= startDate && d <= endDate;
    });
    let filteredCash = cash.filter(c => {
       const d = new Date(c.data);
       return d >= startDate && d <= endDate && c.tipo === 'ENTRADA';
    });

    if (finalSellerId && finalSellerId !== 'all') {
        filteredSales = filteredSales.filter(s => s.vendedor_id === finalSellerId);
        filteredCash = filteredCash.filter(c => c.vendedor_id === finalSellerId);
    }
    return processData(filteredSales, filteredCash);
  },

  exportBackupData: async (): Promise<string> => {
      if (isSupabaseConfigured) {
          throw new Error("Exportação não disponível no modo Online (Supabase).");
      }
      const user = getCurrentUser();
      if (!user) throw new Error("Usuário não logado");

      const allSales = getStorage<Sale[]>('sales', []);
      const allClients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
      const allCash = getStorage<CashEntry[]>('cash', []);
      const allInstallments = getStorage<Installment[]>('installments', []);

      let exportSales = allSales;
      let exportClients = allClients;
      let exportCash = allCash;
      let exportInstallments = allInstallments;

      if (user.perfil !== 'admin') {
          exportSales = allSales.filter(s => s.vendedor_id === user.id);
          exportClients = allClients.filter(c => c.vendedor_id === user.id);
          exportCash = allCash.filter(c => c.vendedor_id === user.id);
          const saleIds = exportSales.map(s => s.id);
          exportInstallments = allInstallments.filter(i => saleIds.includes(i.venda_id));
      }

      const backup = {
          version: '1.0',
          timestamp: new Date().toISOString(),
          exporter: user.email,
          users: user.perfil === 'admin' ? getStorage('users', MOCK_USERS) : [user], 
          clients: exportClients,
          products: getStorage('products', INITIAL_PRODUCTS),
          sales: exportSales,
          installments: exportInstallments,
          cash: exportCash
      };
      return JSON.stringify(backup, null, 2);
  },

  importBackupData: async (jsonData: string): Promise<void> => {
      if (isSupabaseConfigured) {
          throw new Error("Importação não disponível no modo Online (Supabase).");
      }
      try {
          const data = JSON.parse(jsonData);
          if (!data.version) throw new Error("Arquivo inválido");

          setStorage('clients', data.clients || []);
          setStorage('products', data.products || []);
          setStorage('sales', data.sales || []);
          setStorage('installments', data.installments || []);
          setStorage('cash', data.cash || []);

          if (data.users && data.users.length > 0) {
              setStorage('users', data.users);
          }
      } catch (e) {
          console.error(e);
          throw new Error("Erro ao importar backup");
      }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Input, Card, Modal } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';
import { isSupabaseConfigured } from '../services/supabaseClient';
import { Client } from '../types';

const Clients: React.FC = () => {
  const navigate = useNavigate();
  const session = authService.getSession();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const photoInputRef = useRef<HTMLInputElement>(null);

  const [clients, setClients] = useState<Client[]>([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(false);
  const [processingImage, setProcessingImage] = useState(false);

  // State for file upload
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  // Modals
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);

  // Form State
  const [clientForm, setClientForm] = useState<Partial<Client>>({
    nome: '', telefone: '', endereco: '', bairro: '', cidade: '', foto_url: ''
  });
  const [editingId, setEditingId] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [importStatus, setImportStatus] = useState('');

  const loadClients = async () => {
    const data = await dataService.getClients();
    setClients(data);
  };

  useEffect(() => {
    loadClients();
  }, []);

  // --- CRUD Handlers ---

  const handleOpenCreate = () => {
    setEditingId(null);
    setSelectedFile(null);
    setClientForm({ nome: '', telefone: '', endereco: '', bairro: '', cidade: '', foto_url: '' });
    setIsModalOpen(true);
  };

  const handleOpenEdit = (client: Client, e: React.MouseEvent) => {
    e.stopPropagation(); // Stop card click
    setEditingId(client.id);
    setSelectedFile(null);
    setClientForm({
        nome: client.nome || '',
        telefone: client.telefone || '',
        endereco: client.endereco || '',
        bairro: client.bairro || '',
        cidade: client.cidade || '',
        foto_url: client.foto_url || ''
    });
    setIsModalOpen(true);
  };

  const handleOpenDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation(); // Stop card click
    setDeletingId(id);
    setIsDeleteModalOpen(true);
  };

  // --- PHOTO HANDLER ---
  const compressImage = (file: File): Promise<{ base64: string, blob: Blob }> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                const MAX_WIDTH = 800;
                const MAX_HEIGHT = 800;
                let width = img.width;
                let height = img.height;

                if (width > height) {
                    if (width > MAX_WIDTH) {
                        height *= MAX_WIDTH / width;
                        width = MAX_WIDTH;
                    }
                } else {
                    if (height > MAX_HEIGHT) {
                        width *= MAX_HEIGHT / height;
                        height = MAX_HEIGHT;
                    }
                }

                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(img, 0, 0, width, height);

                // Get Base64 for Preview
                const base64 = canvas.toDataURL('image/jpeg', 0.7);

                // Get Blob for Upload
                canvas.toBlob((blob) => {
                    if (blob) resolve({ base64, blob });
                    else reject(new Error("Canvas blob error"));
                }, 'image/jpeg', 0.7);
            };
            img.onerror = (error) => reject(error);
        };
        reader.onerror = (error) => reject(error);
    });
  };

  const handlePhotoChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setProcessingImage(true);
      try {
          const { base64, blob } = await compressImage(file);
          // Show preview
          setClientForm(prev => ({ ...prev, foto_url: base64 }));
          // Store blob for upload
          setSelectedFile(new File([blob], file.name, { type: 'image/jpeg' }));
      } catch (err) {
          console.error("Erro ao processar imagem", err);
          alert("Erro ao processar a imagem.");
      } finally {
          setProcessingImage(false);
      }
    }
  };

  const handleSaveClient = async () => {
    if (!clientForm.nome || !clientForm.telefone) {
        alert("Por favor, preencha o Nome e o Telefone.");
        return;
    }
    setLoading(true);
    try {
      let finalClientId = editingId;
      let finalPhotoUrl = clientForm.foto_url;

      // 1. If creating, save client first to get ID
      if (!editingId) {
          const newClient = await dataService.createClient({
              ...clientForm,
              vendedor_id: session?.id || 'anon',
              foto_url: isSupabaseConfigured ? '' : clientForm.foto_url // Don't save base64 if Supabase
          } as Omit<Client, 'id'>);
          finalClientId = newClient.id;
      }

      // 2. Upload Photo if selected (and we have an ID)
      if (selectedFile && finalClientId) {
          const publicUrl = await dataService.uploadClientPhoto(selectedFile, finalClientId);
          if (publicUrl) {
              finalPhotoUrl = publicUrl;
              // Update with new URL
              await dataService.updateClient(finalClientId, { foto_url: finalPhotoUrl });
          }
      }

      // 3. If editing and just changing text (not photo)
      if (editingId && !selectedFile) {
           const { id, ...updates } = clientForm as any;
           await dataService.updateClient(editingId, updates);
      }

      await loadClients();
      setIsModalOpen(false);
    } catch (error) {
      console.error(error);
      alert("Erro ao salvar cliente.");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteClient = async () => {
    if (!deletingId) return;
    setLoading(true);
    try {
      await dataService.deleteClient(deletingId);
      await loadClients();
      setIsDeleteModalOpen(false);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  // --- CSV IMPORT Handlers ---

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setImportStatus('Lendo arquivo...');

    const reader = new FileReader();
    reader.onload = async (event) => {
        try {
            const text = event.target?.result as string;
            await processCSV(text);
        } catch (err) {
            console.error(err);
            setImportStatus('Erro ao processar arquivo.');
        } finally {
            setLoading(false);
            if (fileInputRef.current) fileInputRef.current.value = '';
        }
    };
    reader.readAsText(file);
  };

  const processCSV = async (csvText: string) => {
      const lines = csvText.split('\n');
      if (lines.length < 2) {
          setImportStatus('Arquivo vazio ou sem cabeçalho.');
          return;
      }
      const headers = lines[0].split(',').map(h => h.trim().toLowerCase().replace(/"/g, ''));
      const nomeIdx = headers.findIndex(h => h.includes('nome'));
      const telIdx = headers.findIndex(h => h.includes('telefone') || h.includes('celular'));
      const endIdx = headers.findIndex(h => h.includes('endereco'));
      const bairroIdx = headers.findIndex(h => h.includes('bairro'));
      const cidIdx = headers.findIndex(h => h.includes('cidade'));

      if (nomeIdx === -1) {
          setImportStatus('Erro: Coluna "Nome" não encontrada.');
          return;
      }

      let count = 0;
      setImportStatus('Importando clientes...');

      for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;
          const cols = line.split(',').map(c => c.trim().replace(/^"|"$/g, ''));

          if (cols[nomeIdx]) {
             const newClient: any = {
                 nome: cols[nomeIdx],
                 telefone: telIdx > -1 ? cols[telIdx] : '',
                 endereco: endIdx > -1 ? cols[endIdx] : '',
                 bairro: bairroIdx > -1 ? cols[bairroIdx] : '',
                 cidade: cidIdx > -1 ? cols[cidIdx] : '',
                 vendedor_id: session?.id || 'anon'
             };
             await dataService.createClient(newClient);
             count++;
          }
      }
      await loadClients();
      setImportStatus(`Sucesso! ${count} clientes importados.`);
      setTimeout(() => { setIsImportModalOpen(false); setImportStatus(''); }, 2000);
  };

  const filteredClients = clients.filter(c => 
    c.nome.toLowerCase().includes(search.toLowerCase()) || 
    c.telefone.includes(search)
  );

  return (
    <div className="p-5 animate-fade-in space-y-4">
      <div className="flex justify-between items-center mb-2">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Clientes</h1>
        <div className="flex gap-2">
            <Button onClick={() => setIsImportModalOpen(true)} variant="secondary" className="!px-3 !py-2" title="Importar Planilha">
               {ICONS.Upload}
            </Button>
            <Button onClick={handleOpenCreate} className="!px-3 !py-2">
               {ICONS.Add}
            </Button>
        </div>
      </div>

      <div className="relative">
        <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500">
          {ICONS.Search}
        </div>
        <Input 
          placeholder="Buscar cliente..." 
          className="pl-10"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      <div className="space-y-3">
        {filteredClients.map(client => (
          <Card 
            key={client.id} 
            className="group cursor-pointer active:bg-gray-50 dark:active:bg-[#353535] relative pr-10"
            onClick={() => navigate(ROUTES.CLIENT_DETAILS.replace(':id', client.id))}
          >
            <div className="flex justify-between items-center">
               <div className="flex items-center gap-3">
                  <div className="w-12 h-12 rounded-full bg-gray-200 dark:bg-[#333] flex items-center justify-center overflow-hidden border border-gray-100 dark:border-white/10 text-gray-500 dark:text-gray-400 font-bold text-lg">
                      {client.foto_url ? (
                          <img src={client.foto_url} alt={client.nome} className="w-full h-full object-cover" />
                      ) : (
                          client.nome.charAt(0).toUpperCase()
                      )}
                  </div>
                  <div>
                    <h3 className="text-gray-900 dark:text-white font-semibold">{client.nome}</h3>
                    <p className="text-gray-400 text-sm">{client.telefone}</p>
                    <p className="text-gray-500 text-xs mt-1">{client.bairro} - {client.cidade}</p>
                  </div>
               </div>
            </div>

            <div className="flex gap-2 items-center mt-3 border-t border-gray-100 dark:border-white/5 pt-2 pl-[60px]">
              <button 
                onClick={(e) => { e.stopPropagation(); navigate(ROUTES.NEW_SALE, { state: { client } }); }}
                className="flex-1 py-2 bg-[#FF7A00]/10 text-[#FF7A00] rounded-lg text-sm font-medium hover:bg-[#FF7A00]/20 z-10 flex justify-center items-center gap-2"
              >
                {ICONS.Sales} Nova Venda
              </button>
              <button 
                onClick={(e) => { e.stopPropagation(); window.open(`https://wa.me/55${client.telefone.replace(/\D/g, '')}`, '_blank'); }}
                className="p-2 bg-green-500/10 text-green-500 rounded-lg hover:bg-green-500/20 z-10"
              >
                {ICONS.Phone}
              </button>
              <button 
                onClick={(e) => handleOpenEdit(client, e)}
                className="p-2 bg-gray-500/10 text-gray-400 rounded-lg hover:bg-gray-500/20 z-10"
              >
                {ICONS.Edit}
              </button>
              <button 
                onClick={(e) => handleOpenDelete(client.id, e)}
                className="p-2 bg-red-500/10 text-red-400 rounded-lg hover:bg-red-500/20 z-10"
              >
                {ICONS.Trash}
              </button>
            </div>
            <div className="absolute right-4 top-4 text-gray-500">{ICONS.Right}</div>
          </Card>
        ))}
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingId ? "Editar Cliente" : "Novo Cliente"}>
        <div className="space-y-4">
          <div className="flex justify-center mb-4">
             <div className="relative">
                <div 
                  onClick={() => photoInputRef.current?.click()}
                  className={`w-24 h-24 rounded-full bg-gray-200 dark:bg-[#333] border-2 border-dashed ${processingImage ? 'border-[#FF7A00] animate-pulse' : 'border-gray-400'} flex items-center justify-center overflow-hidden cursor-pointer hover:border-[#FF7A00] transition-colors`}
                >
                   {clientForm.foto_url ? (
                     <img src={clientForm.foto_url} alt="Foto" className="w-full h-full object-cover" />
                   ) : (
                     <div className="text-gray-400 flex flex-col items-center">
                        {ICONS.Camera}
                        <span className="text-[10px] mt-1">{processingImage ? 'Processando...' : 'Foto'}</span>
                     </div>
                   )}
                </div>
                {clientForm.foto_url && (
                   <button 
                     onClick={() => {
                        setClientForm(prev => ({ ...prev, foto_url: '' }));
                        setSelectedFile(null);
                     }}
                     className="absolute bottom-0 right-0 bg-red-500 text-white p-1 rounded-full shadow-lg"
                     title="Remover foto"
                   >
                     <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M18 6L6 18M6 6l12 12"/></svg>
                   </button>
                )}
             </div>
             <input 
               type="file" 
               accept="image/*" 
               ref={photoInputRef}
               className="hidden" 
               onChange={handlePhotoChange}
             />
          </div>

          <Input 
            label="Nome Completo" 
            value={clientForm.nome || ''} 
            onChange={e => setClientForm({...clientForm, nome: e.target.value})}
          />
          <Input 
            label="Telefone (WhatsApp)" 
            type="tel"
            value={clientForm.telefone || ''} 
            onChange={e => setClientForm({...clientForm, telefone: e.target.value})}
          />
          <Input 
            label="Endereço" 
            value={clientForm.endereco || ''} 
            onChange={e => setClientForm({...clientForm, endereco: e.target.value})}
          />
          <div className="grid grid-cols-2 gap-4">
            <Input 
                label="Bairro" 
                value={clientForm.bairro || ''} 
                onChange={e => setClientForm({...clientForm, bairro: e.target.value})}
            />
            <Input 
                label="Cidade" 
                value={clientForm.cidade || ''} 
                onChange={e => setClientForm({...clientForm, cidade: e.target.value})}
            />
          </div>
          <Button fullWidth onClick={handleSaveClient} isLoading={loading} disabled={processingImage}>
            Salvar
          </Button>
        </div>
      </Modal>

      <Modal isOpen={isImportModalOpen} onClose={() => setIsImportModalOpen(false)} title="Importar Clientes (CSV)">
         <div className="space-y-4">
             <div className="bg-blue-500/10 p-4 rounded-xl text-sm text-blue-600 dark:text-blue-300 border border-blue-500/20">
                <p className="font-bold mb-2">Instruções:</p>
                <p className="mb-2">Salve como <strong>.csv</strong>. Primeira linha: cabeçalhos.</p>
             </div>
             <div className="py-4">
                 <input type="file" accept=".csv" ref={fileInputRef} onChange={handleFileChange} className="hidden" />
                 <Button fullWidth onClick={() => fileInputRef.current?.click()} isLoading={loading}>
                    Selecionar Arquivo CSV
                 </Button>
             </div>
             {importStatus && (
                 <div className={`text-center text-sm p-2 rounded ${importStatus.includes('Erro') ? 'text-red-400 bg-red-500/10' : 'text-green-400 bg-green-500/10'}`}>
                     {importStatus}
                 </div>
             )}
         </div>
      </Modal>

      <Modal isOpen={isDeleteModalOpen} onClose={() => setIsDeleteModalOpen(false)} title="Excluir Cliente">
         <div className="text-center space-y-4">
             <div className="w-16 h-16 bg-red-500/20 rounded-full flex items-center justify-center text-red-500 mx-auto">
                {ICONS.Trash}
             </div>
             <p className="text-gray-600 dark:text-gray-300">Tem certeza que deseja excluir este cliente?</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setIsDeleteModalOpen(false)}>Cancelar</Button>
                 <Button variant="danger" onClick={handleDeleteClient} isLoading={loading}>Excluir</Button>
             </div>
         </div>
      </Modal>
    </div>
  );
};

