    }
    await delay(300);
    const clients = getStorage<Client[]>('clients', INITIAL_CLIENTS);
    const idx = clients.findIndex(c => c.id === id);
    if (idx > -1) {
        clients[idx] = { ...clients[idx], ...updates };
        setStorage('clients', clients);
    }
  },

  deleteClient: async (id: string): Promise<void> => {
