  // Cash Flow State
  const [cashFlow, setCashFlow] = useState<CashEntry[]>([]);
  const [cashPeriod, setCashPeriod] = useState<'day' | 'week' | 'month'>('day');

  const [loading, setLoading] = useState(false);

  // Modals state
  const [confirmItem, setConfirmItem] = useState<(Installment & { cliente_nome: string }) | null>(null);
  const [paymentAmount, setPaymentAmount] = useState('');

  const [showExpenseModal, setShowExpenseModal] = useState(false);
  const [deleteCashId, setDeleteCashId] = useState<string | null>(null);
  const [expenseForm, setExpenseForm] = useState({ descricao: '', valor: '' });

  const loadData = async () => {
    // 1. Load Route (Daily Collection)
    const routeData = await dataService.getInstallmentsByDate(selectedDate);

    if (showOverdue) {
        const allDue = await dataService.getDueInstallments();
        setDueList(allDue);
    } else {
        setDueList(routeData.daily);
    }
    setOverdueCount(routeData.overdueCount);

    // 2. Load Cash
    const flow = await dataService.getCashFlow();
    setCashFlow(flow);
  };

  useEffect(() => {
    loadData();
  }, [selectedDate, showOverdue]);

  const handleOpenPayment = (item: Installment & { cliente_nome: string, venda_id: string }) => {
      setConfirmItem(item);
      setPaymentAmount(item.valor.toFixed(2));
  };

  const handlePay = async () => {
    if (!confirmItem || !session || !paymentAmount) return;
    setLoading(true);
    try {
      await dataService.payInstallment(confirmItem.id, session.id, parseFloat(paymentAmount));
      await loadData();
      setConfirmItem(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleAddExpense = async () => {
    if (!expenseForm.descricao || !expenseForm.valor || !session) return;
    setLoading(true);
    try {
      await dataService.addExpense(expenseForm.descricao, parseFloat(expenseForm.valor), session.id);
      await loadData();
      setShowExpenseModal(false);
      setExpenseForm({ descricao: '', valor: '' });
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteCashEntry = async () => {
      if (!deleteCashId) return;
      setLoading(true);
      try {
          await dataService.deleteCashEntry(deleteCashId);
          await loadData();
          setDeleteCashId(null);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  // Date Navigation Helpers
  const nextDay = () => setSelectedDate(addDays(selectedDate, 1));
  const prevDay = () => setSelectedDate(subDays(selectedDate, 1));

  // Calculations
  const totalDoDia = dueList.reduce((acc, i) => acc + i.valor, 0);

  // Cash Flow Calculations based on Period
  const getFilteredCashFlow = () => {
      const now = new Date();
      let start, end;

      switch (cashPeriod) {
          case 'day':
              start = startOfDay(now);
              end = endOfDay(now);
              break;
          case 'week':
              start = startOfWeek(now, { weekStartsOn: 1 }); // Segunda-feira
              end = endOfWeek(now, { weekStartsOn: 1 });
              break;
          case 'month':
              start = startOfMonth(now);
              end = endOfMonth(now);
              break;
      }

      return cashFlow.filter(entry => 
          isWithinInterval(new Date(entry.data), { start, end })
      );
  };

  const filteredCash = getFilteredCashFlow();
  const cashEntradas = filteredCash.filter(c => c.tipo === 'ENTRADA').reduce((acc, c) => acc + c.valor, 0);
  const cashSaidas = filteredCash.filter(c => c.tipo === 'SAIDA').reduce((acc, c) => acc + c.valor, 0);
  const cashSaldo = cashEntradas - cashSaidas;

  return (
    <div className="p-5 animate-fade-in pb-24">
      {/* Tabs */}
      <div className="flex gap-4 mb-6">
        <button 
          onClick={() => setView('due')}
          className={`flex-1 pb-2 font-bold text-lg transition-colors border-b-2 ${view === 'due' ? 'text-[#FF7A00] border-[#FF7A00]' : 'text-gray-400 dark:text-gray-500 border-transparent'}`}
        >
          A Receber
        </button>
        <button 
          onClick={() => setView('cash')}
          className={`flex-1 pb-2 font-bold text-lg transition-colors border-b-2 ${view === 'cash' ? 'text-[#FF7A00] border-[#FF7A00]' : 'text-gray-400 dark:text-gray-500 border-transparent'}`}
        >
          Caixa
        </button>
      </div>

      {view === 'due' && (
        <div className="space-y-4">
          {/* Date Navigator */}
          <div className="bg-white dark:bg-[#1E1E1E] p-3 rounded-2xl flex items-center justify-between border border-gray-200 dark:border-[#333] shadow-sm">
             <button onClick={prevDay} className="p-2 text-gray-500 hover:bg-gray-100 dark:text-gray-400 dark:hover:text-white dark:hover:bg-white/5 rounded-lg">
                {ICONS.Left}
             </button>

             <div className="flex flex-col items-center">
                <input 
                  type="date" 
                  className="bg-transparent text-gray-900 dark:text-white font-bold text-center text-lg focus:outline-none"
                  value={format(selectedDate, 'yyyy-MM-dd')}
                  onChange={(e) => setSelectedDate(new Date(e.target.value + 'T00:00:00'))}
                />
                <span className="text-xs text-gray-500 capitalize">
                   {isToday(selectedDate) ? 'Hoje' : format(selectedDate, 'EEEE', { locale: ptBR })}
                </span>
             </div>

             <button onClick={nextDay} className="p-2 text-gray-500 hover:bg-gray-100 dark:text-gray-400 dark:hover:text-white dark:hover:bg-white/5 rounded-lg">
                {ICONS.Right}
             </button>
          </div>

          {/* Summary for the day */}
          <div className="flex justify-between items-center px-2">
             <span className="text-gray-500 dark:text-gray-400 text-sm">Total da Rota:</span>
             <span className="text-gray-900 dark:text-white font-bold text-lg">R$ {totalDoDia.toFixed(2)}</span>
          </div>

          {/* Overdue Alert */}
          {overdueCount > 0 && !showOverdue && (
             <div 
                onClick={() => setShowOverdue(true)}
                className="bg-red-50 border border-red-100 dark:bg-red-900/10 dark:border-red-500/20 p-3 rounded-xl flex items-center justify-between cursor-pointer active:scale-[0.98] transition-transform"
             >
                <div className="flex items-center gap-2 text-red-600 dark:text-red-400 text-sm">
                   {ICONS.Alert}
                   <span>Existem <strong>{overdueCount}</strong> parcelas atrasadas anteriores.</span>
                </div>
                <div className="text-red-600 dark:text-red-400 text-xs font-bold underline">Ver Todas</div>
             </div>
          )}

          {/* Back to Day View button if Overdue is showing */}
          {showOverdue && (
              <Button variant="secondary" onClick={() => setShowOverdue(false)} fullWidth className="mb-2">
                 Voltar para Rota do Dia ({format(selectedDate, 'dd/MM')})
              </Button>
          )}

          {/* List */}
          {dueList.length === 0 ? (
            <div className="text-center text-gray-500 py-10">
              <div className="mb-2 opacity-50 flex justify-center">{ICONS.Check}</div>
              <p>Nenhuma cobrança {showOverdue ? 'pendente' : 'para esta data'}.</p>
            </div>
          ) : (
            dueList.map(item => {
              const overdue = isPast(new Date(item.data_vencimento)) && !isToday(new Date(item.data_vencimento));
              return (
                <Card key={item.id} className={`flex justify-between items-center border-l-4 ${overdue ? 'border-l-red-500' : 'border-l-[#FF7A00]'}`}>
                  <div>
                    <h4 className="font-bold text-gray-900 dark:text-white">{item.cliente_nome}</h4>
                    <p className="text-sm text-gray-500">Parcela {item.numero_parcela}</p>
                    <div className="flex items-center gap-2 mt-1">
                      {overdue && <span className="text-[10px] bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 px-1.5 py-0.5 rounded font-bold">Atrasado</span>}
                      <span className="text-xs text-gray-500 dark:text-gray-400">{format(new Date(item.data_vencimento), 'dd/MM/yyyy')}</span>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-2">
                    <span className="font-bold text-lg text-gray-900 dark:text-white">R$ {item.valor.toFixed(2)}</span>
                    <button 
                      onClick={() => handleOpenPayment(item)}
                      className="text-xs bg-green-100 dark:bg-green-500/10 text-green-700 dark:text-green-400 px-3 py-1.5 rounded-lg border border-green-200 dark:border-green-500/20 active:bg-green-200 dark:active:bg-green-500/20 font-medium"
                    >
                      Receber
                    </button>
                  </div>
                </Card>
              );
            })
          )}
        </div>
      )}

      {view === 'cash' && (
        <div className="space-y-6">

          {/* Period Selector */}
          <div className="flex p-1 bg-white dark:bg-[#1E1E1E] rounded-xl border border-gray-200 dark:border-[#333]">
              <button 
                onClick={() => setCashPeriod('day')}
                className={`flex-1 py-1.5 text-xs font-medium rounded-lg transition-all ${cashPeriod === 'day' ? 'bg-[#FF7A00] text-white shadow-md' : 'text-gray-500'}`}
              >
                Hoje
              </button>
              <button 
                onClick={() => setCashPeriod('week')}
                className={`flex-1 py-1.5 text-xs font-medium rounded-lg transition-all ${cashPeriod === 'week' ? 'bg-[#FF7A00] text-white shadow-md' : 'text-gray-500'}`}
              >
                Semana
              </button>
              <button 
                onClick={() => setCashPeriod('month')}
                className={`flex-1 py-1.5 text-xs font-medium rounded-lg transition-all ${cashPeriod === 'month' ? 'bg-[#FF7A00] text-white shadow-md' : 'text-gray-500'}`}
              >
                Mês
              </button>
          </div>

          {/* Caixa Detalhado Summary */}
          <div className="grid grid-cols-2 gap-3">
             <div className="bg-white dark:bg-[#1E1E1E] p-4 rounded-2xl border border-gray-200 dark:border-[#333] col-span-2 shadow-sm">
                <p className="text-gray-500 text-sm">
                    Saldo 
                    {cashPeriod === 'day' ? ' do Dia' : cashPeriod === 'week' ? ' Semanal' : ' Mensal'}
                </p>
                <h2 className={`text-3xl font-bold ${cashSaldo >= 0 ? 'text-gray-900 dark:text-white' : 'text-red-500'}`}>
                  R$ {cashSaldo.toFixed(2)}
                </h2>
             </div>
             <div className="bg-white dark:bg-[#1E1E1E] p-3 rounded-xl border border-gray-200 dark:border-[#333] shadow-sm">
                <div className="flex items-center gap-2 mb-1">
                   <div className="w-2 h-2 rounded-full bg-green-500"></div>
                   <p className="text-xs text-gray-500">Entradas</p>
                </div>
                <p className="text-green-600 dark:text-green-500 font-bold">R$ {cashEntradas.toFixed(2)}</p>
             </div>
             <div className="bg-white dark:bg-[#1E1E1E] p-3 rounded-xl border border-gray-200 dark:border-[#333] shadow-sm">
                <div className="flex items-center gap-2 mb-1">
                   <div className="w-2 h-2 rounded-full bg-red-500"></div>
                   <p className="text-xs text-gray-500">Saídas</p>
                </div>
                <p className="text-red-600 dark:text-red-400 font-bold">R$ {cashSaidas.toFixed(2)}</p>
             </div>
          </div>

          <div className="flex justify-between items-center">
             <h3 className="text-gray-900 dark:text-white font-bold">Movimentações ({filteredCash.length})</h3>
             <button 
                onClick={() => setShowExpenseModal(true)}
                className="text-xs bg-red-100 dark:bg-red-500/10 text-red-600 dark:text-red-400 px-3 py-2 rounded-lg font-medium hover:bg-red-200 dark:hover:bg-red-500/20 flex items-center gap-1"
             >
                {ICONS.Add} Despesa
             </button>
          </div>

          <div className="space-y-3">
            {filteredCash.map(entry => (
               <div key={entry.id} className="flex justify-between items-center p-3 bg-white dark:bg-[#1E1E1E] rounded-xl border border-gray-200 dark:border-[#333] shadow-sm">
                  <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${entry.tipo === 'ENTRADA' ? 'bg-green-100 dark:bg-green-500/10 text-green-600 dark:text-green-500' : 'bg-red-100 dark:bg-red-500/10 text-red-600 dark:text-red-500'}`}>
                      {entry.tipo === 'ENTRADA' ? ICONS.Trending : ICONS.Alert}
                    </div>
                    <div>
                      <p className="text-gray-900 dark:text-white font-medium">{entry.descricao}</p>
                      <p className="text-xs text-gray-500">{format(new Date(entry.data), 'dd/MM HH:mm')}</p>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-1">
                    <span className={`font-bold ${entry.tipo === 'ENTRADA' ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                        {entry.tipo === 'ENTRADA' ? '+' : '-'} R$ {entry.valor.toFixed(2)}
                    </span>
                    <button 
                        onClick={() => setDeleteCashId(entry.id)}
                        className="text-xs text-gray-400 hover:text-red-500"
                    >
                        {ICONS.Trash}
                    </button>
                  </div>
               </div>
            ))}
            {filteredCash.length === 0 && (
              <p className="text-center text-gray-500 py-4 text-sm">
                  Nenhuma movimentação {cashPeriod === 'day' ? 'hoje' : 'neste período'}.
              </p>
            )}
          </div>
        </div>
      )}

      {/* Confirmation Modal */}
      <Modal isOpen={!!confirmItem} onClose={() => setConfirmItem(null)} title="Confirmar Recebimento">
        <div className="space-y-6 text-center">
           <div className="w-16 h-16 bg-green-100 dark:bg-green-500/20 rounded-full flex items-center justify-center text-green-600 dark:text-green-500 mx-auto">
             {ICONS.Check}
           </div>
           <div>
             {confirmItem && (
               <>
                 <p className="text-gray-600 dark:text-gray-300">Receber de <strong className="text-gray-900 dark:text-white">{confirmItem.cliente_nome}</strong>?</p>
                 <p className="text-xs text-gray-500 mt-2 mb-4">Parcela {confirmItem.numero_parcela} • Vencimento {format(new Date(confirmItem.data_vencimento), 'dd/MM/yyyy')}</p>

                 <div className="text-left bg-gray-50 dark:bg-[#121212] p-3 rounded-lg border border-gray-200 dark:border-[#333]">
                     <Input 
                        label="Valor Recebido (R$)" 
                        type="number"
                        step="0.01"
                        value={paymentAmount}
                        onChange={(e) => setPaymentAmount(e.target.value)}
                        className="text-center font-bold text-xl text-green-600 dark:text-green-500"
                     />
                     <p className="text-[10px] text-gray-500 mt-2 text-center">
                        * Se o valor for diferente, a diferença será somada ou descontada na próxima parcela.
                     </p>
                 </div>
               </>
             )}
           </div>
           <div className="grid grid-cols-2 gap-3">
             <Button variant="secondary" onClick={() => setConfirmItem(null)}>Cancelar</Button>
             <Button onClick={handlePay} isLoading={loading} className="bg-green-600 hover:bg-green-700 border-none shadow-green-900/20">
               Confirmar
             </Button>
           </div>
        </div>
      </Modal>

      {/* Add Expense Modal */}
      <Modal isOpen={showExpenseModal} onClose={() => setShowExpenseModal(false)} title="Nova Despesa">
         <div className="space-y-4">
            <Input 
               label="Descrição" 
               placeholder="Ex: Combustível, Almoço..."
               value={expenseForm.descricao}
               onChange={(e) => setExpenseForm(prev => ({ ...prev, descricao: e.target.value }))}
            />
            <Input 
               label="Valor (R$)" 
               type="number"
               step="0.01"
               placeholder="0,00"
               value={expenseForm.valor}
               onChange={(e) => setExpenseForm(prev => ({ ...prev, valor: e.target.value }))}
            />
            <Button 
               fullWidth 
               onClick={handleAddExpense} 
               isLoading={loading}
               variant="danger"
               className="mt-2"
            >
               Lançar Saída
            </Button>
         </div>
      </Modal>

      {/* Delete Cash Entry Modal */}
      <Modal isOpen={!!deleteCashId} onClose={() => setDeleteCashId(null)} title="Excluir Lançamento">
         <div className="text-center space-y-4">
             <div className="w-16 h-16 bg-red-100 dark:bg-red-500/20 rounded-full flex items-center justify-center text-red-500 mx-auto">
                {ICONS.Trash}
             </div>
             <p className="text-gray-600 dark:text-gray-300">Tem certeza que deseja excluir este lançamento do caixa? O saldo será recalculado.</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setDeleteCashId(null)}>Cancelar</Button>
                 <Button variant="danger" onClick={handleDeleteCashEntry} isLoading={loading}>Excluir</Button>
             </div>
         </div>
      </Modal>
    </div>
  );
};

export default Payments;

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Card, Badge, Modal, Input } from '../components/ui';
import { ReceiptModal } from '../components/ReceiptModal';
import { dataService, authService } from '../services/mockSupabase';
import { Client, Sale, Installment } from '../types';
import { format } from 'date-fns';

const ClientDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const session = authService.getSession();
  const photoInputRef = useRef<HTMLInputElement>(null);

  const [client, setClient] = useState<Client | null>(null);
  const [sales, setSales] = useState<Sale[]>([]);
  const [installmentsMap, setInstallmentsMap] = useState<Record<string, Installment[]>>({});
  const [expandedSale, setExpandedSale] = useState<string | null>(null);

  // Modals
  const [editInstallment, setEditInstallment] = useState<Installment | null>(null);
  const [payInstallment, setPayInstallment] = useState<Installment | null>(null);
  const [paymentAmount, setPaymentAmount] = useState('');

  const [deleteSaleId, setDeleteSaleId] = useState<string | null>(null);
  const [returnSaleId, setReturnSaleId] = useState<string | null>(null);
  const [isEditClientOpen, setIsEditClientOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [processingImage, setProcessingImage] = useState(false);

  // File Upload
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  // Receipt Modal State
  const [receiptData, setReceiptData] = useState<{ type: 'SALE' | 'INSTALLMENT', data: any } | null>(null);

  // Forms
  const [editForm, setEditForm] = useState({ valor: '', data_vencimento: '' });
  const [clientForm, setClientForm] = useState<Partial<Client>>({});

  const loadData = async () => {
    if (!id) return;
    const clientData = await dataService.getClientById(id);
    const salesData = await dataService.getSalesByClient(id);
    setClient(clientData || null);
    setSales(salesData);

    const map: Record<string, Installment[]> = {};
    for (const sale of salesData) {
      map[sale.id] = await dataService.getInstallmentsBySale(sale.id);
    }
    setInstallmentsMap(map);
  };

  useEffect(() => {
    loadData();
  }, [id]);

  const toggleSale = async (saleId: string) => {
    if (expandedSale === saleId) {
      setExpandedSale(null);
    } else {
      setExpandedSale(saleId);
      const data = await dataService.getInstallmentsBySale(saleId);
      setInstallmentsMap(prev => ({ ...prev, [saleId]: data }));
    }
  };

  const handleOpenEditClient = () => {
      if(client) {
          setClientForm(client);
          setSelectedFile(null);
          setIsEditClientOpen(true);
      }
  };

  const compressImage = (file: File): Promise<{ base64: string, blob: Blob }> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                const MAX_WIDTH = 800;
                const MAX_HEIGHT = 800;
                let width = img.width;
                let height = img.height;

                if (width > height) {
                    if (width > MAX_WIDTH) {
                        height *= MAX_WIDTH / width;
                        width = MAX_WIDTH;
                    }
                } else {
                    if (height > MAX_HEIGHT) {
                        width *= MAX_HEIGHT / height;
                        height = MAX_HEIGHT;
                    }
                }

                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(img, 0, 0, width, height);

                // Base64
                const base64 = canvas.toDataURL('image/jpeg', 0.7);

                // Blob
                canvas.toBlob((blob) => {
                    if(blob) resolve({ base64, blob });
                    else reject(new Error("Blob error"));
                }, 'image/jpeg', 0.7);
            };
            img.onerror = (error) => reject(error);
        };
        reader.onerror = (error) => reject(error);
    });
  };

  const handlePhotoChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setProcessingImage(true);
      try {
          const { base64, blob } = await compressImage(file);
          setClientForm(prev => ({ ...prev, foto_url: base64 }));
          setSelectedFile(new File([blob], file.name, { type: 'image/jpeg' }));
      } catch (err) {
          console.error(err);
      } finally {
          setProcessingImage(false);
      }
    }
  };

  const handleSaveClient = async () => {
      if(!client || !id) return;
      if(!clientForm.nome || !clientForm.telefone) {
          alert("Nome e Telefone são obrigatórios.");
          return;
      }
      setLoading(true);
      try {
          let finalPhotoUrl = clientForm.foto_url;

          // If file selected, try upload
          if (selectedFile) {
              const url = await dataService.uploadClientPhoto(selectedFile, id);
              if (url) {
                  finalPhotoUrl = url;
              }
              // If url is null (Offline), finalPhotoUrl keeps the Base64 from handlePhotoChange
          }

          const { id: _, ...formFields } = clientForm as any;
          const updates = { ...formFields, foto_url: finalPhotoUrl };

          await dataService.updateClient(id, updates);
          await loadData();
          setIsEditClientOpen(false);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  const handleDeleteSale = async () => {
      if (!deleteSaleId) return;
      setLoading(true);
      try {
          await dataService.deleteSale(deleteSaleId);
          await loadData();
          setDeleteSaleId(null);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  const handleReturnSale = async () => {
      if (!returnSaleId) return;
      setLoading(true);
      try {
          await dataService.returnSale(returnSaleId);
          await loadData();
          setReturnSaleId(null);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  const handleOpenEdit = (inst: Installment) => {
    setEditInstallment(inst);
    setEditForm({
      valor: inst.valor.toString(),
      data_vencimento: inst.data_vencimento.split('T')[0]
    });
  };

  const handleSaveEdit = async () => {
    if (!editInstallment) return;
    setLoading(true);
    try {
      await dataService.updateInstallment(editInstallment.id, {
        valor: parseFloat(editForm.valor),
        data_vencimento: new Date(editForm.data_vencimento).toISOString()
      });
      await loadData();
      setEditInstallment(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleOpenPay = (inst: Installment) => {
      setPayInstallment(inst);
      setPaymentAmount(inst.valor.toFixed(2));
  };

  const handlePay = async () => {
    if (!payInstallment || !session || !paymentAmount) return;
    setLoading(true);
    try {
      const actualPaid = parseFloat(paymentAmount);
      await dataService.payInstallment(payInstallment.id, session.id, actualPaid);
      await loadData();
      const updatedInst = { 
          ...payInstallment, 
          pago: true, 
          data_pagamento: new Date().toISOString(),
          valor: actualPaid 
      };
      setReceiptData({ type: 'INSTALLMENT', data: updatedInst });
      setPayInstallment(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const totalBought = sales.filter(s => s.status !== 'DEVOLVIDO').reduce((acc, s) => acc + s.valor_total, 0);
  const allInstallments: Installment[] = (Object.values(installmentsMap) as Installment[][]).reduce((acc, val) => acc.concat(val), [] as Installment[]);
  const totalDebt = allInstallments.filter(i => !i.pago).reduce((acc, i) => acc + i.valor, 0);

  if (!client) return <div className="p-5 text-center text-gray-500">Carregando...</div>;

  return (
    <div className="flex flex-col h-screen bg-gray-100 dark:bg-[#121212] transition-colors">
      <div className="bg-white dark:bg-[#1E1E1E] p-4 flex items-center gap-4 border-b border-gray-200 dark:border-[#333] sticky top-0 z-10 transition-colors shadow-sm">
        <button onClick={() => navigate(-1)} className="text-gray-900 dark:text-white">
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold text-gray-900 dark:text-white flex-1 truncate">{client.nome}</h1>
        <button onClick={handleOpenEditClient} className="text-[#FF7A00]">
            {ICONS.Edit}
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar pb-24 space-y-6">
        <Card>
           <div className="flex items-center gap-4 mb-4">
               <div className="w-16 h-16 rounded-full bg-gray-100 dark:bg-[#333] flex items-center justify-center overflow-hidden border-2 border-[#FF7A00] text-gray-500 font-bold text-2xl">
                  {client.foto_url ? (
                      <img src={client.foto_url} alt={client.nome} className="w-full h-full object-cover" />
                  ) : (
                      client.nome.charAt(0).toUpperCase()
                  )}
               </div>
               <div>
                  <h2 className="text-xl font-bold text-gray-900 dark:text-white">{client.nome}</h2>
                  <p className="text-sm text-gray-500 dark:text-gray-400">Cliente desde {new Date().getFullYear()}</p>
               </div>
           </div>
           <div className="flex items-start justify-between border-t border-gray-100 dark:border-[#333] pt-4">
              <div className="space-y-2">
                 <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 text-sm">
                    {ICONS.Phone} {client.telefone}
                 </div>
                 <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 text-sm">
                    {ICONS.Map} {client.bairro}, {client.cidade}
                 </div>
              </div>
              <a href={`https://wa.me/55${client.telefone.replace(/\D/g, '')}`} target="_blank" className="bg-green-100 dark:bg-green-500/10 text-green-600 dark:text-green-500 p-2 rounded-lg">
                {ICONS.Phone}
              </a>
           </div>
        </Card>

        <div className="grid grid-cols-2 gap-4">
           <Card className="bg-white dark:bg-[#1E1E1E] border border-gray-200 dark:border-[#333] shadow-sm">
              <p className="text-gray-500 dark:text-gray-400 text-xs uppercase font-bold">Total Comprado</p>
              <p className="text-gray-900 dark:text-white font-bold text-lg">R$ {totalBought.toFixed(2)}</p>
           </Card>
           <Card className="bg-white dark:bg-[#1E1E1E] border border-gray-200 dark:border-[#333] shadow-sm">
              <p className="text-gray-500 dark:text-gray-400 text-xs uppercase font-bold">Em Aberto</p>
              <p className="text-[#FF7A00] font-bold text-lg">R$ {totalDebt.toFixed(2)}</p>
           </Card>
        </div>

        <h2 className="text-gray-900 dark:text-white font-bold text-lg pt-2">Histórico de Compras</h2>
        <div className="space-y-3">
           {sales.map(sale => {
              const installments = installmentsMap[sale.id] || [];
              const isExpanded = expandedSale === sale.id;
              const isReturned = sale.status === 'DEVOLVIDO';

              return (
                <div key={sale.id} className={`bg-white dark:bg-[#1E1E1E] rounded-2xl overflow-hidden border transition-colors shadow-sm ${isReturned ? 'border-red-200 dark:border-red-900/30 opacity-70' : 'border-gray-200 dark:border-[#333]'}`}>
                   <div 
                      onClick={() => toggleSale(sale.id)}
                      className="p-4 flex justify-between items-center cursor-pointer active:bg-gray-50 dark:active:bg-[#252525]"
                   >
                      <div>
                         <div className="flex items-center gap-2 mb-1">
                            <span className="text-gray-900 dark:text-white font-bold">Compra #{sale.id.substring(0,6)}</span>
                            <Badge status={sale.status} />
                         </div>
                         <p className="text-gray-500 dark:text-gray-400 text-xs">
                            {format(new Date(sale.data_venda), 'dd/MM/yyyy')} • {sale.qtd_parcelas} parcelas
                         </p>
                      </div>
                      <div className="text-right">
                         <p className={`font-bold ${isReturned ? 'text-gray-400 line-through' : 'text-[#FF7A00]'}`}>
                            R$ {sale.valor_total.toFixed(2)}
                         </p>
                         <div className="flex justify-end mt-1 text-gray-500">
                           {isExpanded ? ICONS.Up : ICONS.Down}
                         </div>
                      </div>
                   </div>

                   {isExpanded && (
                      <div className="bg-gray-50 dark:bg-[#121212] border-t border-gray-200 dark:border-[#333] p-3 space-y-2">
                           <div className="flex justify-between px-1 pb-2 gap-2 flex-wrap">
                                <button onClick={(e) => { e.stopPropagation(); setReceiptData({ type: 'SALE', data: sale }); }} className="text-xs text-blue-500 dark:text-blue-400 flex items-center gap-1 hover:underline">
                                    {ICONS.Printer} Recibo
                                </button>
                                {!isReturned && (
                                    <>
                                        <button onClick={(e) => { e.stopPropagation(); setReturnSaleId(sale.id); }} className="text-xs text-orange-500 dark:text-orange-400 flex items-center gap-1 hover:underline">
                                            {ICONS.Return} Devolver
                                        </button>
                                        <button onClick={(e) => { e.stopPropagation(); setDeleteSaleId(sale.id); }} className="text-xs text-red-500 dark:text-red-400 flex items-center gap-1 hover:underline">
                                            {ICONS.Trash} Excluir
                                        </button>
                                    </>
                                )}
                           </div>
                           {installments.map(inst => (
                              <div key={inst.id} className="flex items-center justify-between p-3 bg-white dark:bg-[#1E1E1E] rounded-xl border border-gray-200 dark:border-[#333] shadow-sm">
                                 <div className="flex items-center gap-3">
                                    <div className={`w-2 h-2 rounded-full ${inst.pago ? 'bg-green-500' : 'bg-[#FF7A00]'}`} />
                                    <div>
                                       <p className="text-gray-900 dark:text-white text-sm font-medium">Parcela {inst.numero_parcela}</p>
                                       <p className="text-gray-500 text-xs">{format(new Date(inst.data_vencimento), 'dd/MM/yyyy')}</p>
                                    </div>
                                 </div>
                                 <div className="flex items-center gap-3">
                                    <span className={`text-sm font-bold ${inst.pago ? 'text-green-600 dark:text-green-500 line-through opacity-70' : 'text-gray-900 dark:text-white'}`}>
                                       R$ {inst.valor.toFixed(2)}
                                    </span>
                                    {inst.pago ? (
                                        <button onClick={() => setReceiptData({ type: 'INSTALLMENT', data: inst })} className="p-1.5 text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg">
                                            {ICONS.Printer}
                                        </button>
                                    ) : !isReturned && (
                                       <div className="flex gap-1">
                                         <button onClick={() => handleOpenEdit(inst)} className="p-1.5 text-gray-500 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-white/10 rounded-lg">
                                            {ICONS.Edit}
                                         </button>
                                         <button onClick={() => handleOpenPay(inst)} className="p-1.5 text-green-600 dark:text-green-500 hover:bg-green-50 dark:hover:bg-green-900/20 rounded-lg">
                                            {ICONS.Check}
                                         </button>
                                       </div>
                                    )}
                                 </div>
                              </div>
                           ))}
                      </div>
                   )}
                </div>
              );
           })}
        </div>
      </div>

      <Modal isOpen={isEditClientOpen} onClose={() => setIsEditClientOpen(false)} title="Editar Cliente">
        <div className="space-y-4">
          <div className="flex justify-center mb-4">
             <div className="relative">
                <div 
                  onClick={() => photoInputRef.current?.click()}
                  className={`w-24 h-24 rounded-full bg-gray-100 dark:bg-[#333] border-2 border-dashed ${processingImage ? 'border-[#FF7A00] animate-pulse' : 'border-gray-300 dark:border-gray-500'} flex items-center justify-center overflow-hidden cursor-pointer hover:border-[#FF7A00] transition-colors`}
                >
                   {clientForm.foto_url ? (
                     <img src={clientForm.foto_url} alt="Foto" className="w-full h-full object-cover" />
                   ) : (
                     <div className="text-gray-400 flex flex-col items-center">
                        {ICONS.Camera}
                        <span className="text-[10px] mt-1">{processingImage ? 'Processando...' : 'Foto'}</span>
                     </div>
                   )}
                </div>
                {clientForm.foto_url && (
                   <button 
                     onClick={() => {
                        setClientForm(prev => ({ ...prev, foto_url: '' }));
                        setSelectedFile(null);
                     }}
                     className="absolute bottom-0 right-0 bg-red-500 text-white p-1 rounded-full shadow-lg"
                     title="Remover foto"
                   >
                     <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M18 6L6 18M6 6l12 12"/></svg>
                   </button>
                )}
             </div>
             <input type="file" accept="image/*" ref={photoInputRef} className="hidden" onChange={handlePhotoChange} />
          </div>

          <Input label="Nome Completo" value={clientForm.nome || ''} onChange={e => setClientForm({...clientForm, nome: e.target.value})} />
          <Input label="Telefone" type="tel" value={clientForm.telefone || ''} onChange={e => setClientForm({...clientForm, telefone: e.target.value})} />
          <Input label="Endereço" value={clientForm.endereco || ''} onChange={e => setClientForm({...clientForm, endereco: e.target.value})} />
          <div className="grid grid-cols-2 gap-4">
            <Input label="Bairro" value={clientForm.bairro || ''} onChange={e => setClientForm({...clientForm, bairro: e.target.value})} />
            <Input label="Cidade" value={clientForm.cidade || ''} onChange={e => setClientForm({...clientForm, cidade: e.target.value})} />
          </div>
          <Button fullWidth onClick={handleSaveClient} isLoading={loading} disabled={processingImage}>
            Salvar Alterações
          </Button>
        </div>
      </Modal>

      {/* Edit Installment, Pay, Return, Delete Modals (Same as before) */}
      <Modal isOpen={!!editInstallment} onClose={() => setEditInstallment(null)} title="Editar Parcela">
        <div className="space-y-4">
           <Input label="Valor" type="number" value={editForm.valor} onChange={(e) => setEditForm(prev => ({ ...prev, valor: e.target.value }))} />
           <Input label="Vencimento" type="date" value={editForm.data_vencimento} onChange={(e) => setEditForm(prev => ({ ...prev, data_vencimento: e.target.value }))} />
           <Button fullWidth onClick={handleSaveEdit} isLoading={loading}>Salvar</Button>
        </div>
      </Modal>

      <Modal isOpen={!!payInstallment} onClose={() => setPayInstallment(null)} title="Receber Parcela">
        <div className="text-center space-y-4">
           <p className="text-gray-600 dark:text-gray-300">Confirmar recebimento?</p>
           <Input label="Valor Recebido" type="number" value={paymentAmount} onChange={(e) => setPaymentAmount(e.target.value)} className="text-center font-bold text-xl text-green-600 dark:text-green-500" />
           <div className="grid grid-cols-2 gap-3 pt-2">
             <Button variant="secondary" onClick={() => setPayInstallment(null)}>Cancelar</Button>
             <Button onClick={handlePay} isLoading={loading} className="bg-green-600">Confirmar</Button>
           </div>
        </div>
      </Modal>

      <Modal isOpen={!!returnSaleId} onClose={() => setReturnSaleId(null)} title="Devolver Produto">
         <div className="text-center space-y-4">
             <p className="text-gray-600 dark:text-gray-300">Confirmar devolução?</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setReturnSaleId(null)}>Cancelar</Button>
                 <Button variant="primary" onClick={handleReturnSale} isLoading={loading} className="bg-orange-600">Confirmar</Button>
             </div>
         </div>
      </Modal>

      <Modal isOpen={!!deleteSaleId} onClose={() => setDeleteSaleId(null)} title="Excluir Registro">
         <div className="text-center space-y-4">
             <p className="text-gray-600 dark:text-gray-300">Apagar permanentemente?</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setDeleteSaleId(null)}>Cancelar</Button>
                 <Button variant="danger" onClick={handleDeleteSale} isLoading={loading}>Excluir</Button>
             </div>
         </div>
      </Modal>

      {receiptData && <ReceiptModal isOpen={!!receiptData} onClose={() => setReceiptData(null)} type={receiptData.type} data={receiptData.data} client={client} />}
    </div>
  );
};

