export default Dashboard;

import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Input, Card, Modal } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';
import { Client, Product, CartItem, Installment } from '../types';
import { addMonths, format } from 'date-fns';

const NewSale: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const session = authService.getSession();

  const [step, setStep] = useState<1|2|3>(1);
  const [clients, setClients] = useState<Client[]>([]);
  const [products, setProducts] = useState<Product[]>([]);

  // Search States
  const [clientSearch, setClientSearch] = useState('');

  // Sale State
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [installmentsCount, setInstallmentsCount] = useState(1);
  const [generatedInstallments, setGeneratedInstallments] = useState<Omit<Installment, 'id' | 'venda_id'>[]>([]);
  const [loading, setLoading] = useState(false);

  // New Product Modal State
  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [newProductForm, setNewProductForm] = useState({
    nome: '',
    categoria: '',
    valor_avista: '',
    valor_parcelado: ''
  });

  useEffect(() => {
    const init = async () => {
      const [c, p] = await Promise.all([dataService.getClients(), dataService.getProducts()]);
      setClients(c);
      setProducts(p);

      // Handle pre-selected client from navigation state
      const state = location.state as { client?: Client };
      if (state?.client) {
        setSelectedClient(state.client);
        setStep(2);
      }
    };
    init();
  }, [location.state]);

  // -- FILTER LOGIC --
  const filteredClients = clients.filter(c => 
    c.nome.toLowerCase().includes(clientSearch.toLowerCase()) || 
    c.telefone.includes(clientSearch)
  );

  // -- STEP 1: Select Client --
  const handleClientSelect = (client: Client) => {
    setSelectedClient(client);
    setStep(2);
  };

  // -- STEP 2: Products --
  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(p => p.id === product.id);
      if (existing) {
        return prev.map(p => p.id === product.id ? { ...p, quantity: p.quantity + 1 } : p);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(p => p.id !== productId));
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.valor_parcelado * item.quantity), 0);

  // -- STEP 2.5: New Product on the fly --
  const handleOpenNewProduct = () => {
      setNewProductForm({ nome: '', categoria: '', valor_avista: '', valor_parcelado: '' });
      setIsProductModalOpen(true);
  };

  const handleSaveNewProduct = async () => {
      if (!newProductForm.nome || !newProductForm.valor_parcelado) return;
      setLoading(true);
      try {
          await dataService.createProduct({
              nome: newProductForm.nome,
              categoria: newProductForm.categoria || 'Geral',
              valor_avista: Number(newProductForm.valor_avista) || 0,
              valor_parcelado: Number(newProductForm.valor_parcelado),
              ativo: true
          });

          // Refresh list
          const updatedProducts = await dataService.getProducts();
          setProducts(updatedProducts);

          setIsProductModalOpen(false);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  // -- STEP 3: Installments --
  const generateInstallments = () => {
    const list: Omit<Installment, 'id' | 'venda_id'>[] = [];
    const baseValue = Math.floor((cartTotal / installmentsCount) * 100) / 100;
    const remainder = Math.round((cartTotal - (baseValue * installmentsCount)) * 100) / 100;

    const today = new Date();

    for (let i = 0; i < installmentsCount; i++) {
      let val = baseValue;
      if (i === installmentsCount - 1) val += remainder;

      list.push({
        numero_parcela: i + 1,
        valor: val,
        data_vencimento: addMonths(today, i + 1).toISOString(), // First installment next month
        pago: false
      });
    }
    setGeneratedInstallments(list);
  };

  useEffect(() => {
    if (step === 3) generateInstallments();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [installmentsCount, step]);

  const handleFinishSale = async () => {
    if (!selectedClient || cart.length === 0 || !session) return;
    setLoading(true);
    try {
      await dataService.createSale({
        cliente_id: selectedClient.id,
        vendedor_id: session.id,
        valor_total: cartTotal,
        qtd_parcelas: installmentsCount,
        data_venda: new Date().toISOString()
      }, generatedInstallments);

      navigate(ROUTES.SALES);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  // --- RENDER HELPERS ---

  return (
    <div className="flex flex-col h-screen bg-[#F3F4F6] dark:bg-[#121212] text-gray-900 dark:text-white transition-colors duration-300">
      {/* Header */}
      <div className="bg-white dark:bg-[#1E1E1E] p-4 pt-12 flex items-center gap-4 border-b border-gray-100 dark:border-[#333] transition-colors shadow-sm">
        <button onClick={() => step > 1 ? setStep(prev => prev - 1 as any) : navigate(-1)} className="text-gray-900 dark:text-white">
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold">
          {step === 1 ? 'Selecionar Cliente' : step === 2 ? 'Adicionar Produtos' : 'Pagamento'}
        </h1>
        <div className="ml-auto text-xs bg-[#FF7A00]/10 text-[#FF7A00] font-bold px-2 py-1 rounded-lg">Passo {step}/3</div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
        {step === 1 && (
          <div className="space-y-4">
             <div className="relative">
                <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">
                    {ICONS.Search}
                </div>
                <Input 
                  placeholder="Buscar cliente por nome ou telefone..." 
                  className="pl-12"
                  value={clientSearch}
                  onChange={(e) => setClientSearch(e.target.value)}
                  autoFocus
                />
             </div>

             <div className="space-y-3">
                 {filteredClients.map(c => (
                   <Card key={c.id} onClick={() => handleClientSelect(c)} className="flex items-center justify-between hover:border-[#FF7A00] cursor-pointer transition-colors group">
                     <div className="flex items-center gap-3">
                       <div className="w-10 h-10 rounded-full bg-gray-100 dark:bg-[#333] flex items-center justify-center text-gray-500 font-bold overflow-hidden">
                          {c.foto_url ? <img src={c.foto_url} className="w-full h-full object-cover" /> : c.nome.charAt(0)}
                       </div>
                       <div>
                         <p className="font-bold text-gray-900 dark:text-white group-hover:text-[#FF7A00] transition-colors">{c.nome}</p>
                         <p className="text-gray-500 text-xs">{c.bairro || 'Sem endereço'}</p>
                       </div>
                     </div>
                     <div className="text-gray-300 group-hover:text-[#FF7A00]">{ICONS.Right}</div>
                   </Card>
                 ))}
                 {filteredClients.length === 0 && (
                     <div className="text-center py-8">
                         <div className="text-gray-300 mb-2">{ICONS.Search}</div>
                         <p className="text-gray-500 text-sm">Nenhum cliente encontrado.</p>
                     </div>
                 )}
             </div>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-6">
            <div>
              <div className="flex justify-between items-center mb-3">
                  <h3 className="text-gray-500 text-sm font-bold uppercase">Produtos Disponíveis</h3>
                  <button 
                    onClick={handleOpenNewProduct}
                    className="text-xs bg-[#FF7A00] text-white px-3 py-2 rounded-xl font-bold flex items-center gap-1 shadow-lg shadow-orange-500/20"
                  >
                    {ICONS.Add} Cadastrar Novo
                  </button>
              </div>

              <div className="space-y-2">
                {products.length === 0 && (
                    <p className="text-gray-500 text-center py-4 text-sm">Nenhum produto cadastrado.</p>
                )}
                {products.map(p => (
                  <div key={p.id} className="bg-white dark:bg-[#1E1E1E] p-4 rounded-2xl flex justify-between items-center border border-gray-100 dark:border-[#333] shadow-sm">
                    <div>
                      <p className="text-gray-900 dark:text-white font-bold">{p.nome}</p>
                      <p className="text-[#FF7A00] font-bold text-sm">R$ {p.valor_parcelado.toFixed(2)}</p>
                    </div>
                    <Button variant="secondary" onClick={() => addToCart(p)} className="!p-2.5 rounded-xl">
                      {ICONS.Add}
                    </Button>
                  </div>
                ))}
              </div>
            </div>

            {cart.length > 0 && (
              <div className="border-t-2 border-dashed border-gray-200 dark:border-[#333] pt-6 pb-20">
                <h3 className="text-gray-900 dark:text-white font-bold mb-4">Carrinho</h3>
                {cart.map(item => (
                  <div key={item.id} className="flex justify-between items-center mb-3 bg-white dark:bg-[#1E1E1E] p-3 rounded-xl border border-gray-100 dark:border-[#333]">
                    <span className="text-gray-700 dark:text-gray-300 text-sm font-medium">{item.quantity}x {item.nome}</span>
                    <div className="flex items-center gap-3">
                      <span className="text-gray-900 dark:text-white font-bold">R$ {(item.valor_parcelado * item.quantity).toFixed(2)}</span>
                      <button onClick={() => removeFromCart(item.id)} className="text-red-400 bg-red-50 p-1.5 rounded-lg">
                        {ICONS.Close}
                      </button>
                    </div>
                  </div>
                ))}
                <div className="mt-4 flex justify-between items-center bg-[#FF7A00]/10 p-4 rounded-xl border border-[#FF7A00]/20">
                  <span className="text-[#FF7A00] font-bold">Total Estimado</span>
                  <span className="text-[#FF7A00] font-black text-xl">R$ {cartTotal.toFixed(2)}</span>
                </div>
              </div>
            )}
          </div>
        )}

        {step === 3 && (
           <div className="space-y-6">
             <Card className="text-center py-8 bg-white dark:bg-[#1E1E1E]">
               <p className="text-gray-400 text-xs font-bold uppercase mb-1">Valor Total</p>
               <h2 className="text-4xl font-black text-[#FF7A00] mb-2">R$ {cartTotal.toFixed(2)}</h2>
               <div className="inline-block bg-gray-100 dark:bg-[#333] px-3 py-1 rounded-full text-xs text-gray-600 dark:text-gray-300 font-bold">
                  Cliente: {selectedClient?.nome}
               </div>
             </Card>

             <div className="space-y-3">
               <label className="text-gray-700 dark:text-gray-300 font-bold ml-1">Número de Parcelas</label>
               <div className="grid grid-cols-4 gap-2">
                 {[1,2,3,4,5,6,10,12].map(num => (
                   <button 
                    key={num}
                    onClick={() => setInstallmentsCount(num)}
                    className={`h-12 rounded-xl font-bold transition-all shadow-sm ${installmentsCount === num ? 'bg-[#FF7A00] text-white shadow-orange-500/30 translate-y-[-2px]' : 'bg-white dark:bg-[#1E1E1E] text-gray-500 dark:text-gray-400 border border-gray-200 dark:border-[#333]'}`}
                   >
                     {num}x
                   </button>
                 ))}
               </div>
             </div>

             <div className="space-y-3 pb-20">
               <h3 className="text-gray-900 dark:text-white font-bold ml-1">Resumo das Parcelas</h3>
               {generatedInstallments.map((inst, idx) => (
                 <div key={idx} className="flex justify-between items-center p-4 bg-white dark:bg-[#1E1E1E] rounded-xl border border-gray-100 dark:border-[#333] shadow-sm">
                   <div className="flex flex-col">
                      <span className="text-gray-900 dark:text-white font-bold text-sm">Parcela {inst.numero_parcela}/{installmentsCount}</span>
                      <span className="text-gray-400 text-xs">{format(new Date(inst.data_vencimento), 'dd/MM/yyyy')}</span>
                   </div>
                   <span className="text-[#FF7A00] font-bold text-lg">R$ {inst.valor.toFixed(2)}</span>
                 </div>
               ))}
             </div>
           </div>
        )}
      </div>

      <div className="p-4 bg-white dark:bg-[#1E1E1E] border-t border-gray-100 dark:border-[#333] sticky bottom-0 z-20 shadow-[0_-10px_40px_rgba(0,0,0,0.05)]">
        {step === 2 && (
          <Button 
            fullWidth 
            onClick={() => setStep(3)} 
            disabled={cart.length === 0}
            className="py-4"
          >
            Continuar para Pagamento
          </Button>
        )}
        {step === 3 && (
          <Button fullWidth onClick={handleFinishSale} isLoading={loading} className="py-4">
            Finalizar Venda
          </Button>
        )}
      </div>

      {/* New Product Modal */}
      <Modal isOpen={isProductModalOpen} onClose={() => setIsProductModalOpen(false)} title="Novo Produto Rápido">
         <div className="space-y-4">
            <Input 
                label="Nome do Produto"
                value={newProductForm.nome}
                onChange={(e) => setNewProductForm({...newProductForm, nome: e.target.value})}
            />
            <Input 
                label="Categoria (Opcional)"
                value={newProductForm.categoria}
                onChange={(e) => setNewProductForm({...newProductForm, categoria: e.target.value})}
            />
            <div className="grid grid-cols-2 gap-4">
                <Input 
                    label="Valor à Vista"
                    type="number"
                    value={newProductForm.valor_avista}
                    onChange={(e) => setNewProductForm({...newProductForm, valor_avista: e.target.value})}
                />
                <Input 
                    label="Valor Parcelado *"
                    type="number"
                    value={newProductForm.valor_parcelado}
                    onChange={(e) => setNewProductForm({...newProductForm, valor_parcelado: e.target.value})}
                />
            </div>
            <Button fullWidth onClick={handleSaveNewProduct} isLoading={loading}>
                Cadastrar e Adicionar
            </Button>
         </div>
      </Modal>

    </div>
  );
};

