import { createClient } from '@supabase/supabase-js';

// Chaves do LocalStorage (onde salvamos o que você digita na tela de Login)
const LS_KEY = 'cla_supabase_key';
const LS_URL = 'cla_supabase_url';

// 1. Tenta pegar do armazenamento local
const storedUrl = localStorage.getItem(LS_URL);
const storedKey = localStorage.getItem(LS_KEY);

// 2. Tenta pegar do arquivo .env (se existir)
// @ts-ignore
const envUrl = typeof import.meta !== 'undefined' && import.meta.env ? import.meta.env.VITE_SUPABASE_URL : '';
// @ts-ignore
const envKey = typeof import.meta !== 'undefined' && import.meta.env ? import.meta.env.VITE_SUPABASE_KEY : '';

// 3. Define valores de Fallback (Placeholder) para o app não travar se não tiver nada configurado
// Isso permite que o Modo Offline funcione
const DUMMY_URL = 'https://placeholder.supabase.co';
const DUMMY_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.placeholder';

// Lógica de Prioridade: LocalStorage > Env > Dummy
const finalUrl = storedUrl ? storedUrl.trim() : (envUrl || DUMMY_URL);
const finalKey = storedKey ? storedKey.trim() : (envKey || DUMMY_KEY);

// Verifica se está realmente configurado (não é dummy e tem formato de URL)
export const isSupabaseConfigured = 
  finalUrl !== DUMMY_URL && 
  finalKey !== DUMMY_KEY &&
  finalUrl.startsWith('http');

// Função chamada pelo Modal de Login
export const configureSupabase = (key: string, url: string) => {
  if (key) localStorage.setItem(LS_KEY, key.trim());
  if (url) localStorage.setItem(LS_URL, url.trim());
  // Força recarregamento para o createClient pegar os novos dados
  window.location.reload(); 
};

export const clearSupabaseConfig = () => {
  localStorage.removeItem(LS_KEY);
  localStorage.removeItem(LS_URL);
  window.location.reload();
};

// Inicializa o cliente Supabase
// Se estiver offline/sem config, ele inicia com dados fake para não quebrar a UI
export const supabase = createClient(finalUrl, finalKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
  }
});

