import { createClient } from '@supabase/supabase-js';

// Chaves do LocalStorage
const LS_KEY = 'cla_supabase_key';
const LS_URL = 'cla_supabase_url';

// --- VALORES DE FALLBACK (DUMMY) ---
// Estes valores são usados quando o usuário ainda não configurou o banco.
// Eles permitem que a UI carregue no modo "Offline/Demo" sem travar.
const DUMMY_URL = 'https://placeholder.supabase.co';
const DUMMY_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.placeholder';

// 1. Recuperar do Storage
const storedUrl = localStorage.getItem(LS_URL);
const storedKey = localStorage.getItem(LS_KEY);

// 2. Recuperar do Env (opcional)
// @ts-ignore
const envUrl = typeof import.meta !== 'undefined' && import.meta.env ? import.meta.env.VITE_SUPABASE_URL : '';
// @ts-ignore
const envKey = typeof import.meta !== 'undefined' && import.meta.env ? import.meta.env.VITE_SUPABASE_KEY : '';

// 3. Determinar URL Final com Higienização
let finalUrl = DUMMY_URL;
let finalKey = DUMMY_KEY;

// Prioridade: Storage > Env > Dummy
if (storedUrl && storedUrl.includes('http')) {
    finalUrl = storedUrl.trim();
} else if (envUrl && envUrl.includes('http')) {
    finalUrl = envUrl.trim();
}

if (storedKey && storedKey.length > 20) {
    finalKey = storedKey.trim();
} else if (envKey && envKey.length > 20) {
    finalKey = envKey.trim();
}

// 4. Configuração de Estado
// Só consideramos "Configurado" se NÃO for o Dummy e a URL for válida.
export const isSupabaseConfigured = 
  finalUrl !== DUMMY_URL && 
  finalKey !== DUMMY_KEY &&
  finalUrl.startsWith('http');

// 5. Funções Auxiliares
export const configureSupabase = (key: string, url: string) => {
  if (key) localStorage.setItem(LS_KEY, key.trim());
  if (url) localStorage.setItem(LS_URL, url.trim());
  window.location.reload(); 
};

export const clearSupabaseConfig = () => {
  localStorage.removeItem(LS_KEY);
  localStorage.removeItem(LS_URL);
  window.location.reload();
};

// 6. Criar Cliente de forma Segura
// Mesmo se a URL for o Dummy, o createClient não quebra a página, apenas falha nas requisições (o que tratamos no authService).
export const supabase = createClient(finalUrl, finalKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: false // Evita erros de redirecionamento em alguns ambientes
  }
});

