    const newInstallments = installmentsData.map(i => ({ ...i, id: uuidv4(), venda_id: newSaleId, pago: false, data_pagamento: null }));
    setStorage('sales', [newSale, ...sales]);
    setStorage('installments', [...installments, ...newInstallments]);
  },

