                }`}>
                    {testStatus === 'testing' && <span className="animate-spin">⌛</span>}
                    {testStatus === 'success' && <CheckCircle size={14} />}
                    {testStatus === 'error' && <AlertTriangle size={14} />}
                    {testMessage}
