            )}

            <Button fullWidth onClick={handleSaveConfig} isLoading={testStatus === 'testing'}>
               Testar Conexão e Salvar
            </Button>

            {!isSupabaseConfigured && (
               <div className="mt-4 pt-4 border-t border-gray-200 dark:border-white/10">
