                    <span className="bg-gray-100 dark:bg-white/5 px-2 py-1 rounded text-xs text-gray-500">admin@cla.com</span>
                    <span className="bg-gray-100 dark:bg-white/5 px-2 py-1 rounded text-xs text-gray-500">123456</span>
                 </div>
               </div>
            )}
         </div>
      </Modal>
    </div>
  );
};

