ALTER TABLE IF EXISTS users DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS clients DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS products DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS sales DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS installments DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS cash_flow DISABLE ROW LEVEL SECURITY;

-- 2. RELAXAR RESTRIÇÕES DE VENDEDOR
DO $$
BEGIN
    ALTER TABLE clients ALTER COLUMN vendedor_id TYPE text;
    ALTER TABLE clients ALTER COLUMN vendedor_id DROP NOT NULL;

    ALTER TABLE sales ALTER COLUMN vendedor_id TYPE text;
