const isValidKey = (key: string | null) => {
    if (!key) return false;
    const cleanKey = key.trim();
    return (
        cleanKey.length > 20 && 
        !cleanKey.startsWith('sb_') && 
        !cleanKey.includes('publishable')
    );
};

