const deleteCashEntry = async (id: string): Promise<void> => {
      if (isSupabaseConfigured) {
          const { error } = await supabase.from('cash_flow').delete().eq('id', id);
          if (error) handleSupabaseError(error);
          return;
      }
      await delay(300);
