           {payDiff > 0 && (
               <div className="mt-2 text-xs bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 p-2 rounded">
                   Faltam <strong>R$ {payDiff.toFixed(2)}</strong>. Este valor será somado à próxima parcela (ou criado uma nova).
               </div>
           )}
           {payDiff < 0 && (
               <div className="mt-2 text-xs bg-green-50 dark:bg-green-900/20 text-green-600 dark:text-green-400 p-2 rounded">
                   Pagou <strong>R$ {Math.abs(payDiff).toFixed(2)}</strong> a mais. Este valor será descontado da próxima parcela.
               </div>
           )}

           <div className="grid grid-cols-2 gap-3 pt-2">
             <Button variant="secondary" onClick={() => setPayInstallment(null)}>Cancelar</Button>
             <Button onClick={handlePay} isLoading={loading} className="bg-green-600">Confirmar</Button>
           </div>
        </div>
      </Modal>

      <Modal isOpen={!!returnSaleId} onClose={() => setReturnSaleId(null)} title="Devolver Produto">
         <div className="text-center space-y-4">
             <p className="text-gray-600 dark:text-gray-300">Confirmar devolução?</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setReturnSaleId(null)}>Cancelar</Button>
                 <Button variant="primary" onClick={handleReturnSale} isLoading={loading} className="bg-orange-600">Confirmar</Button>
             </div>
         </div>
      </Modal>

      <Modal isOpen={!!deleteSaleId} onClose={() => setDeleteSaleId(null)} title="Excluir Registro">
         <div className="text-center space-y-4">
             <p className="text-gray-600 dark:text-gray-300">Apagar permanentemente?</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setDeleteSaleId(null)}>Cancelar</Button>
                 <Button variant="danger" onClick={handleDeleteSale} isLoading={loading}>Excluir</Button>
             </div>
         </div>
      </Modal>

      {receiptData && (
          <ReceiptModal 
            isOpen={!!receiptData} 
            onClose={() => setReceiptData(null)} 
            type={receiptData.type} 
            data={receiptData.data} 
            client={client} 
            totalValue={receiptData.totalValue}
            remaining={receiptData.remaining}
            description={receiptData.description}
            history={receiptData.history}
          />
      )}
    </div>
  );
};

export default ClientDetails;

export type UserProfileType = 'admin' | 'vendedor';

export interface User {
  id: string;
  email: string;
  nome: string;
  perfil: UserProfileType;
  telefone?: string;
  ativo: boolean;
  comissao_porcentagem?: number; // New field for commission rate (e.g., 5 for 5%)
}

export interface Client {
  id: string;
  nome: string;
  telefone: string;
  endereco: string;
  bairro: string;
  cidade: string;
  observacoes?: string;
  vendedor_id: string;
  foto_url?: string; // Base64 string or URL
  is_mumbuca?: boolean; // Flag para identificar cliente que usa moeda social
}

export interface Product {
  id: string;
  nome: string;
  categoria: string;
  valor_avista: number;
  valor_parcelado: number;
  ativo: boolean;
}

export type SaleStatus = 'ABERTA' | 'PARCIAL' | 'QUITADA' | 'DEVOLVIDO';

export interface Sale {
  id: string;
  cliente_id: string;
  vendedor_id: string;
  valor_total: number;
  qtd_parcelas: number;
  data_venda: string; // ISO Date
  status: SaleStatus;
  cliente_nome?: string; // Helper for UI
  is_mumbuca?: boolean; // Nova flag para Moeda Social
  descricao?: string; // Lista de produtos (Ex: "2x Cama, 1x Mesa")
}

export interface Installment {
  id: string;
  venda_id: string;
  numero_parcela: number;
  valor: number;
  data_vencimento: string; // ISO Date
  pago: boolean;
  data_pagamento?: string | null;
}

export type CashFlowType = 'ENTRADA' | 'SAIDA';

export interface CashEntry {
  id: string;
  data: string; // ISO Date
  tipo: CashFlowType;
  valor: number;
  descricao: string;
  vendedor_id: string;
  venda_id?: string; // Optional link to sale for refunds/returns
}

export interface CartItem extends Product {
  quantity: number;
}

// Report Types
export interface SellerReport {
  vendedor_nome: string;
