    let textToCopy = installSQL;
    if (activeTab === 'rls') textToCopy = fixRLSSQL;

    navigator.clipboard.writeText(textToCopy);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="min-h-screen bg-[#1A1A1A] p-6 flex flex-col items-center">
      <div className="w-full max-w-2xl space-y-6">

        {/* Header */}
        <div className="flex items-center gap-4">
          <button 
            onClick={() => navigate(ROUTES.LOGIN)} 
            className="p-2 bg-[#2E2E2E] rounded-full text-white hover:bg-[#333]"
          >
            {ICONS.Left}
          </button>
          <h1 className="text-2xl font-bold text-white">Setup do Banco de Dados</h1>
        </div>

        <Card className="bg-[#2E2E2E] border-l-4 border-blue-500">
          <h3 className="text-white font-bold text-lg mb-2">Correção de Banco & RLS</h3>
          <p className="text-gray-300 text-sm mb-2">
             Atualizado: Inclui coluna para descrição detalhada dos produtos e correções de permissão.
          </p>
        </Card>

        {/* Tabs */}
        <div className="flex gap-2">
          <button 
            onClick={() => setActiveTab('install')}
            className={`flex-1 py-3 rounded-lg text-xs font-bold transition-colors flex flex-col items-center gap-1 ${activeTab === 'install' ? 'bg-blue-600 text-white ring-2 ring-blue-500/50' : 'bg-[#333] text-gray-400 hover:bg-[#404040]'}`}
          >
            <span>🚀 INSTALAÇÃO COMPLETA</span>
            <span className="text-[9px] font-normal opacity-70">Zera e Cria Tudo</span>
          </button>
          <button 
            onClick={() => setActiveTab('rls')}
            className={`flex-1 py-3 rounded-lg text-xs font-bold transition-colors flex flex-col items-center gap-1 ${activeTab === 'rls' ? 'bg-green-600 text-white ring-2 ring-green-500/50' : 'bg-[#333] text-gray-400 hover:bg-[#404040]'}`}
          >
            <span>🛡️ CORRIGIR ERROS</span>
            <span className="text-[9px] font-normal opacity-70">Add Colunas + Permissões</span>
          </button>
        </div>

        <div className="relative group">
          <div className="flex justify-between items-center mb-2 bg-[#111] p-2 rounded-t-xl border-b border-white/10">
            <label className="text-gray-400 text-xs font-mono pl-2">
                SQL QUERY (Copie e cole no Supabase)
            </label>
            <button 
              onClick={copyToClipboard}
              className={`text-xs px-4 py-1.5 rounded-lg font-bold transition-colors ${copied ? 'bg-green-500 text-white' : 'bg-white text-black hover:bg-gray-200'}`}
            >
              {copied ? 'Copiado!' : 'Copiar Código SQL'}
            </button>
          </div>
          <textarea 
            readOnly
            value={activeTab === 'install' ? installSQL : fixRLSSQL}
            className="w-full h-80 bg-[#111] text-green-400 font-mono text-xs p-4 rounded-b-xl border border-white/10 focus:outline-none resize-none"
          />
        </div>

        <Button fullWidth onClick={() => navigate(ROUTES.LOGIN)}>
          Voltar para Login
        </Button>

      </div>
    </div>
  );
};

export default Setup;

import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Input, Card, Modal } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';
import { Client, Product, CartItem, Installment } from '../types';
import { addMonths, format } from 'date-fns';

const NewSale: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const session = authService.getSession();

  const [step, setStep] = useState<1|2|3>(1);
  const [clients, setClients] = useState<Client[]>([]);
  const [products, setProducts] = useState<Product[]>([]);

  // Search States
  const [clientSearch, setClientSearch] = useState('');

  // Sale State
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [installmentsCount, setInstallmentsCount] = useState(1);
  const [generatedInstallments, setGeneratedInstallments] = useState<Omit<Installment, 'id' | 'venda_id'>[]>([]);
  const [loading, setLoading] = useState(false);

  // Mumbuca State
  const [isMumbuca, setIsMumbuca] = useState(false);

  // New Product Modal State
  const [isProductModalOpen, setIsProductModalOpen] = useState(false);
  const [newProductForm, setNewProductForm] = useState({
    nome: '',
    categoria: '',
    valor_avista: '',
    valor_parcelado: ''
  });

  // 1. Session Check (Crucial for standalone pages)
  useEffect(() => {
    if (!session) {
        alert("Sessão expirada. Faça login novamente.");
        navigate(ROUTES.LOGIN);
    }
  }, [session, navigate]);

  useEffect(() => {
    const init = async () => {
      const [c, p] = await Promise.all([dataService.getClients(), dataService.getProducts()]);
      setClients(c);
      setProducts(p);

      // Handle pre-selected client from navigation state
      const state = location.state as { client?: Client };
      if (state?.client) {
        setSelectedClient(state.client);
        setStep(2);
      }
    };
    init();
  }, [location.state]);

  // -- FILTER LOGIC --
  const normalizeText = (text: string) => {
    return (text || '').normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  };

  const cleanPhone = (phone: string) => {
    return (phone || '').replace(/\D/g, '');
  };

  const filteredClients = clients.filter(c => {
    const searchNorm = normalizeText(clientSearch);
    const searchPhone = cleanPhone(clientSearch);

    const nameMatch = normalizeText(c.nome).includes(searchNorm);
    const phoneMatch = searchPhone.length > 0 && cleanPhone(c.telefone).includes(searchPhone);

    return nameMatch || phoneMatch;
  });

  // -- STEP 1: Select Client --
  const handleClientSelect = (client: Client) => {
    setSelectedClient(client);
    setStep(2);
  };

  // -- STEP 2: Products --
  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(p => p.id === product.id);
      if (existing) {
        return prev.map(p => p.id === product.id ? { ...p, quantity: p.quantity + 1 } : p);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => prev.filter(p => p.id !== productId));
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.valor_parcelado * item.quantity), 0);

  // -- STEP 2.5: New Product on the fly --
  const handleOpenNewProduct = () => {
      setNewProductForm({ nome: '', categoria: '', valor_avista: '', valor_parcelado: '' });
      setIsProductModalOpen(true);
  };

  const handleSaveNewProduct = async () => {
      if (!newProductForm.nome || !newProductForm.valor_parcelado) return;
      setLoading(true);
      try {
          await dataService.createProduct({
              nome: newProductForm.nome,
              categoria: newProductForm.categoria || 'Geral',
              valor_avista: Number(newProductForm.valor_avista) || 0,
              valor_parcelado: Number(newProductForm.valor_parcelado),
              ativo: true
          });

          const updatedProducts = await dataService.getProducts();
          setProducts(updatedProducts);
          setIsProductModalOpen(false);
      } catch (e) {
          console.error(e);
          alert("Erro ao criar produto.");
      } finally {
          setLoading(false);
      }
  };

  // -- STEP 3: Installments --
  const generateInstallments = () => {
    const list: Omit<Installment, 'id' | 'venda_id'>[] = [];
    const baseValue = Math.floor((cartTotal / installmentsCount) * 100) / 100;
    const remainder = Math.round((cartTotal - (baseValue * installmentsCount)) * 100) / 100;

    const today = new Date();

    for (let i = 0; i < installmentsCount; i++) {
      let val = baseValue;
      if (i === installmentsCount - 1) val += remainder;

      list.push({
        numero_parcela: i + 1,
        valor: val,
        data_vencimento: addMonths(today, i + 1).toISOString(),
        pago: false
      });
    }
    setGeneratedInstallments(list);
  };

  useEffect(() => {
    if (step === 3) generateInstallments();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [installmentsCount, step]);

  const handleFinishSale = async () => {
    // 2. Explicit Validation
    if (!session) {
        alert("Erro de autenticação. Faça login novamente.");
        return;
    }
    if (!selectedClient) {
        alert("Erro: Nenhum cliente selecionado.");
        return;
    }
    if (cart.length === 0) {
        alert("Erro: Carrinho vazio.");
        return;
    }

    setLoading(true);
    try {
      // 3. Generate Description
      const description = cart.map(item => `${item.quantity}x ${item.nome}`).join(', ');

      await dataService.createSale({
        cliente_id: selectedClient.id,
        vendedor_id: session.id,
        valor_total: cartTotal,
        qtd_parcelas: installmentsCount,
        data_venda: new Date().toISOString(),
        is_mumbuca: isMumbuca,
        descricao: description
      }, generatedInstallments);

      // Success Feedback
      navigate(ROUTES.SALES);
    } catch (e: any) {
      console.error("Erro venda:", e);
      let msg = e.message || "Erro desconhecido";

      if (msg.includes('descricao') && msg.includes('does not exist')) {
          msg = "Erro no Banco de Dados: Coluna 'Descrição' não existe. Vá em Configurações > Banco de Dados > Corrigir Erros.";
      }

      alert(`Falha ao finalizar venda:\n${msg}`);
    } finally {
      setLoading(false);
    }
  };

  // --- RENDER ---

  return (
    <div className="flex flex-col h-screen bg-[#F3F4F6] dark:bg-[#121212] text-gray-900 dark:text-white transition-colors duration-300">
      {/* Header */}
      <div className="bg-white dark:bg-[#1E1E1E] p-4 pt-12 flex items-center gap-4 border-b border-gray-100 dark:border-[#333] transition-colors shadow-sm sticky top-0 z-30">
        <button onClick={() => step > 1 ? setStep(prev => prev - 1 as any) : navigate(-1)} className="text-gray-900 dark:text-white">
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold">
          {step === 1 ? 'Selecionar Cliente' : step === 2 ? 'Adicionar Produtos' : 'Pagamento'}
        </h1>
        <div className="ml-auto text-xs bg-[#FF7A00]/10 text-[#FF7A00] font-bold px-3 py-1.5 rounded-full">Passo {step}/3</div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
        {step === 1 && (
          <div className="space-y-4">
             <div className="relative">
                <div className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 z-10 pointer-events-none">
                    {ICONS.Search}
                </div>
                <Input 
                  placeholder="Buscar por nome ou telefone..." 
                  className="pl-12 py-4 shadow-sm"
                  value={clientSearch}
                  onChange={(e) => setClientSearch(e.target.value)}
                  autoFocus
                />
                {clientSearch && (
                  <button 
                    onClick={() => setClientSearch('')}
                    className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 p-1"
                  >
                    {ICONS.Close}
                  </button>
                )}
             </div>

             <div className="space-y-3 pb-20">
                 {filteredClients.map(c => (
                   <Card key={c.id} onClick={() => handleClientSelect(c)} className="flex items-center justify-between hover:border-[#FF7A00] cursor-pointer transition-colors group">
                     <div className="flex items-center gap-3">
                       <div className="w-12 h-12 rounded-full bg-gray-100 dark:bg-[#333] flex items-center justify-center text-gray-500 font-bold overflow-hidden border border-gray-200 dark:border-white/10">
                          {c.foto_url ? <img src={c.foto_url} className="w-full h-full object-cover" /> : c.nome.charAt(0)}
                       </div>
                       <div>
                         <p className="font-bold text-gray-900 dark:text-white group-hover:text-[#FF7A00] transition-colors text-lg">{c.nome}</p>
                         <p className="text-gray-500 text-sm">{c.bairro || 'Endereço não informado'}</p>
                       </div>
                     </div>
                     <div className="text-gray-300 group-hover:text-[#FF7A00]">{ICONS.Right}</div>
                   </Card>
                 ))}
                 {filteredClients.length === 0 && (
                     <div className="text-center py-10 opacity-70">
                         <div className="text-gray-300 mb-2 flex justify-center scale-150">{ICONS.Search}</div>
                         <p className="text-gray-500 font-medium">Nenhum cliente encontrado.</p>
                         {clientSearch && <p className="text-xs text-gray-400 mt-1">Tente buscar por outro termo.</p>}
                     </div>
                 )}
             </div>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-6">
            <div>
              <div className="flex justify-between items-center mb-3">
                  <h3 className="text-gray-500 text-sm font-bold uppercase">Produtos Disponíveis</h3>
                  <button 
                    onClick={handleOpenNewProduct}
                    className="text-xs bg-[#FF7A00] text-white px-3 py-2 rounded-xl font-bold flex items-center gap-1 shadow-lg shadow-orange-500/20"
                  >
                    {ICONS.Add} Cadastrar Novo
                  </button>
              </div>

              <div className="space-y-2 pb-6">
                {products.length === 0 && (
                    <p className="text-gray-500 text-center py-4 text-sm">Nenhum produto cadastrado.</p>
                )}
                {products.map(p => (
                  <div key={p.id} className="bg-white dark:bg-[#1E1E1E] p-4 rounded-3xl flex justify-between items-center border border-gray-100 dark:border-[#333] shadow-sm">
                    <div>
                      <p className="text-gray-900 dark:text-white font-bold">{p.nome}</p>
                      <p className="text-[#FF7A00] font-bold text-sm">R$ {p.valor_parcelado.toFixed(2)}</p>
                    </div>
                    <Button variant="secondary" onClick={() => addToCart(p)} className="!p-3 rounded-2xl">
                      {ICONS.Add}
                    </Button>
                  </div>
                ))}
              </div>
            </div>

            {cart.length > 0 && (
              <div className="border-t-2 border-dashed border-gray-200 dark:border-[#333] pt-6 pb-24">
                <h3 className="text-gray-900 dark:text-white font-bold mb-4">Carrinho</h3>
                {cart.map(item => (
                  <div key={item.id} className="flex justify-between items-center mb-3 bg-white dark:bg-[#1E1E1E] p-3 rounded-2xl border border-gray-100 dark:border-[#333]">
                    <span className="text-gray-700 dark:text-gray-300 text-sm font-medium">{item.quantity}x {item.nome}</span>
                    <div className="flex items-center gap-3">
                      <span className="text-gray-900 dark:text-white font-bold">R$ {(item.valor_parcelado * item.quantity).toFixed(2)}</span>
                      <button onClick={() => removeFromCart(item.id)} className="text-red-400 bg-red-50 p-2 rounded-xl hover:bg-red-100 dark:hover:bg-red-900/20 transition-colors">
                        {ICONS.Close}
                      </button>
                    </div>
                  </div>
                ))}
                <div className="mt-4 flex justify-between items-center bg-[#FF7A00]/10 p-4 rounded-2xl border border-[#FF7A00]/20">
                  <span className="text-[#FF7A00] font-bold">Total Estimado</span>
                  <span className="text-[#FF7A00] font-black text-xl">R$ {cartTotal.toFixed(2)}</span>
                </div>
              </div>
            )}
          </div>
        )}

        {step === 3 && (
           <div className="space-y-6">
             <Card className="text-center py-8 bg-white dark:bg-[#1E1E1E]">
               <p className="text-gray-400 text-xs font-bold uppercase mb-1">Valor Total</p>
               <h2 className="text-4xl font-black text-[#FF7A00] mb-2">R$ {cartTotal.toFixed(2)}</h2>
               <div className="inline-block bg-gray-100 dark:bg-[#333] px-3 py-1 rounded-full text-xs text-gray-600 dark:text-gray-300 font-bold">
                  Cliente: {selectedClient?.nome}
               </div>
             </Card>

             {/* MUMBUCA TOGGLE */}
             <div 
                onClick={() => setIsMumbuca(!isMumbuca)}
                className={`p-4 rounded-2xl border-2 cursor-pointer transition-all flex items-center justify-between ${isMumbuca ? 'bg-red-50 border-red-500 dark:bg-red-900/20 dark:border-red-500' : 'bg-white border-gray-100 dark:bg-[#1E1E1E] dark:border-[#333]'}`}
             >
                <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center ${isMumbuca ? 'bg-red-500 text-white' : 'bg-gray-100 text-gray-400 dark:bg-[#333]'}`}>
                        {ICONS.Wallet}
                    </div>
                    <div>
                        <p className={`font-bold ${isMumbuca ? 'text-red-600 dark:text-red-400' : 'text-gray-900 dark:text-white'}`}>Moeda Social Mumbuca</p>
                        <p className="text-xs text-gray-500">Marcar esta venda com pagamento social</p>
                    </div>
                </div>
                <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center ${isMumbuca ? 'border-red-500 bg-red-500' : 'border-gray-300'}`}>
                    {isMumbuca && <span className="text-white text-xs font-bold">✓</span>}
                </div>
             </div>

             <div className="space-y-3">
               <label className="text-gray-700 dark:text-gray-300 font-bold ml-1">Número de Parcelas</label>
               <div className="grid grid-cols-4 gap-2">
                 {[1,2,3,4,5,6,10,12].map(num => (
                   <button 
                    key={num}
                    onClick={() => setInstallmentsCount(num)}
                    className={`h-12 rounded-2xl font-bold transition-all shadow-sm ${installmentsCount === num ? 'bg-[#FF7A00] text-white shadow-orange-500/30 translate-y-[-2px]' : 'bg-white dark:bg-[#1E1E1E] text-gray-500 dark:text-gray-400 border border-gray-200 dark:border-[#333]'}`}
                   >
                     {num}x
                   </button>
                 ))}
               </div>
             </div>

             <div className="space-y-3 pb-24">
               <h3 className="text-gray-900 dark:text-white font-bold ml-1">Resumo das Parcelas</h3>
               {generatedInstallments.map((inst, idx) => (
                 <div key={idx} className="flex justify-between items-center p-4 bg-white dark:bg-[#1E1E1E] rounded-2xl border border-gray-100 dark:border-[#333] shadow-sm">
                   <div className="flex flex-col">
                      <span className="text-gray-900 dark:text-white font-bold text-sm">Parcela {inst.numero_parcela}/{installmentsCount}</span>
                      <span className="text-gray-400 text-xs">{format(new Date(inst.data_vencimento), 'dd/MM/yyyy')}</span>
                   </div>
                   <span className="text-[#FF7A00] font-bold text-lg">R$ {inst.valor.toFixed(2)}</span>
                 </div>
               ))}
             </div>
           </div>
        )}
      </div>

      <div className="p-4 bg-white dark:bg-[#1E1E1E] border-t border-gray-100 dark:border-[#333] sticky bottom-0 z-40 shadow-[0_-10px_40px_rgba(0,0,0,0.05)] rounded-t-[20px]">
        {step === 2 && (
          <Button 
            fullWidth 
            onClick={() => setStep(3)} 
            disabled={cart.length === 0}
            className="py-4 text-lg"
          >
            Continuar para Pagamento
          </Button>
        )}
        {step === 3 && (
          <Button fullWidth onClick={handleFinishSale} isLoading={loading} className="py-4 text-lg">
            Finalizar Venda {isMumbuca && '(Mumbuca)'}
          </Button>
        )}
      </div>

      <Modal isOpen={isProductModalOpen} onClose={() => setIsProductModalOpen(false)} title="Novo Produto Rápido">
         <div className="space-y-4">
            <Input 
                label="Nome do Produto"
                value={newProductForm.nome}
                onChange={(e) => setNewProductForm({...newProductForm, nome: e.target.value})}
            />
            <Input 
                label="Categoria (Opcional)"
                value={newProductForm.categoria}
                onChange={(e) => setNewProductForm({...newProductForm, categoria: e.target.value})}
            />
            <div className="grid grid-cols-2 gap-4">
                <Input 
                    label="Valor à Vista"
                    type="number"
                    value={newProductForm.valor_avista}
                    onChange={(e) => setNewProductForm({...newProductForm, valor_avista: e.target.value})}
                />
                <Input 
                    label="Valor Parcelado *"
                    type="number"
                    value={newProductForm.valor_parcelado}
                    onChange={(e) => setNewProductForm({...newProductForm, valor_parcelado: e.target.value})}
                />
            </div>
            <Button fullWidth onClick={handleSaveNewProduct} isLoading={loading}>
                Cadastrar e Adicionar
            </Button>
         </div>
      </Modal>

    </div>
  );
};

export default NewSale;

import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Card, Badge, Modal, Input } from '../components/ui';
import { ReceiptModal } from '../components/ReceiptModal';
import { dataService, authService } from '../services/mockSupabase';
import { Client, Sale, Installment } from '../types';
import { format } from 'date-fns';

const ClientDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const session = authService.getSession();
  const photoInputRef = useRef<HTMLInputElement>(null);

  const [client, setClient] = useState<Client | null>(null);
  const [sales, setSales] = useState<Sale[]>([]);
  const [installmentsMap, setInstallmentsMap] = useState<Record<string, Installment[]>>({});
  const [expandedSale, setExpandedSale] = useState<string | null>(null);

  // Modals
  const [editInstallment, setEditInstallment] = useState<Installment | null>(null);
  const [payInstallment, setPayInstallment] = useState<Installment | null>(null);
  const [paymentAmount, setPaymentAmount] = useState('');

  const [deleteSaleId, setDeleteSaleId] = useState<string | null>(null);
  const [returnSaleId, setReturnSaleId] = useState<string | null>(null);
  const [isEditClientOpen, setIsEditClientOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [processingImage, setProcessingImage] = useState(false);

  // File Upload
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  // Receipt Modal State
  const [receiptData, setReceiptData] = useState<{ 
      type: 'SALE' | 'INSTALLMENT', 
      data: any,
      totalValue: number,
      remaining: number,
      description: string,
      history: { date: string, paid: number, remaining: number }[]
  } | null>(null);

  // Forms
  const [editForm, setEditForm] = useState({ valor: '', data_vencimento: '' });
  const [clientForm, setClientForm] = useState<Partial<Client>>({});

  const isAdmin = session?.perfil === 'admin';

  const loadData = async () => {
    if (!id) return;
    const clientData = await dataService.getClientById(id);
    const salesData = await dataService.getSalesByClient(id);
    setClient(clientData || null);
    setSales(salesData);

    const map: Record<string, Installment[]> = {};
    for (const sale of salesData) {
      map[sale.id] = await dataService.getInstallmentsBySale(sale.id);
    }
    setInstallmentsMap(map);
  };

  useEffect(() => {
    loadData();
  }, [id]);

  const toggleSale = async (saleId: string) => {
    if (expandedSale === saleId) {
      setExpandedSale(null);
    } else {
      setExpandedSale(saleId);
      const data = await dataService.getInstallmentsBySale(saleId);
      setInstallmentsMap(prev => ({ ...prev, [saleId]: data }));
    }
  };

  // --- RECEIPT CALCULATOR ---
  const openReceipt = (type: 'SALE' | 'INSTALLMENT', dataItem: any, saleId: string, installmentsOverride?: Installment[]) => {
      const currentSale = sales.find(s => s.id === saleId);
      const saleInstallments = installmentsOverride || installmentsMap[saleId] || [];

      if (!currentSale) return;

      // 1. Calculate History of Payments (Sort by Date Paid)
      const paidInstallments = saleInstallments
        .filter(i => i.pago)
        .sort((a, b) => {
            const dateA = new Date(a.data_pagamento || a.data_vencimento).getTime();
            const dateB = new Date(b.data_pagamento || b.data_vencimento).getTime();
            return dateA - dateB;
        });

      let runningBalance = currentSale.valor_total;
      const history = paidInstallments.map(inst => {
          runningBalance -= inst.valor;
          return {
              date: inst.data_pagamento || new Date().toISOString(),
              paid: inst.valor,
              remaining: Math.max(0, runningBalance)
          };
      });

      // 2. Final Remaining Balance
      const totalPaid = saleInstallments
        .filter(i => i.pago)
        .reduce((acc, curr) => acc + curr.valor, 0);

      const remaining = Math.max(0, currentSale.valor_total - totalPaid);

      // 3. Determine Description
      let description = currentSale.descricao || "Produtos Diversos";
      if (type === 'INSTALLMENT') {
          description = `Parc. ${dataItem.numero_parcela} - ${description}`;
      }

      setReceiptData({
          type,
          data: dataItem,
          totalValue: currentSale.valor_total,
          remaining: remaining,
          description: description,
          history: history
      });
  };

  const handleOpenEditClient = () => {
      if(client) {
          setClientForm(client);
          setSelectedFile(null);
          setIsEditClientOpen(true);
      }
  };

  const compressImage = (file: File): Promise<{ base64: string, blob: Blob }> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                const MAX_WIDTH = 800;
                const MAX_HEIGHT = 800;
                let width = img.width;
                let height = img.height;

                if (width > height) {
                    if (width > MAX_WIDTH) {
                        height *= MAX_WIDTH / width;
                        width = MAX_WIDTH;
                    }
                } else {
                    if (height > MAX_HEIGHT) {
                        width *= MAX_HEIGHT / height;
                        height = MAX_HEIGHT;
                    }
                }

                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(img, 0, 0, width, height);

                // Base64
                const base64 = canvas.toDataURL('image/jpeg', 0.7);

                // Blob
                canvas.toBlob((blob) => {
                    if(blob) resolve({ base64, blob });
                    else reject(new Error("Blob error"));
                }, 'image/jpeg', 0.7);
            };
            img.onerror = (error) => reject(error);
        };
        reader.onerror = (error) => reject(error);
    });
  };

  const handlePhotoChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setProcessingImage(true);
      try {
          const { base64, blob } = await compressImage(file);
          setClientForm(prev => ({ ...prev, foto_url: base64 }));
          setSelectedFile(new File([blob], file.name, { type: 'image/jpeg' }));
      } catch (err) {
          console.error(err);
      } finally {
          setProcessingImage(false);
      }
    }
  };

  const handleSaveClient = async () => {
      if(!client || !id) return;
      if(!clientForm.nome || !clientForm.telefone) {
          alert("Nome e Telefone são obrigatórios.");
          return;
      }
      setLoading(true);
      try {
          let finalPhotoUrl = clientForm.foto_url;

          if (selectedFile) {
              const url = await dataService.uploadClientPhoto(selectedFile, id);
              if (url) {
                  finalPhotoUrl = url;
              }
          }

          const { id: _, ...formFields } = clientForm as any;
          const updates = { ...formFields, foto_url: finalPhotoUrl };

          await dataService.updateClient(id, updates);
          await loadData();
          setIsEditClientOpen(false);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  const handleDeleteSale = async () => {
      if (!deleteSaleId) return;
      setLoading(true);
      try {
          await dataService.deleteSale(deleteSaleId);
          await loadData();
          setDeleteSaleId(null);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  const handleReturnSale = async () => {
      if (!returnSaleId) return;
      setLoading(true);
      try {
          await dataService.returnSale(returnSaleId);
          await loadData();
          setReturnSaleId(null);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  const handleOpenEdit = (inst: Installment) => {
    setEditInstallment(inst);
    setEditForm({
      valor: inst.valor.toString(),
      data_vencimento: inst.data_vencimento.split('T')[0]
    });
  };

  const handleSaveEdit = async () => {
    if (!editInstallment) return;
    setLoading(true);
    try {
      await dataService.updateInstallment(editInstallment.id, {
        valor: parseFloat(editForm.valor),
        data_vencimento: new Date(editForm.data_vencimento).toISOString()
      });
      await loadData();
      setEditInstallment(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleOpenPay = (inst: Installment) => {
      setPayInstallment(inst);
      setPaymentAmount(inst.valor.toFixed(2));
  };

  const handlePay = async () => {
    if (!payInstallment || !session || !paymentAmount) return;
    setLoading(true);
    try {
      const actualPaid = parseFloat(paymentAmount);
      await dataService.payInstallment(payInstallment.id, session.id, actualPaid);

      // Get FRESH installments to generate correct history for receipt immediately
      const freshInstallments = await dataService.getInstallmentsBySale(payInstallment.venda_id);

      // Background update of UI
      loadData(); 

      const updatedInst = freshInstallments.find(i => i.id === payInstallment.id);

      if (updatedInst) {
        openReceipt('INSTALLMENT', updatedInst, payInstallment.venda_id, freshInstallments);
      }

      setPayInstallment(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const totalBought = sales.filter(s => s.status !== 'DEVOLVIDO').reduce((acc, s) => acc + s.valor_total, 0);
  const allInstallments: Installment[] = (Object.values(installmentsMap) as Installment[][]).reduce((acc, val) => acc.concat(val), [] as Installment[]);
  const totalDebt = allInstallments.filter(i => !i.pago).reduce((acc, i) => acc + i.valor, 0);

  // Difference Calc for Modal
  const payDiff = payInstallment ? Number((payInstallment.valor - parseFloat(paymentAmount || '0')).toFixed(2)) : 0;

  if (!client) return <div className="p-5 text-center text-gray-500">Carregando...</div>;

  return (
    <div className="flex flex-col h-screen bg-gray-100 dark:bg-[#121212] transition-colors">
      <div className="bg-white dark:bg-[#1E1E1E] p-4 flex items-center gap-4 border-b border-gray-200 dark:border-[#333] sticky top-0 z-10 transition-colors shadow-sm">
        <button onClick={() => navigate(-1)} className="text-gray-900 dark:text-white">
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold text-gray-900 dark:text-white flex-1 truncate">{client.nome}</h1>
        {isAdmin && (
            <button onClick={handleOpenEditClient} className="text-[#FF7A00]">
                {ICONS.Edit}
            </button>
        )}
      </div>

      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar pb-24 space-y-6">
        <Card>
           <div className="flex items-center gap-4 mb-4">
               <div className="w-16 h-16 rounded-full bg-gray-100 dark:bg-[#333] flex items-center justify-center overflow-hidden border-2 border-[#FF7A00] text-gray-500 font-bold text-2xl">
                  {client.foto_url ? (
                      <img src={client.foto_url} alt={client.nome} className="w-full h-full object-cover" />
                  ) : (
                      client.nome.charAt(0).toUpperCase()
                  )}
               </div>
               <div>
                  <h2 className="text-xl font-bold text-gray-900 dark:text-white">{client.nome}</h2>
                  <p className="text-sm text-gray-500 dark:text-gray-400">Cliente desde {new Date().getFullYear()}</p>
               </div>
           </div>
           <div className="flex items-start justify-between border-t border-gray-100 dark:border-[#333] pt-4">
              <div className="space-y-2">
                 <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 text-sm">
                    {ICONS.Phone} {client.telefone}
                 </div>
                 <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 text-sm">
                    {ICONS.Map} {client.bairro}, {client.cidade}
                 </div>
              </div>
              <a href={`https://wa.me/55${client.telefone.replace(/\D/g, '')}`} target="_blank" className="bg-green-100 dark:bg-green-500/10 text-green-600 dark:text-green-500 p-2 rounded-lg">
                {ICONS.Phone}
              </a>
           </div>
        </Card>

        <div className="grid grid-cols-2 gap-4">
           <Card className="bg-white dark:bg-[#1E1E1E] border border-gray-200 dark:border-[#333] shadow-sm">
              <p className="text-gray-500 dark:text-gray-400 text-xs uppercase font-bold">Total Comprado</p>
              <p className="text-gray-900 dark:text-white font-bold text-lg">R$ {totalBought.toFixed(2)}</p>
           </Card>
           <Card className="bg-white dark:bg-[#1E1E1E] border border-gray-200 dark:border-[#333] shadow-sm">
              <p className="text-gray-500 dark:text-gray-400 text-xs uppercase font-bold">Em Aberto</p>
              <p className="text-[#FF7A00] font-bold text-lg">R$ {totalDebt.toFixed(2)}</p>
           </Card>
        </div>

        <h2 className="text-gray-900 dark:text-white font-bold text-lg pt-2">Histórico de Compras</h2>
        <div className="space-y-3">
           {sales.map(sale => {
              const installments = installmentsMap[sale.id] || [];
              const isExpanded = expandedSale === sale.id;
              const isReturned = sale.status === 'DEVOLVIDO';

              return (
                <div key={sale.id} className={`bg-white dark:bg-[#1E1E1E] rounded-2xl overflow-hidden border transition-colors shadow-sm ${isReturned ? 'border-red-200 dark:border-red-900/30 opacity-70' : 'border-gray-200 dark:border-[#333]'}`}>
                   <div 
                      onClick={() => toggleSale(sale.id)}
                      className="p-4 flex justify-between items-center cursor-pointer active:bg-gray-50 dark:active:bg-[#252525]"
                   >
                      <div>
                         <div className="flex items-center gap-2 mb-1">
                            <span className="text-gray-900 dark:text-white font-bold">Compra #{sale.id.substring(0,6)}</span>
                            <Badge status={sale.status} />
                         </div>
                         <div className="flex items-center gap-2">
                             <p className="text-gray-500 dark:text-gray-400 text-xs">
                                {format(new Date(sale.data_venda), 'dd/MM/yyyy')} • {sale.qtd_parcelas} parcelas
                             </p>
                             {sale.is_mumbuca && (
                                <span className="bg-red-500 text-white text-[10px] px-2 py-0.5 rounded-full font-bold">
                                    Mumbuca
                                </span>
                             )}
                         </div>
                      </div>
                      <div className="text-right">
                         <p className={`font-bold ${isReturned ? 'text-gray-400 line-through' : 'text-[#FF7A00]'}`}>
                            R$ {sale.valor_total.toFixed(2)}
                         </p>
                         <div className="flex justify-end mt-1 text-gray-500">
                           {isExpanded ? ICONS.Up : ICONS.Down}
                         </div>
                      </div>
                   </div>

                   {isExpanded && (
                      <div className="bg-gray-50 dark:bg-[#121212] border-t border-gray-200 dark:border-[#333] p-3 space-y-2">
                           <div className="flex justify-between px-1 pb-2 gap-2 flex-wrap">
                                <button onClick={(e) => { e.stopPropagation(); openReceipt('SALE', sale, sale.id); }} className="text-xs text-blue-500 dark:text-blue-400 flex items-center gap-1 hover:underline">
                                    {ICONS.Printer} Recibo
                                </button>
                                {isAdmin && !isReturned && (
                                    <>
                                        <button onClick={(e) => { e.stopPropagation(); setReturnSaleId(sale.id); }} className="text-xs text-orange-500 dark:text-orange-400 flex items-center gap-1 hover:underline">
                                            {ICONS.Return} Devolver
                                        </button>
                                        <button onClick={(e) => { e.stopPropagation(); setDeleteSaleId(sale.id); }} className="text-xs text-red-500 dark:text-red-400 flex items-center gap-1 hover:underline">
                                            {ICONS.Trash} Excluir
                                        </button>
                                    </>
                                )}
                           </div>
                           {installments.map(inst => (
                              <div key={inst.id} className="flex items-center justify-between p-3 bg-white dark:bg-[#1E1E1E] rounded-xl border border-gray-200 dark:border-[#333] shadow-sm">
                                 <div className="flex items-center gap-3">
                                    <div className={`w-2 h-2 rounded-full ${inst.pago ? 'bg-green-500' : 'bg-[#FF7A00]'}`} />
                                    <div>
                                       <p className="text-gray-900 dark:text-white text-sm font-medium">Parcela {inst.numero_parcela}</p>
                                       <p className="text-gray-500 text-xs">{format(new Date(inst.data_vencimento), 'dd/MM/yyyy')}</p>
                                    </div>
                                 </div>
                                 <div className="flex items-center gap-3">
                                    <span className={`text-sm font-bold ${inst.pago ? 'text-green-600 dark:text-green-500 line-through opacity-70' : 'text-gray-900 dark:text-white'}`}>
                                       R$ {inst.valor.toFixed(2)}
                                    </span>
                                    {inst.pago ? (
                                        <button onClick={() => openReceipt('INSTALLMENT', inst, inst.venda_id)} className="p-1.5 text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg">
                                            {ICONS.Printer}
                                        </button>
                                    ) : !isReturned && (
                                       <div className="flex gap-1">
                                         {isAdmin && (
                                             <button onClick={() => handleOpenEdit(inst)} className="p-1.5 text-gray-500 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-white/10 rounded-lg">
                                                {ICONS.Edit}
                                             </button>
                                         )}
                                         <button onClick={() => handleOpenPay(inst)} className="p-1.5 text-green-600 dark:text-green-500 hover:bg-green-50 dark:hover:bg-green-900/20 rounded-lg">
                                            {ICONS.Check}
                                         </button>
                                       </div>
                                    )}
                                 </div>
                              </div>
                           ))}
                      </div>
                   )}
                </div>
              );
           })}
        </div>
      </div>

      <Modal isOpen={isEditClientOpen} onClose={() => setIsEditClientOpen(false)} title="Editar Cliente">
        <div className="space-y-4">
          <div className="flex justify-center mb-4">
             <div className="relative">
                <div 
                  onClick={() => photoInputRef.current?.click()}
                  className={`w-24 h-24 rounded-full bg-gray-100 dark:bg-[#333] border-2 border-dashed ${processingImage ? 'border-[#FF7A00] animate-pulse' : 'border-gray-300 dark:border-gray-500'} flex items-center justify-center overflow-hidden cursor-pointer hover:border-[#FF7A00] transition-colors`}
                >
                   {clientForm.foto_url ? (
                     <img src={clientForm.foto_url} alt="Foto" className="w-full h-full object-cover" />
                   ) : (
                     <div className="text-gray-400 flex flex-col items-center">
                        {ICONS.Camera}
                        <span className="text-[10px] mt-1">{processingImage ? 'Processando...' : 'Foto'}</span>
                     </div>
                   )}
                </div>
                {clientForm.foto_url && (
                   <button 
                     onClick={() => {
                        setClientForm(prev => ({ ...prev, foto_url: '' }));
                        setSelectedFile(null);
                     }}
                     className="absolute bottom-0 right-0 bg-red-500 text-white p-1 rounded-full shadow-lg"
                     title="Remover foto"
                   >
                     <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M18 6L6 18M6 6l12 12"/></svg>
                   </button>
                )}
             </div>
             <input type="file" accept="image/*" ref={photoInputRef} className="hidden" onChange={handlePhotoChange} />
          </div>

          <Input label="Nome Completo" value={clientForm.nome || ''} onChange={e => setClientForm({...clientForm, nome: e.target.value})} />
          <Input label="Telefone" type="tel" value={clientForm.telefone || ''} onChange={e => setClientForm({...clientForm, telefone: e.target.value})} />
          <Input label="Endereço" value={clientForm.endereco || ''} onChange={e => setClientForm({...clientForm, endereco: e.target.value})} />
          <div className="grid grid-cols-2 gap-4">
            <Input label="Bairro" value={clientForm.bairro || ''} onChange={e => setClientForm({...clientForm, bairro: e.target.value})} />
            <Input label="Cidade" value={clientForm.cidade || ''} onChange={e => setClientForm({...clientForm, cidade: e.target.value})} />
          </div>
          <Button fullWidth onClick={handleSaveClient} isLoading={loading} disabled={processingImage}>
            Salvar Alterações
          </Button>
        </div>
      </Modal>

      {/* Edit Installment, Pay, Return, Delete Modals */}
      <Modal isOpen={!!editInstallment} onClose={() => setEditInstallment(null)} title="Editar Parcela">
        <div className="space-y-4">
           <Input label="Valor" type="number" value={editForm.valor} onChange={(e) => setEditForm(prev => ({ ...prev, valor: e.target.value }))} />
           <Input label="Vencimento" type="date" value={editForm.data_vencimento} onChange={(e) => setEditForm(prev => ({ ...prev, data_vencimento: e.target.value }))} />
           <Button fullWidth onClick={handleSaveEdit} isLoading={loading}>Salvar</Button>
        </div>
      </Modal>

      <Modal isOpen={!!payInstallment} onClose={() => setPayInstallment(null)} title="Receber Parcela">
        <div className="text-center space-y-4">
           <p className="text-gray-600 dark:text-gray-300">Confirmar recebimento?</p>
           <Input label="Valor Recebido" type="number" value={paymentAmount} onChange={(e) => setPaymentAmount(e.target.value)} className="text-center font-bold text-xl text-green-600 dark:text-green-500" />

           {/* Feedback Logic */}
           {payDiff > 0 && (
               <div className="mt-2 text-xs bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 p-2 rounded">
                   Faltam <strong>R$ {payDiff.toFixed(2)}</strong>. Este valor será somado à próxima parcela (ou criado uma nova).
               </div>
           )}
           {payDiff < 0 && (
               <div className="mt-2 text-xs bg-green-50 dark:bg-green-900/20 text-green-600 dark:text-green-400 p-2 rounded">
                   Pagou <strong>R$ {Math.abs(payDiff).toFixed(2)}</strong> a mais. Este valor será descontado da próxima parcela.
               </div>
           )}

           <div className="grid grid-cols-2 gap-3 pt-2">
             <Button variant="secondary" onClick={() => setPayInstallment(null)}>Cancelar</Button>
             <Button onClick={handlePay} isLoading={loading} className="bg-green-600">Confirmar</Button>
           </div>
        </div>
      </Modal>

      <Modal isOpen={!!returnSaleId} onClose={() => setReturnSaleId(null)} title="Devolver Produto">
         <div className="text-center space-y-4">
             <p className="text-gray-600 dark:text-gray-300">Confirmar devolução?</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setReturnSaleId(null)}>Cancelar</Button>
                 <Button variant="primary" onClick={handleReturnSale} isLoading={loading} className="bg-orange-600">Confirmar</Button>
             </div>
         </div>
      </Modal>

      <Modal isOpen={!!deleteSaleId} onClose={() => setDeleteSaleId(null)} title="Excluir Registro">
         <div className="text-center space-y-4">
             <p className="text-gray-600 dark:text-gray-300">Apagar permanentemente?</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setDeleteSaleId(null)}>Cancelar</Button>
                 <Button variant="danger" onClick={handleDeleteSale} isLoading={loading}>Excluir</Button>
             </div>
         </div>
      </Modal>

      {receiptData && (
          <ReceiptModal 
            isOpen={!!receiptData} 
            onClose={() => setReceiptData(null)} 
            type={receiptData.type} 
            data={receiptData.data} 
            client={client} 
            totalValue={receiptData.totalValue}
            remaining={receiptData.remaining}
            description={receiptData.description}
            history={receiptData.history}
          />
      )}
    </div>
  );
};

export default ClientDetails;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button, Input, Modal } from '../components/ui';
import { authService } from '../services/mockSupabase';
import { isSupabaseConfigured, configureSupabase, clearSupabaseConfig, supabase } from '../services/supabaseClient';
import { ROUTES } from '../constants';
import { User, Lock, CheckCircle, AlertTriangle, ExternalLink, Settings, Wifi, WifiOff, Handshake } from 'lucide-react';
import { createClient } from '@supabase/supabase-js';

const Login: React.FC = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Config Modal State
  const [showConfig, setShowConfig] = useState(false);
  const [apiKey, setApiKey] = useState('');
  const [apiUrl, setApiUrl] = useState('');
  const [testStatus, setTestStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');
  const [testMessage, setTestMessage] = useState('');

  // Pre-fill URL based on current configuration or default
  useEffect(() => {
    if (showConfig) {
        // Try to get from storage first, otherwise use the active client URL
        const storedUrl = localStorage.getItem('cla_supabase_url');
        const storedKey = localStorage.getItem('cla_supabase_key');

        // Extract URL from current supabase instance
        // @ts-ignore
        const currentUrl = supabase.supabaseUrl;

        // Only autofill if it's not the placeholder
        const effectiveUrl = currentUrl && !currentUrl.includes('placeholder') ? currentUrl : 'https://taubsuolhawpdibrhtkb.supabase.co';

        setApiUrl(storedUrl || effectiveUrl);
        setApiKey(storedKey || '');

        setTestStatus('idle');
        setTestMessage('');
    }
  }, [showConfig]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const { user, error: authError } = await authService.login(email, password);
      if (authError) {
        setError(authError);
        // Se o erro for de conexão/URL, sugere abrir config (apenas se não estiver hardcoded)
        if ((authError.includes('conexão') || authError.includes('fetch')) && !isSupabaseConfigured) {
            setTimeout(() => setShowConfig(true), 1500);
        }
      } else if (user) {
        navigate(ROUTES.DASHBOARD);
      }
    } catch (err) {
      setError('Erro crítico ao tentar logar.');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveConfig = async () => {
    // 1. Basic Validation
    if (!apiUrl) {
        setTestStatus('error');
        setTestMessage("Informe a URL do projeto.");
        return;
    }
    if (!apiKey) {
      setTestStatus('error');
      setTestMessage("Informe a Chave de API.");
      return;
    }

    // 2. Sanitization
    const cleanUrl = apiUrl.trim();
    const cleanKey = apiKey.trim();

    if (cleanUrl.startsWith('postgresql://') || cleanUrl.startsWith('postgres://')) {
        setTestStatus('error');
        setTestMessage("Erro: Use a URL da API (https://...), não a do Banco.");
        return;
    }

    if (!cleanUrl.startsWith('https://')) {
        setTestStatus('error');
        setTestMessage("A URL deve começar com https://");
        return;
    }

    // 3. Connection Test
    setTestStatus('testing');
    setTestMessage("Testando conexão...");

    try {
        const tempClient = createClient(cleanUrl, cleanKey);
        const { error } = await tempClient.from('users').select('count', { count: 'exact', head: true });

        if (error) {
            const isTableMissing = error.code === '42P01' || error.message.includes('does not exist');
            const isAuthError = error.code === 'PGRST301' || error.message.includes('JWT') || error.code === '401';

            if (isTableMissing) {
                 configureSupabase(cleanKey, cleanUrl);
                 return;
            }
            if (isAuthError) {
                throw new Error("Chave de API inválida (Use a 'anon public').");
            }
            if (error.message && (error.message.includes('FetchError') || error.message.includes('Failed to fetch'))) {
                throw new Error("Erro de Rede: Verifique a URL.");
            }
            console.warn("Connection warning:", error);
        }

        setTestStatus('success');
        setTestMessage("Conectado! Reiniciando...");

        setTimeout(() => {
            configureSupabase(cleanKey, cleanUrl);
        }, 1000);

    } catch (err: any) {
        console.error(err);
        setTestStatus('error');
        setTestMessage(err.message || "Falha ao conectar. Verifique URL e Chave.");
    }
  };

  return (
