             </div>

             <div className="py-4">
                 <input 
                    type="file" 
                    accept=".csv"
                    ref={fileInputRef}
                    onChange={handleFileChange}
                    className="hidden" 
                 />
                 <Button fullWidth onClick={() => fileInputRef.current?.click()} isLoading={loading}>
