                }
                throw uploadError;
            }

            const { data: { publicUrl } } = supabase.storage
                .from('clientes-fotos')
                .getPublicUrl(path);

            return `${publicUrl}?t=${timestamp}`;

        } catch (e) {
            console.error("Upload Failed", e);
            return null;
        }
    } else {
        return null;
    }
};

