        // ON DELETE CASCADE handles children, but we call delete on parent
        const { error } = await supabase.from('sales').delete().eq('id', saleId);
        if (error) handleSupabaseError(error);
        return;
    }
    await delay(400);
    const sales = getStorage<Sale[]>('sales', []);
