                 <input 
                   type="date" 
                   className="w-full bg-gray-50 dark:bg-[#2E2E2E] border border-gray-200 dark:border-[#404040] rounded-xl px-2 py-2 text-gray-900 dark:text-white text-xs font-bold"
                   value={startDate}
                   onChange={(e) => setStartDate(e.target.value)}
                 />
             </div>
             <div>
                 <label className="text-[10px] font-bold text-gray-400 ml-1 uppercase">Fim</label>
                 <input 
                   type="date" 
                   className="w-full bg-gray-50 dark:bg-[#2E2E2E] border border-gray-200 dark:border-[#404040] rounded-xl px-2 py-2 text-gray-900 dark:text-white text-xs font-bold"
                   value={endDate}
                   onChange={(e) => setEndDate(e.target.value)}
                 />
             </div>
         </div>

         {/* Summary Cards */}
         <div className="grid grid-cols-2 gap-3">
             <Card className="flex flex-col justify-between">
                 <p className="text-xs text-gray-500 font-bold uppercase">Total Vendido</p>
                 <p className="text-lg font-black text-gray-900 dark:text-white">R$ {totalSold.toFixed(2)}</p>
             </Card>
             <Card className="flex flex-col justify-between border-l-4 border-l-[#FF7A00]">
                 <div className="flex justify-between items-center">
                    <p className="text-xs text-[#FF7A00] font-bold uppercase">Comissão ({commissionRate}%)</p>
                 </div>
                 <p className="text-lg font-black text-[#FF7A00]">R$ {commissionEarned.toFixed(2)}</p>
             </Card>
             <Card className="flex flex-col justify-between border-l-4 border-l-red-500">
                 <p className="text-xs text-red-500 font-bold uppercase">Vales / Pagos</p>
                 <p className="text-lg font-black text-red-600 dark:text-red-400">- R$ {deductions.toFixed(2)}</p>
             </Card>
             <Card className={`flex flex-col justify-between border-l-4 ${balanceToPay >= 0 ? 'border-l-green-500' : 'border-l-red-500'}`}>
                 <p className="text-xs text-gray-500 font-bold uppercase">Saldo a Pagar</p>
                 <p className={`text-lg font-black ${balanceToPay >= 0 ? 'text-green-600' : 'text-red-500'}`}>
                     R$ {balanceToPay.toFixed(2)}
                 </p>
             </Card>
         </div>

         {/* Actions */}
         <div className="flex gap-2">
             <Button 
                variant="danger" 
                className="flex-1 text-xs py-3" 
                onClick={() => { setTransactionForm({ valor: '', descricao: '' }); setShowValeModal(true); }}
             >
                 {ICONS.Money} Cadastrar Vale
             </Button>
             <Button 
                className="flex-1 text-xs py-3 bg-green-600 hover:bg-green-700" 
                onClick={() => { setTransactionForm({ valor: Math.max(0, balanceToPay).toFixed(2), descricao: '' }); setShowPaymentModal(true); }}
             >
                 {ICONS.Check} Pagar Comissão
             </Button>
         </div>

         {/* List Section */}
         <div>
             <div className="flex border-b border-gray-200 dark:border-[#333] mb-2">
                 <button 
                    onClick={() => setActiveTab('sales')}
                    className={`flex-1 pb-2 text-sm font-bold border-b-2 transition-colors ${activeTab === 'sales' ? 'border-[#FF7A00] text-[#FF7A00]' : 'border-transparent text-gray-400'}`}
                 >
                    Vendas ({sales.length})
                 </button>
                 <button 
                    onClick={() => setActiveTab('extract')}
                    className={`flex-1 pb-2 text-sm font-bold border-b-2 transition-colors ${activeTab === 'extract' ? 'border-[#FF7A00] text-[#FF7A00]' : 'border-transparent text-gray-400'}`}
                 >
                    Extrato ({cashFlow.filter(c => c.tipo === 'SAIDA').length})
                 </button>
             </div>

             <div className="space-y-2">
                 {activeTab === 'sales' && sales.map(sale => (
                     <div key={sale.id} className="bg-white dark:bg-[#1E1E1E] p-3 rounded-xl border border-gray-100 dark:border-[#333] flex justify-between items-center">
                         <div>
                             <p className="font-bold text-gray-900 dark:text-white text-sm">{sale.cliente_nome}</p>
                             <p className="text-xs text-gray-500">{format(new Date(sale.data_venda), 'dd/MM/yyyy')}</p>
                         </div>
                         <div className="text-right">
                             <p className="font-bold text-[#FF7A00]">R$ {sale.valor_total.toFixed(2)}</p>
                             <p className="text-[10px] text-gray-400 font-bold uppercase">Comissão: R$ {(sale.valor_total * commissionRate / 100).toFixed(2)}</p>
                         </div>
                     </div>
                 ))}

                 {activeTab === 'extract' && cashFlow.filter(c => c.tipo === 'SAIDA').map(entry => (
                     <div key={entry.id} className="bg-white dark:bg-[#1E1E1E] p-3 rounded-xl border border-gray-100 dark:border-[#333] flex justify-between items-center">
                         <div>
                             <p className="font-bold text-gray-900 dark:text-white text-sm">{entry.descricao}</p>
                             <p className="text-xs text-gray-500">{format(new Date(entry.data), 'dd/MM/yyyy HH:mm')}</p>
                         </div>
                         <p className="font-bold text-red-500">- R$ {entry.valor.toFixed(2)}</p>
                     </div>
                 ))}

                 {(activeTab === 'sales' ? sales.length : cashFlow.filter(c => c.tipo === 'SAIDA').length) === 0 && (
                     <p className="text-center text-gray-400 text-sm py-4">Nenhum registro no período.</p>
                 )}
             </div>
         </div>
      </div>

      {/* --- Modals --- */}
      <Modal isOpen={showValeModal} onClose={() => setShowValeModal(false)} title="Cadastrar Vale">
          <div className="space-y-4">
              <div className="bg-yellow-50 dark:bg-yellow-900/20 p-3 rounded-lg border border-yellow-200 dark:border-yellow-900/30 text-xs text-yellow-700 dark:text-yellow-400">
                  Isso será registrado como uma SAÍDA no caixa vinculada a este vendedor.
              </div>
              <Input 
                  label="Valor (R$)"
                  type="number"
                  value={transactionForm.valor}
                  onChange={(e) => setTransactionForm({ ...transactionForm, valor: e.target.value })}
              />
              <Input 
                  label="Descrição (Opcional)"
                  placeholder="Ex: Adiantamento semanal"
                  value={transactionForm.descricao}
                  onChange={(e) => setTransactionForm({ ...transactionForm, descricao: e.target.value })}
              />
              <Button fullWidth onClick={() => handleAddTransaction('VALE')} isLoading={loading} variant="danger">
                  Confirmar Desconto
              </Button>
          </div>
      </Modal>

      <Modal isOpen={showPaymentModal} onClose={() => setShowPaymentModal(false)} title="Pagar Comissão">
          <div className="space-y-4">
              <div className="bg-green-50 dark:bg-green-900/20 p-3 rounded-lg border border-green-200 dark:border-green-900/30 text-xs text-green-700 dark:text-green-400">
                  Confirme o valor para zerar o saldo pendente.
              </div>
              <Input 
                  label="Valor a Pagar (R$)"
                  type="number"
                  value={transactionForm.valor}
                  onChange={(e) => setTransactionForm({ ...transactionForm, valor: e.target.value })}
              />
              <Input 
                  label="Observação (Opcional)"
                  placeholder="Ex: Ref. mês de Agosto"
                  value={transactionForm.descricao}
                  onChange={(e) => setTransactionForm({ ...transactionForm, descricao: e.target.value })}
              />
              <Button fullWidth onClick={() => handleAddTransaction('PAGAMENTO')} isLoading={loading} className="bg-green-600 hover:bg-green-700">
                  Confirmar Pagamento
              </Button>
          </div>
      </Modal>

    </div>
  );
};

export default SellerDetails;

import React from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Login from './pages/Login';
import Register from './pages/Register';
import Dashboard from './pages/Dashboard';
import Clients from './pages/Clients';
import ClientDetails from './pages/ClientDetails';
import SalesList from './pages/SalesList';
import Payments from './pages/Payments';
import NewSale from './pages/NewSale';
import Sellers from './pages/Sellers';
import SellerDetails from './pages/SellerDetails';
import Reports from './pages/Reports';
import Products from './pages/Products';
import Settings from './pages/Settings';
import Setup from './pages/Setup';
import { ROUTES } from './constants';
import { ThemeProvider } from './contexts/ThemeContext';

const App: React.FC = () => {
  return (
    <ThemeProvider>
      <Router>
        <Routes>
          <Route path={ROUTES.LOGIN} element={<Login />} />
          <Route path={ROUTES.REGISTER} element={<Register />} />
          <Route path={ROUTES.SETUP} element={<Setup />} />

          {/* Protected Routes inside Layout */}
          <Route element={<Layout />}>
            <Route path={ROUTES.DASHBOARD} element={<Dashboard />} />
            <Route path={ROUTES.CLIENTS} element={<Clients />} />
            <Route path={ROUTES.SALES} element={<SalesList />} />
            <Route path={ROUTES.PAYMENTS} element={<Payments />} />
          </Route>

          {/* Fullscreen Routes */}
          <Route path={ROUTES.NEW_SALE} element={<NewSale />} />
          <Route path={ROUTES.CLIENT_DETAILS} element={<ClientDetails />} />
          <Route path={ROUTES.SELLERS} element={<Sellers />} />
          <Route path={ROUTES.SELLER_DETAILS} element={<SellerDetails />} />
          <Route path={ROUTES.REPORTS} element={<Reports />} />
          <Route path={ROUTES.PRODUCTS} element={<Products />} />
          <Route path={ROUTES.SETTINGS} element={<Settings />} />

          {/* Fallback */}
          <Route path="*" element={<Navigate to={ROUTES.LOGIN} replace />} />
        </Routes>
      </Router>
    </ThemeProvider>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Input, Card, Modal, Toast } from '../components/ui';
import { dataService } from '../services/mockSupabase';
import { User } from '../types';
import { format, startOfMonth, endOfMonth } from 'date-fns';

const Sellers: React.FC = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'list' | 'performance'>('list');
  const [sellers, setSellers] = useState<User[]>([]);

  // Performance State
  const [startDate, setStartDate] = useState(format(startOfMonth(new Date()), 'yyyy-MM-dd'));
  const [endDate, setEndDate] = useState(format(endOfMonth(new Date()), 'yyyy-MM-dd'));
  const [performanceData, setPerformanceData] = useState<Record<string, { total: number, count: number }>>({});

  // CRUD State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState({ show: false, message: '' });

  const [form, setForm] = useState<Partial<User>>({
    nome: '',
    email: '',
    perfil: 'vendedor',
    comissao_porcentagem: 0
  });
  const [editingId, setEditingId] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  const loadSellers = async () => {
    const data = await dataService.getSellers();
    setSellers(data);
  };

  useEffect(() => {
    loadSellers();
  }, []);

  // Fetch performance data when switching to that tab or changing dates
  useEffect(() => {
    if (activeTab === 'performance') {
        const fetchPerformance = async () => {
            setLoading(true);
            try {
                const results = await dataService.getSellersPerformance(new Date(startDate), new Date(endDate));
                const map: Record<string, { total: number, count: number }> = {};
                results.forEach(r => {
                    map[r.sellerId] = { total: r.totalSales, count: r.salesCount };
                });
                setPerformanceData(map);
            } catch (e) {
                console.error(e);
            } finally {
                setLoading(false);
            }
        };
        fetchPerformance();
    }
  }, [activeTab, startDate, endDate]);

  const showToast = (msg: string) => {
      setToast({ show: true, message: msg });
  };

  // --- CRUD HANDLERS ---
  const handleOpenCreate = () => {
    setEditingId(null);
    setForm({ nome: '', email: '', perfil: 'vendedor', comissao_porcentagem: 0 });
    setIsModalOpen(true);
  };

  const handleOpenEdit = (seller: User, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingId(seller.id);
    setForm({ ...seller });
    setIsModalOpen(true);
  };

  const handleOpenDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setDeletingId(id);
    setIsDeleteModalOpen(true);
  };

  const handleSave = async () => {
    if (!form.nome || !form.email) return;
    setLoading(true);
    try {
      if (editingId) {
        await dataService.updateSeller(editingId, form);
        showToast('Usuário atualizado com sucesso!');
      } else {
        await dataService.createSeller({
          nome: form.nome,
          email: form.email,
          perfil: form.perfil || 'vendedor',
          ativo: true,
          comissao_porcentagem: Number(form.comissao_porcentagem) || 0
        });
        showToast('Usuário cadastrado com sucesso!');
      }
      await loadSellers();
      setIsModalOpen(false);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
      if (!deletingId) return;
      setLoading(true);
      try {
          await dataService.deleteSeller(deletingId);
          await loadSellers();
          setIsDeleteModalOpen(false);
          showToast('Usuário removido com sucesso!');
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  // Navigate to Detail Page
  const handleSellerClick = (id: string) => {
      navigate(ROUTES.SELLER_DETAILS.replace(':id', id));
  };

  return (
    <div className="flex flex-col h-screen bg-[#F3F4F6] dark:bg-[#121212] transition-colors">
      <div className="bg-white dark:bg-[#1E1E1E] p-4 flex items-center gap-4 border-b border-gray-100 dark:border-[#333] sticky top-0 z-10 shadow-sm">
        <button onClick={() => navigate(-1)} className="text-gray-900 dark:text-white">
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold text-gray-900 dark:text-white">Equipe de Vendas</h1>
      </div>

      {/* Tabs */}
      <div className="px-4 mt-4">
        <div className="flex p-1 bg-white dark:bg-[#1E1E1E] rounded-xl border border-gray-200 dark:border-[#333]">
           <button 
             onClick={() => setActiveTab('list')}
             className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${activeTab === 'list' ? 'bg-[#FF7A00] text-white shadow-md' : 'text-gray-500 dark:text-gray-400'}`}
           >
             Gerenciar
           </button>
           <button 
             onClick={() => setActiveTab('performance')}
             className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${activeTab === 'performance' ? 'bg-[#FF7A00] text-white shadow-md' : 'text-gray-500 dark:text-gray-400'}`}
           >
             Comissões
           </button>
        </div>
      </div>

      <div className="p-4 space-y-4 flex-1 overflow-y-auto custom-scrollbar">

        {/* === LIST VIEW === */}
        {activeTab === 'list' && (
            <>
                <Button onClick={handleOpenCreate} fullWidth icon={ICONS.UserPlus}>
                  Novo Membro
                </Button>

                <div className="space-y-3 pb-20">
                  {sellers.map(seller => (
                    <Card 
                        key={seller.id} 
                        className="flex flex-col gap-3 cursor-pointer hover:border-[#FF7A00] transition-colors group"
                        onClick={() => handleSellerClick(seller.id)}
                    >
                      <div className="flex justify-between items-center">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-full bg-gray-100 dark:bg-[#333] flex items-center justify-center text-gray-500 font-bold border border-gray-200 dark:border-white/10">
                                {seller.nome.charAt(0).toUpperCase()}
                            </div>
                            <div>
                                <h3 className="text-gray-900 dark:text-white font-bold flex items-center gap-2 group-hover:text-[#FF7A00] transition-colors">
                                {seller.nome}
                                {seller.perfil === 'admin' && <span className="bg-red-500/10 text-red-500 text-[10px] px-2 py-0.5 rounded-full border border-red-500/20">ADMIN</span>}
                                </h3>
                                <p className="text-gray-500 text-sm">{seller.email}</p>
                            </div>
                        </div>
                        <div className="text-right">
                            <p className="text-xs text-gray-400 font-bold uppercase">Comissão</p>
                            <p className="text-[#FF7A00] font-bold">{seller.comissao_porcentagem || 0}%</p>
                        </div>
                      </div>

                      <div className="flex gap-2 pt-2 border-t border-gray-100 dark:border-white/5">
                        <button 
                          onClick={(e) => handleOpenEdit(seller, e)}
                          className="flex-1 py-2 bg-gray-50 dark:bg-white/5 text-gray-600 dark:text-gray-400 rounded-lg hover:bg-gray-100 dark:hover:bg-white/10 flex justify-center items-center gap-2 text-sm font-medium z-10"
                        >
                            {ICONS.Edit} Editar
                        </button>
                        <button 
                          onClick={(e) => handleOpenDelete(seller.id, e)}
                          className="flex-1 py-2 bg-red-50 dark:bg-red-500/10 text-red-500 rounded-lg hover:bg-red-100 dark:hover:bg-red-500/20 flex justify-center items-center gap-2 text-sm font-medium z-10"
                        >
                            {ICONS.Trash} Excluir
                        </button>
                      </div>
                    </Card>
                  ))}
                </div>
            </>
        )}

        {/* === PERFORMANCE VIEW === */}
        {activeTab === 'performance' && (
            <div className="space-y-6 animate-fade-in pb-20">
                <div className="grid grid-cols-2 gap-3 bg-white dark:bg-[#1E1E1E] p-4 rounded-2xl border border-gray-200 dark:border-[#333] shadow-sm">
                   <div className="space-y-1">
                     <label className="text-xs text-gray-500 font-bold ml-1">De:</label>
                     <input 
                       type="date" 
                       className="w-full bg-gray-50 dark:bg-[#2E2E2E] border border-gray-200 dark:border-[#404040] rounded-xl px-3 py-2 text-gray-900 dark:text-white text-sm font-bold"
                       value={startDate}
                       onChange={(e) => setStartDate(e.target.value)}
                     />
                   </div>
                   <div className="space-y-1">
                     <label className="text-xs text-gray-500 font-bold ml-1">Até:</label>
                     <input 
                       type="date" 
                       className="w-full bg-gray-50 dark:bg-[#2E2E2E] border border-gray-200 dark:border-[#404040] rounded-xl px-3 py-2 text-gray-900 dark:text-white text-sm font-bold"
                       value={endDate}
                       onChange={(e) => setEndDate(e.target.value)}
                     />
                   </div>
                </div>

                {loading ? (
                    <p className="text-center text-gray-500 py-10">Calculando comissões...</p>
                ) : (
                    <div className="space-y-3">
                        {sellers.map(seller => {
                            const stats = performanceData[seller.id] || { total: 0, count: 0 };
                            const commissionValue = (stats.total * (seller.comissao_porcentagem || 0)) / 100;

                            return (
                                <Card 
                                    key={seller.id} 
                                    className="relative overflow-hidden cursor-pointer"
                                    onClick={() => handleSellerClick(seller.id)}
                                >
                                    <div className="flex justify-between items-start mb-4">
                                        <div className="flex items-center gap-3">
                                            <div className="w-10 h-10 rounded-full bg-gray-100 dark:bg-[#333] flex items-center justify-center text-gray-500 font-bold border border-gray-200 dark:border-white/10">
                                                {seller.nome.charAt(0).toUpperCase()}
                                            </div>
                                            <div>
                                                <h3 className="text-gray-900 dark:text-white font-bold">{seller.nome}</h3>
                                                <p className="text-xs text-gray-500">{stats.count} vendas no período</p>
                                            </div>
                                        </div>
                                        <div className="bg-orange-50 dark:bg-orange-900/20 text-[#FF7A00] px-2 py-1 rounded-lg text-xs font-bold border border-orange-100 dark:border-orange-900/30">
                                            {seller.comissao_porcentagem || 0}% Com.
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 gap-4 border-t border-gray-100 dark:border-white/10 pt-3">
                                        <div>
                                            <p className="text-[10px] text-gray-400 font-bold uppercase">Total Vendido</p>
                                            <p className="text-gray-900 dark:text-white font-bold text-lg">
                                                R$ {stats.total.toFixed(2)}
                                            </p>
                                        </div>
                                        <div className="text-right">
                                            <p className="text-[10px] text-gray-400 font-bold uppercase">A Pagar (Comissão)</p>
                                            <p className="text-green-600 dark:text-green-500 font-black text-xl">
                                                R$ {commissionValue.toFixed(2)}
                                            </p>
                                        </div>
                                    </div>
                                    <div className="absolute right-2 top-2 opacity-50">
                                        {ICONS.Right}
                                    </div>
                                </Card>
                            );
                        })}
                        {sellers.length === 0 && (
                            <p className="text-center text-gray-500">Nenhum vendedor cadastrado.</p>
                        )}
                    </div>
                )}
            </div>
        )}
      </div>

      {/* --- MODALS (CRUD) --- */}
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingId ? "Editar Usuário" : "Cadastrar Usuário"}>
        <div className="space-y-4">
          <Input 
            label="Nome Completo" 
            value={form.nome} 
            onChange={e => setForm({...form, nome: e.target.value})}
          />
          <Input 
            label="E-mail" 
            type="email"
            value={form.email} 
            onChange={e => setForm({...form, email: e.target.value})}
            disabled={!!editingId} 
          />

          <div className="flex flex-col gap-1.5">
             <label className="text-sm font-bold text-gray-700 dark:text-gray-300 ml-1">Perfil de Acesso</label>
             <select 
               className="w-full bg-white dark:bg-[#1E1E1E] border border-gray-200 dark:border-[#333] rounded-2xl px-4 py-4 text-gray-900 dark:text-white font-medium focus:outline-none focus:border-[#FF7A00]"
               value={form.perfil}
               onChange={e => setForm({...form, perfil: e.target.value as any})}
             >
                <option value="vendedor">Vendedor</option>
                <option value="admin">Administrador</option>
             </select>
          </div>

          <Input 
            label="Comissão (%)" 
            type="number"
            placeholder="Ex: 5"
            value={form.comissao_porcentagem} 
            onChange={e => setForm({...form, comissao_porcentagem: Number(e.target.value)})}
          />
          {!editingId && <p className="text-xs text-gray-500">* Senha padrão inicial: 123456</p>}
          <Button fullWidth onClick={handleSave} isLoading={loading}>
            Salvar
          </Button>
        </div>
      </Modal>

      <Modal isOpen={isDeleteModalOpen} onClose={() => setIsDeleteModalOpen(false)} title="Excluir Usuário">
         <div className="text-center space-y-4">
             <div className="w-16 h-16 bg-red-500/20 rounded-full flex items-center justify-center text-red-500 mx-auto">
                {ICONS.Trash}
             </div>
             <p className="text-gray-600 dark:text-gray-300">Tem certeza? O acesso deste usuário será revogado.</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setIsDeleteModalOpen(false)}>Cancelar</Button>
                 <Button variant="danger" onClick={handleDelete} isLoading={loading}>Excluir</Button>
             </div>
         </div>
      </Modal>

      <Toast 
        message={toast.message} 
        isVisible={toast.show} 
        onClose={() => setToast(prev => ({ ...prev, show: false }))} 
      />
    </div>
  );
};

export default Sellers;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Card, Modal, Input } from '../components/ui';
import { dataService, authService } from '../services/mockSupabase';
import { User, Sale, CashEntry } from '../types';
import { format, startOfMonth, endOfMonth, isWithinInterval } from 'date-fns';

const SellerDetails: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const session = authService.getSession();

  const [seller, setSeller] = useState<User | null>(null);

  // Filters
  const [startDate, setStartDate] = useState(format(startOfMonth(new Date()), 'yyyy-MM-dd'));
  const [endDate, setEndDate] = useState(format(endOfMonth(new Date()), 'yyyy-MM-dd'));

  // Data State
  const [sales, setSales] = useState<Sale[]>([]);
  const [cashFlow, setCashFlow] = useState<CashEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'sales' | 'extract'>('sales');

  // Modals
  const [showValeModal, setShowValeModal] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [transactionForm, setTransactionForm] = useState({ valor: '', descricao: '' });

  // 1. Security Check
  useEffect(() => {
      if (!session || session.perfil !== 'admin') {
          alert("Acesso restrito a administradores.");
          navigate(ROUTES.DASHBOARD);
      }
  }, [session, navigate]);

  // 2. Load Initial Data
  useEffect(() => {
      const init = async () => {
          if (!id) return;
          const user = await dataService.getUserById(id);
          if (user) setSeller(user);
          else navigate(ROUTES.SELLERS);
      };
      init();
  }, [id]);

  // 3. Fetch Financial Data
  const loadFinancials = async () => {
      if (!id) return;
      setLoading(true);
      try {
          const start = new Date(startDate);
          start.setHours(0,0,0,0);
          const end = new Date(endDate);
          end.setHours(23,59,59,999);

          // Get All Data filtered manually
          const [allSales, allCash] = await Promise.all([
              dataService.getSales(),
              dataService.getCashFlow(id) // Pass ID to get cash flow for THIS seller
          ]);

          const filteredSales = allSales.filter(s => 
              s.vendedor_id === id && 
              isWithinInterval(new Date(s.data_venda), { start, end })
          );

          // For cash flow, we want entries where this seller is involved
          // Note: In mockSupabase, addExpense uses the ID passed as `vendedor_id`.
          const filteredCash = allCash.filter(c => 
              c.vendedor_id === id && 
              isWithinInterval(new Date(c.data), { start, end })
          );

          setSales(filteredSales);
          setCashFlow(filteredCash);
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  useEffect(() => {
      loadFinancials();
  }, [startDate, endDate, id]);

  // --- Calculations ---
  const totalSold = sales.reduce((acc, s) => acc + s.valor_total, 0);
  const commissionRate = seller?.comissao_porcentagem || 0;
  const commissionEarned = (totalSold * commissionRate) / 100;

  // "Vales" e "Pagamentos" são SAÍDAS no caixa vinculadas a este vendedor
  const deductions = cashFlow
      .filter(c => c.tipo === 'SAIDA')
      .reduce((acc, c) => acc + c.valor, 0);

  const balanceToPay = commissionEarned - deductions;

  // --- Handlers ---
  const handleAddTransaction = async (type: 'VALE' | 'PAGAMENTO') => {
      if (!id || !transactionForm.valor) return;
      setLoading(true);
      try {
          const val = parseFloat(transactionForm.valor);
          const desc = type === 'VALE' 
              ? `[VALE] ${transactionForm.descricao || 'Adiantamento'}` 
              : `[PGTO COMISSÃO] ${transactionForm.descricao || 'Fechamento de Conta'}`;

          await dataService.addExpense(desc, val, id);

          await loadFinancials();
          setShowValeModal(false);
          setShowPaymentModal(false);
          setTransactionForm({ valor: '', descricao: '' });
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  if (!seller) return null;

  return (
    <div className="flex flex-col h-screen bg-[#F3F4F6] dark:bg-[#121212] transition-colors">

      {/* Header */}
      <div className="bg-white dark:bg-[#1E1E1E] p-4 flex items-center gap-4 border-b border-gray-100 dark:border-[#333] sticky top-0 z-10 shadow-sm">
        <button 
            onClick={() => navigate(-1)} 
            className="p-2 -ml-2 rounded-full hover:bg-gray-100 dark:hover:bg-[#333] text-gray-900 dark:text-white transition-colors"
        >
          {ICONS.Left}
        </button>
        <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-gray-100 dark:bg-[#333] flex items-center justify-center text-gray-500 font-bold border border-gray-200 dark:border-white/10">
                {seller.nome.charAt(0).toUpperCase()}
            </div>
            <div>
                <h1 className="text-lg font-bold text-gray-900 dark:text-white leading-tight">{seller.nome}</h1>
                <p className="text-xs text-gray-500">Gestão Financeira</p>
            </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar pb-24 space-y-4">

         {/* Date Filter */}
         <div className="grid grid-cols-2 gap-3 bg-white dark:bg-[#1E1E1E] p-3 rounded-2xl border border-gray-200 dark:border-[#333] shadow-sm">
             <div>
                 <label className="text-[10px] font-bold text-gray-400 ml-1 uppercase">Início</label>
                 <input 
                   type="date" 
                   className="w-full bg-gray-50 dark:bg-[#2E2E2E] border border-gray-200 dark:border-[#404040] rounded-xl px-2 py-2 text-gray-900 dark:text-white text-xs font-bold"
                   value={startDate}
                   onChange={(e) => setStartDate(e.target.value)}
                 />
             </div>
             <div>
                 <label className="text-[10px] font-bold text-gray-400 ml-1 uppercase">Fim</label>
                 <input 
                   type="date" 
                   className="w-full bg-gray-50 dark:bg-[#2E2E2E] border border-gray-200 dark:border-[#404040] rounded-xl px-2 py-2 text-gray-900 dark:text-white text-xs font-bold"
                   value={endDate}
                   onChange={(e) => setEndDate(e.target.value)}
                 />
             </div>
         </div>

         {/* Summary Cards */}
         <div className="grid grid-cols-2 gap-3">
             <Card className="flex flex-col justify-between">
                 <p className="text-xs text-gray-500 font-bold uppercase">Total Vendido</p>
                 <p className="text-lg font-black text-gray-900 dark:text-white">R$ {totalSold.toFixed(2)}</p>
             </Card>
             <Card className="flex flex-col justify-between border-l-4 border-l-[#FF7A00]">
                 <div className="flex justify-between items-center">
                    <p className="text-xs text-[#FF7A00] font-bold uppercase">Comissão ({commissionRate}%)</p>
                 </div>
                 <p className="text-lg font-black text-[#FF7A00]">R$ {commissionEarned.toFixed(2)}</p>
             </Card>
             <Card className="flex flex-col justify-between border-l-4 border-l-red-500">
                 <p className="text-xs text-red-500 font-bold uppercase">Vales / Pagos</p>
                 <p className="text-lg font-black text-red-600 dark:text-red-400">- R$ {deductions.toFixed(2)}</p>
             </Card>
             <Card className={`flex flex-col justify-between border-l-4 ${balanceToPay >= 0 ? 'border-l-green-500' : 'border-l-red-500'}`}>
                 <p className="text-xs text-gray-500 font-bold uppercase">Saldo a Pagar</p>
                 <p className={`text-lg font-black ${balanceToPay >= 0 ? 'text-green-600' : 'text-red-500'}`}>
                     R$ {balanceToPay.toFixed(2)}
                 </p>
             </Card>
         </div>

         {/* Actions */}
         <div className="flex gap-2">
             <Button 
                variant="danger" 
                className="flex-1 text-xs py-3" 
                onClick={() => { setTransactionForm({ valor: '', descricao: '' }); setShowValeModal(true); }}
             >
                 {ICONS.Money} Cadastrar Vale
             </Button>
             <Button 
                className="flex-1 text-xs py-3 bg-green-600 hover:bg-green-700" 
                onClick={() => { setTransactionForm({ valor: Math.max(0, balanceToPay).toFixed(2), descricao: '' }); setShowPaymentModal(true); }}
             >
                 {ICONS.Check} Pagar Comissão
             </Button>
         </div>

         {/* List Section */}
         <div>
             <div className="flex border-b border-gray-200 dark:border-[#333] mb-2">
                 <button 
                    onClick={() => setActiveTab('sales')}
                    className={`flex-1 pb-2 text-sm font-bold border-b-2 transition-colors ${activeTab === 'sales' ? 'border-[#FF7A00] text-[#FF7A00]' : 'border-transparent text-gray-400'}`}
                 >
                    Vendas ({sales.length})
                 </button>
                 <button 
                    onClick={() => setActiveTab('extract')}
                    className={`flex-1 pb-2 text-sm font-bold border-b-2 transition-colors ${activeTab === 'extract' ? 'border-[#FF7A00] text-[#FF7A00]' : 'border-transparent text-gray-400'}`}
                 >
                    Extrato ({cashFlow.filter(c => c.tipo === 'SAIDA').length})
                 </button>
             </div>

             <div className="space-y-2">
                 {activeTab === 'sales' && sales.map(sale => (
                     <div key={sale.id} className="bg-white dark:bg-[#1E1E1E] p-3 rounded-xl border border-gray-100 dark:border-[#333] flex justify-between items-center">
                         <div>
                             <p className="font-bold text-gray-900 dark:text-white text-sm">{sale.cliente_nome}</p>
                             <p className="text-xs text-gray-500">{format(new Date(sale.data_venda), 'dd/MM/yyyy')}</p>
                         </div>
                         <div className="text-right">
                             <p className="font-bold text-[#FF7A00]">R$ {sale.valor_total.toFixed(2)}</p>
                             <p className="text-[10px] text-gray-400 font-bold uppercase">Comissão: R$ {(sale.valor_total * commissionRate / 100).toFixed(2)}</p>
                         </div>
                     </div>
                 ))}

                 {activeTab === 'extract' && cashFlow.filter(c => c.tipo === 'SAIDA').map(entry => (
                     <div key={entry.id} className="bg-white dark:bg-[#1E1E1E] p-3 rounded-xl border border-gray-100 dark:border-[#333] flex justify-between items-center">
                         <div>
                             <p className="font-bold text-gray-900 dark:text-white text-sm">{entry.descricao}</p>
                             <p className="text-xs text-gray-500">{format(new Date(entry.data), 'dd/MM/yyyy HH:mm')}</p>
                         </div>
                         <p className="font-bold text-red-500">- R$ {entry.valor.toFixed(2)}</p>
                     </div>
                 ))}

                 {(activeTab === 'sales' ? sales.length : cashFlow.filter(c => c.tipo === 'SAIDA').length) === 0 && (
                     <p className="text-center text-gray-400 text-sm py-4">Nenhum registro no período.</p>
                 )}
             </div>
         </div>
      </div>

      {/* --- Modals --- */}
      <Modal isOpen={showValeModal} onClose={() => setShowValeModal(false)} title="Cadastrar Vale">
          <div className="space-y-4">
              <div className="bg-yellow-50 dark:bg-yellow-900/20 p-3 rounded-lg border border-yellow-200 dark:border-yellow-900/30 text-xs text-yellow-700 dark:text-yellow-400">
                  Isso será registrado como uma SAÍDA no caixa vinculada a este vendedor.
              </div>
              <Input 
                  label="Valor (R$)"
                  type="number"
                  value={transactionForm.valor}
                  onChange={(e) => setTransactionForm({ ...transactionForm, valor: e.target.value })}
              />
              <Input 
                  label="Descrição (Opcional)"
                  placeholder="Ex: Adiantamento semanal"
                  value={transactionForm.descricao}
                  onChange={(e) => setTransactionForm({ ...transactionForm, descricao: e.target.value })}
              />
              <Button fullWidth onClick={() => handleAddTransaction('VALE')} isLoading={loading} variant="danger">
                  Confirmar Desconto
              </Button>
          </div>
      </Modal>

      <Modal isOpen={showPaymentModal} onClose={() => setShowPaymentModal(false)} title="Pagar Comissão">
          <div className="space-y-4">
              <div className="bg-green-50 dark:bg-green-900/20 p-3 rounded-lg border border-green-200 dark:border-green-900/30 text-xs text-green-700 dark:text-green-400">
                  Confirme o valor para zerar o saldo pendente.
              </div>
              <Input 
                  label="Valor a Pagar (R$)"
                  type="number"
                  value={transactionForm.valor}
                  onChange={(e) => setTransactionForm({ ...transactionForm, valor: e.target.value })}
              />
              <Input 
                  label="Observação (Opcional)"
                  placeholder="Ex: Ref. mês de Agosto"
                  value={transactionForm.descricao}
                  onChange={(e) => setTransactionForm({ ...transactionForm, descricao: e.target.value })}
              />
              <Button fullWidth onClick={() => handleAddTransaction('PAGAMENTO')} isLoading={loading} className="bg-green-600 hover:bg-green-700">
                  Confirmar Pagamento
              </Button>
          </div>
      </Modal>

    </div>
  );
};

export default SellerDetails;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ICONS, ROUTES } from '../constants';
import { Button, Input, Card, Modal, Toast } from '../components/ui';
import { dataService } from '../services/mockSupabase';
import { User } from '../types';
import { format, startOfMonth, endOfMonth } from 'date-fns';

const Sellers: React.FC = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'list' | 'performance'>('list');
  const [sellers, setSellers] = useState<User[]>([]);

  // Performance State
  const [startDate, setStartDate] = useState(format(startOfMonth(new Date()), 'yyyy-MM-dd'));
  const [endDate, setEndDate] = useState(format(endOfMonth(new Date()), 'yyyy-MM-dd'));
  const [performanceData, setPerformanceData] = useState<Record<string, { total: number, count: number }>>({});

  // CRUD State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState({ show: false, message: '' });

  const [form, setForm] = useState<Partial<User>>({
    nome: '',
    email: '',
    perfil: 'vendedor',
    comissao_porcentagem: 0
  });
  const [editingId, setEditingId] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  const loadSellers = async () => {
    const data = await dataService.getSellers();
    setSellers(data);
  };

  useEffect(() => {
    loadSellers();
  }, []);

  // Fetch performance data when switching to that tab or changing dates
  useEffect(() => {
    if (activeTab === 'performance') {
        const fetchPerformance = async () => {
            setLoading(true);
            try {
                const results = await dataService.getSellersPerformance(new Date(startDate), new Date(endDate));
                const map: Record<string, { total: number, count: number }> = {};
                results.forEach(r => {
                    map[r.sellerId] = { total: r.totalSales, count: r.salesCount };
                });
                setPerformanceData(map);
            } catch (e) {
                console.error(e);
            } finally {
                setLoading(false);
            }
        };
        fetchPerformance();
    }
  }, [activeTab, startDate, endDate]);

  const showToast = (msg: string) => {
      setToast({ show: true, message: msg });
  };

  // --- CRUD HANDLERS ---
  const handleOpenCreate = () => {
    setEditingId(null);
    setForm({ nome: '', email: '', perfil: 'vendedor', comissao_porcentagem: 0 });
    setIsModalOpen(true);
  };

  const handleOpenEdit = (seller: User, e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingId(seller.id);
    setForm({ ...seller });
    setIsModalOpen(true);
  };

  const handleOpenDelete = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    setDeletingId(id);
    setIsDeleteModalOpen(true);
  };

  const handleSave = async () => {
    if (!form.nome || !form.email) return;
    setLoading(true);
    try {
      if (editingId) {
        await dataService.updateSeller(editingId, form);
        showToast('Usuário atualizado com sucesso!');
      } else {
        await dataService.createSeller({
          nome: form.nome,
          email: form.email,
          perfil: form.perfil || 'vendedor',
          ativo: true,
          comissao_porcentagem: Number(form.comissao_porcentagem) || 0
        });
        showToast('Usuário cadastrado com sucesso!');
      }
      await loadSellers();
      setIsModalOpen(false);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
      if (!deletingId) return;
      setLoading(true);
      try {
          await dataService.deleteSeller(deletingId);
          await loadSellers();
          setIsDeleteModalOpen(false);
          showToast('Usuário removido com sucesso!');
      } catch (e) {
          console.error(e);
      } finally {
          setLoading(false);
      }
  };

  // Navigate to Detail Page
  const handleSellerClick = (id: string) => {
      navigate(ROUTES.SELLER_DETAILS.replace(':id', id));
  };

  return (
    <div className="flex flex-col h-screen bg-[#F3F4F6] dark:bg-[#121212] transition-colors">
      <div className="bg-white dark:bg-[#1E1E1E] p-4 flex items-center gap-4 border-b border-gray-100 dark:border-[#333] sticky top-0 z-10 shadow-sm">
        <button 
            onClick={() => navigate(ROUTES.DASHBOARD)} 
            className="p-2 -ml-2 rounded-full hover:bg-gray-100 dark:hover:bg-[#333] text-gray-900 dark:text-white transition-colors"
        >
          {ICONS.Left}
        </button>
        <h1 className="text-lg font-bold text-gray-900 dark:text-white">Equipe de Vendas</h1>
      </div>

      {/* Tabs */}
      <div className="px-4 mt-4">
        <div className="flex p-1 bg-white dark:bg-[#1E1E1E] rounded-xl border border-gray-200 dark:border-[#333]">
           <button 
             onClick={() => setActiveTab('list')}
             className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${activeTab === 'list' ? 'bg-[#FF7A00] text-white shadow-md' : 'text-gray-500 dark:text-gray-400'}`}
           >
             Gerenciar
           </button>
           <button 
             onClick={() => setActiveTab('performance')}
             className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${activeTab === 'performance' ? 'bg-[#FF7A00] text-white shadow-md' : 'text-gray-500 dark:text-gray-400'}`}
           >
             Comissões
           </button>
        </div>
      </div>

      <div className="p-4 space-y-4 flex-1 overflow-y-auto custom-scrollbar">

        {/* === LIST VIEW === */}
        {activeTab === 'list' && (
            <>
                <Button onClick={handleOpenCreate} fullWidth icon={ICONS.UserPlus}>
                  Novo Membro
                </Button>

                <div className="space-y-3 pb-20">
                  {sellers.map(seller => (
                    <Card 
                        key={seller.id} 
                        className="flex flex-col gap-3 cursor-pointer hover:border-[#FF7A00] transition-colors group"
                        onClick={() => handleSellerClick(seller.id)}
                    >
                      <div className="flex justify-between items-center">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-full bg-gray-100 dark:bg-[#333] flex items-center justify-center text-gray-500 font-bold border border-gray-200 dark:border-white/10">
                                {seller.nome.charAt(0).toUpperCase()}
                            </div>
                            <div>
                                <h3 className="text-gray-900 dark:text-white font-bold flex items-center gap-2 group-hover:text-[#FF7A00] transition-colors">
                                {seller.nome}
                                {seller.perfil === 'admin' && <span className="bg-red-500/10 text-red-500 text-[10px] px-2 py-0.5 rounded-full border border-red-500/20">ADMIN</span>}
                                </h3>
                                <p className="text-gray-500 text-sm">{seller.email}</p>
                            </div>
                        </div>
                        <div className="text-right">
                            <p className="text-xs text-gray-400 font-bold uppercase">Comissão</p>
                            <p className="text-[#FF7A00] font-bold">{seller.comissao_porcentagem || 0}%</p>
                        </div>
                      </div>

                      <div className="flex gap-2 pt-2 border-t border-gray-100 dark:border-white/5">
                        <button 
                          onClick={(e) => handleOpenEdit(seller, e)}
                          className="flex-1 py-2 bg-gray-50 dark:bg-white/5 text-gray-600 dark:text-gray-400 rounded-lg hover:bg-gray-100 dark:hover:bg-white/10 flex justify-center items-center gap-2 text-sm font-medium z-10"
                        >
                            {ICONS.Edit} Editar
                        </button>
                        <button 
                          onClick={(e) => handleOpenDelete(seller.id, e)}
                          className="flex-1 py-2 bg-red-50 dark:bg-red-500/10 text-red-500 rounded-lg hover:bg-red-100 dark:hover:bg-red-500/20 flex justify-center items-center gap-2 text-sm font-medium z-10"
                        >
                            {ICONS.Trash} Excluir
                        </button>
                      </div>
                    </Card>
                  ))}
                </div>
            </>
        )}

        {/* === PERFORMANCE VIEW === */}
        {activeTab === 'performance' && (
            <div className="space-y-6 animate-fade-in pb-20">
                <div className="grid grid-cols-2 gap-3 bg-white dark:bg-[#1E1E1E] p-4 rounded-2xl border border-gray-200 dark:border-[#333] shadow-sm">
                   <div className="space-y-1">
                     <label className="text-xs text-gray-500 font-bold ml-1">De:</label>
                     <input 
                       type="date" 
                       className="w-full bg-gray-50 dark:bg-[#2E2E2E] border border-gray-200 dark:border-[#404040] rounded-xl px-3 py-2 text-gray-900 dark:text-white text-sm font-bold"
                       value={startDate}
                       onChange={(e) => setStartDate(e.target.value)}
                     />
                   </div>
                   <div className="space-y-1">
                     <label className="text-xs text-gray-500 font-bold ml-1">Até:</label>
                     <input 
                       type="date" 
                       className="w-full bg-gray-50 dark:bg-[#2E2E2E] border border-gray-200 dark:border-[#404040] rounded-xl px-3 py-2 text-gray-900 dark:text-white text-sm font-bold"
                       value={endDate}
                       onChange={(e) => setEndDate(e.target.value)}
                     />
                   </div>
                </div>

                {loading ? (
                    <p className="text-center text-gray-500 py-10">Calculando comissões...</p>
                ) : (
                    <div className="space-y-3">
                        {sellers.map(seller => {
                            const stats = performanceData[seller.id] || { total: 0, count: 0 };
                            const commissionValue = (stats.total * (seller.comissao_porcentagem || 0)) / 100;

                            return (
                                <Card 
                                    key={seller.id} 
                                    className="relative overflow-hidden cursor-pointer"
                                    onClick={() => handleSellerClick(seller.id)}
                                >
                                    <div className="flex justify-between items-start mb-4">
                                        <div className="flex items-center gap-3">
                                            <div className="w-10 h-10 rounded-full bg-gray-100 dark:bg-[#333] flex items-center justify-center text-gray-500 font-bold border border-gray-200 dark:border-white/10">
                                                {seller.nome.charAt(0).toUpperCase()}
                                            </div>
                                            <div>
                                                <h3 className="text-gray-900 dark:text-white font-bold">{seller.nome}</h3>
                                                <p className="text-xs text-gray-500">{stats.count} vendas no período</p>
                                            </div>
                                        </div>
                                        <div className="bg-orange-50 dark:bg-orange-900/20 text-[#FF7A00] px-2 py-1 rounded-lg text-xs font-bold border border-orange-100 dark:border-orange-900/30">
                                            {seller.comissao_porcentagem || 0}% Com.
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 gap-4 border-t border-gray-100 dark:border-white/10 pt-3">
                                        <div>
                                            <p className="text-[10px] text-gray-400 font-bold uppercase">Total Vendido</p>
                                            <p className="text-gray-900 dark:text-white font-bold text-lg">
                                                R$ {stats.total.toFixed(2)}
                                            </p>
                                        </div>
                                        <div className="text-right">
                                            <p className="text-[10px] text-gray-400 font-bold uppercase">A Pagar (Comissão)</p>
                                            <p className="text-green-600 dark:text-green-500 font-black text-xl">
                                                R$ {commissionValue.toFixed(2)}
                                            </p>
                                        </div>
                                    </div>
                                    <div className="absolute right-2 top-2 opacity-50">
                                        {ICONS.Right}
                                    </div>
                                </Card>
                            );
                        })}
                        {sellers.length === 0 && (
                            <p className="text-center text-gray-500">Nenhum vendedor cadastrado.</p>
                        )}
                    </div>
                )}
            </div>
        )}
      </div>

      {/* --- MODALS (CRUD) --- */}
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingId ? "Editar Usuário" : "Cadastrar Usuário"}>
        <div className="space-y-4">
          <Input 
            label="Nome Completo" 
            value={form.nome} 
            onChange={e => setForm({...form, nome: e.target.value})}
          />
          <Input 
            label="E-mail" 
            type="email"
            value={form.email} 
            onChange={e => setForm({...form, email: e.target.value})}
            disabled={!!editingId} 
          />

          <div className="flex flex-col gap-1.5">
             <label className="text-sm font-bold text-gray-700 dark:text-gray-300 ml-1">Perfil de Acesso</label>
             <select 
               className="w-full bg-white dark:bg-[#1E1E1E] border border-gray-200 dark:border-[#333] rounded-2xl px-4 py-4 text-gray-900 dark:text-white font-medium focus:outline-none focus:border-[#FF7A00]"
               value={form.perfil}
               onChange={e => setForm({...form, perfil: e.target.value as any})}
             >
                <option value="vendedor">Vendedor</option>
                <option value="admin">Administrador</option>
             </select>
          </div>

          <Input 
            label="Comissão (%)" 
            type="number"
            placeholder="Ex: 5"
            value={form.comissao_porcentagem} 
            onChange={e => setForm({...form, comissao_porcentagem: Number(e.target.value)})}
          />
          {!editingId && <p className="text-xs text-gray-500">* Senha padrão inicial: 123456</p>}
          <Button fullWidth onClick={handleSave} isLoading={loading}>
            Salvar
          </Button>
        </div>
      </Modal>

      <Modal isOpen={isDeleteModalOpen} onClose={() => setIsDeleteModalOpen(false)} title="Excluir Usuário">
         <div className="text-center space-y-4">
             <div className="w-16 h-16 bg-red-500/20 rounded-full flex items-center justify-center text-red-500 mx-auto">
                {ICONS.Trash}
             </div>
             <p className="text-gray-600 dark:text-gray-300">Tem certeza? O acesso deste usuário será revogado.</p>
             <div className="grid grid-cols-2 gap-3">
                 <Button variant="secondary" onClick={() => setIsDeleteModalOpen(false)}>Cancelar</Button>
                 <Button variant="danger" onClick={handleDelete} isLoading={loading}>Excluir</Button>
             </div>
         </div>
      </Modal>

      <Toast 
        message={toast.message} 
        isVisible={toast.show} 
        onClose={() => setToast(prev => ({ ...prev, show: false }))} 
      />
    </div>
  );
};

export default Sellers;

